@frappe.whitelist()
def sync_planning_line_unit_options_meta():
	"""
	Desk / maintenance: force ``Planning Table`` + ``Planning sheet Item`` ``unit`` Select options
	to the full canonical list (including rewinding machines). Idempotent.
	"""
	ensure_planning_line_unit_docfield_options()
	return {"ok": True}


def _sql_printed_bopp_row_kind(alias="i"):
	"""True when Planning row is on the VR BOPP printing unit or uses PB / PRINTED BOPP item codes."""
	u_esc = (PRINTED_BOPP_FILM_UNIT or "").replace("'", "''")
	ic = f"{alias}.item_code"
	un = f"{alias}.unit"
	return (
		f"({un} = '{u_esc}' OR UPPER(TRIM(IFNULL({ic},''))) LIKE 'PB-%' OR "
		f"(LOCATE('PRINTED', UPPER(IFNULL({ic},''))) > 0 AND LOCATE('BOPP', UPPER(IFNULL({ic},''))) > 0))"
	)


def _sql_pull_color_or_printed_bopp_row(alias="i"):
	"""
	SQL predicate: normal colour rows OR Printed BOPP film rows (often have no colour filled).
	Used in pull / pull_board queries that historically required non-empty colour.
	"""
	return f"(({alias}.color IS NOT NULL AND {alias}.color != '') OR {_sql_printed_bopp_row_kind(alias)})"


# First-segment wins for codes like 105-…-100… (GSM / width digits) so we never classify as 100 instead of 105.
_ITEM_PROCESS_KNOWN_PREFIXES = frozenset(
	{
		"100", "102", "103", "104", "105", "106", "107", "108", "109", "110",
		"200", "201", "202", "203", "211", "212", "213", "214", "216", "217",
		"221", "222", "223", "224", "231", "232", "233", "241", "242", "225", "226",
		"251", "252", "253", "254", "255",
	}
)


def _is_standalone_printing_fg_item_code(item_code):
	"""Design-prefixed 105/106 FG on SO (e.g. 6003-1051131811201395) — not W-CUT/D-CUT bag."""
	ic = str(item_code or "").strip().upper()
	if not ic or "-" not in ic:
		return False
	if _parse_105_item_code(ic):
		return True
	if (_parse_106_item_code(ic) or {}).get("process") == "106":
		return True
	return bool(re.match(r"^[A-Z0-9]+-105\d", ic) or re.match(r"^[A-Z0-9]+-106", ic))


def _item_process_prefix(item_code):
	ic = str(item_code or "").strip()
	if not ic:
		return ""
	if "-" in ic:
		# 6003-105… digit tails contain ``201`` substrings — must not run D-CUT parser before 105 detection.
		if _is_standalone_printing_fg_item_code(ic):
			if re.match(r"^[A-Z0-9]+-106", ic.upper()):
				return "106"
			return "105"
		# W/D-CUT bag FG — parse before segment scan (bag size ``201`` is not W-CUT process 201).
		try:
			from production_entry.production_planning.box_bag_api import _parse_dcut_bag_item_code

			bag_proc = str((_parse_dcut_bag_item_code(ic) or {}).get("process") or "").strip()
			if bag_proc in W_CUT_D_CUT_FG_PROCESS_CODES:
				return bag_proc
		except Exception:
			pass
		# Design-prefixed fabric FG (7465-108D22115I) — segment scan (tail may contain 221).
		all_segments = ic.split("-")
		for seg in all_segments:
			seg_digits = "".join(ch for ch in seg if ch.isdigit())
			if len(seg_digits) >= 3:
				sp = seg_digits[:3]
				if sp in _ITEM_PROCESS_KNOWN_PREFIXES:
					return sp
		parts = ic.split("-", 1)
		head = (parts[0] or "").strip().upper()
		tail = (parts[1] or "").strip().upper() if len(parts) > 1 else ""
		if head in ("253", "255", "254"):
			return head
		if tail.startswith("253"):
			return "253"
		if tail.startswith("255"):
			return "255"
		if tail.startswith("254"):
			return "254"
		if tail.startswith("108"):
			return "108"
	digits = "".join(ch for ch in ic if ch.isdigit())
	return digits[:3] if len(digits) >= 3 else ""


def _bom_item_process_code(item_code):
	"""Process code for BOM parent/child matching (design-first 108/255/107 and legacy layouts)."""
	ic = str(item_code or "").strip()
	if not ic:
		return ""
	if ic.startswith("PB-") or "PRINTED" in ic.upper():
		return "PB-"
	pp = _item_process_prefix(ic)
	lam = _lamination_process_from_item_code(ic)
	if pp in (
		"108", "255", "253", "254", "251", "252",
		"211", "212", "213", "214", "216", "217", "200", "201", "202", "203",
		"221", "222", "223", "224", "231", "232", "233", "241", "242", "225", "226",
	):
		return pp
	if lam in ("104", "107", "255"):
		return lam
	return pp or lam


def _bom_item_matches_process(item_code, expected_process):
	exp = str(expected_process or "").strip()
	if not exp:
		return False
	if _bom_item_process_code(item_code) == exp:
		return True
	if exp == "PB" and (
		_bom_item_process_code(item_code) in ("PB", "PB-") or _is_printed_bopp_item_code(item_code)
	):
		return True
	if exp == "107" and _is_107_mid_bopp_item(item_code):
		return True
	return False


def _printing_table_order_code(planning_sheet_party_code, item_code):
	"""Party code from Planning sheet, or compact code from FG (e.g. 002-105113… -> 002-105)."""
	oc = _cstr(planning_sheet_party_code).strip()
	if oc:
		return oc
	ic = _cstr(item_code).strip()
	if not ic:
		return ""
	if "-" in ic:
		parts = ic.split("-", 2)
		p0 = parts[0].strip()
		if len(parts) >= 2 and p0:
			rest = parts[1]
			digits = "".join(ch for ch in rest if ch.isdigit())
			if len(digits) >= 3:
				return p0 + "-" + digits[:3]
	return ic


def _printing_trace_id_for_pl_row(pl_row):
	"""Prefer explicit trace on the planning row; otherwise derive from FG item_code (105/106-aware)."""
	t = _cstr((pl_row or {}).get("custom_parent_child_trace_id")).strip()
	if t:
		return t
	ic = _cstr((pl_row or {}).get("item_code")).strip()
	return _parent_child_trace_id_from_item_code(ic) if ic else ""


def _printing_work_orders_fallback_for_pl_row(pl_row):
	"""Resolve Work Order(s) when ``production_plan`` is missing on the row or PP-scoped lookup finds nothing.

	Matches ERPNext behaviour where the WO is keyed by SO + FG ``production_item`` even if the Planning row
	lost its Production Plan link field.
	"""
	row_ic = _cstr((pl_row or {}).get("item_code")).strip()
	planning_sheet = _cstr((pl_row or {}).get("planning_sheet")).strip()
	if not row_ic:
		return [], []

	so_name = None
	if planning_sheet and frappe.db.exists("Planning sheet", planning_sheet):
		so_name = _cstr(frappe.db.get_value("Planning sheet", planning_sheet, "sales_order")).strip() or None

	wos = []
	if so_name and frappe.db.has_column("Work Order", "sales_order"):
		wos = (
			frappe.get_all(
				"Work Order",
				filters={"sales_order": so_name, "production_item": row_ic, "docstatus": ["<", 2]},
				fields=["name", "qty", "produced_qty", "status", "production_item"],
				order_by="creation desc",
				limit_page_length=20,
			)
			or []
		)

	if not wos:
		for fld in ("so_item", "sales_order_item"):
			soi = _cstr((pl_row or {}).get(fld)).strip()
			if not soi or not frappe.db.exists("Sales Order Item", soi):
				continue
			si_ic = frappe.db.get_value("Sales Order Item", soi, "item_code")
			if not si_ic:
				continue
			si_ic = str(si_ic).strip()
			fl = {"production_item": si_ic, "docstatus": ["<", 2]}
			if so_name and frappe.db.has_column("Work Order", "sales_order"):
				fl["sales_order"] = so_name
			cand = (
				frappe.get_all(
					"Work Order",
					filters=fl,
					fields=["name", "qty", "produced_qty", "status", "production_item"],
					order_by="creation desc",
					limit_page_length=20,
				)
				or []
			)
			if cand:
				wos = cand
				break

	if not wos and row_ic and len(row_ic) >= 7 and so_name and frappe.db.has_column("Work Order", "sales_order"):
		candidates = (
			frappe.get_all(
				"Work Order",
				filters={"sales_order": so_name, "docstatus": ["<", 2]},
				fields=["name", "qty", "produced_qty", "status", "production_item"],
				order_by="creation desc",
				limit_page_length=50,
			)
			or []
		)
		matched = []
		for wo in candidates:
			pi = _cstr(wo.get("production_item")).strip()
			if not pi:
				continue
			if pi == row_ic or pi.startswith(row_ic):
				matched.append(wo)
		if len(matched) == 1:
			wos = matched

	if not wos:
		fl = {"production_item": row_ic, "docstatus": ["<", 2]}
		if so_name and frappe.db.has_column("Work Order", "sales_order"):
			fl["sales_order"] = so_name
		wos = (
			frappe.get_all(
				"Work Order",
				filters=fl,
				fields=["name", "qty", "produced_qty", "status", "production_item"],
				order_by="creation desc",
				limit_page_length=20,
			)
			or []
		)
	if not wos and not so_name:
		wos = (
			frappe.get_all(
				"Work Order",
				filters={"production_item": row_ic, "docstatus": ["<", 2]},
				fields=["name", "qty", "produced_qty", "status", "production_item"],
				order_by="creation desc",
				limit_page_length=20,
			)
			or []
		)

	tid_fb = _printing_trace_id_for_pl_row(pl_row)
	if (
		len(wos) > 1
		and tid_fb
		and frappe.db.has_column("Work Order", "custom_parent_child_trace_id")
	):
		narrowed = []
		for w in wos:
			wname = w.get("name")
			if not wname:
				continue
			wtr = _cstr(frappe.db.get_value("Work Order", wname, "custom_parent_child_trace_id")).strip()
			if wtr and wtr == tid_fb:
				narrowed.append(w)
		if narrowed:
			wos = narrowed

	wo_names = [w.get("name") for w in wos if w.get("name")]
	return wo_names, wos


def _printing_work_orders_for_pl_row(pp_id, pl_row):
	"""Resolve Work Order(s) for a printing planning row scoped to the same Production Plan.

	Priority: PP + ``custom_parent_child_trace_id`` on Work Order (when present) → exact
	``production_item`` → SO line FG → **unique** prefix match only. Deliberately no
	'sole WO on this PP' fallback — that attached one WO (and fabric transfers) to every
	unmatched line on the plan.
	"""
	if not pp_id:
		return _printing_work_orders_fallback_for_pl_row(pl_row)

	def _fetch_wos(extra=None):
		fl = {"production_plan": pp_id, "docstatus": ["<", 2]}
		if extra:
			fl.update(extra)
		return (
			frappe.get_all(
				"Work Order",
				filters=fl,
				fields=["name", "qty", "produced_qty", "status", "production_item"],
				order_by="creation asc",
				limit_page_length=50,
			)
			or []
		)

	def _narrow_trace_wos(by_trace):
		if not by_trace:
			return []
		if len(by_trace) == 1:
			return by_trace
		row_ic_local = _cstr((pl_row or {}).get("item_code")).strip()
		if not row_ic_local:
			return []
		ex = [w for w in by_trace if _cstr(w.get("production_item")).strip() == row_ic_local]
		if len(ex) == 1:
			return ex
		pref = []
		for w in by_trace:
			pi = _cstr(w.get("production_item")).strip()
			if pi and (pi == row_ic_local or pi.startswith(row_ic_local)):
				pref.append(w)
		if len(pref) == 1:
			return pref
		return []

	row_ic = _cstr((pl_row or {}).get("item_code")).strip()
	tid = _printing_trace_id_for_pl_row(pl_row)
	wos = []

	if tid and frappe.db.has_column("Work Order", "custom_parent_child_trace_id"):
		wos = _narrow_trace_wos(_fetch_wos({"custom_parent_child_trace_id": tid}))

	if not wos and row_ic:
		wos = _fetch_wos({"production_item": row_ic})

	if not wos:
		for fld in ("so_item", "sales_order_item"):
			soi = _cstr((pl_row or {}).get(fld)).strip()
			if not soi or not frappe.db.exists("Sales Order Item", soi):
				continue
			si_ic = frappe.db.get_value("Sales Order Item", soi, "item_code")
			if si_ic:
				wos = _fetch_wos({"production_item": str(si_ic).strip()})
				if wos:
					break
	if not wos and row_ic and len(row_ic) >= 7:
		candidates = _fetch_wos()
		matched = []
		for wo in candidates:
			pi = _cstr(wo.get("production_item")).strip()
			if not pi:
				continue
			if pi == row_ic or pi.startswith(row_ic):
				matched.append(wo)
		if len(matched) == 1:
			wos = matched
	wo_names = [w.get("name") for w in wos if w.get("name")]
	if not wo_names:
		return _printing_work_orders_fallback_for_pl_row(pl_row)
	return wo_names, wos


def _expand_work_orders_for_rm_transfer(wo_names):
	"""Include child and parent Work Orders (material may post against child or parent WO name)."""
	names = [str(n).strip() for n in (wo_names or []) if str(n or "").strip()]
	if not names or not frappe.db.exists("DocType", "Work Order"):
		return names
	out = set(names)
	meta = frappe.get_meta("Work Order")
	for fname in ("parent_work_order", "custom_parent_work_order"):
		if not meta.has_field(fname):
			continue
		for parent in list(out):
			for ch in (
				frappe.get_all(
					"Work Order",
					filters={fname: parent, "docstatus": ["<", 2]},
					pluck="name",
					limit_page_length=80,
				)
				or []
			):
				if ch:
					out.add(ch)
		for wo in list(out):
			par = frappe.db.get_value("Work Order", wo, fname)
			if par:
				out.add(_cstr(par))
	return list(out)


def _fabric_transferred_kg_from_work_order_items(wo_names):
	"""Fabric (100*) RM transferred to WIP — uses ERPNext ``Work Order Item.transferred_qty`` (authoritative)."""
	expanded = _expand_work_orders_for_rm_transfer(wo_names)
	if not expanded:
		return 0.0
	ph = ",".join(["%s"] * len(expanded))
	row = frappe.db.sql(
		f"""
		SELECT SUM(COALESCE(transferred_qty, 0)) AS qty
		FROM `tabWork Order Item`
		WHERE parent IN ({ph})
		  AND IFNULL(item_code, '') LIKE '100%%'
		""",
		tuple(expanded),
		as_dict=True,
	)
	if not row:
		return 0.0
	return flt((row[0] or {}).get("qty") or 0)


def _mtfm_transfer_rows_for_work_orders(wo_names):
	"""Submitted Material Transfer for Manufacture lines (fabric/RM to WIP), keyed by Stock Entry.

	Uses ``COALESCE(transfer_qty, qty)`` and does not require ``t_warehouse`` on every line — some sites
	leave target WIP only on the Stock Entry header or set ``s_warehouse`` only on RM lines.
	"""
	if not wo_names:
		return []
	ph = ",".join(["%s"] * len(wo_names))
	return (
		frappe.db.sql(
			f"""
			SELECT se.name, se.posting_date, se.purpose, se.work_order,
				SUM(ABS(COALESCE(NULLIF(sed.transfer_qty, 0), sed.qty, 0))) AS qty
			FROM `tabStock Entry` se
			INNER JOIN `tabStock Entry Detail` sed ON sed.parent = se.name
			WHERE se.docstatus = 1
			  AND se.purpose = 'Material Transfer for Manufacture'
			  AND IFNULL(se.work_order, '') IN ({ph})
			  AND IFNULL(sed.item_code, '') != ''
			  AND (
				  IFNULL(sed.t_warehouse, '') != ''
				  OR IFNULL(sed.s_warehouse, '') != ''
			  )
			GROUP BY se.name, se.posting_date, se.purpose, se.work_order
			ORDER BY se.posting_date DESC, se.name DESC
			""",
			tuple(wo_names),
			as_dict=True,
		)
		or []
	)


def _get_transfer_and_produced_for_pl_row(pl_row):
    """Return produced/transferred qty metadata for a Process 105 planning row."""
    psi_name = _cstr((pl_row or {}).get("psi_name") or (pl_row or {}).get("planning_sheet_item") or (pl_row or {}).get("item_name"))
    planning_sheet = _cstr((pl_row or {}).get("planning_sheet") or (pl_row or {}).get("plan_name") or (pl_row or {}).get("parent"))
    pp_id = _cstr((pl_row or {}).get("pp_id"))
    out = {
        "produced_qty": 0.0,
        "transferred_qty": 0.0,
        "transfer_status": "pending",
        "transfer_details": [],
        "can_create_spr": False,
        "linked_work_orders": [],
    }

    try:
        if not pp_id and planning_sheet and psi_name and "get_planning_sheet_pp_id" in globals():
            res = get_planning_sheet_pp_id(planning_sheet, planning_sheet_item=psi_name)
            if isinstance(res, dict) and res.get("status") == "ok":
                pp_id = _cstr(res.get("pp_id"))

        wo_names, wos = _printing_work_orders_for_pl_row(pp_id, pl_row)
        out["linked_work_orders"] = list(wo_names)

        if wos:
            out["produced_qty"] = sum(flt(wo.get("produced_qty") or 0) for wo in wos)
        elif pp_id:
            row_ic2 = _cstr((pl_row or {}).get("item_code")).strip()
            if not row_ic2:
                legacy = (
                    frappe.get_all(
                        "Work Order",
                        filters={"production_plan": pp_id, "docstatus": ["<", 2]},
                        fields=["produced_qty"],
                        order_by="creation asc",
                        limit_page_length=50,
                    )
                    or []
                )
                out["produced_qty"] = sum(flt(wo.get("produced_qty") or 0) for wo in legacy)

        by_se = {}

        if psi_name:
            sed_cols = [
                c
                for c in ("planning_sheet_item", "custom_planning_sheet_item", "planning_sheet_item_name")
                if frappe.db.has_column("Stock Entry Detail", c)
            ]
            transfer_rows = []
            if sed_cols:
                match_or = " OR ".join([f"IFNULL(sed.`{c}`, '') = %s" for c in sed_cols])
                tr_params = tuple([psi_name] * len(sed_cols))
                qty_sum = (
                    "SUM(ABS(COALESCE(NULLIF(sed.transfer_qty, 0), sed.qty, 0)))"
                    if frappe.db.has_column("Stock Entry Detail", "transfer_qty")
                    else "SUM(ABS(COALESCE(sed.qty, 0)))"
                )
                transfer_rows = (
                    frappe.db.sql(
                        f"""
                SELECT se.name, se.posting_date, se.purpose,
                    {qty_sum} AS qty
                FROM `tabStock Entry` se
                INNER JOIN `tabStock Entry Detail` sed ON sed.parent = se.name
                WHERE se.docstatus = 1
                  AND se.purpose IN ('Material Transfer', 'Material Transfer for Manufacture')
                  AND ({match_or})
                GROUP BY se.name, se.posting_date, se.purpose
                ORDER BY se.posting_date DESC, se.name DESC
                """,
                        tr_params,
                        as_dict=True,
                    )
                    or []
                )
            for r in transfer_rows:
                nm = r.get("name")
                if nm:
                    by_se[nm] = r

        for r in _mtfm_transfer_rows_for_work_orders(_expand_work_orders_for_rm_transfer(wo_names)):
            nm = r.get("name")
            if nm and nm not in by_se:
                by_se[nm] = r

        details = list(by_se.values())
        details.sort(key=lambda x: (_cstr(x.get("posting_date")), _cstr(x.get("name"))), reverse=True)
        out["transfer_details"] = details
        se_kg = sum(flt(x.get("qty") or 0) for x in details)
        wo_fabric_kg = _fabric_transferred_kg_from_work_order_items(wo_names)
        # Fabric input: prefer BOM fabric RM transferred on the WO (parent/child WO items); Stock Entry sum as fallback.
        out["transferred_qty"] = max(se_kg, wo_fabric_kg)

        if out["transferred_qty"] > 0:
            out["can_create_spr"] = True
            out["transfer_status"] = "transferred"
        elif out["produced_qty"] > 0:
            out["transfer_status"] = "pending"
        else:
            out["transfer_status"] = "pending"

        if out["transferred_qty"] > 0 and out["produced_qty"] > 0 and out["transferred_qty"] < out["produced_qty"]:
            out["transfer_status"] = "partial"
    except Exception:
        frappe.log_error(
            frappe.get_traceback(),
            "_get_transfer_and_produced_for_pl_row",
        )

    return out


def _rewinding_width_mm_from_item_code(item_code):
	"""Last hyphen segment on 102 codes, e.g. 1021035420501600-1600 -> 1600 (mm)."""
	ic = str(item_code or "").strip()
	if _item_process_prefix(ic) != "102":
		return None
	parts = ic.split("-")
	if len(parts) < 2:
		return None
	tail = parts[-1].strip()
	if tail.isdigit():
		return cint(tail)
	return None


def _parse_sheet_cutting_item_code(item_code):
	"""Parse 251/252 sheet-cutting code as PPP|QQQ|CCC|GGG|SSS (series id)."""
	ic = str(item_code or "").strip().upper()
	if not ic:
		return {}
	design_code = ""
	m = re.match(r"^(?P<design>[A-Z0-9]+)-(?P<body>25[12]\d{12})$", ic)
	if m:
		design_code = (m.group("design") or "").strip()
		digits = m.group("body")
	else:
		digits = "".join(ch for ch in ic if ch.isdigit())
		if len(digits) < 15:
			return {}
		# Accept prefixed/mixed item codes by taking the rightmost 251/252 + 12 digits block.
		matches = re.findall(r"(25[12]\d{12})", digits)
		if matches:
			digits = matches[-1]
	if digits[:3] not in ("251", "252") or len(digits) < 15:
		return {}
	return {
		"process": digits[:3],
		"design_code": design_code,
		"quality_code": digits[3:6],
		"colour_code": digits[6:9],
		"gsm": cint(digits[9:12] or 0),
		"series_id": digits[12:15],
	}


def _is_printed_bopp_item_code(item_code):
	"""PB / Printed BOPP film child lines — no roll width on the planning row."""
	su = str(item_code or "").strip().upper()
	if not su:
		return False
	if su.startswith("PB-"):
		return True
	if "PRINTED" in su and "BOPP" in su:
		return True
	return False


def _is_cylinder_yield_so_item(item_code):
	"""CY-* cylinder reference lines on SO — never create or sync on Planning Sheet."""
	su = _cstr(item_code).strip().upper()
	if not su:
		return False
	if re.match(r"^CY(\s|-|:|$)", su):
		return True
	compact = re.sub(r"[\s:]+", "-", su)
	return compact.startswith("CY-")


def _purge_cylinder_yield_rows_from_planning_sheet(planning_sheet_name):
	"""Remove any CY cylinder reference rows left on a planning sheet."""
	if not planning_sheet_name:
		return 0
	removed = 0
	for doctype, parentfield in (
		("Planning Table", _get_pt_parentfield()),
		("Planning sheet Item", "items"),
	):
		if not frappe.db.exists("DocType", doctype):
			continue
		rows = frappe.get_all(
			doctype,
			filters={"parent": planning_sheet_name},
			fields=["name", "item_code"],
			limit_page_length=0,
		) or []
		for row in rows:
			if _is_cylinder_yield_so_item(row.get("item_code")):
				frappe.delete_doc(doctype, row.name, force=1, ignore_permissions=True)
				removed += 1
	if removed:
		frappe.db.commit()
	return removed


def _apply_mandatory_planning_row_defaults(row, item_code=None):
	"""Ensure gsm / quality exist before Planning sheet save validation."""
	if not row:
		return row
	ic = _cstr(item_code or row.get("item_code")).strip()
	q = _cstr(row.get("quality") or row.get("custom_quality")).strip()
	if not q:
		q = "GENERIC"
		try:
			q2, _c, _g = resolve_quality_color_gsm_from_item_code(ic)
			if q2:
				q = q2
		except Exception:
			pass
	row["quality"] = q
	if frappe.db.has_column("Planning Table", "custom_quality") or frappe.db.has_column(
		"Planning sheet Item", "custom_quality"
	):
		row["custom_quality"] = q
	gsm_val = cint(row.get("gsm") or 0)
	if gsm_val <= 0:
		try:
			_q, _c, g = resolve_quality_color_gsm_from_item_code(ic)
			if g:
				gsm_val = cint(g)
		except Exception:
			pass
	row["gsm"] = gsm_val or 0
	return row


def _parse_two_dim_sheet_size(text):
	"""Return (width_inch, height_inch) from strings like ``12 * 16``, ``12x16``, ``12\" x 16\"``."""
	s = _cstr(text).strip()
	if not s:
		return (0.0, 0.0)
	s = s.replace('"', " ").replace("″", " ").replace("′", " ")
	for sep in ("×", "x", "X", "*"):
		s = s.replace(sep, "|")
	parts = [p.strip() for p in s.split("|") if p.strip()]
	if len(parts) >= 2:
		try:
			a = flt(re.sub(r"[^\d.]+", "", parts[0]) or 0)
			b = flt(re.sub(r"[^\d.]+", "", parts[1]) or 0)
			return (a, b) if a > 0 and b > 0 else (0.0, 0.0)
		except Exception:
			return (0.0, 0.0)
	if len(parts) == 1:
		try:
			v = flt(re.sub(r"[^\d.]+", "", parts[0]) or 0)
			return (v, 0.0) if v > 0 else (0.0, 0.0)
		except Exception:
			return (0.0, 0.0)
	return (0.0, 0.0)


def _normalize_sheet_size_str(sz):
	"""Normalize sheet size text to ``W * H`` with rounded inch dimensions."""
	s = _cstr(sz).strip()
	if not s:
		return ""
	a, b = _parse_two_dim_sheet_size(s)
	if a > 0 and b > 0:
		return f"{int(round(a))} * {int(round(b))}"
	return s


def _format_sheet_size_label(width_inch, height_inch, fallback_str=""):
	"""Build display sheet size ``12 * 16`` from dimensions or parse ``fallback_str``."""
	w, h = flt(width_inch or 0), flt(height_inch or 0)
	if w > 0 and h > 0:
		return f"{int(round(w))} * {int(round(h))}"
	return _normalize_sheet_size_str(fallback_str)


def _parse_253_item_code(item_code):
	"""Laminated sheet (253): QQQ|CCC|GGG|SSS after 253-, optional lamination GSM suffix (same letters as 104)."""
	code = re.sub(r"\s+", "", str(item_code or "").strip().upper())
	if not code:
		return {}
	# Compact: 253105542100001-A (no hyphen after 253)
	m0 = re.match(
		r"^253(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<size>\d{3})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m0:
		lam = (m0.group("lam") or "").strip().upper()
		lam_g = cint(_LAM_GSM_SUFFIX_MAP.get(lam, 0) or 0) if lam else 0
		return {
			"process": "253",
			"design_code": "",
			"quality_code": m0.group("quality"),
			"colour_code": m0.group("colour"),
			"gsm": cint(m0.group("gsm") or 0),
			"series_id": m0.group("size"),
			"lam_suffix": lam,
			"lam_gsm_code": lam,
			"lam_gsm": lam_g,
		}
	m = re.match(
		r"^253-(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<size>\d{3})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m:
		lam = (m.group("lam") or "").strip().upper()
		lam_g = cint(_LAM_GSM_SUFFIX_MAP.get(lam, 0) or 0) if lam else 0
		return {
			"process": "253",
			"design_code": "",
			"quality_code": m.group("quality"),
			"colour_code": m.group("colour"),
			"gsm": cint(m.group("gsm") or 0),
			"series_id": m.group("size"),
			"lam_suffix": lam,
			"lam_gsm_code": lam,
			"lam_gsm": lam_g,
		}
	m2 = re.match(
		r"^(?P<design>[A-Z0-9]+)-253(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<size>\d{3})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m2:
		lam = (m2.group("lam") or "").strip().upper()
		lam_g = cint(_LAM_GSM_SUFFIX_MAP.get(lam, 0) or 0) if lam else 0
		return {
			"process": "253",
			"design_code": (m2.group("design") or "").strip(),
			"quality_code": m2.group("quality"),
			"colour_code": m2.group("colour"),
			"gsm": cint(m2.group("gsm") or 0),
			"series_id": m2.group("size"),
			"lam_suffix": lam,
			"lam_gsm_code": lam,
			"lam_gsm": lam_g,
		}
	return {}


def _parse_254_item_code(item_code):
	"""Laminated printed sheet (254): same 12-digit body as 253 after ``254``, optional lamination GSM suffix."""
	code = re.sub(r"\s+", "", str(item_code or "").strip().upper())
	if not code:
		return {}

	def _row(design, gd):
		lam = (gd.get("lam") or "").strip().upper()
		lam_g = cint(_LAM_GSM_SUFFIX_MAP.get(lam, 0) or 0) if lam else 0
		return {
			"process": "254",
			"design_code": design or "",
			"quality_code": gd.get("quality"),
			"colour_code": gd.get("colour"),
			"gsm": cint(gd.get("gsm") or 0),
			"series_id": gd.get("size"),
			"lam_suffix": lam,
			"lam_gsm_code": lam,
			"lam_gsm": lam_g,
		}

	m0 = re.match(
		r"^254(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<size>\d{3})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m0:
		return _row("", m0.groupdict())
	m = re.match(
		r"^254-(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<size>\d{3})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m:
		return _row("", m.groupdict())
	m2 = re.match(
		r"^(?P<design>[A-Z0-9]+)-254(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<size>\d{3})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m2:
		return _row((m2.group("design") or "").strip(), m2.groupdict())
	return {}


def _hyphen_trace_lam_suffix_segment(lam_code):
	"""Lamination tail for hyphenated traces; letter suffixes stay uppercase (e.g. ``…-A``)."""
	s = _cstr(lam_code).strip()
	if not s:
		return ""
	return s.upper() if s.isalpha() else s


def _hyphen_trace_from_laminated_sheet_parse(p, process_prefix):
	"""253/254: ``process-quality-colour-gsm-size[-lam]`` (optional ``design-`` prefix when parsed)."""
	if not p:
		return ""
	proc = _cstr(process_prefix).strip()
	if proc not in ("253", "254"):
		return ""
	dc = _cstr(p.get("design_code")).strip()
	qc = _cstr(p.get("quality_code")).strip()
	cc = _cstr(p.get("colour_code")).strip()
	gsm = _cstr(p.get("gsm") or "").strip()
	sid = _cstr(p.get("series_id")).strip()
	lc = _hyphen_trace_lam_suffix_segment(p.get("lam_suffix") or p.get("lam_gsm_code"))
	segs = [proc]
	if qc:
		segs.append(qc.zfill(3) if qc.isdigit() else qc)
	if cc:
		segs.append(cc.zfill(3) if cc.isdigit() else cc)
	if gsm:
		segs.append(str(gsm).zfill(3))
	if sid:
		segs.append(sid.zfill(3) if sid.isdigit() else sid)
	if lc:
		segs.append(lc)
	if len(segs) <= 1:
		return ""
	body = "-".join(segs)
	if dc:
		return f"{dc}-{body}"
	return body


def _trace_from_253_254_sales_order_fg_row(item_code, sales_order_item_name):
	"""BOM / board rows that are not the 253/254 FG on the same SO line share that FG's hyphenated trace."""
	soi = _cstr(sales_order_item_name).strip()
	ic = _cstr(item_code).strip()
	if not soi or not ic:
		return ""
	try:
		if not frappe.db.exists("Sales Order Item", soi):
			return ""
		soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
	except Exception:
		return ""
	if not soi_ic:
		return ""
	fg_pf = _item_process_prefix(soi_ic)
	if fg_pf not in ("252", "253", "254"):
		return ""
	if _item_process_prefix(ic) == fg_pf:
		return ""
	return _parent_child_trace_id_from_item_code(soi_ic) or ""


def _sheet_cutting_series_size_map(series_ids):
	"""Map series_id -> {'width_inch': float, 'height_inch': float, 'sheet_size': 'W*H'}."""
	ids = [str(x or "").strip() for x in (series_ids or []) if str(x or "").strip()]
	if not ids or not frappe.db.exists("DocType", "Sheet Cutting Series"):
		return {}
	meta = frappe.get_meta("Sheet Cutting Series")
	width_field = None
	height_field = None
	size_field = None
	for fn in ("width_in_inches", "custom_width_in_inches", "width", "sheet_width_inch"):
		if meta.has_field(fn):
			width_field = fn
			break
	for fn in ("height_in_inches", "custom_height_in_inches", "height", "sheet_height_inch"):
		if meta.has_field(fn):
			height_field = fn
			break
	for fn in ("size_in_inches", "custom_size_in_inches", "size"):
		if meta.has_field(fn):
			size_field = fn
			break
	series_id_fields = [fn for fn in ("series_id", "custom_series_id", "code", "series_code") if meta.has_field(fn)]
	read_fields = ["name"] + [f for f in (width_field, height_field, size_field) if f]
	for sf in series_id_fields:
		if sf not in read_fields:
			read_fields.append(sf)
	out = {}
	by_sid = {}
	by_name = {
		_cstr(r.get("name")): r
		for r in (frappe.get_all("Sheet Cutting Series", filters={"name": ["in", ids]}, fields=read_fields, limit_page_length=0) or [])
	}
	for sid in ids:
		row = by_name.get(sid)
		if not row and series_id_fields:
			for sf in series_id_fields:
				got = frappe.get_all(
					"Sheet Cutting Series",
					filters={sf: sid},
					fields=read_fields,
					limit_page_length=1,
				)
				if got:
					row = got[0]
					break
		if not row:
			continue
		w = flt(row.get(width_field)) if width_field else 0
		h = flt(row.get(height_field)) if height_field else 0
		sz = _cstr(row.get(size_field)) if size_field else ""
		if sz:
			sz = _normalize_sheet_size_str(sz)
		if not sz and w > 0 and h > 0:
			sz = _format_sheet_size_label(w, h, "")
		wr = float(int(round(w))) if w > 0 else 0.0
		hr = float(int(round(h))) if h > 0 else 0.0
		by_sid[sid] = {"width_inch": wr, "height_inch": hr, "sheet_size": sz}
	out.update(by_sid)
	return out


