def _trace_is_native_107_process(trace_id):
	"""True when trace is for process **107**, not a **108** parent chain (incl. design-prefixed ``6002-107-…``)."""
	t = _cstr(trace_id).strip()
	if not t:
		return False
	if t.startswith("107-"):
		return True
	return bool(re.search(r"(^|-)107(?:-|$)", t))


def _is_fabric_100_item_code(item_code):
	"""Non-woven / fabric BOM child rows (process 100 / ``100-…``), not FG codes like ``1000-…``."""
	ic = str(item_code or "").strip()
	if not ic:
		return False
	if _item_process_prefix(ic) == "100":
		return True
	if ic.startswith("100-"):
		return True
	# Compact fabric encoding (100 + quality + color + …); exclude process 1000/1001 prefixes.
	if ic.startswith("100") and not ic.startswith("1000") and len(ic) >= 9:
		return True
	return False


def _trace_is_native_100_process(trace_id):
	"""True when trace was derived from the fabric item code (``100-QQQ-CCC-GGG-WWWW``), not a parent FG."""
	t = _cstr(trace_id).strip()
	if not t:
		return False
	if t.startswith("100-"):
		return True
	digits = "".join(ch for ch in t if ch.isdigit())
	return bool(digits.startswith("100") and len(digits) >= 16)


def _trace_is_native_process_trace(trace_id, process_code):
	"""True when trace is the item's own process id (``104-…`` on a 104 row), not a parent FG chain."""
	t = _cstr(trace_id).strip()
	pc = _cstr(process_code).strip()
	if not t or not pc:
		return False
	if re.match(rf"^[A-Z0-9]+-{re.escape(pc)}-", t):
		return False
	if t.startswith(f"{pc}-"):
		return True
	return bool(re.search(rf"(^|-){re.escape(pc)}(?:-|$)", t))


def _fabric_row_has_stable_parent_trace(item_code, current_trace_id):
	"""Fabric ``100*`` row already linked to a parent-chain trace — do not replace on save/backfill."""
	if not _is_fabric_100_item_code(item_code):
		return False
	cur = _cstr(current_trace_id).strip()
	if not cur:
		return False
	if _trace_is_native_100_process(cur):
		return False
	for proc in ("104", "106", "107"):
		if _trace_is_native_process_trace(cur, proc):
			return False
	return True


def _should_preserve_trace_on_desk_save(item_code, current_trace_id, new_trace_id):
	"""Do not replace an existing parent-chain trace on incidental Planning sheet save."""
	cur = _cstr(current_trace_id).strip()
	new_tid = _cstr(new_trace_id).strip()
	if not new_tid:
		return False
	if not cur:
		return False
	if cur == new_tid:
		return True
	if _fabric_row_has_stable_parent_trace(item_code, cur):
		return True
	ic_pp = _item_process_prefix(item_code) or _lamination_process_from_item_code(item_code)
	if not ic_pp:
		return False
	# Never downgrade e.g. 6002-106-… → 104-105-… when user only changed unit/qty on save.
	if not _trace_is_native_process_trace(cur, ic_pp) and _trace_is_native_process_trace(new_tid, ic_pp):
		return True
	# Child already on FG chain; new id is a different native process only.
	for other_pp in ("104", "106", "107", "105", "108", "255"):
		if other_pp == ic_pp:
			continue
		if not _trace_is_native_process_trace(cur, other_pp) and _trace_is_native_process_trace(new_tid, ic_pp):
			if re.search(rf"(^|-){re.escape(other_pp)}(?:-|$)", cur):
				return True
	return False


def _should_apply_trace_to_row(item_code, current_trace_id, new_trace_id):
	"""Whether to write ``new_trace_id`` on this row (fabric rows keep stable parent traces)."""
	new_tid = _cstr(new_trace_id).strip()
	if not new_tid:
		return False
	if _should_preserve_trace_on_desk_save(item_code, current_trace_id, new_trace_id):
		return False
	cur = _cstr(current_trace_id).strip()
	ic_pp = _item_process_prefix(item_code) or _lamination_process_from_item_code(item_code)
	if not _is_fabric_100_item_code(item_code):
		if not cur:
			return True
		if cur == new_tid:
			return False
		if ic_pp == "251" and _trace_is_native_process_trace(cur, "252") and _trace_is_native_process_trace(new_tid, "251"):
			return True
		if ic_pp and _trace_is_native_process_trace(cur, ic_pp) and not _trace_is_native_process_trace(new_tid, ic_pp):
			return True
		return False
	if not cur:
		return True
	if cur == new_tid:
		return False
	if _trace_is_native_process_trace(cur, "252") and _trace_is_native_process_trace(new_tid, "251"):
		return True
	if _fabric_row_has_stable_parent_trace(item_code, cur):
		return False
	if _trace_is_native_100_process(cur) and not _trace_is_native_100_process(new_tid):
		return True
	return False


def _fabric_trace_sql_preserve_clause(column="custom_parent_child_trace_id"):
	"""SQL fragment: only touch fabric rows with empty or native-``100`` trace (keep parent-linked traces)."""
	col = column
	return f"""(
		IFNULL(TRIM({col}), '') = ''
		OR {col} LIKE '100-%%'
	)"""


def _trace_from_104_parse_body(p):
	"""Hyphenated 104 trace: ``{design}-104-{quality}-{colour}-{gsm}-{width}[-lam]``."""
	if not p:
		return ""
	dc = _cstr(p.get("design_code") or "").strip().upper()
	qc = _cstr(p.get("quality_code") or "").strip()
	cc = _cstr(p.get("colour_code") or "").strip()
	gsm = cint(p.get("gsm") or 0)
	wc = _cstr(p.get("width_code") or "").strip()
	lam = _cstr(p.get("lam_suffix") or p.get("lam_gsm_code") or "").strip().upper()
	if not (qc or cc or gsm or wc):
		return ""
	segs = ["104"]
	if qc:
		segs.append(str(qc).zfill(3) if str(qc).isdigit() else qc)
	if cc:
		segs.append(str(cc).zfill(3) if str(cc).isdigit() else cc)
	if gsm:
		segs.append(str(gsm).zfill(3))
	if wc:
		segs.append(str(wc).zfill(4))
	body = "-".join(segs)
	if lam:
		body = f"{body}-{lam}"
	if dc:
		return f"{dc}-{body}"
	return body


def _trace_from_106_parse_body(p, design_code=None):
	"""Hyphenated 106 trace: ``{design}-106-{quality}-{colour}-{gsm}-{width_mm}[-lam]``."""
	if not p:
		return ""
	dc = _cstr(design_code if design_code is not None else p.get("design_code")).strip()
	qc = _cstr(p.get("quality_code")).strip()
	cc = _cstr(p.get("colour_code")).strip()
	gsm = _cstr(p.get("gsm")).strip()
	wmm = _cstr(p.get("width_mm")).strip()
	lc = _cstr(p.get("lam_gsm_code")).strip()
	if not (qc or cc or gsm or wmm or lc):
		return ""
	segs = ["106"]
	if qc:
		segs.append(qc.zfill(3) if qc.isdigit() else qc)
	if cc:
		segs.append(cc.zfill(3) if cc.isdigit() else cc)
	if gsm:
		segs.append(str(gsm).zfill(3))
	if wmm:
		segs.append(str(wmm).zfill(4))
	if lc:
		segs.append(lc)
	if len(segs) <= 1:
		return ""
	body = "-".join(segs)
	if dc:
		return f"{dc}-{body}"
	return body


def _trace_from_sheet_cutting_fg_on_sales_order_line(sales_order_item, planning_sheet_name=None, pt_rows=None):
	"""FG sheet-cutting trace on the same SO line (252/253/254/255/251) for BOM children (105/100/104…)."""
	soi = _cstr(sales_order_item).strip()
	if not soi:
		return ""
	rows = pt_rows
	if rows is None and planning_sheet_name:
		rows = (
			frappe.get_all(
				"Planning Table",
				filters={"parent": planning_sheet_name},
				fields=["item_code", "sales_order_item", "so_item"],
				limit_page_length=2000,
			)
			or []
		)
	if not rows:
		return ""
	for pref in ("251", "252", "253", "254", "255"):
		for r in rows:
			ric = _cstr(r.get("item_code") if isinstance(r, dict) else getattr(r, "item_code", "")).strip()
			if _item_process_prefix(ric) != pref:
				continue
			rsoi = _cstr(
				(r.get("sales_order_item") if isinstance(r, dict) else getattr(r, "sales_order_item", None))
				or (r.get("so_item") if isinstance(r, dict) else getattr(r, "so_item", None))
			).strip()
			if rsoi != soi:
				continue
			if pref in ("253", "254"):
				pf = _parse_253_item_code(ric) if pref == "253" else _parse_254_item_code(ric)
				t = _hyphen_trace_from_laminated_sheet_parse(pf or {}, pref)
			elif pref == "251":
				t = _parent_child_trace_id_from_item_code(ric)
			elif pref == "252":
				t = _trace_from_252_parse_body(_parse_sheet_cutting_item_code(ric) or {})
			else:
				t = _hyphen_trace_from_255_parse(_parse_255_item_code(ric) or {})
			if t:
				return t
	return ""


def _no_of_sheets_from_sales_order_item(so_item_name):
	"""Planned sheet PCS from Sales Order Item (site may use different custom field names)."""
	soi = _cstr(so_item_name).strip()
	if not soi or not frappe.db.exists("Sales Order Item", soi):
		return 0
	for fld in (
		"custom_no_of_sheets_pcs",
		"custom_no_of_sheets",
		"no_of_sheets",
		"custom_total_no_of_sheets",
		"total_no_of_sheets",
		"custom_no_of_sheet",
		"no_of_sheet",
	):
		try:
			if frappe.db.has_column("Sales Order Item", fld):
				v = flt(frappe.db.get_value("Sales Order Item", soi, fld) or 0)
				if v > 0:
					return v
		except Exception:
			pass
	try:
		so_row = frappe.get_cached_doc("Sales Order Item", soi)
		for fld in (
			"custom_no_of_sheets_pcs",
			"custom_no_of_sheets",
			"no_of_sheets",
			"custom_total_no_of_sheets",
			"total_no_of_sheets",
		):
			v = flt(getattr(so_row, fld, None) or 0)
			if v > 0:
				return v
	except Exception:
		pass
	return 0


def _trace_from_255_parent_on_sales_order_line(sales_order_item, planning_sheet_name=None, pt_rows=None):
	"""255 parent trace on the same SO line (e.g. ``6002-255-F-101-100-002``) for 107/100/PB children."""
