def _quality_name_from_master(q_code):
	"""Resolve Quality Master document name from a 3-digit quality code (e.g. 127 → HARINI BAGS - GOLD)."""
	qc = _cstr(q_code).strip()
	if not qc:
		return ""
	try:
		from production_entry.production_planning.doctype.planning_sheet.planning_sheet import (
			_quality_name_by_code,
		)

		qn = _quality_name_by_code(qc)
		if qn:
			return _cstr(qn).strip().upper()
	except Exception:
		pass
	for qc_try in _quality_code_lookup_candidates_py(qc):
		try:
			if frappe.db.exists("Quality Master", qc_try):
				return _cstr(qc_try).strip().upper()
		except Exception:
			pass
		for fld in ("custom_quality_code", "quality_code", "short_code", "code"):
			try:
				if not frappe.db.has_column("Quality Master", fld):
					continue
				qual_name = frappe.db.get_value("Quality Master", {fld: qc_try}, "name")
				if qual_name:
					return _cstr(qual_name).strip().upper()
			except Exception:
				pass
	return ""


def _quality_code_lookup_candidates_py(q_code):
	q = _cstr(q_code).strip()
	if not q:
		return []
	out = []
	seen = set()
	for v in (
		q,
		q.lstrip("0") or "0",
		q.zfill(2),
		q.zfill(3),
		(q.lstrip("0") or "0").zfill(2),
		(q.lstrip("0") or "0").zfill(3),
	):
		if v and v not in seen:
			seen.add(v)
			out.append(v)
	return out


def _width_inch_from_105_item_code(item_code):
	"""Roll width in inches from process 105 item code (last 4 digits = mm)."""
	p = _parse_105_item_code(item_code) or {}
	wmm = cint(p.get("width_mm") or 0)
	if wmm > 0:
		return round(wmm / 25.4)
	return 0.0


def _is_design_first_hyphen_item_code(item_code):
	"""True when item code uses design-first layout (6002-252… / 6002-105…); legacy digit[9:12] GSM is wrong."""
	ic = _cstr(item_code).strip().upper()
	if "-" not in ic:
		return False
	pp = _item_process_prefix(ic)
	if pp in ("251", "252", "253", "254", "255", "105", "106"):
		return True
	if _lamination_process_from_item_code(ic) in ("104", "107", "255"):
		return True
	if _is_printing_105_parent_process(ic):
		return True
	return False


def _sync_sheet_cutting_no_of_sheets_from_so(planning_sheet_name):
	"""Copy planned sheet PCS from Sales Order Item onto all sheet-cutting FG rows (251–255)."""
	if not planning_sheet_name:
		return
	if not frappe.db.has_column("Planning Table", "custom_no_of_sheets"):
		return
	rows = (
		frappe.get_all(
			"Planning Table",
			filters={"parent": planning_sheet_name},
			fields=["name", "item_code", "sales_order_item", "so_item", "source_item"],
			limit_page_length=2000,
		)
		or []
	)
	for r in rows:
		ic = _cstr(r.get("item_code")).strip()
		pp = _item_process_prefix(ic)
		if pp not in ("251", "252", "253", "254", "255") and _lamination_process_from_item_code(ic) != "255":
			continue
		soik = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		nos = _no_of_sheets_from_sales_order_item(soik)
		if nos <= 0:
			continue
		frappe.db.set_value("Planning Table", r.get("name"), "custom_no_of_sheets", nos, update_modified=False)
		legacy = _cstr(r.get("source_item"))
		if legacy and frappe.db.exists("Planning sheet Item", legacy):
			if frappe.db.has_column("Planning sheet Item", "custom_no_of_sheets"):
				frappe.db.set_value("Planning sheet Item", legacy, "custom_no_of_sheets", nos, update_modified=False)


def _sync_252_roll_width_from_105_child(planning_sheet_name):
	"""Process 252 FG: roll width = BOM printing child (105) on the same SO line, not sheet-series width."""
	if not planning_sheet_name:
		return
	if not frappe.db.has_column("Planning Table", "width_inch"):
		return
	rows = (
		frappe.get_all(
			"Planning Table",
			filters={"parent": planning_sheet_name},
			fields=["name", "item_code", "sales_order_item", "so_item", "source_item"],
			limit_page_length=2000,
		)
		or []
	)
	if not rows:
		return
	w_by_soi = {}
	for r in rows:
		ic = _cstr(r.get("item_code")).strip()
		if _item_process_prefix(ic) != "105" and not _is_printing_105_parent_process(ic):
			continue
		soik = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		if not soik:
			continue
		w = _width_inch_from_105_item_code(ic)
		if w > 0:
			w_by_soi[soik] = w
	if not w_by_soi:
		return
	for r in rows:
		ic = _cstr(r.get("item_code")).strip()
		if _item_process_prefix(ic) != "252":
			continue
		soik = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		w = flt(w_by_soi.get(soik) or 0)
		if w <= 0:
			continue
		frappe.db.set_value("Planning Table", r.get("name"), "width_inch", w, update_modified=False)
		legacy = _cstr(r.get("source_item"))
		if legacy and frappe.db.exists("Planning sheet Item", legacy):
			if frappe.db.has_column("Planning sheet Item", "width_inch"):
				frappe.db.set_value("Planning sheet Item", legacy, "width_inch", w, update_modified=False)


def _box_bag_line_specs_from_item_code(item_code):
	"""Quality, colour, and total GSM from box/d-cut item codes."""
	ic = _cstr(item_code).strip()
	pp = _item_process_prefix(ic)
	if pp not in BOX_BAG_PROCESS_CODES and pp not in W_CUT_D_CUT_FG_PROCESS_CODES:
		return None
	try:
		if pp in BOPP_BOX_BAG_PROCESS_CODES:
			from production_entry.production_planning.bopp_bag_api import _parse_bopp_bag_item_code
			p = _parse_bopp_bag_item_code(ic) or {}
		elif pp in W_CUT_D_CUT_FG_PROCESS_CODES:
			from production_entry.production_planning.box_bag_api import _parse_dcut_bag_item_code
			p = _parse_dcut_bag_item_code(ic) or {}
		else:
			from production_entry.production_planning.box_bag_api import _parse_box_bag_item_code
			p = _parse_box_bag_item_code(ic) or {}
	except Exception:
		return None
	qc = _cstr(p.get("quality_letter")).strip().upper()
	quality = _cstr(_LAMINATION_QUALITY_BY_CODE.get(qc, "") or "").strip().upper() or qc
	color = ""
	cc = _cstr(p.get("colour_code")).strip()
	if cc:
		try:
			color = (_get_color_by_code(cc) or "").strip().upper()
		except Exception:
			color = ""
	gsm = cint(p.get("total_gsm") or 0)
	return {"quality": quality, "color": color, "gsm": gsm, "parsed": p}


def resolve_quality_color_gsm_from_item_code(item_code, item_name=None):
	"""Quality, colour name, and GSM for planning / SPR rows (255, 107, 104, legacy numeric, PB)."""
	ic = _cstr(item_code).strip()
	nm = _cstr(item_name).strip()
	if not ic:
		return "", "", 0
	quality = ""
	color = ""
	gsm = 0
	pp = _item_process_prefix(ic)
	lam = _lamination_process_from_item_code(ic)
	if lam == "255" or pp == "255":
		p = _parse_255_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip().upper()
		quality = _cstr(p.get("quality_name") or "").strip().upper()
		if not quality and qc:
			quality = _cstr(_LAMINATION_QUALITY_BY_CODE.get(qc, "") or "").strip().upper()
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(_combined_bopp_line_gsm(p) or 0) or cint(p.get("fabric_gsm") or 0)
		return quality, color, gsm
	if lam == "107" or pp == "107":
		p = _parse_107_item_code(ic) or {}
		quality = _cstr(p.get("quality_name") or "").strip().upper()
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(_combined_bopp_line_gsm(p) or 0) or cint(p.get("fabric_gsm") or 0)
		return quality, color, gsm
	if pp == "106" or "-106" in ic.upper():
		p = _parse_106_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip()
		quality = _quality_name_from_master(qc) or qc
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(p.get("gsm") or 0)
		return _cstr(quality).strip().upper(), _cstr(color).strip().upper(), gsm
	if pp == "109":
		p = _parse_109_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip()
		quality = _quality_name_from_master(qc) or qc
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(p.get("gsm") or 0) or cint(_gsm_from_lamination_item_code(ic) or 0)
		return _cstr(quality).strip().upper(), _cstr(color).strip().upper(), gsm
	if pp == "108":
		p = _parse_108_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip().upper()
		quality = _cstr(p.get("quality_name") or _LAMINATION_QUALITY_BY_CODE.get(qc, "") or "").strip().upper()
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(_combined_bopp_line_gsm(p) or 0) or cint(p.get("fabric_gsm") or 0)
		return quality, color, gsm
	if pp == "110":
		p = _parse_110_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip().upper()
		quality = _cstr(p.get("quality_name") or _LAMINATION_QUALITY_BY_CODE.get(qc, "") or "").strip().upper()
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(_combined_bopp_line_gsm(p) or 0) or cint(p.get("fabric_gsm") or 0)
		return quality, color, gsm
	if lam == "104" or pp == "104":
		p = _parse_104_item_code(ic) or {}
		gsm = cint(p.get("gsm") or 0) or cint(_gsm_from_lamination_item_code(ic) or 0)
		qc = _cstr(p.get("quality_code") or "").strip()
		quality = _quality_name_from_master(qc) or qc
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		return _cstr(quality).strip().upper(), _cstr(color).strip().upper(), gsm
	if pp == "105" or _is_printing_105_parent_process(ic):
		p = _parse_105_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip()
		quality = _quality_name_from_master(qc) or qc
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(p.get("gsm") or 0)
		if gsm:
			return _cstr(quality).strip().upper(), _cstr(color).strip().upper(), gsm
	if pp in ("251", "252", "253", "254"):
		if pp in ("253", "254"):
			p = (_parse_253_item_code(ic) if pp == "253" else _parse_254_item_code(ic)) or {}
		else:
			p = _parse_sheet_cutting_item_code(ic) or {}
		qc = _cstr(p.get("quality_code") or "").strip()
		quality = _quality_name_from_master(qc) or qc
		cc = _cstr(p.get("colour_code") or "").strip()
		if cc:
			try:
				color = (_get_color_by_code(cc) or "").strip().upper()
			except Exception:
				color = ""
		gsm = cint(p.get("gsm") or 0)
		if gsm:
			return _cstr(quality).strip().upper(), _cstr(color).strip().upper(), gsm
	box_specs = _box_bag_line_specs_from_item_code(ic)
	if box_specs:
		return box_specs["quality"], box_specs["color"], box_specs["gsm"]
	# Legacy numeric + item-name fallback (planning_sheet.extract_quality_and_color)
	try:
		from production_entry.production_planning.doctype.planning_sheet.planning_sheet import (
			extract_quality_and_color,
		)

		quality, color = extract_quality_and_color(nm or frappe.db.get_value("Item", ic, "item_name") or "", item_code=ic)
	except Exception:
		quality, color = "", ""
	if not gsm and not _is_design_first_hyphen_item_code(ic):
		digits = "".join(ch for ch in ic if ch.isdigit())
		if len(digits) >= 12:
			try:
				gsm = cint(digits[9:12])
			except Exception:
				gsm = 0
	return _cstr(quality).strip().upper(), _cstr(color).strip().upper(), cint(gsm or 0)


def _is_sheet_cutting_fg_item_code(item_code) -> bool:
	"""True for FG sheet-cutting processes 251–255 (incl. design-first 255)."""
	ic = _cstr(item_code).strip().upper()
	if not ic:
		return False
	pp = _item_process_prefix(ic)
	if pp in ("251", "252", "253", "254", "255"):
		return True
	return _lamination_process_from_item_code(ic) == "255"


def _parse_any_sheet_cutting_item_code(item_code):
	"""Unified parse for 251/252/253/254/255 — includes ``series_id`` (3-digit size code) like 251."""
	ic = _cstr(item_code).strip().upper()
	if not ic:
		return {}
	pp = _item_process_prefix(ic)
	if pp in ("251", "252"):
		return _parse_sheet_cutting_item_code(ic) or {}
	if pp == "253":
		return _parse_253_item_code(ic) or {}
	if pp == "254":
		return _parse_254_item_code(ic) or {}
	if pp == "255" or _lamination_process_from_item_code(ic) == "255":
		p = dict(_parse_255_item_code(ic) or {})
		if not _cstr(p.get("series_id")).strip():
			wc = _cstr(p.get("width_code")).strip()
			if wc.isdigit() and len(wc) == 3:
				p["series_id"] = wc.zfill(3)
		return p
	return {}


def _sheet_cutting_series_id_from_item_code(item_code) -> str:
	"""3-digit Sheet Cutting Series code from item (e.g. 255 …LAC**002**0G → ``002``)."""
	p = _parse_any_sheet_cutting_item_code(item_code)
	sid = _cstr(p.get("series_id")).strip()
	if sid.isdigit():
		return sid.zfill(3)[-3:]
	wc = _cstr(p.get("width_code")).strip()
	if wc.isdigit() and len(wc) == 3:
		return wc.zfill(3)
	return ""


def _sheet_dimensions_from_series_id(series_id):
	"""Lookup width, height, and display sheet size from Sheet Cutting Series master."""
	sid = _cstr(series_id).strip()
	if not sid:
		return {"series_id": "", "width_inch": 0.0, "height_inch": 0.0, "sheet_size": ""}
	if sid.isdigit():
		sid = sid.zfill(3)[-3:]
	info = (_sheet_cutting_series_size_map([sid]) or {}).get(sid) or {}
	w = flt(info.get("width_inch") or 0)
	h = flt(info.get("height_inch") or 0)
	sz = _cstr(info.get("sheet_size") or "")
	if sz:
		sz = _normalize_sheet_size_str(sz)
	elif w > 0 and h > 0:
		sz = _format_sheet_size_label(w, h, "")
	return {"series_id": sid, "width_inch": w, "height_inch": h, "sheet_size": sz}


def _sheet_dimensions_from_item_code(item_code):
	"""
	Sheet size for all sheet-cutting FG (251–255): always from item-code size segment → Sheet Cutting Series.
	Same rule as 251 (PPP|QQQ|CCC|GGG|**SSS**). For 255: letters after lam GSM, then 3-digit size code (e.g. 002).
	"""
	ic = _cstr(item_code).strip()
	if not ic or not _is_sheet_cutting_fg_item_code(ic):
		return {"series_id": "", "width_inch": 0.0, "height_inch": 0.0, "sheet_size": ""}
	sid = _sheet_cutting_series_id_from_item_code(ic)
	if sid:
		out = _sheet_dimensions_from_series_id(sid)
		if out.get("sheet_size") or flt(out.get("width_inch")) > 0:
			return out
	# Last resort only when series master row is missing
	sz = ""
	h = 0.0
	if frappe.db.has_column("Item", "custom_sheet_size"):
		sz = _normalize_sheet_size_str(frappe.db.get_value("Item", ic, "custom_sheet_size") or "")
	w = 0.0
	if sz:
		aw, ah = _parse_two_dim_sheet_size(sz)
		if aw > 0:
			w = aw
		h = flt(ah or 0)
	return {"series_id": sid, "width_inch": w, "height_inch": h, "sheet_size": sz}


def _sheet_size_for_item_code(item_code, width_inch=0):
	"""Sheet size + width for sheet-cutting items via Sheet Cutting Series; else empty."""
	dims = _sheet_dimensions_from_item_code(item_code)
	sz = _cstr(dims.get("sheet_size"))
	w = flt(dims.get("width_inch") or 0)
	if w <= 0:
		w = flt(width_inch or 0)
	return sz, w


def _stamp_sheet_cutting_size_on_planning_dict(row_dict, item_code):
	"""Set ``sheet_size`` and ``width_inch`` on a planning row dict from item code → Sheet Cutting Series."""
	if not row_dict or not _is_sheet_cutting_fg_item_code(item_code):
		return
	dims = _sheet_dimensions_from_item_code(item_code)
	sz = _cstr(dims.get("sheet_size") or "")
	if sz and frappe.db.has_column("Planning Table", "sheet_size"):
		row_dict["sheet_size"] = _normalize_sheet_size_str(sz)
	# Sheet-cutting FG: sheet_size from series; roll width comes from BOM fabric (100/105/104/107), not series width.
	return


def enrich_planning_child_row_from_item_code(row, planning_sheet_name=None):
	"""Desk save: fill quality/colour/GSM, sheet size, trace id, PB design fields from item_code."""
	if not row:
		return
	ic = _cstr(getattr(row, "item_code", None) or "").strip()
	if not ic:
		return
	soi = _cstr(getattr(row, "sales_order_item", None) or getattr(row, "so_item", None) or "").strip()
	item_name = _cstr(getattr(row, "item_name", None) or frappe.db.get_value("Item", ic, "item_name") or "")
	q, c, g = resolve_quality_color_gsm_from_item_code(ic, item_name)
	if q:
		if hasattr(row, "quality"):
			row.quality = q
		if hasattr(row, "custom_quality"):
			row.custom_quality = q
	if c and hasattr(row, "color"):
		row.color = c
	if g and hasattr(row, "gsm"):
		row.gsm = g
	w = flt(getattr(row, "width_inch", 0) or 0)
	sz, w2 = _sheet_size_for_item_code(ic, w)
	if _is_sheet_cutting_fg_item_code(ic):
		if sz and hasattr(row, "sheet_size"):
			row.sheet_size = sz
	elif w2 > 0 and hasattr(row, "width_inch"):
		row.width_inch = w2
		if sz and hasattr(row, "sheet_size"):
			row.sheet_size = sz
	elif sz and hasattr(row, "sheet_size"):
		row.sheet_size = sz
	pp = _item_process_prefix(ic)
	if pp in ("251", "252", "105") or _is_printing_105_parent_process(ic):
		p_sc = _parse_sheet_cutting_item_code(ic) if pp in ("251", "252") else (_parse_105_item_code(ic) or {})
		dc = _cstr((p_sc or {}).get("design_code") or "").strip()
		if dc and hasattr(row, "custom_design_code"):
			row.custom_design_code = dc
		for _kdm, _vdm in (_design_master_extra_fields(dc) or {}).items():
			if not _vdm or not str(_vdm).strip():
				continue
			if hasattr(row, _kdm) and not _cstr(getattr(row, _kdm, None)).strip():
				setattr(row, _kdm, _vdm)
	if pp == "252" and planning_sheet_name and hasattr(row, "width_inch"):
		soik = _cstr(getattr(row, "sales_order_item", None) or getattr(row, "so_item", None) or "").strip()
		if soik:
			for sib in (
				frappe.get_all(
					"Planning Table",
					filters={"parent": planning_sheet_name, "sales_order_item": soik},
					fields=["item_code"],
					limit_page_length=20,
				)
				or []
			):
				sic = _cstr(sib.get("item_code")).strip()
				if _item_process_prefix(sic) != "105" and not _is_printing_105_parent_process(sic):
					continue
				w105 = _width_inch_from_105_item_code(sic)
				if w105 > 0:
					row.width_inch = w105
					break
	if pp in BOX_BAG_PROCESS_CODES or pp in W_CUT_D_CUT_FG_PROCESS_CODES:
		from production_entry.production_planning.box_bag_api import _bag_series_size_map
		if pp in BOPP_BOX_BAG_PROCESS_CODES:
			from production_entry.production_planning.bopp_bag_api import _parse_bopp_bag_item_code
			p = _parse_bopp_bag_item_code(ic)
		elif pp in W_CUT_D_CUT_FG_PROCESS_CODES:
			from production_entry.production_planning.box_bag_api import _parse_dcut_bag_item_code
			p = _parse_dcut_bag_item_code(ic)
		else:
			from production_entry.production_planning.box_bag_api import _parse_box_bag_item_code
			p = _parse_box_bag_item_code(ic)
		box_specs = _box_bag_line_specs_from_item_code(ic)
		if box_specs:
			if box_specs.get("quality") and hasattr(row, "quality"):
				row.quality = box_specs["quality"]
			if box_specs.get("quality") and hasattr(row, "custom_quality"):
				row.custom_quality = box_specs["quality"]
			if box_specs.get("color") and hasattr(row, "color"):
				row.color = box_specs["color"]
			if cint(box_specs.get("gsm") or 0) and hasattr(row, "gsm"):
				row.gsm = cint(box_specs["gsm"])
		bs_id = p.get("bag_size_id")
		if bs_id and hasattr(row, "bag_size"):
			bsm = _bag_series_size_map()
			sz = bsm.get(bs_id)
			if sz:
				row.bag_size = sz
			else:
				row.bag_size = bs_id
		if p.get("finishing_label") and hasattr(row, "custom_finishing"):
			row.custom_finishing = p.get("finishing_label")
		if p.get("lam_gsm") and hasattr(row, "custom_lam_gsm"):
			row.custom_lam_gsm = cint(p.get("lam_gsm") or 0)
		if p.get("bopp_gsm") and hasattr(row, "custom_bopp_gsm"):
			row.custom_bopp_gsm = cint(p.get("bopp_gsm") or 0)
		dc = _cstr(p.get("design_code") or "").strip()
		if dc and hasattr(row, "custom_design_code"):
			row.custom_design_code = dc
		for _kdm, _vdm in (_design_master_extra_fields(dc) or {}).items():
			if not _vdm or not str(_vdm).strip():
				continue
			if hasattr(row, _kdm) and not _cstr(getattr(row, _kdm, None)).strip():
				setattr(row, _kdm, _vdm)

	if pp == "255" or _lamination_process_from_item_code(ic) == "255":
		extras = _planning_row_dict_255_lamination_extras(ic, None, soi) or {}
		for k, v in (extras or {}).items():
			if v is None:
				continue
			try:
				setattr(row, k, v)
			except Exception:
				pass
	if _matches_printed_bopp_board_row(row):
		_apply_printed_bopp_planning_fields_to_row(row, ic)
		dc = _design_code_from_printed_bopp_item_code(ic) or _pb_design_code_from_sales_order_item(soi)
		if dc and hasattr(row, "custom_design_code") and not _cstr(getattr(row, "custom_design_code", None)).strip():
			row.custom_design_code = dc
		dn = _printing_design_name_from_row(row, dc, soi) or _pb_design_name_from_sales_order_item(soi)
		if dn and hasattr(row, "custom_design_name"):
			row.custom_design_name = dn
		da = _printing_design_attachment_from_row(row, soi)
		if da and hasattr(row, "custom_design_attachment"):
			row.custom_design_attachment = da
	tid = _parent_child_trace_id_for_planning_row(ic, soi or None, planning_sheet_name)
	if tid:
		cur_tid = _cstr(getattr(row, "custom_parent_child_trace_id", None)).strip()
		if _is_fabric_100_item_code(ic) and _fabric_row_has_stable_parent_trace(ic, cur_tid):
			return
		pp = _item_process_prefix(ic)
		lam = _lamination_process_from_item_code(ic)
		force = (
			not cur_tid
			or lam == "255"
			or pp == "255"
			or lam == "107"
			or pp == "107"
			or pp == "109"
			or pp == "104"
			or lam == "104"
			or _is_sheet_cutting_parent_process(ic)
			or _is_sheet_cutting_child_process(ic)
			or (cur_tid and tid and cur_tid != tid)
		)
		if force or cur_tid != tid:
			_set_trace_id_if_supported(row, tid, item_code=ic)


def _sync_planning_row_quality_specs(planning_sheet_name):
	"""Fill missing quality / colour / GSM on board + legacy rows from item_code (create / regenerate / update)."""
	if not planning_sheet_name:
		return
	for table in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.exists("DocType", table):
			continue
		fields = ["name", "item_code", "item_name"]
		for col in ("quality", "custom_quality", "color", "gsm"):
			if frappe.db.has_column(table, col):
				fields.append(col)
		rows = (
			frappe.get_all(
				table,
				filters={"parent": planning_sheet_name},
				fields=fields,
				limit_page_length=2000,
			)
			or []
		)
		for r in rows:
			ic = _cstr(r.get("item_code")).strip()
			if not ic:
				continue
			inm = _cstr(r.get("item_name") or frappe.db.get_value("Item", ic, "item_name") or "")
			q, c, g = resolve_quality_color_gsm_from_item_code(ic, inm)
			up = {}
			cq = _cstr(r.get("custom_quality") or r.get("quality")).strip()
			if q and not cq:
				if frappe.db.has_column(table, "custom_quality"):
					up["custom_quality"] = q
				if frappe.db.has_column(table, "quality"):
					up["quality"] = q
			cc = _cstr(r.get("color")).strip()
			if c and not cc and frappe.db.has_column(table, "color"):
				up["color"] = c
			if g and frappe.db.has_column(table, "gsm"):
				cur_gsm = cint(r.get("gsm") or 0)
				if not cur_gsm or (_item_process_prefix(ic) in BOX_BAG_PROCESS_CODES and cur_gsm != g):
					up["gsm"] = g
			if up:
				frappe.db.set_value(table, r.get("name"), up, update_modified=False)


def _decoded_width_inch_for_planning_item(item_code, item_name="", db_width=0):
	"""Roll width from item-code parsers; falls back to name/text helpers."""
	w = flt(db_width or 0)
	if w > 0:
		return w
	ic = _cstr(item_code).strip()
	inm = _cstr(item_name).strip()
	if not ic:
		return 0
	pp = _bom_item_process_code(ic) or _item_process_prefix(ic)
	if pp in ("108", "110"):
		parsed = (_parse_110_item_code(ic) if pp == "110" else _parse_108_item_code(ic)) or {}
		w = flt(parsed.get("width_inch") or 0)
		if w > 0:
			rw = round(w, 1)
			return float(int(rw)) if abs(rw - round(rw)) < 1e-9 else rw
	return _resolve_planning_row_width_inch(ic, 0, inm)


def _sync_planning_row_width_specs(planning_sheet_name):
	"""Backfill missing width_inch on board + legacy rows from item-code decoders."""
	if not planning_sheet_name:
		return
	for table in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.exists("DocType", table):
			continue
		if not frappe.db.has_column(table, "width_inch"):
			continue
		fields = ["name", "item_code", "item_name", "width_inch"]
		rows = (
			frappe.get_all(
				table,
				filters={"parent": planning_sheet_name},
				fields=fields,
				limit_page_length=2000,
			)
			or []
		)
		for r in rows:
			ic = _cstr(r.get("item_code")).strip()
			if not ic or flt(r.get("width_inch") or 0) > 0:
				continue
			w = _decoded_width_inch_for_planning_item(ic, r.get("item_name") or "")
			if w <= 0:
				continue
			frappe.db.set_value(table, r.get("name"), "width_inch", w, update_modified=False)


def _patch_bag_fg_bom_child_row_specs(planning_sheet_name, pt_name, child_ic, child_pp, so_it=None):
	"""Update an existing planning row when BOM sync skipped insert (missing width/specs)."""
	if not pt_name or not child_ic:
		return
	specs = _bag_fg_bom_child_row_specs(child_ic, child_pp, so_it)
	up = {}
	for fld in ("gsm", "width_inch", "color", "quality", "custom_quality"):
		if specs.get(fld) is not None and frappe.db.has_column("Planning Table", fld):
			cur = frappe.db.get_value("Planning Table", pt_name, fld)
			if fld == "width_inch" and flt(cur or 0) > 0:
				continue
			if fld in ("gsm",) and cint(cur or 0) > 0 and fld == "gsm":
				continue
			if fld in ("color", "quality", "custom_quality") and _cstr(cur).strip():
				continue
			up[fld] = specs[fld]
	for fld in ("custom_fabric_gsm", "custom_lam_gsm", "custom_bopp_gsm"):
		if specs.get(fld) is not None and frappe.db.has_column("Planning Table", fld):
			if cint(frappe.db.get_value("Planning Table", pt_name, fld) or 0) > 0:
				continue
			up[fld] = specs[fld]
	if not up:
		return
	frappe.db.set_value("Planning Table", pt_name, up, update_modified=False)
	src = frappe.db.get_value("Planning Table", pt_name, "source_item")
	if src and frappe.db.exists("Planning sheet Item", src):
		psi_up = {k: v for k, v in up.items() if frappe.db.has_column("Planning sheet Item", k)}
		if psi_up:
			frappe.db.set_value("Planning sheet Item", src, psi_up, update_modified=False)


def _parse_108_item_code(item_code):
	"""
	Slitting FG process **108** — design-first BOPP laminated slitted NW fabric.
	Tail order after ``108``: quality letter, 3-digit colour, fabric letter, lam letter, BOPP letter,
	then width (4 digits = mm with optional ``MM`` suffix, or 3 digits = legacy tenths-of-inch like 107),
	optional finish tokens.
	"""
	code = re.sub(r"\s+", "", str(item_code or "").strip().upper())
	if not code:
		return {}

	def _row_mm(design, gd):
		width_code = gd.get("width") or ""
		width_mm = cint(width_code) if width_code.isdigit() else 0
		width_inch = flt(width_mm) / 25.4 if width_mm else 0.0
		qc = (gd.get("quality") or "").strip().upper()
		lam_letter = (gd.get("lam") or "").strip().upper()
		lam_val = cint(_LAM_GSM_SUFFIX_MAP.get(lam_letter, 0) or 0)
		return {
			"design_code": design or "",
			"process": "108",
			"quality_code": qc,
			"quality_name": _LAMINATION_QUALITY_BY_CODE.get(qc, ""),
			"colour_code": gd.get("colour") or "",
			"fabric_gsm_code": (gd.get("fabric") or "").strip().upper(),
			"fabric_gsm": cint(_LAMINATION_FABRIC_GSM_BY_CODE.get((gd.get("fabric") or "").strip().upper(), "") or 0),
			"bopp_gsm_code": (gd.get("bopp") or "").strip().upper(),
			"bopp_gsm": cint(_LAMINATION_BOPP_GSM_BY_CODE.get((gd.get("bopp") or "").strip().upper(), "") or 0),
			"lam_gsm_code": lam_letter,
			"lam_gsm": lam_val,
			"width_code": width_code,
			"width_mm": width_mm,
			"width_inch": width_inch,
			"finish_matte_glossy": (gd.get("finish1") or "").strip() or "0",
			"finish_metallic_cooler": (gd.get("finish2") or "").strip() or "0",
		}

	def _row_inch3(design, gd):
		width_code = gd.get("width") or ""
		width_inch = flt(width_code) / 10.0 if width_code.isdigit() and len(width_code) == 3 else 0.0
		width_mm = cint(round(width_inch * 25.4)) if width_inch else 0
		qc = (gd.get("quality") or "").strip().upper()
		lam_letter = (gd.get("lam") or "").strip().upper()
		lam_val = cint(_LAM_GSM_SUFFIX_MAP.get(lam_letter, 0) or 0)
		return {
			"design_code": design or "",
			"process": "108",
			"quality_code": qc,
			"quality_name": _LAMINATION_QUALITY_BY_CODE.get(qc, ""),
			"colour_code": gd.get("colour") or "",
			"fabric_gsm_code": (gd.get("fabric") or "").strip().upper(),
			"fabric_gsm": cint(_LAMINATION_FABRIC_GSM_BY_CODE.get((gd.get("fabric") or "").strip().upper(), "") or 0),
			"bopp_gsm_code": (gd.get("bopp") or "").strip().upper(),
			"bopp_gsm": cint(_LAMINATION_BOPP_GSM_BY_CODE.get((gd.get("bopp") or "").strip().upper(), "") or 0),
			"lam_gsm_code": lam_letter,
			"lam_gsm": lam_val,
			"width_code": width_code,
			"width_mm": width_mm,
			"width_inch": width_inch,
			"finish_matte_glossy": (gd.get("finish1") or "").strip() or "0",
			"finish_metallic_cooler": (gd.get("finish2") or "").strip() or "0",
		}

	m = re.match(
		r"^(?P<design>[A-Z0-9]+)-108(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})MM$",
		code,
	)
	if m:
		return _row_mm(m.group("design"), m.groupdict())
	mw = re.match(
		r"^(?P<design>[A-Z0-9]+)-108(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})(?P<finish1>[A-Z0-9])(?P<finish2>[A-Z0-9])$",
		code,
	)
	if mw:
		return _row_mm(mw.group("design"), mw.groupdict())
	m3 = re.match(
		r"^(?P<design>[A-Z0-9]+)-108(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{3})(?P<finish1>\d)(?P<finish2>\d)$",
		code,
	)
	if m3:
		return _row_inch3(m3.group("design"), m3.groupdict())
	m2 = re.match(r"^(?P<design>[A-Z0-9]+)-108(?P<body>\d+)$", code)
	if m2:
		return {
			"design_code": m2.group("design") or "",
			"process": "108",
			"quality_code": "",
			"quality_name": "",
			"colour_code": "",
			"fabric_gsm_code": "",
			"fabric_gsm": 0,
			"bopp_gsm_code": "",
			"bopp_gsm": 0,
			"lam_gsm_code": "",
			"lam_gsm": 0,
			"width_code": "",
			"width_mm": 0,
			"width_inch": 0.0,
			"finish_matte_glossy": "0",
			"finish_metallic_cooler": "0",
		}
	pos = code.find("-108")
	if pos > 0:
		design = re.sub(r"[^A-Z0-9]", "", code[:pos])
		tail = code[pos + 4 :]
		m4 = re.match(
			r"^(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})MM$",
			tail,
		)
		if m4 and design:
			return _row_mm(design, m4.groupdict())
		m5 = re.match(
			r"^(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})(?P<finish1>[A-Z0-9])(?P<finish2>[A-Z0-9])$",
			tail,
		)
		if m5 and design:
			return _row_mm(design, m5.groupdict())
		m6 = re.match(
			r"^(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{3})(?P<finish1>\d)(?P<finish2>\d)$",
			tail,
		)
		if m6 and design:
			return _row_inch3(design, m6.groupdict())
	return {}


def _parse_110_item_code(item_code):
	"""
	Slitting FG process **110** — BOPP metallic loop handle fabric (same tail structure as 108).
	Tail order after ``110``: quality letter, 3-digit colour, fabric letter, lam letter, BOPP letter,
	then width (4 digits mm with optional MM suffix, or 3-digit legacy inch*10), optional finish tokens.
	"""
	code = re.sub(r"\s+", "", str(item_code or "").strip().upper())
	if not code:
		return {}

	def _row_mm(design, gd):
		width_code = gd.get("width") or ""
		width_mm = cint(width_code) if width_code.isdigit() else 0
		width_inch = flt(width_mm) / 25.4 if width_mm else 0.0
		qc = (gd.get("quality") or "").strip().upper()
		lam_letter = (gd.get("lam") or "").strip().upper()
		lam_val = cint(_LAM_GSM_SUFFIX_MAP.get(lam_letter, 0) or 0)
		return {
			"design_code": design or "",
			"process": "110",
			"quality_code": qc,
			"quality_name": _LAMINATION_QUALITY_BY_CODE.get(qc, ""),
			"colour_code": gd.get("colour") or "",
			"fabric_gsm_code": (gd.get("fabric") or "").strip().upper(),
			"fabric_gsm": cint(_LAMINATION_FABRIC_GSM_BY_CODE.get((gd.get("fabric") or "").strip().upper(), "") or 0),
			"bopp_gsm_code": (gd.get("bopp") or "").strip().upper(),
			"bopp_gsm": cint(_LAMINATION_BOPP_GSM_BY_CODE.get((gd.get("bopp") or "").strip().upper(), "") or 0),
			"lam_gsm_code": lam_letter,
			"lam_gsm": lam_val,
			"width_code": width_code,
			"width_mm": width_mm,
			"width_inch": width_inch,
			"finish_matte_glossy": (gd.get("finish1") or "").strip() or "0",
			"finish_metallic_cooler": (gd.get("finish2") or "").strip() or "0",
		}

	def _row_inch3(design, gd):
		width_code = gd.get("width") or ""
		width_inch = flt(width_code) / 10.0 if width_code.isdigit() and len(width_code) == 3 else 0.0
		width_mm = cint(round(width_inch * 25.4)) if width_inch else 0
		qc = (gd.get("quality") or "").strip().upper()
		lam_letter = (gd.get("lam") or "").strip().upper()
		lam_val = cint(_LAM_GSM_SUFFIX_MAP.get(lam_letter, 0) or 0)
		return {
			"design_code": design or "",
			"process": "110",
			"quality_code": qc,
			"quality_name": _LAMINATION_QUALITY_BY_CODE.get(qc, ""),
			"colour_code": gd.get("colour") or "",
			"fabric_gsm_code": (gd.get("fabric") or "").strip().upper(),
			"fabric_gsm": cint(_LAMINATION_FABRIC_GSM_BY_CODE.get((gd.get("fabric") or "").strip().upper(), "") or 0),
			"bopp_gsm_code": (gd.get("bopp") or "").strip().upper(),
			"bopp_gsm": cint(_LAMINATION_BOPP_GSM_BY_CODE.get((gd.get("bopp") or "").strip().upper(), "") or 0),
			"lam_gsm_code": lam_letter,
			"lam_gsm": lam_val,
			"width_code": width_code,
			"width_mm": width_mm,
			"width_inch": width_inch,
			"finish_matte_glossy": (gd.get("finish1") or "").strip() or "0",
			"finish_metallic_cooler": (gd.get("finish2") or "").strip() or "0",
		}

	m = re.match(
		r"^(?P<design>[A-Z0-9]+)-110(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})MM$",
		code,
	)
	if m:
		return _row_mm(m.group("design"), m.groupdict())
	mw = re.match(
		r"^(?P<design>[A-Z0-9]+)-110(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})(?P<finish1>[A-Z0-9])(?P<finish2>[A-Z0-9])$",
		code,
	)
	if mw:
		return _row_mm(mw.group("design"), mw.groupdict())
	m3 = re.match(
		r"^(?P<design>[A-Z0-9]+)-110(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{3})(?P<finish1>\d)(?P<finish2>\d)$",
		code,
	)
	if m3:
		return _row_inch3(m3.group("design"), m3.groupdict())
	pos = code.find("-110")
	if pos > 0:
		design = re.sub(r"[^A-Z0-9]", "", code[:pos])
		tail = code[pos + 4 :]
		m4 = re.match(
			r"^(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})MM$",
			tail,
		)
		if m4 and design:
			return _row_mm(design, m4.groupdict())
		m5 = re.match(
			r"^(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{4})(?P<finish1>[A-Z0-9])(?P<finish2>[A-Z0-9])$",
			tail,
		)
		if m5 and design:
			return _row_mm(design, m5.groupdict())
		m6 = re.match(
			r"^(?P<quality>[A-Z])(?P<colour>\d{3})(?P<fabric>[A-Z])(?P<lam>[A-Z])(?P<bopp>[A-Z])(?P<width>\d{3})(?P<finish1>\d)(?P<finish2>\d)$",
			tail,
		)
		if m6 and design:
			return _row_inch3(design, m6.groupdict())
	return {}


def _resolve_lamination_bom(item_code):
	"""Active BOM for the FG item, or for its template item when this line is a variant."""
	ic = (item_code or "").strip()
	if not ic:
		return None

	def _pick_bom_for_item(it_code):
		bn = frappe.db.get_value(
			"BOM",
			{"item": it_code, "docstatus": 1, "is_active": 1, "is_default": 1},
			"name",
			order_by="modified desc",
		)
		if not bn:
			bn = frappe.db.get_value(
				"BOM",
				{"item": it_code, "docstatus": 1, "is_active": 1},
				"name",
				order_by="is_default desc, modified desc",
			)
		if not bn and frappe.db.exists("Item", it_code):
			default_bom = _cstr(frappe.db.get_value("Item", it_code, "default_bom")).strip()
			if default_bom and frappe.db.exists("BOM", default_bom):
				bn = default_bom
		if not bn:
			bn = frappe.db.get_value(
				"BOM",
				{"item": it_code, "docstatus": 1},
				"name",
				order_by="is_active desc, is_default desc, modified desc",
			)
		return bn

	bom_name = _pick_bom_for_item(ic)
	if not bom_name and frappe.db.exists("Item", ic):
		tmpl = frappe.db.get_value("Item", ic, "variant_of")
		if tmpl:
			bom_name = _pick_bom_for_item(tmpl)
	if not bom_name:
		return None
	bom = frappe.get_doc("BOM", bom_name)
	if int(bom.docstatus or 0) != 1:
		return None
	if cint(bom.is_active) != 1 and frappe.db.has_column("BOM", "is_active"):
		return None
	return bom


def _bom_sync_diagnosis_message(fg_item_code, process_code=None):
	"""Human-readable hint when BOM sync fails for 255/108 FG (BOM must be on the FG item, not only on 107)."""
	ic = _cstr(fg_item_code).strip()
	pp = process_code or _bom_item_process_code(ic)
	lines = [
		_("No active submitted BOM found for FG item <b>{0}</b> (process <b>{1}</b>).").format(ic, pp or "?"),
		_("Open the <b>{0}</b> item → BOM tab: submit the BOM, set <b>Is Active</b>, and <b>Is Default</b>.").format(ic),
		_("The BOM must be on the <b>255/108 FG item</b> with a <b>107</b> child row (not only a BOM on the 107 item)."),
	]
	any_bom = frappe.db.get_value("BOM", {"item": ic}, "name", order_by="modified desc")
	if any_bom:
		ds, ia = frappe.db.get_value("BOM", any_bom, ["docstatus", "is_active"]) or (0, 0)
		lines.append(
			_("Found BOM <b>{0}</b> for this item but it is not usable (docstatus={1}, is_active={2}). Submit and activate it.").format(
				any_bom, ds, ia
			)
		)
	child_guess = frappe.db.sql(
		"""
		SELECT DISTINCT bi.item_code
		FROM `tabBOM Item` bi
		INNER JOIN `tabBOM` b ON b.name = bi.parent
		WHERE b.item = %s AND b.docstatus = 1
		LIMIT 5
		""",
		(ic,),
		as_dict=True,
	)
	if child_guess:
		codes = ", ".join([_cstr(r.get("item_code")) for r in child_guess if r.get("item_code")])
		lines.append(_("BOM line items on file: {0}").format(codes))
	return "<br>".join(lines)


def _pick_first_100_from_bom_items(bom_items, parent_item_code):
	rows = []
	for row in bom_items or []:
		ic = (row.item_code or "").strip()
		if ic.startswith("100"):
			rows.append((ic, row))
	if not rows:
		return None
	if len(rows) > 1:
		frappe.log_error(
			title="Lamination BOM 100 fallback",
			message=f"Parent {parent_item_code}: multiple 100 rows in BOM ({', '.join([r[0] for r in rows])}). Using first row.",
		)
	return rows[0]


def _pick_exact_pb_from_bom_items(bom_items, design_code):
	"""Pick PB row for BOPP BOM: PB-<design>, PB-<design>-…, or PRINTED BOPP - <design> - … (cylinder in next segment)."""
	if not design_code:
		return None
	design_u = str(design_code).strip().upper()
	target = f"PB-{design_u}"
	for row in bom_items or []:
		raw = (row.item_code or "").strip()
		ic = raw.upper()
		if ic == target or ic.startswith(target + "-") or ic.startswith(target + "_"):
			return (raw, row)
	for row in bom_items or []:
		raw = (row.item_code or "").strip()
		ic = raw.upper()
		if not ic.startswith("PB-"):
			continue
		rest = ic[3:].strip("-_ ")
		head = (rest.split("-")[0].split("_")[0] if rest else "").strip().upper()
		if head == design_u or design_u.startswith(head) or head.startswith(design_u):
			return (raw, row)
	# Long-form printed BOPP child, e.g. PRINTED BOPP - 7425 - 1C - 15M - 1020 MM
	for row in bom_items or []:
		raw = (row.item_code or "").strip()
		if " - " not in raw:
			continue
		parts = [p.strip() for p in raw.split(" - ")]
		if len(parts) < 2:
			continue
		head0 = parts[0].upper().replace(" ", "")
		if "PRINTEDBOPP" not in head0:
			continue
		if (parts[1] or "").strip().upper() == design_u:
			return (raw, row)
	return None


def _printed_bopp_finish_size_mm_from_item_code(ic, item_name=""):
	"""Width (mm) from revised ``PB-*-405MM-*`` or legacy last numeric segment."""
	pb = _parse_pb_item_code(ic)
	if pb.get("bopp_finish_mm"):
		return pb["bopp_finish_mm"]
	for src in (str(ic or "").strip(), str(item_name or "").strip()):
		if not src:
			continue
		if " - " in src and "PRINTED" in src.upper() and "BOPP" in src.upper():
			parts = [p.strip() for p in src.split(" - ")]
			for p in reversed(parts):
				m = re.match(r"^(\d+)\s*MM$", p, re.I)
				if m:
					return m.group(1)
			if parts:
				lastp = parts[-1]
				digits = re.sub(r"[^\d]", "", lastp)
				if digits:
					return str(int(digits))
		su = src.replace("_", "-")
		segs = [x.strip() for x in su.split("-") if x.strip()]
		if segs:
			last = segs[-1]
			digits = re.sub(r"[^\d]", "", last)
			if digits:
				return str(int(digits))
	return ""


def _cylinder_or_design_token_from_printed_bopp(ic, item_name=""):
	"""
	Cylinder / design-colour token after ``TFS-`` (e.g. ``1C``).
	Short ``PB-*`` codes often omit it — then parse from ``item_name`` if it contains ``TFS - 1C``.
	Skips ``15M``-style meter segments between design and finish size.
	"""
	ic0 = str(ic or "").strip()
	im0 = str(item_name or "").strip()
	for src in (ic0, im0):
		if not src or " - " not in src:
			continue
		parts = [p.strip() for p in src.split(" - ")]
		head0 = (parts[0] or "").upper().replace(" ", "")
		if "PRINTED" not in head0 or "BOPP" not in head0:
			continue
		for i, p in enumerate(parts):
			pu = re.sub(r"\s+", "", (p or "").upper())
			if pu == "TFS" or pu.startswith("TFS"):
				if i + 1 < len(parts):
					return (parts[i + 1] or "").strip()
	comb = f"{ic0} {im0}"
	m = re.search(r"TFS\s*-\s*([A-Za-z0-9]+)", comb, re.I)
	if m:
		return m.group(1).strip()
	su = ic0.upper()
	if su.startswith("PB-"):
		pb = _parse_pb_item_code(ic0)
		if pb.get("format") == "revised":
			return ""
		segs = [x.strip() for x in su.split("-") if x.strip()]
		if len(segs) >= 4:
			for seg in segs[2:-1]:
				if re.match(r"^\d+M$", seg, re.I):
					continue
				if re.match(r"^\d+MM?$", seg, re.I):
					continue
				if re.match(r"^\d+[A-Z]{1,2}$", seg, re.I) and seg not in ("MM", "GC", "GM", "MG"):
					return seg
		elif len(segs) == 3:
			mid = segs[2]
			if mid and not re.match(r"^\d+$", re.sub(r"[^\d]", "", mid)):
				if not re.match(r"^\d+M$", mid, re.I):
					return mid
	return ""


def _cylinder_type_from_printed_bopp_item_code(ic, item_name=""):
	"""Cylinder token after ``TFS-`` (e.g. ``1C``); optional ``item_name`` for short ``PB-*`` codes."""
	return _cylinder_or_design_token_from_printed_bopp(ic, item_name)


def _printed_bopp_design_colours_token(ic, item_name=""):
	"""Same token as cylinder for PB lines (e.g. ``1C`` = one design colour)."""
	return _cylinder_or_design_token_from_printed_bopp(ic, item_name)


def _design_code_from_printed_bopp_item_code(ic):
	"""Design / style code segment for long-form printed BOPP items."""
	pb = _parse_pb_item_code(ic)
	if pb.get("design_code"):
		return pb["design_code"]
	s = str(ic or "").strip()
	if not s:
		return ""
	if " - " in s:
		parts = [p.strip() for p in s.split(" - ")]
		head0 = (parts[0] or "").upper().replace(" ", "")
		if "PRINTED" in head0 and "BOPP" in head0 and len(parts) >= 2:
			return (parts[1] or "").strip()
	if s.upper().startswith("PB-"):
		segs = [x.strip() for x in s.split("-") if x.strip()]
		if len(segs) >= 2:
			return (segs[1] or "").strip()
	return ""


def _parse_pb_item_code(item_code):
	"""
	Revised PB layout: ``PB-{design}-{gsmM}-{widthMM}-{finishSuffix}``
	e.g. ``PB-6003-15M-405MM-0M`` → single coat ``15M MATTE``.
	``PB-6002-30M-405MM-MM`` → total 30 gsm → finishing ``15M MATTE 15M METALLIC``.
	Legacy: ``PB-{design}-{gsmM}-{width}`` or long-form PRINTED BOPP - … lines.
	"""
	ic = _cstr(item_code).strip().upper()
	out = {
		"design_code": "",
		"gsm_token": "",
		"gsm": 0,
		"bopp_finish_mm": "",
		"finish_suffix": "",
		"finishing_text": "",
		"format": "",
	}
	if not ic:
		return out
	if ic.startswith("PB-"):
		segs = [x.strip() for x in ic.split("-") if x.strip()]
		if len(segs) < 3:
			return out
		out["design_code"] = segs[1]
		# Revised: PB / design / 15M / 405MM / 0M
		if len(segs) >= 5 and re.match(r"^\d+MM?$", segs[3], re.I):
			out["format"] = "revised"
			out["gsm_token"] = segs[2].upper()
			gm = re.match(r"^(\d+)M$", segs[2], re.I)
			if gm:
				microns = cint(gm.group(1))
				out["gsm"] = round(microns * 0.91, 1)
				out["microns"] = microns
			wm = re.match(r"^(\d+)MM?$", segs[3], re.I)
			if wm:
				out["bopp_finish_mm"] = wm.group(1)
			out["finish_suffix"] = segs[4].upper()
			out["finishing_text"] = _pb_finishing_display_text(out["gsm_token"], out["finish_suffix"])
			return out
		# Legacy short PB-* (no dedicated finish suffix segment)
		out["format"] = "legacy_pb"
		for i in range(2, len(segs)):
			seg = segs[i]
			if re.match(r"^\d+M$", seg, re.I):
				out["gsm_token"] = seg.upper()
				microns_leg = cint(re.match(r"^(\d+)M$", seg, re.I).group(1))
				out["gsm"] = round(microns_leg * 0.91, 1)
				out["microns"] = microns_leg
			wm = re.match(r"^(\d+)MM?$", seg, re.I)
			if wm and not out["bopp_finish_mm"]:
				out["bopp_finish_mm"] = wm.group(1)
			elif re.match(r"^\d+$", seg) and not out["bopp_finish_mm"]:
				out["bopp_finish_mm"] = seg
		return out
	return out


def _pb_coating_gsm_token(gsm_token, num_passes):
	"""
	Split total BOPP gsm in the item code across coating passes.

	``PB-6002-30M-405MM-MM`` → token ``30M``, two passes → ``15M`` each (not ``30M`` each).
	When total does not divide evenly (e.g. ``15M`` + dual suffix), keep the token as-is per pass.
	"""
	gsm_token = _cstr(gsm_token).strip().upper()
	num_passes = cint(num_passes or 1)
	if num_passes <= 1:
		return gsm_token
	m = re.match(r"^(\d+)M$", gsm_token, re.I)
	if not m:
		return gsm_token
	n = cint(m.group(1))
	if n <= 0:
		return gsm_token
	if n % num_passes == 0 and n >= num_passes:
		return f"{n // num_passes}M"
	return gsm_token


_LAMINATION_FINISH_MG_WORDS = {
	"0": "PLAIN",
	"P": "PLAIN",
	"M": "MATTE",
	"G": "GLOSSY",
}
_LAMINATION_FINISH_MC_WORDS = {
	"0": "PLAIN",
	"P": "PLAIN",
	"M": "METALLIC",
	"C": "COOLER",
	"G": "GLOSSY",
}


def _lamination_finishing_display_text(mg, mc):
	"""Human-readable finishing for 107/108/255 item-code tails (e.g. P/P → PLAIN / PLAIN, 0/P → 0/PLAIN)."""
	mg = _cstr(mg).strip().upper() or "0"
	mc = _cstr(mc).strip().upper() or "0"
	if mg == "0" and mc == "P":
		return "0/PLAIN"
	if mg == "P" and mc == "P":
		return "PLAIN / PLAIN"
	if mg == "0" and mc == "0":
		return "PLAIN / PLAIN"
	w1 = _LAMINATION_FINISH_MG_WORDS.get(mg, mg)
	w2 = _LAMINATION_FINISH_MC_WORDS.get(mc, mc)
	if mg == "0":
		return f"0/{w2}"
	return f"{w1} / {w2}"


def _two_char_finishing_display_text(code):
	"""Box/BOPP bag 2-char finishing suffix → words (PP → PLAIN / PLAIN, 0P → 0/PLAIN, MG → METALLIC / GLOSSY)."""
	suffix = _cstr(code).strip().upper()
	if not suffix:
		return ""
	if suffix == "PP":
		return "PLAIN / PLAIN"
	if suffix == "0P":
		return "0/PLAIN"
	try:
		from production_entry.production_planning.box_bag_api import _box_bag_finishing_label
		return _box_bag_finishing_label(suffix)
	except Exception:
		return suffix


def _pb_finishing_display_text(gsm_token, finish_suffix):
	"""
	Build Finishing column text for Printed BOPP from gsm token (e.g. ``30M``) and suffix.

	- ``0M`` → ``30M MATTE`` (single coat — full token)
	- ``0G`` → ``30M GLOSSY``
	- ``MM`` → ``15M MATTE 15M METALLIC`` when token is ``30M`` (total gsm split across two coats)
	- ``GC`` → ``15M GLOSSY 15M COOLER`` for ``30M`` token
	"""
	gsm_token = _cstr(gsm_token).strip().upper()
	suffix = _cstr(finish_suffix).strip().upper()
	if not gsm_token:
		return ""
	if not suffix:
		return ""

	if suffix in ("0M", "M0", "00"):
		return f"{gsm_token} MATTE"
	if suffix in ("0G", "G0"):
		return f"{gsm_token} GLOSS"
	if suffix == "MM":
		coat = _pb_coating_gsm_token(gsm_token, 2)
		return f"{coat} MATTE {coat} METALLIC"
	if suffix == "GC":
		coat = _pb_coating_gsm_token(gsm_token, 2)
		return f"{coat} GLOSSY {coat} COOLER"
	if suffix == "GM":
		coat = _pb_coating_gsm_token(gsm_token, 2)
		return f"{coat} GLOSSY {coat} MATTE"
	if suffix == "MG":
		coat = _pb_coating_gsm_token(gsm_token, 2)
		return f"{coat} MATTE {coat} METALLIC"
	if len(suffix) == 2:
		c0, c1 = suffix[0], suffix[1]
		parts = []
		coat_b = _pb_coating_gsm_token(gsm_token, 2)
		if c1 == "M":
			parts.append(f"{coat_b} MATTE")
		elif c1 == "G":
			parts.append(f"{coat_b} GLOSSY")
		if c0 == "M" and c1 != "M":
			parts.append(f"{coat_b} METALLIC")
		elif c0 == "C":
			parts.append(f"{coat_b} COOLER")
		if parts:
			return " ".join(parts)
	return ""


def _printed_bopp_planning_fields_from_item_code(item_code, item_name="", so_item_name=None):
	"""Planning / Printed BOPP fields from revised ``PB-*`` item code + SO design colours."""
	ic = _cstr(item_code).strip()
	inm = _cstr(item_name).strip()
	so_item_name = _cstr(so_item_name).strip()
	pb = _parse_pb_item_code(ic)
	out = {}
	so_cyl = _pb_cylinder_fields_from_sales_order_item(so_item_name) if so_item_name else {}
	if so_cyl:
		out.update(so_cyl)
	if not pb.get("design_code") and not pb.get("gsm"):
		return out
	dc = pb.get("design_code") or _design_code_from_printed_bopp_item_code(ic)
	if dc:
		for tbl in ("Planning Table", "Planning sheet Item"):
			if frappe.db.has_column(tbl, "custom_design_code"):
				out["custom_design_code"] = dc
	gsm_val = cint(pb.get("gsm") or 0)
	if gsm_val > 0:
		if frappe.db.has_column("Planning Table", "gsm") or frappe.db.has_column("Planning sheet Item", "gsm"):
			out["gsm"] = gsm_val
		if frappe.db.has_column("Planning Table", "custom_bopp_gsm") or frappe.db.has_column(
			"Planning sheet Item", "custom_bopp_gsm"
		):
			out["custom_bopp_gsm"] = gsm_val
	bfs = pb.get("bopp_finish_mm") or _printed_bopp_finish_size_mm_from_item_code(ic, inm)
	if bfs:
		for tbl in ("Planning Table", "custom_bopp_finish_size_mm"), ("Planning sheet Item", "custom_bopp_finish_size_mm"):
			if frappe.db.has_column(tbl[0], tbl[1]):
				out["custom_bopp_finish_size_mm"] = bfs
	fin = pb.get("finishing_text") or ""
	if fin:
		for tbl in ("Planning Table", "custom_finishing"), ("Planning sheet Item", "custom_finishing"):
			if frappe.db.has_column(tbl[0], tbl[1]):
				out["custom_finishing"] = fin
		if frappe.db.has_column("Planning Table", "finishing") or frappe.db.has_column("Planning sheet Item", "finishing"):
			out["finishing"] = fin
	if not out.get("custom_cylinder_type"):
		cyl = _printed_bopp_design_colours_token(ic, inm)
		if cyl:
			out["custom_cylinder_type"] = cyl
			out.setdefault("custom_no_of_design_colours", cyl)
			wt_fb = _cstr(out.get("custom_white_tint")).strip() or _white_tint_yes_no_from_sales_order_item(so_item_name)
			out.setdefault(
				"custom_total_no_of_colours",
				_total_colours_token_for_printed_bopp(cyl, wt_fb) or cyl,
			)
	return out


def _apply_printed_bopp_planning_fields_to_row(row, item_code=None, item_name=None, so_item_name=None):
	"""Set gsm / BOPP gsm / finish mm / finishing / cylinder / design on a PB planning child row."""
	if not row:
		return
	ic = _cstr(item_code or getattr(row, "item_code", None)).strip()
	if not ic or not _is_printed_bopp_item_code(ic):
		return
	inm = _cstr(item_name or getattr(row, "item_name", None) or frappe.db.get_value("Item", ic, "item_name")).strip()
	soi = _cstr(
		so_item_name
		or getattr(row, "sales_order_item", None)
		or getattr(row, "so_item", None)
		or _printing_sales_order_item_from_row(row)
	).strip()
	fields = _printed_bopp_planning_fields_from_item_code(ic, inm, soi)
	for k, v in fields.items():
		if v is None or v == "":
			continue
		if hasattr(row, k):
			setattr(row, k, v)
	wt = _cstr(getattr(row, "custom_white_tint", None)).strip()
	ndc = _cstr(getattr(row, "custom_no_of_design_colours", None)).strip() or _cstr(fields.get("custom_no_of_design_colours")).strip()
	if ndc and hasattr(row, "custom_total_no_of_colours"):
		tnc = _total_colours_token_for_printed_bopp(ndc, wt) or _cstr(fields.get("custom_total_no_of_colours")).strip() or ndc
		setattr(row, "custom_total_no_of_colours", tnc)


def _stamp_printed_bopp_fields_on_planning_sheet(planning_sheet_name):
	"""Backfill revised PB parsing (gsm, finishing, BOPP finish mm) on board + legacy rows."""
	if not planning_sheet_name or not frappe.db.exists("Planning sheet", planning_sheet_name):
		return 0
	updated = 0
	for doctype in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.table_exists(doctype):
			continue
		flds = ["name", "item_code", "item_name"]
		for col in ("sales_order_item", "so_item"):
			if frappe.db.has_column(doctype, col):
				flds.append(col)
		rows = frappe.get_all(
			doctype,
			filters={"parent": planning_sheet_name},
			fields=flds,
			limit_page_length=0,
		) or []
		for row in rows:
			ic = _cstr(row.get("item_code")).strip()
			if not _is_printed_bopp_item_code(ic):
				continue
			inm = _cstr(row.get("item_name") or frappe.db.get_value("Item", ic, "item_name")).strip()
			soi = _cstr(row.get("sales_order_item") or row.get("so_item")).strip()
			patch = _printed_bopp_planning_fields_from_item_code(ic, inm, soi)
			if not patch:
				continue
			apply = {}
			for k, v in patch.items():
				if not frappe.db.has_column(doctype, k):
					continue
				cur = frappe.db.get_value(doctype, row["name"], k)
				if cur != v and (v or v == 0):
					apply[k] = v
			if apply:
				frappe.db.set_value(doctype, row["name"], apply, update_modified=False)
				updated += 1
	return updated


def _find_planning_table_lamination_parent_row(planning_sheet_name, lam_item_code, sales_order_item_name):
	"""Match parent lamination PT row by SO line (Planning Table may use sales_order_item or so_item)."""
	if not planning_sheet_name or not lam_item_code or not sales_order_item_name:
		return None
	rows = frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name, "item_code": lam_item_code},
		fields=["name", "sales_order_item", "so_item"],
		limit=30,
	)
	soi = (sales_order_item_name or "").strip()
	for r in rows or []:
		if (r.get("sales_order_item") or "").strip() == soi:
			return r.get("name")
		if (r.get("so_item") or "").strip() == soi:
			return r.get("name")
	if rows:
		return rows[0].get("name")
	return None


def _pb_design_name_from_sales_order_item(so_item_name):
	"""Optional human design name from Sales Order Item custom fields (site-specific)."""
	if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
		return ""
	try:
		meta = frappe.get_meta("Sales Order Item")
	except Exception:
		return ""
	for fn in (
		"custom_design_name",
		"custom_pb_design_name",
		"custom_style_name",
		"custom_print_design",
		"design_name",
	):
		try:
			if meta.has_field(fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
		except Exception:
			continue
	return ""


def _pb_design_code_from_sales_order_item(so_item_name):
	"""Design / style code from Sales Order Item (e.g. 6002 for BOPP laminated parents)."""
	if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
		return ""
	try:
		meta = frappe.get_meta("Sales Order Item")
	except Exception:
		return ""
	for fn in (
		"custom_design_code",
		"custom_pb_design_code",
		"design_code",
		"custom_style_code",
	):
		try:
			if meta.has_field(fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
		except Exception:
			continue
	try:
		for df in (meta.fields or []):
			fn = (getattr(df, "fieldname", None) or "").strip()
			if not fn:
				continue
			low = fn.lower()
			if "design" in low and "code" in low and frappe.db.has_column("Sales Order Item", fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
	except Exception:
		pass
	return ""


def _pb_design_colour_from_sales_order_item(so_item_name):
	"""Optional design colour from Sales Order Item custom fields (site-specific)."""
	if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
		return ""
	# 1) Fast path: known fieldnames.
	for fn in (
		"custom_design_colour",
		"custom_design_color",
		"custom_pb_design_colour",
		"custom_pb_design_color",
		"custom_print_colour",
		"custom_print_color",
		"custom_design_colour_",
		"custom_design_color_",
		"custom_design_colours",
		"custom_design_colors",
		"design_colour",
		"design_color",
	):
		try:
			# Prefer reading the actual column even if DocType metadata is stale/missing.
			if frappe.db.has_column("Sales Order Item", fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
		except Exception:
			continue
	# 2) Fallback: scan Sales Order Item fields for anything like design+colour/color.
	try:
		meta = frappe.get_meta("Sales Order Item")
		candidates = []
		for df in (meta.fields or []):
			fn = (getattr(df, "fieldname", None) or "").strip()
			if not fn:
				continue
			low = fn.lower()
			if "design" in low and ("colour" in low or "color" in low):
				candidates.append(fn)
		for fn in candidates:
			if frappe.db.has_column("Sales Order Item", fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
	except Exception:
		pass
	return ""


def _count_pb_design_colours_from_so_text(raw):
	"""
	Count design colours from SO text such as ``1.BLUE2.RED`` → 2, or plain ``2C`` → 2.
	"""
	s = _cstr(raw).strip()
	if not s:
		return 0
	m = re.match(r"^(\d+)\s*C\b", s, re.I)
	if m and not re.search(r"\d+\s*\.", s):
		return cint(m.group(1))
	hits = re.findall(r"(\d+)\s*\.", s)
	if hits:
		return len(hits)
	parts = re.split(r"[,;|/\n]+", s)
	n_named = 0
	for p in parts:
		p = p.strip()
		if p and re.search(r"[A-Za-z]", p):
			n_named += 1
	if n_named > 0:
		return n_named
	digits = re.findall(r"\b(\d+)\b", s)
	if len(digits) == 1 and cint(digits[0]) > 0:
		return cint(digits[0])
	return 0


def _pb_cylinder_fields_from_sales_order_item(so_item_name, white_tint=None):
	"""
	From SO design colour string (e.g. ``1.BLUE2.RED``):
	- ``custom_cylinder_type`` → ``2C``
	- ``custom_no_of_design_colours`` → ``2C`` (same count token)
	- ``custom_total_no_of_colours`` → ``3C`` when white tint Yes, else ``2C``
	"""
	so_item_name = _cstr(so_item_name).strip()
	if not so_item_name:
		return {}
	raw = _pb_design_colour_from_sales_order_item(so_item_name)
	n = _count_pb_design_colours_from_so_text(raw)
	if n <= 0:
		return {}
	cyl = f"{n}C"
	wt = _cstr(white_tint).strip() if white_tint is not None else ""
	if not wt:
		wt = _white_tint_yes_no_from_sales_order_item(so_item_name) or ""
	tnc = _total_colours_token_for_printed_bopp(cyl, wt) or cyl
	out = {
		"custom_cylinder_type": cyl,
		"custom_no_of_design_colours": cyl,
		"custom_total_no_of_colours": tnc,
	}
	if raw and (
		frappe.db.has_column("Planning Table", "custom_design_colour")
		or frappe.db.has_column("Planning sheet Item", "custom_design_colour")
	):
		out["custom_design_colour"] = raw
	wt_norm = _normalized_white_tint_select(wt)
	if wt_norm and (
		frappe.db.has_column("Planning Table", "custom_white_tint")
		or frappe.db.has_column("Planning sheet Item", "custom_white_tint")
	):
		out["custom_white_tint"] = wt_norm
	return out


def _printing_design_attachment_from_sales_order_item(so_item_name):
	"""Best-effort printing design attachment URL from Sales Order Item."""
	if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
		return ""
	# Prefer direct DB column reads to survive metadata drift.
	for fn in (
		"custom_design_attachment",
		"custom_print_design_attachment",
		"custom_printing_design_attachment",
		"custom_design_image",
		"custom_print_design_image",
		"image",
		"attachment",
	):
		try:
			if frappe.db.has_column("Sales Order Item", fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
		except Exception:
			continue
	# Fallback: scan fields for likely attachment/image.
	try:
		meta = frappe.get_meta("Sales Order Item")
		candidates = []
		for df in (meta.fields or []):
			fn = (getattr(df, "fieldname", None) or "").strip()
			ft = (getattr(df, "fieldtype", None) or "").strip()
			if not fn:
				continue
			low = fn.lower()
			if "design" in low and ("attach" in low or "image" in low):
				candidates.append((fn, ft))
		for fn, ft in candidates:
			if frappe.db.has_column("Sales Order Item", fn):
				v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
				if (v or "").strip():
					return (v or "").strip()
	except Exception:
		pass
	return ""


@frappe.whitelist()
def _design_master_extra_fields(design_code):
	"""If ``Design Master`` is installed and the DB table exists, resolve design name / attachment by code.

	Safe on sites where the DocType is registered but ``tabDesign Master`` was never migrated
	(``has_column`` / ``get_table_columns`` would otherwise raise ProgrammingError).
	"""
	out = {}
	dc = (design_code or "").strip()
	if not dc:
		return out
	try:
		if not frappe.db.exists("DocType", "Design Master"):
			return out
		dm_cols = set(frappe.db.get_table_columns("Design Master") or [])
	except Exception:
		return out
	name = None
	try:
		if frappe.db.exists("Design Master", dc):
			name = dc
	except Exception:
		name = None
	if not name:
		for fld in ("design_code", "code", "style_code", "custom_design_code"):
			if fld not in dm_cols:
				continue
			try:
				name = frappe.db.get_value("Design Master", {fld: dc}, "name")
			except Exception:
				name = None
			if name:
				break
	if not name:
		return out
	try:
		meta = frappe.get_meta("Design Master")
		doc = frappe.get_cached_doc("Design Master", name)
	except Exception:
		return out
	for fn in (
		"design_name",
		"design_title",
		"subject",
		"title",
		"custom_design_name",
	):
		if meta.has_field(fn):
			v = _cstr(getattr(doc, fn, None)).strip()
			if v:
				out["custom_design_name"] = v
				break
	for fn in ("design_attachment", "attachment", "custom_design_attachment", "custom_attachment", "image", "file"):
		if meta.has_field(fn):
			v = _cstr(getattr(doc, fn, None)).strip()
			if v:
				out["custom_design_attachment"] = v
				break
	if "custom_design_attachment" not in out:
		for df in meta.fields or []:
			ft = _cstr(getattr(df, "fieldtype", None))
			fn = _cstr(getattr(df, "fieldname", None))
			if not fn or ft not in ("Attach", "Attach Image", "Image"):
				continue
			low = fn.lower()
			if "design" not in low and "style" not in low:
				continue
			v = _cstr(getattr(doc, fn, None)).strip()
			if v:
				out["custom_design_attachment"] = v
				break
	for fn in (
		"design_colour",
		"design_color",
		"design_colours",
		"custom_design_colour",
		"custom_design_color",
	):
		if meta.has_field(fn):
			v = _cstr(getattr(doc, fn, None)).strip()
			if v:
				out["custom_design_colour"] = v
				break
	return out


def _design_code_from_planning_item_code(item_code):
	"""Parse design code from FG / parent item codes (105, 106, 108, 252–255, …)."""
	ic = _cstr(item_code).strip()
	if not ic:
		return ""
	pp = _item_process_prefix(ic)
	if pp == "105" or _is_printing_105_parent_process(ic):
		return _cstr((_parse_105_item_code(ic) or {}).get("design_code")).strip().upper()
	if pp == "106":
		return _cstr((_parse_106_item_code(ic) or {}).get("design_code")).strip().upper()
	if pp == "108":
		return _cstr((_parse_108_item_code(ic) or {}).get("design_code")).strip().upper() or _fg_design_prefix_from_item_code(ic)
	if pp in ("251", "252", "253", "255"):
		return _cstr((_parse_sheet_cutting_item_code(ic) or {}).get("design_code")).strip().upper()
	if pp == "254":
		return _cstr((_parse_254_item_code(ic) or {}).get("design_code")).strip().upper()
	if _matches_printed_bopp_board_row(frappe._dict({"item_code": ic})):
		return _design_code_from_printed_bopp_item_code(ic) or ""
	prefix = _fg_design_prefix_from_item_code(ic)
	if prefix and pp in ("107", "108", "255"):
		return prefix.upper()
	return ""


def _planning_row_supports_design_fields(doctype="Planning Table"):
	"""True when this child table has at least one design column."""
	for fld in ("custom_design_code", "custom_design_name", "custom_design_attachment"):
		try:
			if frappe.db.has_column(doctype, fld):
				return True
		except Exception:
			pass
	return False


def _apply_design_fields_to_planning_dict(planning_dict, so_item_name=None, design_code=None, item_code=None):
	"""Fill custom_design_code / name / attachment (SO → Design Master). Safe for populate + DB updates."""
	if planning_dict is None:
		return
	planning_dict = planning_dict if isinstance(planning_dict, dict) else {}
	so_item_name = _cstr(so_item_name).strip()
	item_code = _cstr(item_code).strip()
	dc = _cstr(design_code).strip().upper()
	if not dc and item_code:
		dc = _design_code_from_planning_item_code(item_code)
	if not dc and so_item_name:
		dc = _cstr(_pb_design_code_from_sales_order_item(so_item_name)).strip().upper()
	if dc:
		for tbl in ("Planning Table", "Planning sheet Item"):
			if frappe.db.has_column(tbl, "custom_design_code"):
				if not _cstr(planning_dict.get("custom_design_code")).strip():
					planning_dict["custom_design_code"] = dc
	dn = _pb_design_name_from_sales_order_item(so_item_name) if so_item_name else ""
	if not dn and dc:
		dn = _cstr((_design_master_extra_fields(dc) or {}).get("custom_design_name")).strip()
	if dn and dn.upper() != dc.upper():
		for tbl in ("Planning Table", "Planning sheet Item"):
			if frappe.db.has_column(tbl, "custom_design_name"):
				if not _cstr(planning_dict.get("custom_design_name")).strip():
					planning_dict["custom_design_name"] = dn
	da = _printing_design_attachment_from_sales_order_item(so_item_name) if so_item_name else ""
	if not da:
		da = _printing_design_attachment_from_row(planning_dict, so_item_name)
	if not da and dc:
		da = _cstr((_design_master_extra_fields(dc) or {}).get("custom_design_attachment")).strip()
	if da:
		for tbl in ("Planning Table", "Planning sheet Item"):
			if frappe.db.has_column(tbl, "custom_design_attachment"):
				if not _cstr(planning_dict.get("custom_design_attachment")).strip():
					planning_dict["custom_design_attachment"] = da
	for k, v in (_design_master_extra_fields(dc) or {}).items():
		if not v or not _cstr(v).strip():
			continue
		if not (frappe.db.has_column("Planning Table", k) or frappe.db.has_column("Planning sheet Item", k)):
			continue
		if not _cstr(planning_dict.get(k)).strip():
			planning_dict[k] = v


def _apply_design_fields_to_planning_row_doc(row, so_item_name, item_code=None):
	"""Desk / populate: set missing design fields on an existing child row document."""
	if not row:
		return
	patch = {}
	_apply_design_fields_to_planning_dict(
		patch, so_item_name=so_item_name, item_code=item_code or getattr(row, "item_code", None)
	)
	for k, v in patch.items():
		if not v or not hasattr(row, k):
			continue
		if not _cstr(getattr(row, k, None)).strip():
			setattr(row, k, v)


def _stamp_design_fields_on_planning_sheet(planning_sheet_name):
	"""Backfill design name + attachment on all design-process rows (create / regenerate / update)."""
	if not planning_sheet_name or not frappe.db.exists("Planning sheet", planning_sheet_name):
		return 0
	if not _planning_row_supports_design_fields():
		return 0
	design_procs = frozenset({
		"105", "106", "107", "108", "201", "203", "212", "214", "216", "217",
		"221", "222", "223", "224", "225", "226", "231", "232", "233", "241", "242",
		"252", "253", "254", "255", "251",
	})
	updated = 0
	flds = ["name", "item_code", "sales_order_item", "so_item"]
	for col in ("custom_design_code", "custom_design_name", "custom_design_attachment", "custom_design_colour"):
		if frappe.db.has_column("Planning Table", col):
			flds.append(col)
	for doctype in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.table_exists(doctype):
			continue
		rows = frappe.get_all(
			doctype,
			filters={"parent": planning_sheet_name},
			fields=[f for f in flds if frappe.db.has_column(doctype, f)],
			limit_page_length=0,
		) or []
		for row in rows:
			ic = _cstr(row.get("item_code")).strip()
			if not ic:
				continue
			pp = _item_process_prefix(ic)
			if (
				pp not in design_procs
				and pp not in BOPP_BOX_BAG_PROCESS_CODES
				and not _is_printing_105_parent_process(ic)
				and not _matches_printed_bopp_board_row(row)
				and _lamination_process_from_item_code(ic) != "107"
			):
				continue
			soi = _cstr(row.get("sales_order_item") or row.get("so_item")).strip()
			patch = {}
			_apply_design_fields_to_planning_dict(
				patch,
				so_item_name=soi,
				design_code=_cstr(row.get("custom_design_code")).strip() or None,
				item_code=ic,
			)
			apply = {}
			for k, v in patch.items():
				if not frappe.db.has_column(doctype, k) or not _cstr(v).strip():
					continue
				cur = _cstr(row.get(k)).strip()
				if not cur or (k == "custom_design_name" and cur.upper() == _cstr(patch.get("custom_design_code")).upper()):
					apply[k] = v
			if apply:
				frappe.db.set_value(doctype, row["name"], apply, update_modified=False)
				updated += 1
	return updated


def _stamp_finishing_display_on_planning_sheet(planning_sheet_name):
	"""Backfill human-readable custom_finishing from item-code tails (107/108/255/bag)."""
	if not planning_sheet_name or not frappe.db.exists("Planning sheet", planning_sheet_name):
		return 0
	if not (
		frappe.db.has_column("Planning Table", "custom_finishing")
		or frappe.db.has_column("Planning sheet Item", "custom_finishing")
	):
		return 0
	updated = 0
	for doctype in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.table_exists(doctype):
			continue
		rows = frappe.get_all(
			doctype,
			filters={"parent": planning_sheet_name},
			fields=["name", "item_code", "custom_finishing"],
			limit_page_length=0,
		) or []
		for row in rows:
			ic = _cstr(row.get("item_code")).strip()
			if not ic:
				continue
			fin_txt = ""
			lam = _lamination_process_from_item_code(ic)
			if lam == "107":
				p = _parse_107_item_code(ic) or {}
				fin_txt = _lamination_finishing_display_text(
					p.get("finish_matte_glossy"), p.get("finish_metallic_cooler")
				)
			elif _item_process_prefix(ic) == "255":
				p = _parse_255_item_code(ic) or {}
				fin_txt = _lamination_finishing_display_text(
					p.get("finish_matte_glossy"), p.get("finish_metallic_cooler")
				)
			elif _item_process_prefix(ic) == "108":
				p = _parse_108_item_code(ic) or {}
				fin_txt = _lamination_finishing_display_text(
					p.get("finish_matte_glossy"), p.get("finish_metallic_cooler")
				)
			elif _item_process_prefix(ic) in BOPP_BOX_BAG_PROCESS_CODES:
				try:
					from production_entry.production_planning.bopp_bag_api import _parse_bopp_bag_item_code
					p = _parse_bopp_bag_item_code(ic) or {}
					fin_txt = p.get("finishing_label") or _two_char_finishing_display_text(p.get("finishing_code"))
				except Exception:
					fin_txt = ""
			elif _item_process_prefix(ic) in BOX_BAG_PROCESS_CODES or _item_process_prefix(ic) in W_CUT_D_CUT_FG_PROCESS_CODES:
				try:
					from production_entry.production_planning.box_bag_api import _parse_box_bag_item_code, _parse_dcut_bag_item_code
					pp = _item_process_prefix(ic)
					if pp in W_CUT_D_CUT_FG_PROCESS_CODES:
						p = _parse_dcut_bag_item_code(ic) or {}
					else:
						p = _parse_box_bag_item_code(ic) or {}
					fin_txt = p.get("finishing_label") or _two_char_finishing_display_text(p.get("finishing_code"))
				except Exception:
					fin_txt = ""
			if not fin_txt:
				continue
			cur = _cstr(row.get("custom_finishing")).strip()
			if cur == fin_txt:
				continue
			frappe.db.set_value(doctype, row.get("name"), "custom_finishing", fin_txt, update_modified=False)
			updated += 1
	return updated


def _align_so_line_bom_parent_qty_from_sales_order(planning_sheet_name, so_item):
	"""When SO FG qty changes, align intermediate BOM parent rows (107/104/106/105…) with SO qty."""
	if not planning_sheet_name or not so_item:
		return 0
	soi = _cstr(getattr(so_item, "name", None)).strip()
	fg_ic = _cstr(getattr(so_item, "item_code", None)).strip()
	new_qty = flt(getattr(so_item, "qty", 0))
	if not soi or not fg_ic or new_qty <= 0:
		return 0
	fg_pp = _bom_item_process_code(fg_ic)
	updated = 0
	for doctype in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.table_exists(doctype):
			continue
		for so_col in ("sales_order_item", "so_item"):
			if not frappe.db.has_column(doctype, so_col):
				continue
			rows = frappe.get_all(
				doctype,
				filters={"parent": planning_sheet_name, so_col: soi},
				fields=["name", "item_code", "qty"],
				limit_page_length=0,
			) or []
			for row in rows:
				ic = _cstr(row.get("item_code")).strip()
				if not ic or ic == fg_ic:
					continue
				pp = _bom_item_process_code(ic)
				if pp == "100" or _is_printed_bopp_item_code(ic):
					continue
				mirror = False
				if pp in ("107", "104") and fg_pp in ("108", "255", "253", "254", "109"):
					mirror = True
				elif pp == "106" and fg_pp in ("254", "106"):
					mirror = True
				elif pp == "105" and fg_pp in ("252", "105"):
					mirror = True
				elif pp in ("103", "102", "109") and fg_pp in ("103", "102", "109", "108"):
					mirror = True
				elif pp == "251" and fg_pp in ("251", "252"):
					mirror = True
				if not mirror:
					continue
				cur = flt(row.get("qty") or 0)
				if abs(cur - new_qty) > 1e-6 and frappe.db.has_column(doctype, "qty"):
					frappe.db.set_value(doctype, row["name"], "qty", new_qty, update_modified=False)
					updated += 1
	return updated


def _set_planning_table_qty_with_legacy_sync(planning_sheet_name, pt_row_name, qty):
	"""Set qty on Planning Table and the linked Planning sheet Item (legacy top grid)."""
	if not pt_row_name or not frappe.db.exists("Planning Table", pt_row_name):
		return False
	qty = flt(qty)
	if frappe.db.has_column("Planning Table", "qty"):
		frappe.db.set_value("Planning Table", pt_row_name, "qty", qty, update_modified=False)
	legacy_name = ""
	if frappe.db.has_column("Planning Table", "source_item"):
		legacy_name = _cstr(frappe.db.get_value("Planning Table", pt_row_name, "source_item")).strip()
	if legacy_name and frappe.db.exists("Planning sheet Item", legacy_name):
		if frappe.db.has_column("Planning sheet Item", "qty"):
			frappe.db.set_value("Planning sheet Item", legacy_name, "qty", qty, update_modified=False)
		return True
	if not planning_sheet_name:
		planning_sheet_name = frappe.db.get_value("Planning Table", pt_row_name, "parent")
	ic = _cstr(frappe.db.get_value("Planning Table", pt_row_name, "item_code")).strip()
	soi = ""
	for col in ("sales_order_item", "so_item"):
		if frappe.db.has_column("Planning Table", col):
			soi = _cstr(frappe.db.get_value("Planning Table", pt_row_name, col)).strip()
			if soi:
				break
	psi_name = _find_legacy_planning_sheet_item_row(planning_sheet_name, ic, soi)
	if psi_name and frappe.db.has_column("Planning sheet Item", "qty"):
		frappe.db.set_value("Planning sheet Item", psi_name, "qty", qty, update_modified=False)
		if frappe.db.has_column("Planning Table", "source_item"):
			frappe.db.set_value("Planning Table", pt_row_name, "source_item", psi_name, update_modified=False)
		return True
	return False


def _find_legacy_planning_sheet_item_row(planning_sheet_name, item_code, so_item_key=None):
	"""Resolve Planning sheet Item row for board row (item_code + optional SO line)."""
	psn = _cstr(planning_sheet_name).strip()
	ic = _cstr(item_code).strip()
	soik = _cstr(so_item_key).strip()
	if not psn or not ic or not frappe.db.table_exists("Planning sheet Item"):
		return ""
	filters = {"parent": psn, "item_code": ic}
	if soik:
		if frappe.db.has_column("Planning sheet Item", "sales_order_item"):
			rows = frappe.get_all(
				"Planning sheet Item",
				filters={**filters, "sales_order_item": soik},
				pluck="name",
				limit=1,
			)
			if rows:
				return rows[0]
		if frappe.db.has_column("Planning sheet Item", "so_item"):
			rows = frappe.get_all(
				"Planning sheet Item",
				filters={**filters, "so_item": soik},
				pluck="name",
				limit=1,
			)
			if rows:
				return rows[0]
	rows = frappe.get_all("Planning sheet Item", filters=filters, pluck="name", limit=1)
	return rows[0] if rows else ""


def _sync_legacy_planning_sheet_items_qty_from_board(planning_sheet_name):
	"""Copy rescaled BOM qty from Production board (Planning Table) → Planning sheet Item grid."""
	if not planning_sheet_name or not frappe.db.exists("Planning sheet", planning_sheet_name):
		return 0
	if not frappe.db.table_exists("Planning sheet Item") or not frappe.db.has_column("Planning sheet Item", "qty"):
		return 0
	if not frappe.db.table_exists("Planning Table") or not frappe.db.has_column("Planning Table", "qty"):
		return 0
	pt_fields = ["name", "item_code", "qty"]
	for col in ("sales_order_item", "so_item", "source_item"):
		if frappe.db.has_column("Planning Table", col):
			pt_fields.append(col)
	board_rows = (
		frappe.get_all(
			"Planning Table",
			filters={"parent": planning_sheet_name},
			fields=pt_fields,
			limit_page_length=0,
		)
		or []
	)
	updated = 0
	for br in board_rows:
		qty = flt(br.get("qty") or 0)
		pt_name = br.get("name")
		ic = _cstr(br.get("item_code")).strip()
		if not pt_name or not ic or qty <= 0:
			continue
		soi = _cstr(br.get("sales_order_item") or br.get("so_item")).strip()
		legacy_name = _cstr(br.get("source_item")).strip()
		target_psi = legacy_name if legacy_name and frappe.db.exists("Planning sheet Item", legacy_name) else ""
		if not target_psi:
			target_psi = _find_legacy_planning_sheet_item_row(planning_sheet_name, ic, soi)
		if not target_psi:
			continue
		cur = flt(frappe.db.get_value("Planning sheet Item", target_psi, "qty") or 0)
		if abs(cur - qty) > 1e-6:
			frappe.db.set_value("Planning sheet Item", target_psi, "qty", qty, update_modified=False)
			updated += 1
		if (
			frappe.db.has_column("Planning Table", "source_item")
			and legacy_name != target_psi
		):
			frappe.db.set_value("Planning Table", pt_name, "source_item", target_psi, update_modified=False)
	return updated


def _trace_108_from_107_item_code(item_code):
	"""Build a design-prefixed **108** trace from a process-107 item (same segments as 107 parse)."""
	return _trace_from_108_parse_body(_parse_107_item_code(item_code) or {})


def _is_107_mid_bopp_item(item_code):
	ic = str(item_code or "").strip()
	if not ic:
		return False
	return _lamination_process_from_item_code(ic) == "107" or (
		_item_process_prefix(ic) == "107" and "-107" in ic.upper()
	)


def _108_trace_maps_for_sheet(planning_sheet_name, pt_rows=None):
	"""108 FG traces on a sheet keyed by SO line, design prefix, and (design, width)."""
	out = {
		"has_108": False,
		"trace_by_soi": {},
		"trace_by_design": {},
		"trace_by_design_width": {},
		"default_108": "",
	}
	if not planning_sheet_name:
		return out
	if pt_rows is None:
		pt_rows = (
			frappe.get_all(
				"Planning Table",
				filters={"parent": planning_sheet_name},
				fields=["name", "item_code", "sales_order_item", "so_item"],
				limit_page_length=2000,
			)
			or []
		)
	for pr in pt_rows or []:
		icp = str(pr.get("item_code") or "")
		if _item_process_prefix(icp) != "108":
			continue
		tid = _parent_child_trace_id_from_item_code(icp)
		if not tid:
			continue
		out["has_108"] = True
		if not out["default_108"]:
			out["default_108"] = tid
		soik = _pt_soi_key(pr)
		if soik:
			out["trace_by_soi"][soik] = tid
		dp = _fg_design_prefix_from_item_code(icp)
		if dp:
			out["trace_by_design"][dp] = tid
			p108 = _parse_108_item_code(icp) or {}
			wc = (p108.get("width_code") or "").strip()
			if wc:
				out["trace_by_design_width"][(dp, wc)] = tid
	return out


def _resolve_108_family_trace(item_code, sales_order_item=None, planning_sheet_name=None, pt_rows=None):
	"""Trace for 107 mid-BOM rows on BOPP slitting (108) sheets — always ``108-…``, never ``107-…``."""
	ic = str(item_code or "").strip()
	if not _is_107_mid_bopp_item(ic):
		return ""
	soi = (sales_order_item or "").strip()
	if soi and frappe.db.exists("Sales Order Item", soi):
		try:
			soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
			if _item_process_prefix(soi_ic) == "108":
				return _parent_child_trace_id_from_item_code(soi_ic) or ""
		except Exception:
			pass
	maps = _108_trace_maps_for_sheet(planning_sheet_name, pt_rows=pt_rows) if planning_sheet_name else {}
	if maps.get("has_108"):
		if soi and soi in maps.get("trace_by_soi", {}):
			return maps["trace_by_soi"][soi]
		dp = _fg_design_prefix_from_item_code(ic)
		p107 = _parse_107_item_code(ic) or {}
		wc = (p107.get("width_code") or "").strip()
		if dp and wc and (dp, wc) in maps.get("trace_by_design_width", {}):
			return maps["trace_by_design_width"][(dp, wc)]
		if dp and dp in maps.get("trace_by_design", {}):
			return maps["trace_by_design"][dp]
		if maps.get("default_108"):
			return maps["default_108"]
	return ""


def _resolve_255_family_trace_for_107(item_code, sales_order_item=None, planning_sheet_name=None, pt_rows=None):
	"""255 FG trace for 107 mid-BOM rows on BOPP laminated sheet (255) — never native ``107-``."""
	if not _is_107_mid_bopp_item(item_code):
		return ""
	soi = (sales_order_item or "").strip()
	if soi and frappe.db.exists("Sales Order Item", soi):
		try:
			soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
			if _item_process_prefix(soi_ic) == "255" or _is_sheet_cutting_parent_process(soi_ic):
				tid = _parent_child_trace_id_from_item_code(soi_ic) or _trace_from_255_parent_on_sales_order_line(
					soi, planning_sheet_name, pt_rows
				)
				if tid:
					return tid
		except Exception:
			pass
	if planning_sheet_name:
		rows = pt_rows
		if rows is None:
			rows = (
				frappe.get_all(
					"Planning Table",
					filters={"parent": planning_sheet_name},
					fields=["item_code", "sales_order_item", "so_item", "custom_parent_child_trace_id"],
					limit_page_length=2000,
				)
				or []
			)
		for pr in rows or []:
			ric = _cstr(pr.get("item_code") if isinstance(pr, dict) else getattr(pr, "item_code", "")).strip()
			if not (_is_sheet_cutting_parent_process(ric) or _item_process_prefix(ric) == "255"):
				continue
			rsoi = _pt_soi_key(pr if isinstance(pr, dict) else frappe._dict(pr))
			if soi and rsoi and rsoi != soi:
				continue
			tid = _cstr(pr.get("custom_parent_child_trace_id") if isinstance(pr, dict) else getattr(pr, "custom_parent_child_trace_id", "")).strip()
			if not tid:
				tid = _parent_child_trace_id_from_item_code(ric) or _trace_from_255_parent_on_sales_order_line(
					rsoi, planning_sheet_name, rows
				)
			if tid:
				return tid
		t255 = _trace_from_255_parent_on_sales_order_line(soi, planning_sheet_name, rows)
		if t255:
			return t255
	return ""


def _resolve_lam107_planning_trace(item_code, sales_order_item=None, planning_sheet_name=None, pt_rows=None):
	"""107 rows on 108/255 sheets inherit parent FG trace; never keep a native ``107-`` trace."""
	if not _is_107_mid_bopp_item(item_code):
		return ""
	t108 = _resolve_108_family_trace(item_code, sales_order_item, planning_sheet_name, pt_rows)
	if t108 and not _trace_is_native_107_process(t108):
		return t108
	t255 = _resolve_255_family_trace_for_107(item_code, sales_order_item, planning_sheet_name, pt_rows)
	if t255 and not _trace_is_native_107_process(t255):
		return t255
	if planning_sheet_name:
		maps = _108_trace_maps_for_sheet(planning_sheet_name, pt_rows=pt_rows)
		if maps.get("default_108"):
			return maps["default_108"]
		t255 = _trace_from_255_parent_on_sales_order_line(
			(sales_order_item or "").strip(), planning_sheet_name, pt_rows
		)
		if t255:
			return t255
	return ""


def _parent_child_trace_id_for_planning_row(
	item_code, sales_order_item_name=None, planning_sheet_name=None, skip_main_parent=False
):
	"""Trace from ``item_code``; 107 mid-BOM on 108/255 sheets uses parent FG trace (never ``107-``)."""
	ic = str(item_code or "").strip()
	soi = (sales_order_item_name or "").strip()
	if soi and (_is_fabric_100_item_code(ic) or _is_printed_bopp_item_code(ic)):
		pt_rows_early = None
		so_by_early = {}
		if planning_sheet_name:
			pt_rows_early = (
				frappe.get_all(
					"Planning Table",
					filters={"parent": planning_sheet_name},
					fields=["item_code", "sales_order_item", "so_item", "custom_parent_child_trace_id"],
					limit_page_length=2000,
				)
				or []
			)
			_so_n = frappe.db.get_value("Planning sheet", planning_sheet_name, "sales_order")
			if _so_n:
				try:
					_so_d = frappe.get_doc("Sales Order", _so_n)
					so_by_early = {str(it.name): it for it in (_so_d.items or [])}
				except Exception:
					so_by_early = {}
		if not skip_main_parent:
			main_early = _main_parent_trace_for_so_line(soi, planning_sheet_name, pt_rows_early, so_by_early)
			if main_early:
				return main_early
	if _is_107_mid_bopp_item(ic):
		t107p = _resolve_lam107_planning_trace(ic, soi, planning_sheet_name)
		if t107p and not _trace_is_native_107_process(t107p):
			return t107p
		if soi and frappe.db.exists("Sales Order Item", soi):
			try:
				soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
				pp_so = _bom_item_process_code(soi_ic)
				if pp_so == "108":
					tg = _parent_child_trace_id_from_item_code(soi_ic)
					if tg:
						return tg
				if pp_so == "255" or _is_sheet_cutting_parent_process(soi_ic):
					tg = _parent_child_trace_id_from_item_code(soi_ic) or _trace_from_255_parent_on_sales_order_line(
						soi, planning_sheet_name
					)
					if tg:
						return tg
			except Exception:
				pass
		if planning_sheet_name:
			t255 = _trace_from_255_parent_on_sales_order_line(soi, planning_sheet_name)
			if t255:
				return t255
		t108 = _resolve_108_family_trace(ic, soi, planning_sheet_name)
		if t108 and not _trace_is_native_107_process(t108):
			return t108
		t255f = _resolve_255_family_trace_for_107(ic, soi, planning_sheet_name)
		if t255f and not _trace_is_native_107_process(t255f):
			return t255f
		# Standalone 107 FG on the SO line only — keep native 107-* trace.
		if soi:
			try:
				soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
				if _bom_item_process_code(soi_ic) == "107" and _lamination_process_from_item_code(soi_ic) == "107":
					return _parent_child_trace_id_from_item_code(ic)
			except Exception:
				pass
		return ""
	if _is_sheet_cutting_parent_process(ic):
		t_native = _parent_child_trace_id_from_item_code(ic)
		if t_native:
			return t_native
		t255 = _hyphen_trace_from_255_parse(_parse_255_item_code(ic) or {})
		if t255:
			return t255
	if soi and planning_sheet_name:
		t221_parent = _trace_from_221_parent_on_sales_order_line(soi, planning_sheet_name)
		if t221_parent:
			return t221_parent
		t255_parent = _trace_from_255_parent_on_sales_order_line(soi, planning_sheet_name)
		if t255_parent:
			return t255_parent
		t109_parent = _trace_from_109_parent_on_sales_order_line(soi, planning_sheet_name)
		if t109_parent:
			return t109_parent
		t_sc_fg = _trace_from_sheet_cutting_fg_on_sales_order_line(soi, planning_sheet_name)
		if t_sc_fg:
			return t_sc_fg
	fg_trace = _trace_from_253_254_sales_order_fg_row(ic, soi)
	if fg_trace:
		return fg_trace
	sc_trace = _resolve_sheet_cutting_parent_trace(ic, soi, planning_sheet_name)
	if sc_trace:
		return sc_trace
	t108 = _resolve_108_family_trace(ic, soi, planning_sheet_name)
	if t108:
		return t108
	return _parent_child_trace_id_from_item_code(ic)


def _printing_sales_order_item_from_row(row):
	"""Best-effort Sales Order Item link from table/board row variants."""
	if not row:
		return ""
	for key in ("sales_order_item", "salesOrderItem", "so_item", "sales_order_detail"):
		val = _cstr(row.get(key))
		if val:
			return val
	return ""


def _printing_design_name_from_row(row, design_code=None, so_item_name=None):
	"""Prefer real design name; never use the numeric design code as the name."""
	design_code = _cstr(design_code).strip()
	so_item_name = _cstr(so_item_name).strip() or _printing_sales_order_item_from_row(row)
	for val in (
		(row or {}).get("custom_design_name"),
		(row or {}).get("design_name"),
		_pb_design_name_from_sales_order_item(so_item_name),
	):
		name = _cstr(val).strip()
		if name and name != design_code:
			return name
	return ""


def _printing_design_attachment_from_row(row, so_item_name=None):
	"""Get print design attachment from Planning Table row, then Sales Order Item."""
	so_item_name = _cstr(so_item_name).strip() or _printing_sales_order_item_from_row(row)
	for val in (
		(row or {}).get("custom_design_attachment"),
		(row or {}).get("design_attachment"),
		(row or {}).get("custom_design_image"),
		(row or {}).get("design_image"),
		_printing_design_attachment_from_sales_order_item(so_item_name),
	):
		url = _cstr(val).strip()
		if url:
			return url
	return ""


def _printing_length_values_from_row(row):
	"""Resolve planned length fields from Planning Table, legacy PSI, then Sales Order Item."""
	row = row or {}
	meter = flt(row.get("meter") or row.get("planned_meter") or row.get("custom_meter") or 0)
	meter_per_roll = flt(row.get("meter_per_roll") or row.get("custom_meter_per_roll") or row.get("custom_meterperroll") or 0)
	no_of_rolls = flt(row.get("no_of_rolls") or row.get("custom_no_of_rolls") or 0)
	source_item = _cstr(row.get("source_item"))
	so_item_name = _printing_sales_order_item_from_row(row)
	psi_name = _cstr(row.get("psi_name") or row.get("itemName") or row.get("item_name") or row.get("name"))

	def _take(src):
		nonlocal meter, meter_per_roll, no_of_rolls, source_item, so_item_name
		if not src:
			return
		meter = meter or flt(src.get("meter") or src.get("planned_meter") or src.get("custom_meter") or 0)
		meter_per_roll = meter_per_roll or flt(src.get("meter_per_roll") or src.get("custom_meter_per_roll") or src.get("custom_meterperroll") or 0)
		no_of_rolls = no_of_rolls or flt(src.get("no_of_rolls") or src.get("custom_no_of_rolls") or 0)
		source_item = source_item or _cstr(src.get("source_item"))
		so_item_name = so_item_name or _cstr(src.get("sales_order_item") or src.get("so_item"))

	try:
		if psi_name and frappe.db.exists("Planning Table", psi_name):
			fields = [
				f
				for f in ("meter", "meter_per_roll", "no_of_rolls", "source_item", "sales_order_item", "so_item")
				if frappe.db.has_column("Planning Table", f)
			]
			if fields:
				_take(frappe.db.get_value("Planning Table", psi_name, fields, as_dict=True) or {})
	except Exception:
		pass

	try:
		if source_item and frappe.db.exists("Planning sheet Item", source_item):
			fields = [
				f
				for f in ("meter", "meter_per_roll", "no_of_rolls", "so_item")
				if frappe.db.has_column("Planning sheet Item", f)
			]
			if fields:
				_take(frappe.db.get_value("Planning sheet Item", source_item, fields, as_dict=True) or {})
	except Exception:
		pass

	try:
		if so_item_name and frappe.db.exists("Sales Order Item", so_item_name):
			fields = [
				f
				for f in ("custom_meter", "custom_meter_per_roll", "custom_meterperroll", "custom_no_of_rolls")
				if frappe.db.has_column("Sales Order Item", f)
			]
			if fields:
				_take(frappe.db.get_value("Sales Order Item", so_item_name, fields, as_dict=True) or {})
	except Exception:
		pass
	return meter, meter_per_roll, no_of_rolls


def _printing_planned_meter_from_row(row, width_inch=0, gsm=0):
	"""Planned meters: stored meter first, then meter/roll * rolls, then kg/GSM/width."""
	meter, meter_per_roll, no_of_rolls = _printing_length_values_from_row(row)
	if meter > 0:
		return meter
	if meter_per_roll > 0 and no_of_rolls > 0:
		return meter_per_roll * no_of_rolls
	qty = flt((row or {}).get("qty") or 0)
	width_inch = flt(width_inch or (row or {}).get("width_inch") or 0)
	gsm = flt(gsm or (row or {}).get("gsm") or 0)
	if qty > 0 and width_inch > 0 and gsm > 0:
		return round((qty * 1000) / (gsm * width_inch * 0.0254))
	return 0


def _is_white_tint_yes(val):
	s = str(val or "").strip().lower()
	return s in ("yes", "y", "1", "true")


def _normalized_white_tint_select(raw):
	"""Normalize free-text / legacy values to Yes / No / empty for Planning Table Select."""
	s = str(raw or "").strip()
	if not s or s == "0":
		return ""
	if _is_white_tint_yes(s):
		return "Yes"
	if s.lower() in ("no", "n", "false"):
		return "No"
	return s


def _white_tint_yes_no_from_sales_order_item(so_item_name):
	"""Yes/No from Sales Order Item custom fields (site-specific)."""
	if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
		return ""
	try:
		meta = frappe.get_meta("Sales Order Item")
	except Exception:
		return ""
	for fn in ("custom_white_tint", "custom_white_tin", "custom_is_white_tint", "white_tint"):
		try:
			if not meta.has_field(fn):
				continue
			v = frappe.db.get_value("Sales Order Item", so_item_name, fn)
			vs = str(v or "").strip()
			if not vs:
				continue
			n = _normalized_white_tint_select(vs)
			if n:
				return n
		except Exception:
			continue
	return ""


def _effective_white_tint_for_pb_planning_row(pt_row_name, so_item_name):
	"""Prefer normalized value on Planning Table; otherwise Sales Order; ignore legacy finish digit ``0``."""
	cur = ""
	if pt_row_name:
		cur = str(frappe.db.get_value("Planning Table", pt_row_name, "custom_white_tint") or "").strip()
	n_cur = _normalized_white_tint_select(cur)
	if n_cur:
		return n_cur
	return _white_tint_yes_no_from_sales_order_item(so_item_name) or ""


def _total_colours_token_for_printed_bopp(ndc_token, white_tint_str):
	"""
	Total print colours = design cylinder token (e.g. ``2C``) plus one when white tint is Yes.
	"""
	tok = (ndc_token or "").strip()
	if not tok:
		return ""
	m = re.match(r"^(\d+)\s*C\b", tok, re.I)
	if not m:
		return tok
	n = cint(m.group(1))
	if n <= 0:
		return tok
	if _is_white_tint_yes(white_tint_str):
		n += 1
	return f"{n}C"


def _pb_total_colours_for_display(ndc_token, white_tint_str=None, pt_row_name=None, so_item_name=None):
	"""Printed BOPP table / API: total colours from design count + planning-row white tint (not stale SO-only)."""
	ndc = _cstr(ndc_token).strip()
	if not ndc:
		return ""
	wt = _cstr(white_tint_str).strip()
	if pt_row_name:
		wt = _effective_white_tint_for_pb_planning_row(pt_row_name, so_item_name) or wt
	elif so_item_name and not wt:
		wt = _white_tint_yes_no_from_sales_order_item(so_item_name) or wt
	return _total_colours_token_for_printed_bopp(ndc, wt) or ndc


def _apply_printed_bopp_total_colours_to_row(row):
	"""
	Persist ``custom_total_no_of_colours`` on a Planning Table child row from
	``custom_no_of_design_colours`` (or PB item code) + ``custom_white_tint``.
	Used on child validate and on Planning sheet save so the desk grid matches the Printed BOPP table API.
	"""
	try:
		if row is None:
			return False
		dt = getattr(row, "doctype", None) or ""
		if not dt or not frappe.db.has_column(dt, "custom_total_no_of_colours"):
			return False
		if not _matches_printed_bopp_board_row(row):
			return False
		ic = getattr(row, "item_code", None)
		if not ic:
			return False
		soi = _printing_sales_order_item_from_row(row)
		ndc = str(getattr(row, "custom_no_of_design_colours", None) or "").strip()
		if not ndc and soi:
			so_cyl = _pb_cylinder_fields_from_sales_order_item(soi)
			ndc = _cstr(so_cyl.get("custom_no_of_design_colours")).strip()
		if not ndc:
			pb_nm = frappe.db.get_value("Item", ic, "item_name") or ""
			ndc = (_printed_bopp_design_colours_token(ic, pb_nm) or "").strip()
		if not ndc:
			return False
		wt = str(getattr(row, "custom_white_tint", None) or "").strip()
		tnc = _total_colours_token_for_printed_bopp(ndc, wt) or ndc
		setattr(row, "custom_total_no_of_colours", tnc)
		return True
	except Exception:
		return False


def _matches_printed_bopp_board_row(it):
	"""Rows for Printed BOPP Film board/table: PB-*, long-form PRINTED BOPP - …, or VR BOPP printing unit."""
	if not it:
		return False
	try:
		ic = str((it.get("item_code") if isinstance(it, dict) else getattr(it, "item_code", None)) or "").strip().upper()
		u = str((it.get("unit") if isinstance(it, dict) else getattr(it, "unit", None)) or "").strip()
	except Exception:
		return False
	if u == PRINTED_BOPP_FILM_UNIT:
		return True
	if ic.startswith("PB-"):
		return True
	if "PRINTED" in ic and "BOPP" in ic:
		return True
	return False


def _scaled_component_qty_from_bom_row(bom_name, bom_row, parent_so_qty):
	bom = frappe.get_doc("BOM", bom_name)
	fg_qty = flt(bom.quantity) or 1.0
	if fg_qty <= 0:
		fg_qty = 1.0
	return (flt(parent_so_qty) or 0) * (flt(getattr(bom_row, "qty", 0)) or 0) / fg_qty


def _resolve_107_child_components(lam_item_code):
	parsed = _parse_107_item_code(lam_item_code)
	design_code = (parsed.get("design_code") or "").strip().upper()
	if not design_code:
		m = re.match(r"^([A-Z0-9]+)-107", str(lam_item_code or "").strip().upper())
		if m:
			design_code = (m.group(1) or "").strip().upper()
	bom = _resolve_lamination_bom(lam_item_code)
	if not bom:
		return {}
	fab = _pick_first_100_from_bom_items(bom.items, lam_item_code)
	pb = _pick_exact_pb_from_bom_items(bom.items, design_code)
	return {
		"bom_name": bom.name,
		"design_code": design_code,
		"fabric": fab,
		"pb": pb,
		"parsed": parsed,
	}


def _planning_row_dict_107_lamination_extras(
	item_code, parsed107_early, sales_order_item_name=None, planning_sheet_name=None
):
    """
    Planning Table / Planning sheet Item fields for the 107 PARENT row (and shared finishing on PB child).
    - Finishing (mg/mc) from parsed item-code finishes.
    - Parent/child trace id: 108/255 sheet parents only — never native ``107-`` on mid-BOM rows.
    - White tint: Yes/No from Sales Order Item (not the second finish digit).
    - BOPP / LAM GSM from parsed letter codes.
    - Cylinder Type is NOT set here; it belongs only on the PB child row.
    """
    out = {}
    if not (LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(item_code or "")) == "107"):
        return out
    p107r = parsed107_early or (_parse_107_item_code(item_code) or {})
    trace_id = _parent_child_trace_id_for_planning_row(
        item_code, sales_order_item_name, planning_sheet_name
    )
    if trace_id and _trace_is_native_107_process(trace_id):
        trace_id = ""
    if trace_id and (
        frappe.db.has_column("Planning Table", "custom_parent_child_trace_id")
        or frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id")
    ):
        out["custom_parent_child_trace_id"] = trace_id
    mg = (p107r.get("finish_matte_glossy") or "").strip() or "0"
    mc = (p107r.get("finish_metallic_cooler") or "").strip() or "0"
    fin_txt = _lamination_finishing_display_text(mg, mc)
    if fin_txt and (
        frappe.db.has_column("Planning Table", "custom_finishing")
        or frappe.db.has_column("Planning sheet Item", "custom_finishing")
    ):
        out["custom_finishing"] = fin_txt
    if sales_order_item_name:
        wt = _white_tint_yes_no_from_sales_order_item(sales_order_item_name)
        if wt and (
            frappe.db.has_column("Planning Table", "custom_white_tint")
            or frappe.db.has_column("Planning sheet Item", "custom_white_tint")
        ):
            out["custom_white_tint"] = wt
    bgv = cint(p107r.get("bopp_gsm") or 0)
    if bgv > 0:
        if frappe.db.has_column("Planning Table", "custom_bopp_gsm"):
            out["custom_bopp_gsm"] = bgv
        if frappe.db.has_column("Planning sheet Item", "custom_bopp_gsm"):
            out["custom_bopp_gsm"] = bgv
    lgv = cint(p107r.get("lam_gsm") or 0)
    if lgv > 0:
        if frappe.db.has_column("Planning Table", "custom_lam_gsm"):
            out["custom_lam_gsm"] = lgv
        if frappe.db.has_column("Planning sheet Item", "custom_lam_gsm"):
            out["custom_lam_gsm"] = lgv
    dcode = _cstr(p107r.get("design_code")).strip()
    if dcode and (
        frappe.db.has_column("Planning Table", "custom_design_code")
        or frappe.db.has_column("Planning sheet Item", "custom_design_code")
    ):
        out["custom_design_code"] = dcode
    dc_so = _pb_design_code_from_sales_order_item(sales_order_item_name)
    if dc_so and not out.get("custom_design_code") and (
        frappe.db.has_column("Planning Table", "custom_design_code")
        or frappe.db.has_column("Planning sheet Item", "custom_design_code")
    ):
        out["custom_design_code"] = dc_so
    da_so = _printing_design_attachment_from_sales_order_item(sales_order_item_name)
    if da_so and (
        frappe.db.has_column("Planning Table", "custom_design_attachment")
        or frappe.db.has_column("Planning sheet Item", "custom_design_attachment")
    ):
        out["custom_design_attachment"] = da_so
    col_so = _pb_design_colour_from_sales_order_item(sales_order_item_name)
    if col_so and (
        frappe.db.has_column("Planning Table", "custom_design_colour")
        or frappe.db.has_column("Planning sheet Item", "custom_design_colour")
    ):
        out["custom_design_colour"] = col_so
    if dcode:
        for _kdm, _vdm in (_design_master_extra_fields(dcode) or {}).items():
            if not _vdm or not _cstr(_vdm).strip():
                continue
            if _kdm in out and _cstr(out.get(_kdm)).strip():
                continue
            if frappe.db.has_column("Planning Table", _kdm) or frappe.db.has_column("Planning sheet Item", _kdm):
                out[_kdm] = _vdm
        dn_dm = _cstr((_design_master_extra_fields(dcode) or {}).get("custom_design_name")).strip()
        if dn_dm and (
            frappe.db.has_column("Planning Table", "custom_design_name")
            or frappe.db.has_column("Planning sheet Item", "custom_design_name")
        ):
            out.setdefault("custom_design_name", dn_dm)
    return out


def _planning_row_dict_255_lamination_extras(item_code, parsed255_early, sales_order_item_name=None):
	"""Planning fields for 255 sheet-cutting parent rows (same extras pattern as 107)."""
	out = {}
	if _item_process_prefix(str(item_code or "")) != "255":
		return out
	p255 = parsed255_early or (_parse_255_item_code(item_code) or {})
	trace_id = _parent_child_trace_id_from_item_code(item_code)
	if trace_id and (
		frappe.db.has_column("Planning Table", "custom_parent_child_trace_id")
		or frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id")
	):
		out["custom_parent_child_trace_id"] = trace_id
	mg = (p255.get("finish_matte_glossy") or "").strip() or "0"
	mc = (p255.get("finish_metallic_cooler") or "").strip() or "0"
	fin_txt = _lamination_finishing_display_text(mg, mc)
	if fin_txt and (
		frappe.db.has_column("Planning Table", "custom_finishing")
		or frappe.db.has_column("Planning sheet Item", "custom_finishing")
	):
		out["custom_finishing"] = fin_txt
	if sales_order_item_name:
		wt = _white_tint_yes_no_from_sales_order_item(sales_order_item_name)
		if wt and (
			frappe.db.has_column("Planning Table", "custom_white_tint")
			or frappe.db.has_column("Planning sheet Item", "custom_white_tint")
		):
			out["custom_white_tint"] = wt
	bgv = cint(p255.get("bopp_gsm") or 0)
	if bgv > 0:
		if frappe.db.has_column("Planning Table", "custom_bopp_gsm"):
			out["custom_bopp_gsm"] = bgv
		if frappe.db.has_column("Planning sheet Item", "custom_bopp_gsm"):
			out["custom_bopp_gsm"] = bgv
	lgv = cint(p255.get("lam_gsm") or 0)
	if lgv > 0:
		if frappe.db.has_column("Planning Table", "custom_lam_gsm"):
			out["custom_lam_gsm"] = lgv
		if frappe.db.has_column("Planning sheet Item", "custom_lam_gsm"):
			out["custom_lam_gsm"] = lgv
	dcode = _cstr(p255.get("design_code")).strip()
	if dcode and (
		frappe.db.has_column("Planning Table", "custom_design_code")
		or frappe.db.has_column("Planning sheet Item", "custom_design_code")
	):
		out["custom_design_code"] = dcode
	dc_so = _pb_design_code_from_sales_order_item(sales_order_item_name)
	if dc_so and not out.get("custom_design_code") and (
		frappe.db.has_column("Planning Table", "custom_design_code")
		or frappe.db.has_column("Planning sheet Item", "custom_design_code")
	):
		out["custom_design_code"] = dc_so
	da_so = _printing_design_attachment_from_sales_order_item(sales_order_item_name)
	if da_so and (
		frappe.db.has_column("Planning Table", "custom_design_attachment")
		or frappe.db.has_column("Planning sheet Item", "custom_design_attachment")
	):
		out["custom_design_attachment"] = da_so
	col_so = _pb_design_colour_from_sales_order_item(sales_order_item_name)
	if col_so and (
		frappe.db.has_column("Planning Table", "custom_design_colour")
		or frappe.db.has_column("Planning sheet Item", "custom_design_colour")
	):
		out["custom_design_colour"] = col_so
	return out


def _planning_row_dict_108_slitting_extras(item_code, parsed108_early, sales_order_item_name=None):
	"""Planning fields for 108 slitting parent rows (BOPP stack letters + finishing; same shape as 255 extras)."""
	out = {}
	if _item_process_prefix(str(item_code or "")) != "108":
		return out
	p108 = parsed108_early or (_parse_108_item_code(item_code) or {})
	trace_id = _parent_child_trace_id_from_item_code(item_code)
	if trace_id and (
		frappe.db.has_column("Planning Table", "custom_parent_child_trace_id")
		or frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id")
	):
		out["custom_parent_child_trace_id"] = trace_id
	mg = (p108.get("finish_matte_glossy") or "").strip() or "0"
	mc = (p108.get("finish_metallic_cooler") or "").strip() or "0"
	fin_txt = _lamination_finishing_display_text(mg, mc)
	if fin_txt and (
		frappe.db.has_column("Planning Table", "custom_finishing")
		or frappe.db.has_column("Planning sheet Item", "custom_finishing")
	):
		out["custom_finishing"] = fin_txt
	if sales_order_item_name:
		wt = _white_tint_yes_no_from_sales_order_item(sales_order_item_name)
		if wt and (
			frappe.db.has_column("Planning Table", "custom_white_tint")
			or frappe.db.has_column("Planning sheet Item", "custom_white_tint")
		):
			out["custom_white_tint"] = wt
	bgv = cint(p108.get("bopp_gsm") or 0)
	if bgv > 0:
		if frappe.db.has_column("Planning Table", "custom_bopp_gsm"):
			out["custom_bopp_gsm"] = bgv
		if frappe.db.has_column("Planning sheet Item", "custom_bopp_gsm"):
			out["custom_bopp_gsm"] = bgv
	lgv = cint(p108.get("lam_gsm") or 0)
	if lgv > 0:
		if frappe.db.has_column("Planning Table", "custom_lam_gsm"):
			out["custom_lam_gsm"] = lgv
		if frappe.db.has_column("Planning sheet Item", "custom_lam_gsm"):
			out["custom_lam_gsm"] = lgv
	dcode = _cstr(p108.get("design_code")).strip()
	if dcode and (
		frappe.db.has_column("Planning Table", "custom_design_code")
		or frappe.db.has_column("Planning sheet Item", "custom_design_code")
	):
		out["custom_design_code"] = dcode
	dc_so = _pb_design_code_from_sales_order_item(sales_order_item_name)
	if dc_so and not out.get("custom_design_code") and (
		frappe.db.has_column("Planning Table", "custom_design_code")
		or frappe.db.has_column("Planning sheet Item", "custom_design_code")
	):
		out["custom_design_code"] = dc_so
	da_so = _printing_design_attachment_from_sales_order_item(sales_order_item_name)
	if da_so and (
		frappe.db.has_column("Planning Table", "custom_design_attachment")
		or frappe.db.has_column("Planning sheet Item", "custom_design_attachment")
	):
		out["custom_design_attachment"] = da_so
	col_so = _pb_design_colour_from_sales_order_item(sales_order_item_name)
	if col_so and (
		frappe.db.has_column("Planning Table", "custom_design_colour")
		or frappe.db.has_column("Planning sheet Item", "custom_design_colour")
	):
		out["custom_design_colour"] = col_so
	return out


def _parent_child_trace_id_from_item_code(item_code):
	"""
	Trace ID format (where PPP|QQQ|CCC|GGG|WWWW applies):
	  <process>-<quality>-<colour>-<gsm>-<width>[-suffix]
	- QQQ: quality / format (digits 3-6), included for uniqueness across SO lines.
	Examples:
	- 1031052210500050 -> 103-105-221-050-0050
	- 1041030010231475-B1 -> 104-103-001-023-1475-B1 (suffix lam / variant)
	106 (design-first): <design>-106-<quality>-<colour>-<gsm>-<width_mm>[-lam code]
	107 (design-first): 107-<quality letter>-<colour>-<stack gsm>-<width code> (stack = fabric+BOPP+lam; lam omitted when stack used).
	255 (design-first): 255-<quality letter>-<colour>-<stack gsm>-<width code> — BOM children inherit this same string from the 255 parent row.
	"""
	ic = str(item_code or "").strip()
	if _lamination_process_from_item_code(ic) == "107":
		t107 = _trace_from_107_parse_body(_parse_107_item_code(ic) or {})
		if t107:
			return t107
	if _lamination_process_from_item_code(ic) == "255" or _item_process_prefix(ic) == "255":
		p255 = _parse_255_item_code(ic) or {}
		t255 = _hyphen_trace_from_255_parse(p255)
		if t255:
			return t255
		return ""
	# 253/254 must resolve here — ``_is_sheet_cutting_child_process`` includes these prefixes and would otherwise return "".
	_ic_proc = _item_process_prefix(ic)
	if _ic_proc == "253":
		_t253 = _hyphen_trace_from_laminated_sheet_parse(_parse_253_item_code(ic) or {}, "253")
		if _t253:
			return _t253
	if _ic_proc == "254":
		_t254 = _hyphen_trace_from_laminated_sheet_parse(_parse_254_item_code(ic) or {}, "254")
		if _t254:
			return _t254
	if _item_process_prefix(ic) == "108" or re.search(r"-108(?=[A-Z])", ic.upper()):
		t108 = _trace_from_108_parse_body(_parse_108_item_code(ic) or {})
		if t108:
			return t108
	# 105 (design-first): <design>-105-<quality>-<colour>-<gsm>-<width_mm>
	if "-105" in ic.upper() or ic.strip().startswith("105"):
		t105 = _trace_from_105_parse_body(_parse_105_item_code(ic) or {})
		if t105:
			return t105
	process = _item_process_prefix(ic)
	if process == "104" or _lamination_process_from_item_code(ic) == "104":
		t104 = _trace_from_104_parse_body(_parse_104_item_code(ic) or {})
		if t104:
			return t104
	if process == "251":
		p = _parse_sheet_cutting_item_code(ic)
		if not p:
			return ""
		return "251-{0}-{1}-{2}-{3}".format(
			_cstr(p.get("quality_code")),
			_cstr(p.get("colour_code")),
			_cstr(p.get("gsm")).zfill(3),
			_cstr(p.get("series_id")),
		)
	if process == "252":
		return _trace_from_252_parse_body(_parse_sheet_cutting_item_code(ic) or {})
	if process in ("221", "224"):
		from production_entry.production_planning.box_bag_api import _parse_box_bag_item_code
		p = _parse_box_bag_item_code(ic)
		segs = [
			_cstr(p.get("design_code")).strip(),
			process
		]
		q = _cstr(p.get("quality_letter")).strip()
		if q: segs.append(q)
		gsm = _cstr(p.get("fabric_gsm")).strip()
		if gsm and gsm != "0": segs.append(gsm)
		cc = _cstr(p.get("colour_code")).strip()
		if cc: segs.append(cc)
		bs = _cstr(p.get("bag_size_id")).strip()
		if bs: segs.append(bs)
		fin = _cstr(p.get("finishing_code")).strip()
		if fin: segs.append(fin)
		return "-".join(segs)
	if process in W_CUT_D_CUT_FG_PROCESS_CODES:
		from production_entry.production_planning.box_bag_api import _parse_dcut_bag_item_code
		p = _parse_dcut_bag_item_code(ic)
		segs = [
			_cstr(p.get("design_code")).strip(),
			_cstr(p.get("bag_size_id")).strip(),
			process,
		]
		q = _cstr(p.get("quality_letter")).strip()
		if q: segs.append(q)
		cc = _cstr(p.get("colour_code")).strip()
		if cc: segs.append(cc)
		total_gsm = cint(p.get("total_gsm") or 0)
		if total_gsm > 0: segs.append(str(total_gsm))
		fin = _cstr(p.get("finishing_code")).strip()
		if fin: segs.append(fin)
		return "-".join([s for s in segs if _cstr(s)])
	if process in BOPP_BOX_BAG_PROCESS_CODES:
		from production_entry.production_planning.bopp_bag_api import _parse_bopp_bag_item_code
		p = _parse_bopp_bag_item_code(ic)
		# Trace format: design-numcolors-process-size-quality-color-totalgsm-finishing
		segs = [_cstr(p.get("design_code")).strip()]
		nc = _cstr(p.get("num_colors")).strip()
		if nc: segs.append(nc + "C")
		segs.append(process)
		bs = _cstr(p.get("bag_size_id")).strip()
		if bs: segs.append(bs)
		q = _cstr(p.get("quality_letter")).strip()
		if q: segs.append(q)
		cc = _cstr(p.get("colour_code")).strip()
		if cc: segs.append(cc)
		total_gsm = int(p.get("total_gsm") or 0)
		if total_gsm > 0: segs.append(str(total_gsm))
		fin = _cstr(p.get("finishing_code")).strip()
		if fin: segs.append(fin)
		return "-".join(segs)
	# 109 laminated slitting: 109QQQCCCGGGWWWW[-lam_suffix]
	if process == "109":
		p = _parse_109_item_code(ic) or {}
		if (p.get("colour_code") or "").strip() or (p.get("gsm") or "").strip() or (p.get("width_code") or "").strip():
			qc = _cstr(p.get("quality_code")).strip()
			cc = _cstr(p.get("colour_code")).strip()
			gsm = _cstr(p.get("gsm")).strip()
			wc = _cstr(p.get("width_code")).strip()
			lc = _cstr(p.get("lam_gsm_code")).strip()
			segs = ["109"]
			if qc:
				segs.append(qc)
			if cc:
				segs.append(cc)
			if gsm:
				segs.append(str(gsm).zfill(3))
			if wc:
				segs.append(str(wc).zfill(4))
			if lc:
				segs.append(lc)
			if len(segs) > 1:
				return "-".join(segs)
	# 106 laminated printing: <design>-106QQQCCCGGGWWWW[-suffix]
	if process == "106" or "-106" in ic.upper():
		t106 = _trace_from_106_parse_body(_parse_106_item_code(ic) or {})
		if t106:
			return t106
	# Fabric 100: 100QQQCCCGGGWWWW (same digit layout as 102/103/104 body)
	if process == "100":
		left = ic
		suffix = ""
		if "-" in ic:
			left, right = ic.rsplit("-", 1)
			suffix = str(right or "").strip().upper()
		digits = "".join(ch for ch in left if ch.isdigit())
		if len(digits) >= 16 and digits.startswith("100"):
			qual = digits[3:6]
			colour = digits[6:9]
			gsm = digits[9:12]
			width = digits[12:16]
			if colour and gsm and width:
				if suffix:
					return f"100-{qual}-{colour}-{gsm}-{width}-{suffix}"
				return f"100-{qual}-{colour}-{gsm}-{width}"
		return ""
	if len(ic) < 16:
		return ""
	if process not in ("102", "103", "104"):
		return ""

	left = ic
	suffix = ""
	if "-" in ic:
		left, right = ic.rsplit("-", 1)
		suffix = str(right or "").strip().upper()

	digits = "".join(ch for ch in left if ch.isdigit())
	if len(digits) < 16:
		return ""

	quality = digits[3:6]
	colour = digits[6:9]      # positions 6-8: colour code
	gsm = digits[9:12]        # positions 9-11: gsm
	width = digits[12:16]     # positions 12-15: width
	
	if not colour or not gsm or not width:
		return ""
	
	if suffix:
		return f"{process}-{quality}-{colour}-{gsm}-{width}-{suffix}"
	return f"{process}-{quality}-{colour}-{gsm}-{width}"


def _parse_105_item_code(item_code):
	"""
	Process 105 printing item code:
	  <design>-105<quality><colour><gsm><width_mm>
	Example:
	  6001-1050011010301600
	    design=6001, process=105, quality=001, colour=101, gsm=030, width_mm=1600
	"""
	code = str(item_code or "").strip().upper()
	if not code:
		return {}
	m = re.match(
		r"^(?P<design>[A-Z0-9]+)-105(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<width>\d{4})$",
		code,
	)
	if not m:
		return {}
	g = m.groupdict()
	return {
		"design_code": (g.get("design") or "").strip(),
		"process": "105",
		"quality_code": (g.get("quality") or "").strip(),
		"colour_code": (g.get("colour") or "").strip(),
		"gsm": (g.get("gsm") or "").strip(),
		"width_mm": (g.get("width") or "").strip(),
	}


def _parse_106_item_code(item_code):
	"""
	Process 106 laminated printing item:
	  <design>-106<quality><colour><gsm><width_mm>-<lam_gsm_code>
	  <design>-106-<quality>-<colour>-<gsm>-<width_mm>[-lam]
	Example: 002-1061085211051600-A / 6002-106-105-221-110-0405-A
	"""
	code = re.sub(r"\s+", "", str(item_code or "").strip().upper())
	if not code:
		return {}

	def _row(design, gd):
		lam = (gd.get("lam") or "").strip().upper()
		return {
			"design_code": (design or "").strip(),
			"process": "106",
			"quality_code": (gd.get("quality") or "").strip(),
			"colour_code": (gd.get("colour") or "").strip(),
			"gsm": (gd.get("gsm") or "").strip(),
			"width_mm": (gd.get("width") or "").strip(),
			"lam_gsm_code": lam,
			"lam_gsm": cint(_LAM_GSM_SUFFIX_MAP.get(lam, 0) or 0),
		}

	m = re.match(
		r"^(?P<design>[A-Z0-9]+)-106-(?P<quality>[A-Z0-9]{1,3})-(?P<colour>\d{3})-(?P<gsm>\d{3})-(?P<width>\d{4})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m:
		return _row((m.group("design") or "").strip(), m.groupdict())
	m2 = re.match(
		r"^(?P<design>[A-Z0-9]+)-106(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<width>\d{4})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m2:
		return _row((m2.group("design") or "").strip(), m2.groupdict())
	return {}


def _parse_109_item_code(item_code):
	"""
	Process 109 laminated slitting item:
	  109<quality><colour><gsm><width>-<lam_gsm_code>
	Example: 1091000010800050-A
	"""
	code = str(item_code or "").strip().upper()
	m = re.match(
		r"^109(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<width>\d{4})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if not m:
		return {}
	g = m.groupdict()
	return {
		"process": "109",
		"quality_code": (g.get("quality") or "").strip(),
		"colour_code": (g.get("colour") or "").strip(),
		"gsm": (g.get("gsm") or "").strip(),
		"width_code": (g.get("width") or "").strip(),
		"lam_gsm_code": (g.get("lam") or "").strip(),
		"lam_gsm": cint(_LAM_GSM_SUFFIX_MAP.get((g.get("lam") or "").strip(), 0) or 0),
	}


def _is_printing_parent_process(item_code):
	return _item_process_prefix(item_code) in ("105", "106")


def _is_slitting_parent_process(item_code):
	return _item_process_prefix(item_code) in ("103", "108", "109", "110")


def _is_sheet_cutting_child_process(item_code):
	"""Rows that inherit trace from sheet-cutting FG (251–255) on the same SO line — not the FG rows themselves."""
	ic = str(item_code or "").strip()
	if not ic:
		return False
	pp = _item_process_prefix(ic)
	if pp in ("251", "252", "253", "254", "255") or _lamination_process_from_item_code(ic) == "255":
		return False
	if pp in ("100", "104", "105", "106", "107") or ic.startswith("100"):
		return True
	if _lamination_process_from_item_code(ic) in ("104", "107"):
		return True
	return False


def _is_sheet_cutting_parent_process(item_code):
	"""Sheet-cutting FG on the SO line (251–255) — defines parent trace for BOM children on the same line."""
	ic = str(item_code or "").strip()
	if not ic:
		return False
	pp = _item_process_prefix(ic)
	if pp in ("251", "252", "253", "254"):
		return True
	return pp == "255" or _lamination_process_from_item_code(ic) == "255"


def _sheet_cutting_canonical_parent_trace_id(item_code, sibling_rows=None, sales_order_item=None):
	"""
	One parent trace id per sheet-cutting SO line.
	251 rows keep 251-* traces; 252/253/254/255 rows keep their own process traces.
	"""
	ic = str(item_code or "").strip().upper()
	if not ic:
		return ""
	soi = _cstr(sales_order_item).strip()
	rows = sibling_rows or []
	pp = _item_process_prefix(ic)

	if pp == "251":
		return _parent_child_trace_id_from_item_code(ic)

	# Prefer an explicit 252 row on the same SO line (native parent-id shape).
	if soi and rows:
		for r in rows:
			ric = _cstr(r.get("item_code") if isinstance(r, dict) else getattr(r, "item_code", "")).strip()
			if _item_process_prefix(ric) != "252":
				continue
			rsoi = _cstr(
				(r.get("sales_order_item") if isinstance(r, dict) else getattr(r, "sales_order_item", None))
				or (r.get("so_item") if isinstance(r, dict) else getattr(r, "so_item", None))
			).strip()
			if rsoi != soi:
				continue
			t = _trace_from_252_parse_body(_parse_sheet_cutting_item_code(ric) or {})
			if t:
				return t

	if pp == "252":
		return _trace_from_252_parse_body(_parse_sheet_cutting_item_code(ic) or {})

	if pp == "255" or _lamination_process_from_item_code(ic) == "255":
		t255 = _hyphen_trace_from_255_parse(_parse_255_item_code(ic) or {})
		if t255:
			return t255
		return ""

	if pp == "253":
		return _hyphen_trace_from_laminated_sheet_parse(_parse_253_item_code(ic) or {}, "253")

	if pp == "254":
		return _hyphen_trace_from_laminated_sheet_parse(_parse_254_item_code(ic) or {}, "254")

	return ""


def _resolve_sheet_cutting_parent_trace(item_code, sales_order_item=None, planning_sheet_name=None, pt_rows=None):
	"""255 parent trace for sheet-cutting; children inherit from 255 (or 252) on the same SO line."""
	ic = str(item_code or "").strip()
	if not ic:
		return ""
	if _is_sheet_cutting_parent_process(ic):
		t255 = _hyphen_trace_from_255_parse(_parse_255_item_code(ic) or {})
		if t255:
			return t255
		rows = pt_rows
		if rows is None and planning_sheet_name:
			rows = (
				frappe.get_all(
					"Planning Table",
					filters={"parent": planning_sheet_name},
					fields=["item_code", "sales_order_item", "so_item"],
					limit_page_length=2000,
				)
				or []
			)
		return _sheet_cutting_canonical_parent_trace_id(ic, rows, sales_order_item)

	if not _is_sheet_cutting_child_process(ic):
		return ""

	soi = _cstr(sales_order_item).strip()
	rows = pt_rows
	if rows is None and planning_sheet_name:
		rows = (
			frappe.get_all(
				"Planning Table",
				filters={"parent": planning_sheet_name},
				fields=["item_code", "sales_order_item", "so_item"],
				limit_page_length=2000,
			)
			or []
		)
	if rows:
		for r in rows:
			ric = _cstr(r.get("item_code") if isinstance(r, dict) else getattr(r, "item_code", "")).strip()
			if not _is_sheet_cutting_parent_process(ric):
				continue
			rsoi = _cstr(
				(r.get("sales_order_item") if isinstance(r, dict) else getattr(r, "sales_order_item", None))
				or (r.get("so_item") if isinstance(r, dict) else getattr(r, "so_item", None))
			).strip()
			if soi and rsoi and rsoi != soi:
				continue
			t = _sheet_cutting_canonical_parent_trace_id(ric, rows, soi or rsoi)
			if t:
				return t
	return _sheet_cutting_canonical_parent_trace_id(ic, rows, soi)


def _stage3_lam_gsm_from_item_code(item_code):
	proc = _item_process_prefix(item_code)
	if proc == "106":
		return cint((_parse_106_item_code(item_code) or {}).get("lam_gsm") or 0)
	if proc == "109":
		return cint((_parse_109_item_code(item_code) or {}).get("lam_gsm") or 0)
	if proc == "253":
		return cint((_parse_253_item_code(item_code) or {}).get("lam_gsm") or 0)
	if proc == "254":
		return cint((_parse_254_item_code(item_code) or {}).get("lam_gsm") or 0)
	if proc == "255" or _lamination_process_from_item_code(str(item_code or "")) == "255":
		return cint((_parse_255_item_code(item_code) or {}).get("lam_gsm") or 0)
	if proc == "108":
		return cint((_parse_108_item_code(item_code) or {}).get("lam_gsm") or 0)
	return 0


def _printing_color_from_item_code(item_code):
	proc = _item_process_prefix(item_code)
	if proc == "105":
		parsed = _parse_105_item_code(item_code) or {}
	elif proc == "106":
		parsed = _parse_106_item_code(item_code) or {}
	else:
		return ""
	colour_code = _cstr(parsed.get("colour_code"))
	if not colour_code:
		return ""
	try:
		return _get_color_by_code(colour_code) or colour_code
	except Exception:
		return colour_code


def _set_trace_id_if_supported(row_dict_or_doc, trace_id, item_code=None):
	if not trace_id:
		return
	ic = _cstr(item_code).strip()
	cur = ""
	try:
		if isinstance(row_dict_or_doc, dict):
			ic = ic or _cstr(row_dict_or_doc.get("item_code")).strip()
			cur = _cstr(row_dict_or_doc.get("custom_parent_child_trace_id")).strip()
		else:
			ic = ic or _cstr(getattr(row_dict_or_doc, "item_code", None)).strip()
			cur = _cstr(getattr(row_dict_or_doc, "custom_parent_child_trace_id", None)).strip()
	except Exception:
		pass
	if not cur:
		pass
	elif not _should_apply_trace_to_row(ic, cur, trace_id):
		return
	can_write = False
	try:
		can_write = frappe.db.has_column("Planning Table", "custom_parent_child_trace_id") or frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id")
	except Exception:
		can_write = False
	if not can_write:
		return
	try:
		if isinstance(row_dict_or_doc, dict):
			row_dict_or_doc["custom_parent_child_trace_id"] = trace_id
		else:
			setattr(row_dict_or_doc, "custom_parent_child_trace_id", trace_id)
	except Exception:
		pass


def _safe_set_planning_trace_id(doctype, row_name, item_code, new_trace_id, current_trace_id=None):
	"""DB set trace only when allowed (never downgrade fabric parent trace to native ``100-``)."""
	if not row_name or not frappe.db.has_column(doctype, "custom_parent_child_trace_id"):
		return False
	ic = _cstr(item_code).strip()
	cur = _cstr(current_trace_id).strip()
	if cur == "":
		try:
			cur = _cstr(frappe.db.get_value(doctype, row_name, "custom_parent_child_trace_id")).strip()
		except Exception:
			cur = ""
	if not cur:
		frappe.db.set_value(doctype, row_name, "custom_parent_child_trace_id", new_trace_id, update_modified=False)
		return True
	if not _should_apply_trace_to_row(ic, cur, new_trace_id):
		return False
	frappe.db.set_value(doctype, row_name, "custom_parent_child_trace_id", new_trace_id, update_modified=False)
	return True


def _planning_row_matches_sales_order_fg(item_code, so_item_key, so_by_name):
	"""True when this planning row is the SO finished-good line (not a BOM child on the same SO key)."""
	soik = _cstr(so_item_key).strip()
	ic = _cstr(item_code).strip()
	if not soik or not ic:
		return False
	so_it = so_by_name.get(soik) if so_by_name else None
	if not so_it:
		return False
	return _cstr(getattr(so_it, "item_code", None)).strip() == ic


def _bom_parent_trace_for_child_on_so_line(child_ic, so_item_key, planning_sheet_name, pt_rows, so_by_name=None):
	"""Parent FG trace for BOM children (100 / 104 / 106 / 107 / PB) on the same SO line — not child's native id."""
	soik = _cstr(so_item_key).strip()
	ic = _cstr(child_ic).strip()
	if not soik or not ic:
		return ""
	child_pp = _bom_item_process_code(ic)
	if child_pp not in ("100", "103", "104", "106", "107") and not _is_printed_bopp_item_code(ic):
		return ""
	so_it = (so_by_name or {}).get(soik)
	if so_it:
		fg_ic = _cstr(getattr(so_it, "item_code", None)).strip()
		fg_pp = _bom_item_process_code(fg_ic)
		if fg_pp and child_pp:
			t_chain = _fg_trace_for_bom_child_chain(so_it, fg_ic, fg_pp, child_pp)
			if t_chain:
				return t_chain
		if fg_pp in BAG_FG_TRACE_STAMP_PROCESSES:
			tid_bag = _parent_child_trace_id_from_item_code(fg_ic)
			if tid_bag:
				return tid_bag
		if fg_pp in ("255", "254", "253", "252", "251", "221", "108", "109", "106", "105"):
			tid_fg = _parent_child_trace_id_from_item_code(fg_ic)
			if tid_fg:
				return tid_fg
		if fg_pp == "106" and child_pp in ("104", "100", "106"):
			t106 = _fg_trace_for_bom_child_chain(so_it, fg_ic, fg_pp, child_pp) or _parent_child_trace_id_from_item_code(
				fg_ic
			)
			if t106:
				return t106
		if fg_pp == "108":
			tid108 = _parent_child_trace_id_from_item_code(fg_ic)
			if tid108:
				return tid108
	main_tid = _main_parent_trace_for_so_line(soik, planning_sheet_name, pt_rows, so_by_name)
	if main_tid:
		return main_tid
	if so_it:
		fg_pp = _bom_item_process_code(_cstr(getattr(so_it, "item_code", None)).strip())
		if fg_pp in ("255", "254", "253", "252", "251", "221", "108", "109", "106", "105"):
			return ""
	for pr in pt_rows or []:
		if _pt_soi_key(pr) != soik:
			continue
		pic = _cstr(pr.get("item_code") if isinstance(pr, dict) else getattr(pr, "item_code", "")).strip()
		if not pic:
			continue
		if _lamination_process_from_item_code(pic) not in ("104", "107") and _bom_item_process_code(pic) not in (
			"104",
			"107",
		):
			continue
		tid = _parent_child_trace_id_from_item_code(pic) or _parent_child_trace_id_for_planning_row(
			pic, soik, planning_sheet_name
		)
		if tid:
			return tid
	return ""


def _main_parent_trace_for_so_line(so_item_key, planning_sheet_name, pt_rows, so_by_name):
	"""Main parent trace for a Sales Order line — always from the SO FG item_code when possible."""
	soik = _cstr(so_item_key).strip()
	if not soik:
		return ""
	so_it = (so_by_name or {}).get(soik)
	if so_it:
		fg_ic = _cstr(getattr(so_it, "item_code", None)).strip()
		if fg_ic:
			tid = _parent_child_trace_id_from_item_code(fg_ic)
			if tid:
				return tid
			tid = _parent_child_trace_id_for_planning_row(
				fg_ic, soik, planning_sheet_name, skip_main_parent=True
			)
			if tid:
				return tid
	parent_priority = (
		"221",
		"222",
		"223",
		"224",
		"225",
		"226",
		"231",
		"232",
		"233",
		"241",
		"242",
		"211",
		"212",
		"213",
		"214",
		"216",
		"217",
		"200",
		"201",
		"202",
		"203",
		"255",
		"254",
		"253",
		"252",
		"251",
		"108",
		"106",
		"105",
		"109",
		"107",
		"104",
		"103",
		"102",
	)
	for pref in parent_priority:
		for pr in pt_rows or []:
			if _pt_soi_key(pr) != soik:
				continue
			ic = _cstr(pr.get("item_code") if isinstance(pr, dict) else getattr(pr, "item_code", "")).strip()
			if not ic:
				continue
			pp = _bom_item_process_code(ic)
			if pp != pref and not (pref == "107" and _lamination_process_from_item_code(ic) == "107"):
				continue
			if so_it and _planning_row_matches_sales_order_fg(ic, soik, so_by_name):
				tid = _parent_child_trace_id_from_item_code(ic)
				if tid:
					return tid
			if pref in (
				"221",
				"222",
				"223",
				"224",
				"225",
				"226",
				"231",
				"232",
				"233",
				"241",
				"242",
				"211",
				"212",
				"213",
				"214",
				"216",
				"217",
				"200",
				"201",
				"202",
				"203",
				"255",
				"254",
				"253",
				"252",
				"251",
				"108",
				"106",
				"105",
				"109",
				"104",
				"103",
				"102",
			) and (
				pp == pref or (pref == "107" and _lamination_process_from_item_code(ic) == "107")
			):
				tid = _parent_child_trace_id_from_item_code(ic) or _parent_child_trace_id_for_planning_row(
					ic, soik, planning_sheet_name, skip_main_parent=True
				)
				if tid:
					return tid
	return ""


def _trace_for_planning_row_using_main_parent(row, planning_sheet_name, pt_rows, so_by_name):
	"""Resolve trace for one board/legacy row; children use the SO line main parent trace."""
	ic = _cstr(row.get("item_code") if isinstance(row, dict) else getattr(row, "item_code", "")).strip()
	soik = _pt_soi_key(row if isinstance(row, dict) else frappe._dict(row))
	if not ic:
		return ""
	if soik and _planning_row_matches_sales_order_fg(ic, soik, so_by_name):
		tid = _parent_child_trace_id_from_item_code(ic)
		if tid:
			return tid
		return _parent_child_trace_id_for_planning_row(ic, soik, planning_sheet_name)
	if soik and not _planning_row_matches_sales_order_fg(ic, soik, so_by_name):
		main_tid = _main_parent_trace_for_so_line(soik, planning_sheet_name, pt_rows, so_by_name)
		if main_tid:
			return main_tid
	if soik:
		so_it = (so_by_name or {}).get(soik)
		bom_parent_tid = _bom_parent_trace_for_child_on_so_line(
			ic, soik, planning_sheet_name, pt_rows, so_by_name=so_by_name
		)
		if bom_parent_tid and not (
			_bom_item_process_code(_cstr(getattr(so_it, "item_code", None)).strip()) == "108"
			and _trace_is_native_107_process(bom_parent_tid)
		):
			return bom_parent_tid
	if _is_107_mid_bopp_item(ic):
		tid = _resolve_lam107_planning_trace(ic, soik, planning_sheet_name, pt_rows=pt_rows)
		if tid and not _trace_is_native_107_process(tid):
			return tid
	return _parent_child_trace_id_for_planning_row(ic, soik, planning_sheet_name) or _parent_child_trace_id_from_item_code(
		ic
	)


def _planning_trace_sheet_context(planning_sheet_name):
	"""SO line map + all Planning Table rows for trace resolution on one sheet."""
	so_by_name = {}
	so_name = frappe.db.get_value("Planning sheet", planning_sheet_name, "sales_order") if planning_sheet_name else None
	if so_name:
		try:
			so_doc = frappe.get_doc("Sales Order", so_name)
			so_by_name = {str(it.name): it for it in (so_doc.items or [])}
		except Exception:
			so_by_name = {}
	pt_rows = []
	if planning_sheet_name and frappe.db.exists("Planning sheet", planning_sheet_name):
		pt_fields = _planning_child_row_fields_for_query("Planning Table")
		pt_rows = (
			frappe.get_all(
				"Planning Table",
				filters={"parent": planning_sheet_name},
				fields=pt_fields,
				limit_page_length=5000,
			)
			or []
		)
	return pt_rows, so_by_name


def _resolve_trace_id_for_planning_row(row, planning_sheet_name, pt_rows=None, so_by_name=None):
	"""Best trace for any process row (FG, 100/104/106/107/255/109…)."""
	if not row:
		return ""
	if pt_rows is None or so_by_name is None:
		_pt, _so = _planning_trace_sheet_context(planning_sheet_name)
		pt_rows = pt_rows if pt_rows is not None else _pt
		so_by_name = so_by_name if so_by_name is not None else _so
	ic = _cstr(row.get("item_code") if isinstance(row, dict) else getattr(row, "item_code", None)).strip()
	if not ic:
		return ""
	soik = _pt_soi_key(row if isinstance(row, dict) else frappe._dict(row))
	tid = _trace_for_planning_row_using_main_parent(row, planning_sheet_name, pt_rows, so_by_name)
	if not tid:
		tid = _parent_child_trace_id_for_planning_row(ic, soik or None, planning_sheet_name)
	if not tid:
		tid = _parent_child_trace_id_from_item_code(ic)
	return _cstr(tid).strip()


def ensure_all_planning_sheet_trace_ids(planning_sheet_name):
	"""Fill Parent Child Trace ID on every Planning Table + Planning sheet Item row (all processes)."""
	psn = _cstr(planning_sheet_name).strip()
	if not psn or not frappe.db.exists("Planning sheet", psn):
		return {"updated": 0, "missing_item_code": 0, "no_trace_resolved": 0}
	if not (
		frappe.db.has_column("Planning Table", "custom_parent_child_trace_id")
		or frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id")
	):
		return {"updated": 0, "noop": "custom_parent_child_trace_id column missing on site"}
	pt_rows, so_by_name = _planning_trace_sheet_context(psn)
	updated = 0
	no_trace = 0
	for doctype in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.has_column(doctype, "custom_parent_child_trace_id"):
			continue
		fields = _planning_child_row_fields_for_query(doctype)
		for r in frappe.get_all(
			doctype, filters={"parent": psn}, fields=fields, limit_page_length=5000
		):
			ic = _cstr(r.get("item_code")).strip()
			if not ic:
				continue
			cur = _cstr(r.get("custom_parent_child_trace_id")).strip()
			tid = _resolve_trace_id_for_planning_row(r, psn, pt_rows, so_by_name)
			if not tid:
				no_trace += 1
				continue
			if not cur:
				frappe.db.set_value(
					doctype, r.name, "custom_parent_child_trace_id", tid, update_modified=False
				)
				updated += 1
			elif cur != tid and _safe_set_planning_trace_id(doctype, r.name, ic, tid, current_trace_id=cur):
				updated += 1
			# Mirror trace on linked legacy row when board row was updated (and vice versa).
			if doctype == "Planning Table" and frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id"):
				soik = _pt_soi_key(r)
				if soik:
					psi = frappe.db.get_value(
						"Planning sheet Item",
						{"parent": psn, "item_code": ic, "so_item": soik},
						"name",
					)
					if not psi and frappe.db.has_column("Planning sheet Item", "sales_order_item"):
						psi = frappe.db.get_value(
							"Planning sheet Item",
							{"parent": psn, "item_code": ic, "sales_order_item": soik},
							"name",
						)
					if psi:
						psi_cur = _cstr(frappe.db.get_value("Planning sheet Item", psi, "custom_parent_child_trace_id")).strip()
						if not psi_cur:
							frappe.db.set_value(
								"Planning sheet Item", psi, "custom_parent_child_trace_id", tid, update_modified=False
							)
			elif doctype == "Planning sheet Item" and frappe.db.has_column("Planning Table", "custom_parent_child_trace_id"):
				soik = _pt_soi_key(r)
				if soik:
					pt = frappe.db.get_value(
						"Planning Table",
						{"parent": psn, "item_code": ic, "sales_order_item": soik},
						"name",
					)
					if not pt:
						pt = frappe.db.get_value(
							"Planning Table",
							{"parent": psn, "item_code": ic, "so_item": soik},
							"name",
						)
					if pt:
						pt_cur = _cstr(frappe.db.get_value("Planning Table", pt, "custom_parent_child_trace_id")).strip()
						if not pt_cur:
							frappe.db.set_value(
								"Planning Table", pt, "custom_parent_child_trace_id", tid, update_modified=False
							)
	return {
		"updated": updated,
		"no_trace_resolved": no_trace,
		"planning_sheet": psn,
	}


@frappe.whitelist()
def ensure_planning_sheet_trace_ids(planning_sheet_name=None):
	"""Desk / API: stamp traces on all rows for one planning sheet."""
	if not planning_sheet_name:
		frappe.throw(_("Planning sheet is required."))
	return ensure_all_planning_sheet_trace_ids(planning_sheet_name)


def _stamp_sales_order_fg_trace_ids(planning_sheet_name):
	"""Stamp every planning row: SO FG native trace; BOM/children use that line's main parent trace."""
	if not planning_sheet_name:
		return 0
	if not (
		frappe.db.has_column("Planning Table", "custom_parent_child_trace_id")
		or frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id")
	):
		return 0
	so_name = frappe.db.get_value("Planning sheet", planning_sheet_name, "sales_order")
	so_by_name = {}
	if so_name:
		try:
			so_doc = frappe.get_doc("Sales Order", so_name)
			so_by_name = {str(it.name): it for it in (so_doc.items or [])}
		except Exception:
			so_by_name = {}
	pt_rows = (
		frappe.get_all(
			"Planning Table",
			filters={"parent": planning_sheet_name},
			fields=["name", "item_code", "sales_order_item", "so_item"],
			limit_page_length=5000,
		)
		or []
	)
	updated = 0
	for doctype in ("Planning Table", "Planning sheet Item"):
		if not frappe.db.exists("DocType", doctype):
			continue
		if not frappe.db.has_column(doctype, "custom_parent_child_trace_id"):
			continue
		fields = ["name", "item_code", "so_item"]
		if frappe.db.has_column(doctype, "sales_order_item"):
			fields.append("sales_order_item")
		for r in frappe.get_all(doctype, filters={"parent": planning_sheet_name}, fields=fields, limit_page_length=5000):
			tid = _trace_for_planning_row_using_main_parent(r, planning_sheet_name, pt_rows, so_by_name)
			if not tid:
				continue
			cur = _cstr(frappe.db.get_value(doctype, r.name, "custom_parent_child_trace_id")).strip()
			if cur == tid:
				continue
			if _safe_set_planning_trace_id(doctype, r.name, r.get("item_code"), tid, current_trace_id=cur):
				updated += 1
	return updated


def _sql_fabric_row_join_predicate(alias_pt="pt", alias_fab="fab"):
	"""
	SQL AND-clause predicates to pair a parent PT row with its BOM fabric (100%) row.

	1. Trace-first: non-empty traces on BOTH sides and equal (authoritative across many SO lines on one sheet).
	2. Fallback: legacy SO-key match on fabric.so_item (parent prefers sales_order_item else so_item).
	"""
	has_trace = False
	try:
		has_trace = bool(frappe.db.has_column("Planning Table", "custom_parent_child_trace_id"))
	except Exception:
		has_trace = False
	so_fallback = (
		"NULLIF(TRIM(IFNULL(%s.so_item,'')), '') <> '' "
		"AND NULLIF(TRIM(IFNULL(%s.so_item,'')), '') = COALESCE(NULLIF(TRIM(IFNULL(%s.sales_order_item,'')), ''), "
		"NULLIF(TRIM(IFNULL(%s.so_item,'')), ''))"
		% (alias_fab, alias_fab, alias_pt, alias_pt)
	)
	if not has_trace:
		return "(%s)" % so_fallback
	trace_eq = (
		"(NULLIF(TRIM(IFNULL(%s.custom_parent_child_trace_id,'')), '') IS NOT NULL "
		"AND NULLIF(TRIM(IFNULL(%s.custom_parent_child_trace_id,'')), '') <> '' "
		"AND NULLIF(TRIM(IFNULL(%s.custom_parent_child_trace_id,'')), '') IS NOT NULL "
		"AND NULLIF(TRIM(IFNULL(%s.custom_parent_child_trace_id,'')), '') <> '' "
		"AND TRIM(IFNULL(%s.custom_parent_child_trace_id,'')) = TRIM(IFNULL(%s.custom_parent_child_trace_id,'')))"
		% (
			alias_pt,
			alias_pt,
			alias_fab,
			alias_fab,
			alias_pt,
			alias_fab,
		)
	)
	return "((%s) OR (%s))" % (trace_eq, so_fallback)


def _sql_correlated_pick_one_fabric_name(alias_pt="pt"):
	"""
	Scalar correlated subquery: pick exactly one fabric (100%) Planning Table row per parent row.
	Matches trace ID first when both sides have it; else SO-line key via fab.so_item.
	"""
	try:
		has_trace = bool(frappe.db.has_column("Planning Table", "custom_parent_child_trace_id"))
	except Exception:
		has_trace = False
	pa = alias_pt
	so_match = (
		"(NULLIF(TRIM(IFNULL(f2.so_item,'')), '') <> '' "
		"AND NULLIF(TRIM(IFNULL(f2.so_item,'')), '') = COALESCE("
		"NULLIF(TRIM(IFNULL({pa}.sales_order_item,'')), ''), "
		"NULLIF(TRIM(IFNULL({pa}.so_item,'')), '')))"
	).format(pa=pa)
	trace_match_body = ""
	if has_trace:
		trace_match_body = (
			"NULLIF(TRIM(IFNULL({pa}.custom_parent_child_trace_id,'')), '') IS NOT NULL "
			"AND NULLIF(TRIM(IFNULL({pa}.custom_parent_child_trace_id,'')), '') <> '' "
			"AND NULLIF(TRIM(IFNULL(f2.custom_parent_child_trace_id,'')), '') IS NOT NULL "
			"AND NULLIF(TRIM(IFNULL(f2.custom_parent_child_trace_id,'')), '') <> '' "
			"AND TRIM(IFNULL({pa}.custom_parent_child_trace_id,'')) = "
			"TRIM(IFNULL(f2.custom_parent_child_trace_id,''))"
		).format(pa=pa)
	if has_trace:
		where_clause = "(" + "(" + trace_match_body + ") OR " + so_match + ")"
		inner_case = trace_match_body
	else:
		where_clause = "{}".format(so_match)
		inner_case = "NULLIF(TRIM(IFNULL(f2.so_item,'')), '') <> ''"
	return (
		"(SELECT f2.name FROM `tabPlanning Table` AS f2 "
		"WHERE f2.parent = {}.parent AND f2.item_code LIKE '100%%' "
		"AND {} "
		"ORDER BY CASE WHEN ({}) THEN 0 ELSE 1 END DESC, IFNULL(f2.modified, f2.creation) DESC LIMIT 1)"
	).format(pa, where_clause, inner_case)


def _sql_correlated_pick_one_sheet_bom_roll_child(alias_pt="pt"):
	"""Scalar subquery: 105/104/107 BOM child on the same SO line (sheet-cutting roll width, not fabric 100)."""
	pa = alias_pt
	so_match = (
		"(NULLIF(TRIM(IFNULL(c2.so_item,'')), '') <> '' "
		"AND NULLIF(TRIM(IFNULL(c2.so_item,'')), '') = COALESCE("
		"NULLIF(TRIM(IFNULL({pa}.sales_order_item,'')), ''), "
		"NULLIF(TRIM(IFNULL({pa}.so_item,'')), '')))"
	).format(pa=pa)
	return (
		"(SELECT c2.name FROM `tabPlanning Table` AS c2 "
		"WHERE c2.parent = {pa}.parent "
		"AND (TRIM(IFNULL(c2.item_code,'')) LIKE '105%%' "
		"OR UPPER(TRIM(IFNULL(c2.item_code,''))) LIKE '%%-105%%' "
		"OR TRIM(IFNULL(c2.item_code,'')) LIKE '104%%' "
		"OR TRIM(IFNULL(c2.item_code,'')) LIKE '107%%' "
		"OR UPPER(TRIM(IFNULL(c2.item_code,''))) LIKE '%%-104%%' "
		"OR UPPER(TRIM(IFNULL(c2.item_code,''))) LIKE '%%-107%%') "
		"AND ({so_match}) "
		"ORDER BY CASE "
		"WHEN (TRIM(IFNULL({pa}.item_code,'')) LIKE '%%252%%' OR TRIM(IFNULL({pa}.item_code,'')) LIKE '252%%') "
		" AND (TRIM(IFNULL(c2.item_code,'')) LIKE '105%%' OR UPPER(TRIM(IFNULL(c2.item_code,''))) LIKE '%%-105%%') THEN 0 "
		"WHEN TRIM(IFNULL(c2.item_code,'')) LIKE '104%%' OR UPPER(TRIM(IFNULL(c2.item_code,''))) LIKE '%%-104%%' THEN 1 "
		"WHEN TRIM(IFNULL(c2.item_code,'')) LIKE '107%%' OR UPPER(TRIM(IFNULL(c2.item_code,''))) LIKE '%%-107%%' THEN 2 "
		"ELSE 3 END, "
		"IFNULL(c2.modified, c2.creation) DESC LIMIT 1)"
	).format(pa=pa, so_match=so_match)


def _submitted_spr_run_date_map(spr_names):
	"""Map SPR name -> run_date (or custom_run_date, etc.) for submitted docs only."""
	out = {}
	if not spr_names or not frappe.db.exists("DocType", "Shaft Production Run"):
		return out
	spr_cols = set(frappe.db.get_table_columns("Shaft Production Run") or [])
	run_col = ""
	for c in ("run_date", "custom_run_date", "start_date", "posting_date", "creation"):
		if c in spr_cols:
			run_col = c
			break
	if not run_col:
		return out
	names = [str(x or "").strip() for x in spr_names if str(x or "").strip()]
	if not names:
		return out
	sf = ",".join(["%s"] * len(names))
	for rr in frappe.db.sql(
		f"SELECT name, {run_col} as run_date FROM `tabShaft Production Run` WHERE docstatus = 1 AND name IN ({sf})",
		tuple(names),
		as_dict=True,
	):
		out[str(rr.get("name") or "").strip()] = rr.get("run_date")
	return out


def _expand_spr_name_tokens(*raw_values):
	"""Split CSV/semicolon spr_name fields into unique ordered SPR document names."""
	out = []
	seen = set()
	for raw in raw_values:
		for segment in str(raw or "").replace(";", ",").split(","):
			sn = segment.strip()
			if sn and sn not in seen:
				seen.add(sn)
				out.append(sn)
	return out


def _resolve_spr_produced_weight_kg(
	spr_raw,
	item_code=None,
	spr_id_produced_map=None,
	spr_item_kg_by_code=None,
	spr_metrics=None,
	width_inch=None,
	spr_item_kg_by_width=None,
	use_width_slice=True,
):
	"""Produced kg for one Planning Table row's SPR link — never PP-aggregated totals."""
	total = 0.0
	found = False
	item_code = (item_code or "").strip()
	width_key = round(flt(width_inch or 0), 1)
	spr_id_produced_map = spr_id_produced_map or {}
	spr_item_kg_by_code = spr_item_kg_by_code or {}
	spr_item_kg_by_width = spr_item_kg_by_width or {}
	spr_metrics = spr_metrics or {}
	for sid in _expand_spr_name_tokens(spr_raw):
		if use_width_slice:
			if item_code:
				spi_kg = flt((spr_item_kg_by_code.get(sid) or {}).get(item_code, 0))
				if spi_kg > 0:
					total += spi_kg
					found = True
					continue
			if width_key > 0:
				w_kg = flt((spr_item_kg_by_width.get(sid) or {}).get(width_key, 0))
				if w_kg > 0:
					total += w_kg
					found = True
					continue
		if sid in spr_id_produced_map:
			qty = flt(spr_id_produced_map.get(sid) or 0)
			if qty > 0:
				total += qty
				found = True
				continue
		m = spr_metrics.get(sid)
		if m:
			produced = flt(m.get("total_produced", 0))
			if produced > 0:
				total += produced
				found = True
	return flt(total) if found else None


def _should_use_spr_width_slice(sheet_items, item, spr_raw) -> bool:
	"""Per-width roll kg only when multiple board rows share one SPR at different widths."""
	spr_tokens = _expand_spr_name_tokens(spr_raw)
	if not spr_tokens:
		return False
	width_key = round(
		flt(
			(item or {}).get("width_inch")
			or (item or {}).get("width")
			or (item or {}).get("custom_width")
			or 0
		),
		1,
	)
	if width_key <= 0:
		return False
	siblings = []
	for it in sheet_items or []:
		if _expand_spr_name_tokens(it.get("spr_name")) != spr_tokens:
			continue
		siblings.append(it)
	if len(siblings) <= 1:
		return False
	positive_widths = set()
	for s in siblings:
		w = round(flt(s.get("width_inch") or s.get("width") or s.get("custom_width") or 0), 1)
		if w > 0:
			positive_widths.add(w)
	return len(positive_widths) > 1


def _spr_header_produced_total_kg(spr_raw, spr_id_produced_map=None, spr_metrics=None) -> float:
	"""Sum produced kg across all SPR ids in a Planning row spr_name field (comma-separated)."""
	total = 0.0
	seen = set()
	for sid in _expand_spr_name_tokens(spr_raw):
		if sid in seen:
			continue
		seen.add(sid)
		part = 0.0
		if spr_id_produced_map and sid in spr_id_produced_map:
			part = flt(spr_id_produced_map.get(sid) or 0)
		if part <= 0:
			m = (spr_metrics or {}).get(sid)
			if m:
				part = flt(m.get("total_produced", 0))
		total += part
	return flt(total)


SPR_SHIFT_PILOT_UNIT = "Unit 4"
SPR_SHIFT_PILOT_DATES = frozenset({"2026-06-23", "2026-06-24"})


def _normalize_spr_shift_label(shift_raw) -> str:
	s = str(shift_raw or "").strip().lower()
	if "night" in s:
		return "night"
	return "day"


def _spr_shift_runs_for_row(row_spr, spr_id_run_meta=None) -> tuple[list, list]:
	"""Build day/night SPR run lists for Production Table shift columns."""
	spr_id_run_meta = spr_id_run_meta or {}
	day_runs: list = []
	night_runs: list = []
	seen: set = set()
	for sid in _expand_spr_name_tokens(row_spr):
		if sid in seen:
			continue
		seen.add(sid)
		meta = spr_id_run_meta.get(sid) or {}
		if cint(meta.get("docstatus")) != 1:
			continue
		kg = flt(meta.get("produced_kg") or 0)
		if kg <= 0:
			continue
		run = {
			"spr_name": sid,
			"run_date": str(meta.get("run_date") or ""),
			"kg": kg,
		}
		if _normalize_spr_shift_label(meta.get("shift")) == "night":
			night_runs.append(run)
		else:
			day_runs.append(run)
	day_runs.sort(key=lambda r: r.get("run_date") or "")
	night_runs.sort(key=lambda r: r.get("run_date") or "")
	return day_runs, night_runs


def _spr_split_row_produced_share(
	sheet_items,
	current_item,
	spr_raw,
	item_code,
	spr_id_produced_map=None,
	spr_metrics=None,
	spr_item_kg_by_code=None,
):
	"""
	When multiple Planning Table rows share the same SPR + item_code (split/merge family),
	return this row's share of the SPR produced kg — never the full header on every row.
	"""
	ic = (item_code or "").strip()
	spr_tokens = _expand_spr_name_tokens(spr_raw)
	if not ic or not spr_tokens:
		return None
	siblings = []
	for it in sheet_items or []:
		if (it.get("item_code") or "").strip() != ic:
			continue
		if _expand_spr_name_tokens(it.get("spr_name")) != spr_tokens:
			continue
		siblings.append(it)
	if len(siblings) <= 1:
		return None
	header_kg = _spr_header_produced_total_kg(spr_raw, spr_id_produced_map, spr_metrics)
	if header_kg <= 0:
		for sid in spr_tokens:
			header_kg = max(header_kg, flt((spr_item_kg_by_code or {}).get(sid, {}).get(ic, 0)))
	if header_kg <= 0:
		return None
	total_qty = sum(flt(it.get("qty", 0)) for it in siblings)
	if total_qty <= 0:
		return flt(header_kg) / len(siblings)
	row_qty = flt(current_item.get("qty", 0))
	return flt(header_kg) * row_qty / total_qty


def _fabric_ready_date_from_child_sprs(run_date_map, raw_child_spr):
	"""Pick a single display date from mapped submitted SPR run dates (CSV on child fabric link)."""
	best = None
	for sn in _expand_spr_name_tokens(raw_child_spr):
		d = run_date_map.get(sn)
		if d is None:
			continue
		if best is None or str(d) > str(best):
			best = d
	return best or ""


@frappe.whitelist()
def prune_planning_table_spr_links(planning_table_names=None):
	"""
	Remove missing/deleted SPR ids from Planning Table.spr_name (comma-separated).
	Accepts a JSON list or python list of Planning Table row names.
	"""
	import json

	if isinstance(planning_table_names, str):
		try:
			planning_table_names = json.loads(planning_table_names)
		except Exception:
			planning_table_names = [planning_table_names]
	planning_table_names = planning_table_names or []
	if not isinstance(planning_table_names, list):
		return {"status": "error", "message": "planning_table_names must be a list", "updated": 0}
	if not frappe.db.has_column("Planning Table", "spr_name") or not frappe.db.exists("DocType", "Shaft Production Run"):
		return {"status": "ok", "updated": 0}

	updated = 0
	for nm in [str(x or "").strip() for x in planning_table_names if str(x or "").strip()]:
		if not frappe.db.exists("Planning Table", nm):
			continue
		raw = str(frappe.db.get_value("Planning Table", nm, "spr_name") or "").strip()
		if not raw:
			continue
		kept = []
		for sid in _expand_spr_name_tokens(raw):
			if frappe.db.exists("Shaft Production Run", sid):
				kept.append(sid)
		new_val = ", ".join(kept)
		if new_val != raw:
			frappe.db.set_value("Planning Table", nm, "spr_name", new_val, update_modified=False)
			updated += 1
	if updated:
		frappe.db.commit()
	return {"status": "ok", "updated": updated}


def _month_letter_from_date(dt):
    """January=A and December=L (single letter month code)."""
    m = int(getattr(dt, "month", 1) or 1)
    m = max(1, min(12, m))
    return chr(ord("A") + m - 1)


def _next_lamination_order_code():
    """U + YY + month letter (A-L) + 3-digit series, for example U26D001."""
    now = frappe.utils.now_datetime()
    yy = str(now.year)[-2:]
    ml = _month_letter_from_date(now)
    prefix = f"U{yy}{ml}"
    sheet_code_field = "custom_lamination_order_code" if frappe.db.has_column("Planning sheet", "custom_lamination_order_code") else "custom_lamination_booking_id"
    rows = frappe.db.sql(
        """
        SELECT {field} FROM `tabPlanning sheet`
        WHERE IFNULL({field}, '') != ''
          AND {field} LIKE %s
        ORDER BY {field} DESC
        LIMIT 1
        """.format(field=sheet_code_field),
        (prefix + "%",),
    )
    n = 1
    if rows and rows[0][0]:
        tail = str(rows[0][0])[len(prefix) :]
        try:
            n = int(tail) + 1
        except Exception:
            n = 1
    if n > 999:
        frappe.throw(_("Lamination order code series exhausted for prefix %s (max 999).") % prefix)
    return prefix + str(n).zfill(3)


def ensure_lamination_booking_for_planning_sheet(doc):
	"""One lamination order code per Planning sheet when any 104/107 parent row exists; copy to row tables + SO."""
	if not LAMINATION_FLOW_ENABLED:
		return
	try:
		meta = frappe.get_meta("Planning sheet")
	except Exception:
		return
	has_sheet_code_new = meta.has_field("custom_lamination_order_code") or frappe.db.has_column("Planning sheet", "custom_lamination_order_code")
	has_sheet_code_old = meta.has_field("custom_lamination_booking_id") or frappe.db.has_column("Planning sheet", "custom_lamination_booking_id")
	if not (has_sheet_code_new or has_sheet_code_old):
		return
	has_pt_booking_new = frappe.db.has_column("Planning Table", "custom_lamination_order_code_")
	has_pt_booking_old = frappe.db.has_column("Planning Table", "custom_lamination_booking_id")
	has_psi_booking = frappe.db.has_column("Planning sheet Item", "custom_lamination_order_code")
	has_psi_lam_gsm = frappe.db.has_column("Planning sheet Item", "custom_lam_gsm")
	has_pt_lam_gsm = frappe.db.has_column("Planning Table", "custom_lam_gsm")
	has_psi_bopp_gsm = frappe.db.has_column("Planning sheet Item", "custom_bopp_gsm")
	has_pt_bopp_gsm = frappe.db.has_column("Planning Table", "custom_bopp_gsm")
	has_psi_lam_side = frappe.db.has_column("Planning sheet Item", "custom_lam_side")
	has_pt_lam_side = frappe.db.has_column("Planning Table", "custom_lam_side_")
	has_ps_lam_side = frappe.db.has_column("Planning sheet", "custom_lam_side")

	has_lamination_parent = False
	for fn in ("planned_items", "items", "custom_planned_items"):
		if not meta.has_field(fn):
			continue
		for row in doc.get(fn) or []:
			ic = (getattr(row, "item_code", None) or "").strip()
			if _is_lamination_parent_process(ic):
				has_lamination_parent = True
				break
		if has_lamination_parent:
			break
	if not has_lamination_parent:
		return

	code = ""
	if LAMINATION_ORDER_CODE_ENABLED:
		if has_sheet_code_new:
			code = (getattr(doc, "custom_lamination_order_code", None) or "").strip()
		if not code and has_sheet_code_old:
			code = (getattr(doc, "custom_lamination_booking_id", None) or "").strip()
		if not code:
			code = _next_lamination_order_code()
		if has_sheet_code_new:
			doc.custom_lamination_order_code = code
		if has_sheet_code_old:
			doc.custom_lamination_booking_id = code

	# Build a map of SO item -> lamination side for 104/107 rows.
	# Support multiple possible field names on Sales Order Item.
	so_lam_side_map = {}
	so_name = (getattr(doc, "sales_order", None) or "").strip()
	if so_name:
		try:
			soi_cols = set(frappe.db.get_table_columns("Sales Order Item") or [])
			side_field = ""
			for fn in ("custom_lamination_side", "custom_lam_side", "lamination_side"):
				if fn in soi_cols:
					side_field = fn
					break
			so_items_data = frappe.get_all(
				"Sales Order Item",
				filters={"parent": so_name},
				fields=["name", "item_code", side_field] if side_field else ["name", "item_code"],
			) if side_field else []
			for soi in so_items_data:
				side_val = (soi.get(side_field) or "").strip() if side_field else ""
				if side_val:
					so_lam_side_map[soi["name"]] = side_val
					so_lam_side_map[soi["item_code"]] = side_val
		except Exception:
			pass

	# Stamp header-level lam side (from first lamination SO item that has a value)
	if has_ps_lam_side and so_lam_side_map:
		first_lam_side = next(iter(so_lam_side_map.values()), "")
		if first_lam_side:
			doc.custom_lam_side = first_lam_side

	for fn in ("planned_items", "items", "custom_planned_items"):
		if not meta.has_field(fn):
			continue
		for row in doc.get(fn) or []:
			ic = (getattr(row, "item_code", None) or "").strip()
			if not _is_lamination_parent_process(ic):
				continue
			lam_gsm_val = _lam_gsm_from_item_code_suffix(ic)
			p107_book = {}
			if _lamination_process_from_item_code(ic) == "107":
				p107_book = _parse_107_item_code(ic) or {}
			if lam_gsm_val <= 0 and _lamination_process_from_item_code(ic) == "107":
				lam_gsm_val = cint(p107_book.get("lam_gsm") or 0)
			bopp_gsm_book = cint(p107_book.get("bopp_gsm") or 0) if p107_book else 0
			if fn in ("planned_items", "custom_planned_items"):
				if LAMINATION_ORDER_CODE_ENABLED and code:
					if has_pt_booking_new:
						row.custom_lamination_order_code_ = code
					elif has_pt_booking_old:
						row.custom_lamination_booking_id = code
				if has_pt_lam_gsm:
					row.custom_lam_gsm = lam_gsm_val
				if has_pt_bopp_gsm and bopp_gsm_book > 0:
					row.custom_bopp_gsm = bopp_gsm_book
				if has_pt_lam_side:
					lam_side_val = so_lam_side_map.get(getattr(row, "so_item", "") or "") or so_lam_side_map.get(ic, "")
					if lam_side_val and (
						_lamination_process_from_item_code(ic) in ("107", "104")
						or _item_process_prefix(ic) in ("104", "109")
					):
						row.custom_lam_side_ = lam_side_val
			else:
				if LAMINATION_ORDER_CODE_ENABLED and code and has_psi_booking:
					row.custom_lamination_order_code = code
				if has_psi_lam_gsm:
					row.custom_lam_gsm = lam_gsm_val
				if has_psi_bopp_gsm and bopp_gsm_book > 0:
					row.custom_bopp_gsm = bopp_gsm_book
				if has_psi_lam_side:
					lam_side_val = so_lam_side_map.get(getattr(row, "so_item", "") or "") or so_lam_side_map.get(ic, "")
					if lam_side_val and (
						_lamination_process_from_item_code(ic) in ("107", "104")
						or _item_process_prefix(ic) in ("104", "109")
					):
						row.custom_lam_side = lam_side_val

	# Header fallback: if map was empty, derive from first lamination row lam side value.
	if has_ps_lam_side and not (getattr(doc, "custom_lam_side", None) or "").strip():
		for fn in ("planned_items", "items", "custom_planned_items"):
			if not meta.has_field(fn):
				continue
			for row in doc.get(fn) or []:
				ic = (getattr(row, "item_code", None) or "").strip()
				if _lamination_process_from_item_code(ic) != "107":
					continue
				row_side = (
					(getattr(row, "custom_lam_side_", None) or "").strip()
					or (getattr(row, "custom_lam_side", None) or "").strip()
				)
				if row_side:
					doc.custom_lam_side = row_side
					break
			if (getattr(doc, "custom_lam_side", None) or "").strip():
				break

	# Mirror code to Sales Order header when available
	sales_order = (getattr(doc, "sales_order", None) or "").strip()
	if LAMINATION_ORDER_CODE_ENABLED and code and sales_order:
		try:
			if frappe.db.has_column("Sales Order", "custom_lamination_order_code"):
				frappe.db.set_value("Sales Order", sales_order, "custom_lamination_order_code", code, update_modified=False)
			elif frappe.db.has_column("Sales Order", "custom_lamination_booking_id"):
				frappe.db.set_value("Sales Order", sales_order, "custom_lamination_booking_id", code, update_modified=False)
		except Exception:
			frappe.log_error(frappe.get_traceback(), "sync_lamination_order_code_sales_order")


def _fabric_gsm_from_item_name(item_name: str) -> int:
    """Parse Fabric GSM from item name by finding the F-<number> pattern (e.g. 'F-60' or 'F - 60' → 60)."""
    if not item_name:
        return 0
    m = re.search(r'\bF\s*-\s*(\d+)\b', item_name, re.IGNORECASE)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            pass
    return 0


def _nominal_inch_from_mm(mm):
	"""Convert mm width to inches, snapped to nearest 0.5" (800 mm → 31.5", 405 mm → 16")."""
	mm_val = flt(mm or 0)
	if mm_val <= 0:
		return 0.0
	return round(round(mm_val / 25.4 * 2.0) / 2.0, 1)


def _nominal_inch_from_width_code(width_code_str):
	"""4-digit tail = mm (0405 → 16"); 3-digit tail = tenths of an inch."""
	wc = _cstr(width_code_str).strip()
	if not wc.isdigit():
		return 0.0
	if len(wc) == 4:
		return _nominal_inch_from_mm(cint(wc))
	if len(wc) == 3:
		return round(flt(cint(wc)) / 10.0, 1)
	return 0.0


def _planning_row_stored_width_inch(row=None, ex=None):
	"""Width from Planning Table / board row before item-code parsing."""
	r = row or {}
	e = ex or {}
	return flt(
		e.get("pt_width_inch")
		or r.get("width_inch")
		or r.get("widthInch")
		or r.get("width")
		or 0
	)


def _parse_104_item_code(item_code):
	"""Process 104 laminated roll: ``104`` + QQQ + CCC + GGG + WWWW [``-lam``]; optional design prefix."""
	code = re.sub(r"\s+", "", str(item_code or "").strip().upper())
	if not code:
		return {}

	def _row(design, gd):
		lam = (gd.get("lam") or "").strip().upper()
		lam_g = cint(_LAM_GSM_SUFFIX_MAP.get(lam, 0) or 0) if lam else 0
		wc = (gd.get("width") or "").strip()
		width_inch = _nominal_inch_from_width_code(wc) if wc else 0.0
		return {
			"process": "104",
			"design_code": design or "",
			"quality_code": gd.get("quality"),
			"colour_code": gd.get("colour"),
			"gsm": cint(gd.get("gsm") or 0),
			"width_code": wc,
			"width_inch": width_inch,
			"lam_suffix": lam,
			"lam_gsm_code": lam,
			"lam_gsm": lam_g,
		}

	m = re.match(
		r"^104(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<width>\d{4})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m:
		return _row("", m.groupdict())
	m2 = re.match(
		r"^(?P<design>[A-Z0-9]+)-104(?P<quality>\d{3})(?P<colour>\d{3})(?P<gsm>\d{3})(?P<width>\d{4})(?:-(?P<lam>[A-Z0-9]+))?$",
		code,
	)
	if m2:
		return _row((m2.group("design") or "").strip(), m2.groupdict())
	return {}


def _width_inch_from_104_item_code(item_code, item_name=""):
	"""Roll width (inch) from 104: prefer ``W - 31.5`` in the item name, else WWWW mm (``0800`` → 31.5")."""
	ic = _cstr(item_code).strip()
	inm = _cstr(item_name).strip()
	if ic and not inm:
		try:
			if frappe.db.exists("Item", ic):
				inm = _cstr(frappe.db.get_value("Item", ic, "item_name") or "")
		except Exception:
			inm = ""
	_, wname = _parse_gsm_width_from_item_text(f"{ic} {inm}".strip())
	if flt(wname) > 0:
		return round(flt(wname), 2)
	p = _parse_104_item_code(ic) or {}
	w = flt(p.get("width_inch") or 0)
	if w > 0:
		return w
	digits = "".join(ch for ch in ic if ch.isdigit())
	for m in re.finditer(r"104\d{13}", digits):
		block = m.group(0)
		if len(block) >= 16:
			wc = block[12:16]
			if wc.isdigit():
				return _nominal_inch_from_width_code(wc)
	return 0.0


def _resolve_planning_row_width_inch(item_code, db_width=0, item_name=""):
	"""Roll width (inch) for order tables — Planning Table value first, then item-code / name text."""
	w = flt(db_width or 0)
	ic = _cstr(item_code).strip()
	inm = _cstr(item_name).strip()
	if not ic:
		return w
	# Fabric (100*): always prefer exact width from item name (e.g. W - 42.32), even if
	# a previously rounded width_inch (42.3) is already stored on the planning row.
	if ( _item_process_prefix(ic) == "100" or ic.startswith("100") ) and inm:
		_, wtxt = _parse_gsm_width_from_item_text(f"{ic} {inm}")
		if flt(wtxt) > 0:
			w = round(flt(wtxt), 2)
			return w
	if w <= 0:
		lam = _lamination_process_from_item_code(ic)
		pp = _item_process_prefix(ic)
		if lam == "104":
			w = _width_inch_from_104_item_code(ic, inm)
		elif lam == "107":
			w = flt((_parse_107_item_code(ic) or {}).get("width_inch") or 0)
		elif pp == "255" or lam == "255":
			w = flt((_parse_255_item_code(ic) or {}).get("width_inch") or 0)
		elif pp == "108":
			w = flt((_parse_108_item_code(ic) or {}).get("width_inch") or 0)
		elif pp == "110":
			w = flt((_parse_110_item_code(ic) or {}).get("width_inch") or 0)
		elif pp == "106":
			p106 = _parse_106_item_code(ic) or {}
			wmm = cint(p106.get("width_mm") or 0)
			if wmm > 0:
				w = _nominal_inch_from_mm(wmm)
		elif pp == "105":
			p105 = _parse_105_item_code(ic) or {}
			wmm = cint(p105.get("width_mm") or 0)
			if wmm > 0:
				w = _nominal_inch_from_mm(wmm)
		elif pp == "103":
			digits = "".join(ch for ch in ic if ch.isdigit())
			if len(digits) >= 16 and digits.startswith("103"):
				wc = digits[12:16]
				if wc.isdigit():
					w = _nominal_inch_from_width_code(wc)
		elif pp == "109":
			p109 = _parse_109_item_code(ic) or {}
			wc = _cstr(p109.get("width_code")).strip()
			if wc.isdigit():
				w = _nominal_inch_from_width_code(wc)
		elif pp == "100" or ic.startswith("100"):
			_, wtxt = _parse_gsm_width_from_item_text(f"{ic} {inm}")
			if wtxt > 0:
				w = wtxt
	if w <= 0:
		_, wtxt = _parse_gsm_width_from_item_text(f"{ic} {inm}")
		if wtxt > 0:
			w = wtxt
	if w > 0 and not _is_printed_bopp_item_code(ic):
		# Keep two decimals so fabric widths like 42.32 / 45.47 are not collapsed to 42.3 / 45.5
		rw = round(flt(w), 2)
		return float(int(rw)) if abs(rw - round(rw)) < 1e-9 else rw
	return w


def _gsm_from_lamination_item_code(item_code: str) -> int:
	"""Fabric GSM from lamination FG code: 16-digit block 104+QQQ+CCC+GGG+WWWW → GSM = digits[9:12].
	Finds embedded ``104`` + 13 digits so prefixed codes (e.g. design + 104…) do not mis-align slices."""
	if not item_code:
		return 0
	digits_all = "".join(ch for ch in str(item_code).strip() if ch.isdigit())
	best = 0
	for m in re.finditer(r"104\d{13}", digits_all):
		block = m.group(0)
		if len(block) >= 12:
			try:
				best = cint(block[9:12])
			except Exception:
				pass
	if best > 0:
		return best
	# Legacy: whole digit stream is exactly the 104 body (no leading design digits).
	if digits_all.startswith("104") and len(digits_all) >= 12:
		try:
			return cint(digits_all[9:12])
		except Exception:
			return 0
	return 0


def _lam_gsm_from_item_code_suffix(item_code: str) -> int:
	"""104 / 253: lam GSM from suffix after last '-'. 107 / 255: from embedded lam letter via parsers."""
	code = str(item_code or "").strip().upper()
	if not code:
		return 0
	if _lamination_process_from_item_code(code) == "107":
		p = _parse_107_item_code(code)
		return cint(p.get("lam_gsm") or 0)
	if _lamination_process_from_item_code(code) == "255" or _item_process_prefix(code) == "255":
		p = _parse_255_item_code(code)
		return cint(p.get("lam_gsm") or 0)
	if _item_process_prefix(code) == "253":
		p = _parse_253_item_code(code)
		if p:
			return cint(p.get("lam_gsm") or 0)
		if "-" not in code:
			return 0
		_left, suffix = code.rsplit("-", 1)
		return cint(_LAM_GSM_SUFFIX_MAP.get(suffix.strip(), 0) or 0)
	if _item_process_prefix(code) == "108":
		p = _parse_108_item_code(code)
		return cint(p.get("lam_gsm") or 0)
	if _item_process_prefix(code) == "254":
		p = _parse_254_item_code(code)
		return cint(p.get("lam_gsm") or 0)
	if _lamination_process_from_item_code(code) != "104":
		return 0
	if "-" not in code:
		return 0
	_left, suffix = code.rsplit("-", 1)
	return cint(_LAM_GSM_SUFFIX_MAP.get(suffix.strip(), 0) or 0)


def _lam_side_from_sales_order_item(so_item_name: str) -> str:
    """Fetch lamination side directly from Sales Order Item row."""
    if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
        return ""
    cols = set(frappe.db.get_table_columns("Sales Order Item") or [])
    for fn in ("custom_lamination_side", "custom_lam_side", "lamination_side"):
        if fn in cols:
            try:
                return str(frappe.db.get_value("Sales Order Item", so_item_name, fn) or "").strip()
            except Exception:
                return ""
    return ""


def _ensure_sheet_lamination_order_code(sheet_name):
	"""Backfill lamination order code for a sheet if missing (supports old/new field names)."""
	sheet_name = (sheet_name or "").strip()
	if not sheet_name or not frappe.db.exists("Planning sheet", sheet_name):
		return ""
	if not LAMINATION_ORDER_CODE_ENABLED:
		has_sheet_new = frappe.db.has_column("Planning sheet", "custom_lamination_order_code")
		has_sheet_old = frappe.db.has_column("Planning sheet", "custom_lamination_booking_id")
		fields = ["name"]
		if has_sheet_new:
			fields.append("custom_lamination_order_code")
		if has_sheet_old:
			fields.append("custom_lamination_booking_id")
		sheet = frappe.db.get_value("Planning sheet", sheet_name, fields, as_dict=True) or {}
		return (
			(sheet.get("custom_lamination_order_code") or sheet.get("custom_lamination_booking_id") or "")
			.strip()
		)

	has_sheet_new = frappe.db.has_column("Planning sheet", "custom_lamination_order_code")
	has_sheet_old = frappe.db.has_column("Planning sheet", "custom_lamination_booking_id")
	if not (has_sheet_new or has_sheet_old):
		return ""

	fields = ["name", "sales_order"]
	if has_sheet_new:
		fields.append("custom_lamination_order_code")
	if has_sheet_old:
		fields.append("custom_lamination_booking_id")
	sheet = frappe.db.get_value("Planning sheet", sheet_name, fields, as_dict=True) or {}

	code = (sheet.get("custom_lamination_order_code") or sheet.get("custom_lamination_booking_id") or "").strip()
	if code:
		return code

	has_lamination = frappe.db.sql(
		"""
		SELECT 1
		FROM `tabPlanning Table`
		WHERE parent=%s
		  AND (item_code LIKE '104%%' OR item_code LIKE %s)
		LIMIT 1
		""",
		(sheet_name, "%-107%"),
		as_list=True,
	)
	if not has_lamination:
		return ""

	code = _next_lamination_order_code()
	updates = []
	if has_sheet_new:
		updates.append("custom_lamination_order_code = %s")
	if has_sheet_old:
		updates.append("custom_lamination_booking_id = %s")
	if updates:
		frappe.db.sql(
			f"UPDATE `tabPlanning sheet` SET {', '.join(updates)} WHERE name = %s",
			tuple(([code] * len(updates)) + [sheet_name]),
		)

	if frappe.db.has_column("Planning Table", "custom_lamination_order_code_"):
		frappe.db.sql(
			"""
			UPDATE `tabPlanning Table`
			SET custom_lamination_order_code_ = %s
			WHERE parent = %s AND (item_code LIKE '104%%' OR item_code LIKE %s)
			""",
			(code, sheet_name, "%-107%"),
		)
	if frappe.db.has_column("Planning Table", "custom_lamination_booking_id"):
		frappe.db.sql(
			"""
			UPDATE `tabPlanning Table`
			SET custom_lamination_booking_id = %s
			WHERE parent = %s AND (item_code LIKE '104%%' OR item_code LIKE %s)
			""",
			(code, sheet_name, "%-107%"),
		)
	if frappe.db.has_column("Planning sheet Item", "custom_lamination_order_code"):
		frappe.db.sql(
			"""
			UPDATE `tabPlanning sheet Item`
			SET custom_lamination_order_code = %s
			WHERE parent = %s AND (item_code LIKE '104%%' OR item_code LIKE %s)
			""",
			(code, sheet_name, "%-107%"),
		)

	so = (sheet.get("sales_order") or "").strip()
	if so:
		if frappe.db.has_column("Sales Order", "custom_lamination_order_code"):
			frappe.db.set_value("Sales Order", so, "custom_lamination_order_code", code, update_modified=False)
		elif frappe.db.has_column("Sales Order", "custom_lamination_booking_id"):
			frappe.db.set_value("Sales Order", so, "custom_lamination_booking_id", code, update_modified=False)

	return code


@frappe.whitelist()
def get_fabric_item_from_laminated_item(lam_item_code):
	"""
	Resolve the single fabric FG (item code prefix 100) from the 104/107 laminated item's active BOM.
	Returns {"fabric_item_code", "bom_no"}. Raises with a clear message if invalid.
	"""
	item_code = (lam_item_code or "").strip()
	if len(item_code) < 3:
		frappe.throw(_("Item code is too short to read process prefix (need at least 3 characters)."))
	proc = _lamination_process_from_item_code(item_code)
	if proc not in ("104", "107"):
		frappe.throw(
			_("Lamination item must have process code 104 or 107. Got: {0}").format(proc or "")
		)
	return _get_fabric_item_from_process_item(item_code, expected_process=proc, process_label="Lamination")


# Sheet FG BOM first child before fabric 100 (251 has direct 100 on FG BOM).
_SHEET_FG_FIRST_CHILD = {
	"252": "105",
	"253": "104",
	"254": "106",
	"255": "107",
}


def _resolve_fabric_through_bom_chain(item_code, process_code, process_label):
	"""Resolve fabric 100* for sheet FG items (251 direct; 252–255 via mid-chain BOM)."""
	item_code = _cstr(item_code).strip()
	process_code = _cstr(process_code).strip()
	if not frappe.db.exists("Item", item_code):
		frappe.throw(_("Item {0} does not exist.").format(item_code))

	if process_code == "251":
		bom = _resolve_lamination_bom(item_code)
		if not bom:
			frappe.throw(_("No active submitted BOM for {0} item {1}.").format(process_label.lower(), item_code))
		fabric_rows = []
		for row in bom.items or []:
			ic = (row.item_code or "").strip()
			if len(ic) >= 3 and ic[:3] == "100":
				fabric_rows.append(ic)
		if not fabric_rows:
			frappe.throw(
				_("BOM {0} has no fabric FG row (item code must start with 100). Fix BOM for {1}.").format(
					bom.name, item_code
				)
			)
		if len(fabric_rows) > 1:
			frappe.throw(
				_("BOM {0} has multiple fabric components (100): {1}. Keep exactly one fabric FG.").format(
					bom.name, ", ".join(fabric_rows)
				)
			)
		fabric_item_code = fabric_rows[0]
		if not frappe.db.exists("Item", fabric_item_code):
			frappe.throw(_("Fabric item {0} from BOM does not exist.").format(fabric_item_code))
		return {"fabric_item_code": fabric_item_code, "bom_no": bom.name}

	first_child = _SHEET_FG_FIRST_CHILD.get(process_code)
	if not first_child:
		frappe.throw(_("Unsupported sheet process {0} for fabric chain.").format(process_code))

	mid_res = _get_bom_child_item_from_process_item(item_code, process_code, first_child, process_label)
	mid_ic = mid_res["child_item_code"]
	fg_bom_no = mid_res["bom_no"]

	if process_code == "255":
		res107 = _resolve_107_child_components(mid_ic)
		fab = res107.get("fabric")
		if not fab:
			frappe.throw(
				_("BOM {0} for {1} has no fabric 100 child through 107 {2}. Fix the 107 BOM.").format(
					fg_bom_no, item_code, mid_ic
				)
			)
		fabric_item_code = fab[0]
		if not frappe.db.exists("Item", fabric_item_code):
			frappe.throw(_("Fabric item {0} from BOM does not exist.").format(fabric_item_code))
		return {"fabric_item_code": fabric_item_code, "bom_no": fg_bom_no}

	if process_code == "254":
		mid104_res = _get_bom_child_item_from_process_item(mid_ic, "106", "104", process_label)
		mid_ic = mid104_res["child_item_code"]
		fabric_proc = "104"
	else:
		fabric_proc = first_child

	fabric_res = _get_fabric_item_from_process_item(mid_ic, expected_process=fabric_proc, process_label=process_label)
	return {"fabric_item_code": fabric_res["fabric_item_code"], "bom_no": fg_bom_no}


def _get_fabric_item_from_process_item(item_code, expected_process, process_label):
	item_code = (item_code or "").strip()
	if len(item_code) < 3:
		frappe.throw(_("Item code is too short to read process prefix (need at least 3 characters)."))
	if expected_process in ("104", "107"):
		if _lamination_process_from_item_code(item_code) != expected_process:
			frappe.throw(
				_("{0} item must have process code {1}. Got: {2}").format(
					process_label, expected_process, _lamination_process_from_item_code(item_code) or ""
				)
			)
	elif expected_process == "102":
		if _item_process_prefix(item_code) != "102":
			frappe.throw(
				_("{0} item must have process code 102 in item code. Got: {1}").format(
					process_label, _item_process_prefix(item_code) or ""
				)
			)
	elif _item_process_prefix(item_code) != expected_process:
		frappe.throw(
			_("{0} item must have process code {1} in item code (first 3 digits). Got: {2}").format(
				process_label, expected_process, _item_process_prefix(item_code) or ""
			)
		)
	if not frappe.db.exists("Item", item_code):
		frappe.throw(_("Item {0} does not exist.").format(item_code))

	if expected_process in ("251", "252", "253", "254", "255"):
		return _resolve_fabric_through_bom_chain(item_code, expected_process, process_label)

	# Use same BOM resolution as lamination sync (default/active BOM on FG or on template via variant_of).
	bom = _resolve_lamination_bom(item_code)
	if not bom:
		frappe.throw(_("No active submitted BOM for {0} item {1}.").format(process_label.lower(), item_code))
	bom_name = bom.name
	fabric_rows = []
	for row in bom.items or []:
		ic = (row.item_code or "").strip()
		if len(ic) >= 3 and ic[:3] == "100":
			fabric_rows.append((ic, row))

	if len(fabric_rows) == 0:
		frappe.throw(
			_("BOM {0} has no fabric FG row (item code must start with 100). Fix BOM for {1}.").format(
				bom_name, item_code
			)
		)
	if len(fabric_rows) > 1:
		codes = ", ".join([f[0] for f in fabric_rows])
		frappe.throw(
			_("BOM {0} has multiple fabric components (100): {1}. Keep exactly one fabric FG.").format(bom_name, codes)
		)

	fabric_item_code = fabric_rows[0][0]
	if not frappe.db.exists("Item", fabric_item_code):
		frappe.throw(_("Fabric item {0} from BOM does not exist.").format(fabric_item_code))

	return {"fabric_item_code": fabric_item_code, "bom_no": bom_name}


def _pick_bom_child_rows_for_process(bom_items, expected_child_process, parent_item_code=""):
	"""Match BOM lines to a process code (107/104/…) including design-first item codes."""
	exp = str(expected_child_process or "").strip()
	rows = []
	for row in bom_items or []:
		ic = (row.item_code or "").strip()
		if not ic:
			continue
		if _bom_item_matches_process(ic, exp):
			rows.append((ic, row))
	if rows:
		return rows
	if exp == "PB":
		pb_rows = []
		for row in bom_items or []:
			ic = (row.item_code or "").strip()
			if ic and _is_printed_bopp_item_code(ic):
				pb_rows.append((ic, row))
		return pb_rows
	if exp != "107":
		return []
	# 107 on 255/108 BOMs: any non-fabric, non-PB line that is a BOPP mid item.
	fallback = []
	for row in bom_items or []:
		ic = (row.item_code or "").strip()
		if not ic or ic.startswith("100") or _is_printed_bopp_item_code(ic):
			continue
		if _is_107_mid_bopp_item(ic) or _lamination_process_from_item_code(ic) == "107":
			fallback.append((ic, row))
		elif re.search(r"-107(?=[A-Z0-9])", ic.upper()) or re.search(r"-107\d", ic.upper()):
			fallback.append((ic, row))
	if fallback:
		return fallback
	return []


def _get_bom_child_item_from_process_item(item_code, expected_parent_process, expected_child_process, process_label):
	"""Resolve one child process item from the active BOM for chained Stage 3 planning."""
	item_code = (item_code or "").strip()
	if not item_code:
		frappe.throw(_("{0} item code is required.").format(process_label))
	if not _bom_item_matches_process(item_code, expected_parent_process):
		frappe.throw(
			_("{0} parent must have process {1}. Got: {2}").format(
				process_label, expected_parent_process, _bom_item_process_code(item_code) or ""
			)
		)
	bom = _resolve_lamination_bom(item_code)
	if not bom:
		frappe.throw(_("No active submitted BOM for {0} item {1}.").format(process_label.lower(), item_code))
	child_rows = _pick_bom_child_rows_for_process(bom.items, expected_child_process, item_code)
	if len(child_rows) == 0:
		frappe.throw(
			_("BOM {0} has no process {1} child row for {2}.").format(
				bom.name, expected_child_process, item_code
			)
		)
	if len(child_rows) > 1:
		codes = ", ".join([r[0] for r in child_rows])
		frappe.throw(
			_("BOM {0} has multiple process {1} child rows: {2}. Keep exactly one.").format(
				bom.name, expected_child_process, codes
			)
		)
	child_item_code = child_rows[0][0]
	if not frappe.db.exists("Item", child_item_code):
		frappe.throw(_("Child item {0} from BOM does not exist.").format(child_item_code))
	return {"child_item_code": child_item_code, "bom_no": bom.name}


@frappe.whitelist()
def get_fabric_item_from_slitting_item(slitting_item_code):
	"""Resolve the single 100* fabric child for a slitting 103 item."""
	return _get_fabric_item_from_process_item(slitting_item_code, expected_process="103", process_label="Slitting")


@frappe.whitelist()
def get_fabric_item_from_rewinding_item(rewinding_item_code):
	"""Resolve the single 100* fabric child for a rewinding 102 item."""
	return _get_fabric_item_from_process_item(rewinding_item_code, expected_process="102", process_label="Rewinding")


@frappe.whitelist()
def get_fabric_item_from_sheet_cutting_item(sheet_cutting_item_code):
	"""Resolve the single 100* fabric child for a sheet-cutting 251 item."""
	return _get_fabric_item_from_process_item(
		sheet_cutting_item_code, expected_process="251", process_label="Sheet cutting"
	)


def _fabric_qty_from_bom(
	bom_name, fabric_item_code, lamination_so_qty, from_uom=None, parent_item_code=None, planning_sheet_name=None
):
	"""Lamination SO qty (FG) -> required fabric qty using BOM line qty / BOM quantity."""
	bom = frappe.get_doc("BOM", bom_name)
	fg_qty = flt(bom.quantity) or 1.0
	if fg_qty <= 0:
		fg_qty = 1.0
	lamination_so_qty = flt(lamination_so_qty) or 0
	
	if from_uom and parent_item_code and bom.uom and from_uom != bom.uom:
		# Convert lamination_so_qty from `from_uom` to `bom.uom`
		from_conv = 1.0
		if from_uom != frappe.db.get_value("Item", parent_item_code, "stock_uom"):
			from_conv = frappe.db.get_value("UOM Conversion Detail", {"parent": parent_item_code, "uom": from_uom}, "conversion_factor") or 1.0
		
		to_conv = 1.0
		if bom.uom != frappe.db.get_value("Item", parent_item_code, "stock_uom"):
			to_conv = frappe.db.get_value("UOM Conversion Detail", {"parent": parent_item_code, "uom": bom.uom}, "conversion_factor") or 1.0

		# UOM Conversion Detail conversion_factor is stored as:
		#   1 stock_uom = conversion_factor(uom) * qty_in_uom
		# so: qty_in_bom_uom = qty_in_from_uom * to_conv / from_conv
		lamination_so_qty = (lamination_so_qty * flt(to_conv)) / flt(from_conv)

	for row in bom.items or []:
		if (row.item_code or "").strip() == fabric_item_code:
			raw_qty = flt(lamination_so_qty) * flt(row.qty) / fg_qty
			bom_row_uom = _cstr(getattr(row, "uom", None) or "").strip()
			stock_uom = _cstr(frappe.db.get_value("Item", fabric_item_code, "stock_uom") or "").strip()
			if (
				planning_sheet_name
				and _planning_sheet_has_bag_fg(planning_sheet_name)
				and bom_row_uom.lower() == "meter"
			):
				return raw_qty
			return _uom_qty_to_stock_uom(fabric_item_code, raw_qty, bom_row_uom or stock_uom)
	return lamination_so_qty


def _fabric_qty_uom_from_bom(
	bom_name, fabric_item_code, parent_qty, from_uom=None, parent_item_code=None, planning_sheet_name=None
):
	"""Return (qty, uom) for a planning row; bag sheets keep Meter on BOM meter lines until desk convert."""
	qty = _fabric_qty_from_bom(
		bom_name, fabric_item_code, parent_qty, from_uom=from_uom, parent_item_code=parent_item_code, planning_sheet_name=planning_sheet_name
	)
	uom = _cstr(frappe.db.get_value("Item", fabric_item_code, "stock_uom") or "Kg").strip() or "Kg"
	if planning_sheet_name and _planning_sheet_has_bag_fg(planning_sheet_name):
		bom = frappe.get_doc("BOM", bom_name)
		for row in bom.items or []:
			if (row.item_code or "").strip() == (fabric_item_code or "").strip():
				br_uom = _cstr(getattr(row, "uom", None) or "").strip()
				if br_uom.lower() == "meter":
					return flt(qty), "Meter"
				break
	return flt(qty), uom


def _ensure_lamination_parent_units_on_sheet(planning_sheet_name):
	"""104/107 parent rows must use Lamination Unit so Lamination Order Table (107 BOPP / 104) can list them."""
	if not LAMINATION_FLOW_ENABLED or not planning_sheet_name:
		return False
	touched = False
	for row in frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		fields=["name", "item_code", "unit"],
	):
		ic = (row.get("item_code") or "").strip()
		if not _is_lamination_parent_process(ic):
			continue
		if normalize_planning_unit_for_select(row.get("unit")) != LAMINATION_UNIT:
			frappe.db.set_value("Planning Table", row.name, "unit", LAMINATION_UNIT, update_modified=False)
			touched = True
	for row in frappe.get_all(
		"Planning sheet Item",
		filters={"parent": planning_sheet_name},
		fields=["name", "item_code", "unit"],
	):
		ic = (row.get("item_code") or "").strip()
		if not _is_lamination_parent_process(ic):
			continue
		if normalize_planning_unit_for_select(row.get("unit")) != LAMINATION_UNIT:
			frappe.db.set_value("Planning sheet Item", row.name, "unit", LAMINATION_UNIT, update_modified=False)
			touched = True
	return touched


def _sync_stage3_safe(planning_sheet_name):
	"""254→106→104→100 (and other stage-3 BOM chains). Isolated so it still runs when lamination fabric sync is off."""
	if not planning_sheet_name:
		return
	try:
		_sync_stage3_process_planning_rows(planning_sheet_name)
	except Exception:
		frappe.log_error(frappe.get_traceback(), "_sync_stage3_process_planning_rows")


def _pt_soi_key(row):
	"""Normalize SO line key from a Planning Table / PSI row dict."""
	return (row.get("sales_order_item") or row.get("so_item") or "").strip()


def _planning_child_row_fields_for_query(doctype):
	"""Only columns that exist on this site's child table (PSI may lack sales_order_item)."""
	flds = ["name", "item_code"]
	for col in ("sales_order_item", "so_item", "custom_parent_child_trace_id"):
		try:
			if frappe.db.has_column(doctype, col):
				flds.append(col)
		except Exception:
			pass
	return flds


def _fg_design_prefix_from_item_code(item_code):
	"""Design prefix before ``-108`` / ``-107`` / ``-254`` (e.g. ``7465-108F…`` → ``7465``)."""
	ic = str(item_code or "").strip().upper()
	if "-" in ic:
		return ic.split("-", 1)[0]
	return ""


def _parent_fg_trace_for_lamination_row(planning_sheet_name, sales_order_item, parent_item_code=None):
	"""108/255 FG trace on the same planning sheet + SO line (for fabric progress / child stamping)."""
	soi = _cstr(sales_order_item).strip()
	ic = _cstr(parent_item_code).strip()
	pp = _item_process_prefix(ic)
	lam = _lamination_process_from_item_code(ic)
	if planning_sheet_name:
		if pp == "108" or lam == "107":
			maps = _108_trace_maps_for_sheet(planning_sheet_name)
			if maps.get("has_108"):
				if soi and soi in maps.get("trace_by_soi", {}):
					return maps["trace_by_soi"][soi]
				if maps.get("default_108"):
					return maps["default_108"]
			if soi:
				t108 = _resolve_108_family_trace(ic or "107", soi, planning_sheet_name)
				if t108:
					return t108
		if _is_sheet_cutting_parent_process(ic) or pp == "255" or lam == "255":
			t255 = _trace_from_255_parent_on_sales_order_line(soi, planning_sheet_name)
			if t255:
				return t255
	if soi and frappe.db.exists("Sales Order Item", soi):
		try:
			soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
			soi_pp = _item_process_prefix(soi_ic)
			if soi_pp == "108":
				return _parent_child_trace_id_from_item_code(soi_ic) or ""
			if soi_pp == "255" or _is_sheet_cutting_parent_process(soi_ic):
				return (
					_trace_from_255_parent_on_sales_order_line(soi, planning_sheet_name)
					or _parent_child_trace_id_from_item_code(soi_ic)
					or ""
				)
		except Exception:
			pass
	if pp == "108":
		return _parent_child_trace_id_from_item_code(ic) or ""
	if _is_sheet_cutting_parent_process(ic) or pp == "255":
		return _parent_child_trace_id_from_item_code(ic) or _trace_from_255_parent_on_sales_order_line(
			soi, planning_sheet_name
		)
	return ""


def _lamination_process_for_order_row(item_code, sales_order_item=None):
	"""Process code for lamination order table; 107 rows on 108 SO lines report as 108."""
	lp = _lamination_process_from_item_code(item_code) or _item_process_prefix(item_code)
	soi = _cstr(sales_order_item).strip()
	if lp == "107" and soi and frappe.db.exists("Sales Order Item", soi):
		try:
			soi_ic = _cstr(frappe.db.get_value("Sales Order Item", soi, "item_code")).strip()
			if _item_process_prefix(soi_ic) == "108":
				return "108"
		except Exception:
			pass
	return lp


def _so_fg_process_for_planning_row(row, so_by_name=None):
	"""Process code of the Sales Order finished-good line linked to this planning row."""
	soik = _pt_soi_key(row if isinstance(row, dict) else frappe._dict(row))
	if not soik:
		return ""
	so_it = (so_by_name or {}).get(soik)
	if not so_it:
		return ""
	return _bom_item_process_code(_cstr(getattr(so_it, "item_code", None)).strip())


def _stamp_108_bopp_family_trace_ids(planning_sheet_name):
	"""Force 107 / 100 / PB rows to use the **108** parent trace (never a 107-* trace on the mid BOM row)."""
	if not planning_sheet_name:
		return
	if not frappe.db.has_column("Planning Table", "custom_parent_child_trace_id"):
		return
	so_by_name = {}
	_so_n = frappe.db.get_value("Planning sheet", planning_sheet_name, "sales_order")
	if _so_n:
		try:
			_so_d = frappe.get_doc("Sales Order", _so_n)
			so_by_name = {str(it.name): it for it in (_so_d.items or [])}
		except Exception:
			so_by_name = {}
	pt_fields = _planning_child_row_fields_for_query("Planning Table")
	pt_rows = (
		frappe.get_all(
			"Planning Table",
			filters={"parent": planning_sheet_name},
			fields=pt_fields,
			limit_page_length=2000,
		)
		or []
	)
	trace_by_soi = {}
	trace_by_design = {}
	soi_by_design = {}
	default_108_trace = ""
	for pr in pt_rows:
		icp = str(pr.get("item_code") or "")
		if _bom_item_process_code(icp) != "108":
			continue
		soik = _pt_soi_key(pr)
		tid = _parent_child_trace_id_from_item_code(icp) or _cstr(pr.get("custom_parent_child_trace_id")).strip()
		if not tid:
			continue
		default_108_trace = tid
		if soik:
			trace_by_soi[soik] = tid
		dp = _fg_design_prefix_from_item_code(icp)
		if dp:
			trace_by_design[dp] = tid
			if soik:
				soi_by_design[dp] = soik
	if not default_108_trace and not trace_by_soi:
		return

	def _is_108_bopp_child(ic):
		iu = str(ic or "").upper()
		if _lamination_process_from_item_code(ic) == "107" or "-107" in iu:
			return True
		if str(ic or "").startswith("100"):
			return True
		if iu.startswith("PB-") or ("PRINTED" in iu and "BOPP" in iu):
			return True
		return False

	def _resolve_108_trace(row):
		ic = str(row.get("item_code") or "")
		soik = _pt_soi_key(row)
		if soik and soik in trace_by_soi:
			return trace_by_soi[soik], soik
		dp = _fg_design_prefix_from_item_code(ic)
		if dp and dp in trace_by_design:
			return trace_by_design[dp], soi_by_design.get(dp) or soik
		if _is_108_bopp_child(ic) and default_108_trace:
			fallback_soi = next(iter(trace_by_soi.keys())) if trace_by_soi else ""
			return default_108_trace, fallback_soi
		return "", ""

	def _apply_trace(table_doctype, row):
		if not _is_108_bopp_child(row.get("item_code")):
			return
		fg_pp = _so_fg_process_for_planning_row(row, so_by_name)
		if fg_pp and fg_pp != "108":
			return
		tid, parent_soi = _resolve_108_trace(row)
		if not tid:
			return
		nm = row.get("name")
		up = {}
		cur_tid = _cstr(row.get("custom_parent_child_trace_id")).strip()
		ic_row = row.get("item_code")
		if tid and _should_force_fg_family_trace(ic_row, cur_tid, tid, "108"):
			up["custom_parent_child_trace_id"] = tid
		if parent_soi:
			if table_doctype == "Planning Table":
				if frappe.db.has_column("Planning Table", "sales_order_item"):
					if not _cstr(frappe.db.get_value("Planning Table", nm, "sales_order_item")).strip():
						up["sales_order_item"] = parent_soi
				if frappe.db.has_column("Planning Table", "so_item"):
					if not _cstr(frappe.db.get_value("Planning Table", nm, "so_item")).strip():
						up["so_item"] = parent_soi
			elif table_doctype == "Planning sheet Item":
				if frappe.db.has_column("Planning sheet Item", "sales_order_item"):
					if not _cstr(frappe.db.get_value("Planning sheet Item", nm, "sales_order_item")).strip():
						up["sales_order_item"] = parent_soi
				if frappe.db.has_column("Planning sheet Item", "so_item"):
					if not _cstr(frappe.db.get_value("Planning sheet Item", nm, "so_item")).strip():
						up["so_item"] = parent_soi
		if up:
			frappe.db.set_value(table_doctype, nm, up, update_modified=False)

	for pr in pt_rows:
		_apply_trace("Planning Table", pr)

	if frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id"):
		psi_fields = _planning_child_row_fields_for_query("Planning sheet Item")
		psi_rows = (
			frappe.get_all(
				"Planning sheet Item",
				filters={"parent": planning_sheet_name},
				fields=psi_fields,
				limit_page_length=2000,
			)
			or []
		)
		for psi in psi_rows:
			_apply_trace("Planning sheet Item", psi)


def _is_fg_stamp_parent_item_code(item_code, fg_prefixes):
	ic = _cstr(item_code).strip()
	if not ic:
		return False
	pp = _item_process_prefix(ic)
	fg_set = set(fg_prefixes or ())
	if pp in fg_set:
		return True
	iu = ic.upper()
	for fg in fg_set:
		if re.search(rf"-{re.escape(fg)}(?=[A-Z0-9])", iu):
			return True
	if "255" in fg_set and _is_sheet_cutting_parent_process(ic):
		return True
	return False


def _should_force_fg_family_trace(item_code, current_trace_id, fg_trace_id, fg_process):
	"""Replace wrong native child traces (``104-``, ``107-``, ``108-``) with the SO FG parent trace."""
	if _should_apply_trace_to_row(item_code, current_trace_id, fg_trace_id):
		return True
	cur = _cstr(current_trace_id).strip()
	new_tid = _cstr(fg_trace_id).strip()
	fp = _cstr(fg_process).strip()
	if not cur or not new_tid:
		return False
	if cur == new_tid:
		return False
	child_pp = _bom_item_process_code(item_code)
	for wrong in ("103", "104", "107", "108", "106", "109", "100"):
		if child_pp == wrong and not re.search(rf"(^|-){re.escape(wrong)}(?:-|$)", new_tid):
			return True
		if _trace_is_native_process_trace(cur, wrong) or (
			wrong == "107" and _trace_is_native_107_process(cur)
		):
			for fg in BAG_FG_TRACE_STAMP_PROCESSES:
				if re.search(rf"(^|-){re.escape(fg)}(?:-|$)", new_tid):
					return True
	if fp and re.search(rf"(^|-){re.escape(fp)}(?:-|$)", new_tid) and not re.search(
		rf"(^|-){re.escape(fp)}(?:-|$)", cur
	):
		for wrong in ("103", "104", "107", "108", "106", "109", "100"):
			if wrong == fp:
				continue
			if _trace_is_native_process_trace(cur, wrong) or (
				wrong == "107" and _trace_is_native_107_process(cur)
			):
				return True
	return False


def _is_fg_stamp_child_item_code(item_code, include_pb=False, include_107_mid=False):
	ic = _cstr(item_code).strip()
	if not ic:
		return False
	if include_107_mid and _is_107_mid_bopp_item(ic):
		return True
	pp = _item_process_prefix(ic)
	lam = _lamination_process_from_item_code(ic)
	if pp in ("103", "104", "106") or lam in ("104",):
		return True
	if ic.startswith("100"):
		return True
	if include_pb and _is_printed_bopp_item_code(ic):
		return True
	return False


def _stamp_fg_family_trace_ids(planning_sheet_name, fg_prefixes, include_pb=False, include_107_mid=False):
	"""Force BOM children (104 / 106 / 100 / PB / mid-107) to use the FG parent trace on the same SO line."""
	if not planning_sheet_name or not fg_prefixes:
		return
	if not frappe.db.has_column("Planning Table", "custom_parent_child_trace_id"):
		return
	fg_set = tuple(fg_prefixes)
	pt_rows, so_by_name = _planning_trace_sheet_context(planning_sheet_name)
	trace_by_soi = {}
	trace_by_design = {}
	soi_by_design = {}
	default_fg_trace = ""
	for pr in pt_rows:
		icp = _cstr(pr.get("item_code")).strip()
		if not _is_fg_stamp_parent_item_code(icp, fg_set):
			continue
		soik = _pt_soi_key(pr)
		tid = _parent_child_trace_id_from_item_code(icp) or _parent_child_trace_id_for_planning_row(
			icp, soik, planning_sheet_name
		)
		if not tid and "255" in fg_set:
			tid = _trace_from_255_parent_on_sales_order_line(soik, planning_sheet_name, pt_rows=pt_rows)
		if not tid and "109" in fg_set:
			tid = _trace_from_109_parent_on_sales_order_line(soik, planning_sheet_name, pt_rows=pt_rows)
		if not tid:
			continue
		default_fg_trace = tid
		if soik:
			trace_by_soi[soik] = tid
		dp = _fg_design_prefix_from_item_code(icp)
		if dp:
			trace_by_design[dp] = tid
			if soik:
				soi_by_design[dp] = soik
	if not default_fg_trace and not trace_by_soi:
		return

	def _resolve_fg_trace(row):
		ic = _cstr(row.get("item_code")).strip()
		soik = _pt_soi_key(row)
		if soik and soik in trace_by_soi:
			return trace_by_soi[soik], soik
		dp = _fg_design_prefix_from_item_code(ic)
		if dp and dp in trace_by_design:
			des_soi = _cstr(soi_by_design.get(dp)).strip()
			# Multi-item SO: never reuse another line's design trace (e.g. 226 vs 216 both design 7465).
			if soik and des_soi and soik == des_soi:
				return trace_by_design[dp], soik
			if not soik and des_soi:
				return trace_by_design[dp], des_soi
		return "", ""

	def _apply_fg_trace(table_doctype, row):
		ic_row = _cstr(row.get("item_code")).strip()
		if _is_fg_stamp_parent_item_code(ic_row, fg_set):
			tid = _parent_child_trace_id_from_item_code(ic_row) or _parent_child_trace_id_for_planning_row(
				ic_row, _pt_soi_key(row), planning_sheet_name
			)
			if not tid:
				return
			nm = row.get("name")
			up = {}
			cur_tid = _cstr(row.get("custom_parent_child_trace_id")).strip()
			if _should_apply_trace_to_row(ic_row, cur_tid, tid):
				up["custom_parent_child_trace_id"] = tid
			if up:
				frappe.db.set_value(table_doctype, nm, up, update_modified=False)
			return
		if not _is_fg_stamp_child_item_code(
			row.get("item_code"), include_pb=include_pb, include_107_mid=include_107_mid
		):
			return
		tid, parent_soi = _resolve_fg_trace(row)
		if not tid:
			soik_fb = _pt_soi_key(row)
			if soik_fb:
				tid = _bom_parent_trace_for_child_on_so_line(
					ic_row, soik_fb, planning_sheet_name, pt_rows, so_by_name=so_by_name
				)
				parent_soi = soik_fb
		if not tid:
			return
		nm = row.get("name")
		up = {}
		cur_tid = _cstr(row.get("custom_parent_child_trace_id")).strip()
		ic_row = row.get("item_code")
		fg_proc = ""
		for _fp in fg_set:
			if re.search(rf"(^|-){re.escape(_fp)}(?:-|$)", tid):
				fg_proc = _fp
				break
		if _should_force_fg_family_trace(ic_row, cur_tid, tid, fg_proc):
			up["custom_parent_child_trace_id"] = tid
		if parent_soi:
			if table_doctype == "Planning Table":
				if frappe.db.has_column("Planning Table", "sales_order_item"):
					if not _cstr(frappe.db.get_value("Planning Table", nm, "sales_order_item")).strip():
						up["sales_order_item"] = parent_soi
				if frappe.db.has_column("Planning Table", "so_item"):
					if not _cstr(frappe.db.get_value("Planning Table", nm, "so_item")).strip():
						up["so_item"] = parent_soi
			elif table_doctype == "Planning sheet Item":
				if frappe.db.has_column("Planning sheet Item", "sales_order_item"):
					if not _cstr(frappe.db.get_value("Planning sheet Item", nm, "sales_order_item")).strip():
						up["sales_order_item"] = parent_soi
				if frappe.db.has_column("Planning sheet Item", "so_item"):
					if not _cstr(frappe.db.get_value("Planning sheet Item", nm, "so_item")).strip():
						up["so_item"] = parent_soi
		if up:
			frappe.db.set_value(table_doctype, nm, up, update_modified=False)

	for pr in pt_rows:
		icp = _cstr(pr.get("item_code")).strip()
		if _is_fg_stamp_parent_item_code(icp, fg_set):
			_apply_fg_trace("Planning Table", pr)
		elif _is_fg_stamp_child_item_code(icp, include_pb=include_pb, include_107_mid=include_107_mid):
			_apply_fg_trace("Planning Table", pr)

	if frappe.db.has_column("Planning sheet Item", "custom_parent_child_trace_id"):
		psi_fields = _planning_child_row_fields_for_query("Planning sheet Item")
		psi_rows = (
			frappe.get_all(
				"Planning sheet Item",
				filters={"parent": planning_sheet_name},
				fields=psi_fields,
				limit_page_length=2000,
			)
			or []
		)
		for psi in psi_rows:
			icp = _cstr(psi.get("item_code")).strip()
			if _is_fg_stamp_parent_item_code(icp, fg_set) or _is_fg_stamp_child_item_code(
				icp, include_pb=include_pb, include_107_mid=include_107_mid
			):
				_apply_fg_trace("Planning sheet Item", psi)


def _stamp_109_family_trace_ids(planning_sheet_name):
	"""109 slitting FG: 104 / 100 children inherit ``109-…`` (never native ``104-`` / ``108-``)."""
	_stamp_fg_family_trace_ids(planning_sheet_name, ("109",))


