@frappe.whitelist()
def assign_printing_shift(shift_date=None, shift_label="DAY", item_name=None, unit=None):
    """Assign DAY/NIGHT shift for printing (105) rows (design-first item codes with -105...)."""
    target_date = getdate(shift_date or frappe.utils.nowdate())
    shift_label = (shift_label or "DAY").strip().upper()
    if shift_label not in ("DAY", "NIGHT"):
        frappe.throw(_("Shift must be DAY or NIGHT."))
    if not frappe.db.has_column("Planning Table", "custom_printing_shift"):
        frappe.throw(_("Field custom_printing_shift is missing on Planning Table. Please migrate."))
    printing_units = [
        PRINTING_UNIT_2_COLOUR,
        PRINTING_UNIT_4_COLOUR,
        PRINTING_UNIT_TT,
        PRINTING_UNASSIGNED_UNIT,
    ]
    allowed_units = set(printing_units)
    unit_filter = normalize_planning_unit_for_select(unit) if unit else ""
    if unit_filter and unit_filter not in allowed_units:
        unit_filter = _cstr(unit)
    row_unit = ""
    if item_name and frappe.db.has_column("Planning Table", "unit"):
        row_unit = _cstr(frappe.db.get_value("Planning Table", _cstr(item_name), "unit"))
    check_unit = row_unit or unit_filter
    pt_date_col = "planned_date" if frappe.db.has_column("Planning Table", "planned_date") else (
        "custom_item_planned_date" if frappe.db.has_column("Planning Table", "custom_item_planned_date") else None
    )
    maint_ref = target_date
    if item_name and pt_date_col:
        pv = frappe.db.get_value("Planning Table", _cstr(item_name).strip(), pt_date_col)
        if pv:
            maint_ref = getdate(pv)
    if check_unit and is_date_under_maintenance(check_unit, str(maint_ref)):
        info = get_maintenance_info_on_date(check_unit, str(maint_ref)) or {}
        frappe.throw(
            _("Cannot place printing orders on {0}. {1} is off ({2}) from {3} to {4}.").format(
                maint_ref,
                check_unit,
                info.get("type") or "Maintenance",
                info.get("start_date") or maint_ref,
                info.get("end_date") or maint_ref,
            )
        )

    has_sheet_planned = frappe.db.has_column("Planning sheet", "custom_planned_date")
    eff_date = (
        f"CASE WHEN pt.{pt_date_col} IS NOT NULL THEN pt.{pt_date_col} ELSE COALESCE(ps.custom_planned_date, ps.ordered_date) END"
        if (has_sheet_planned and pt_date_col)
        else (f"COALESCE(pt.{pt_date_col}, ps.ordered_date)" if pt_date_col else "COALESCE(ps.custom_planned_date, ps.ordered_date)")
    )

    filt_parts = [
        "UPPER(TRIM(IFNULL(pt.item_code,''))) LIKE '105%%'",
        "UPPER(TRIM(IFNULL(pt.item_code,''))) LIKE '%%-105%%'",
        "UPPER(TRIM(IFNULL(pt.item_code,''))) LIKE '106%%'",
        "UPPER(TRIM(IFNULL(pt.item_code,''))) LIKE '%%-106%%'",
    ]
    filt_params = []
    if frappe.db.has_column("Planning Table", "unit"):
        unit_marks = ",".join(["%s"] * len(printing_units))
        filt_parts.append(f"TRIM(IFNULL(pt.unit, '')) IN ({unit_marks})")
        filt_params.extend(printing_units)
    filt = "(" + " OR ".join(filt_parts) + ")"
    if item_name:
        set_parts = ["pt.custom_printing_shift = %s"]
        values = [shift_label]
        values.extend(filt_params)
        values.append(str(item_name).strip())
        frappe.db.sql(
            f"""
            UPDATE `tabPlanning Table` pt
            INNER JOIN `tabPlanning sheet` ps ON ps.name = pt.parent
            SET {", ".join(set_parts)}
            WHERE ps.docstatus < 2
              AND {filt}
              AND pt.name = %s
            """,
            tuple(values),
        )
    else:
        unit_clause = ""
        values = [shift_label]
        values.extend(filt_params)
        values.append(target_date)
        if unit_filter and frappe.db.has_column("Planning Table", "unit"):
            unit_clause = " AND TRIM(IFNULL(pt.unit, '')) = %s"
            values.append(unit_filter)
        frappe.db.sql(
            f"""
            UPDATE `tabPlanning Table` pt
            INNER JOIN `tabPlanning sheet` ps ON ps.name = pt.parent
            SET pt.custom_printing_shift = %s
            WHERE ps.docstatus < 2
              AND {filt}
              AND DATE({eff_date}) = DATE(%s)
              {unit_clause}
            """,
            tuple(values),
        )
    updated = frappe.db.sql("SELECT ROW_COUNT() as c", as_dict=True)[0].get("c") or 0
    frappe.db.commit()
    return {"status": "ok", "updated_count": int(updated), "date": str(target_date), "shift": shift_label}


