def _item_quality_from_db(item_code):
	"""Item quality without assuming `custom_quality` exists on Item (site-specific custom fields)."""
	ic = str(item_code or "").strip()
	if not ic or not frappe.db.exists("Item", ic):
		return ""
	# Try each column in order; catch DB errors so missing columns never break planning/BOPP sync.
	for col in ("custom_quality", "quality"):
		try:
			v = frappe.db.get_value("Item", ic, col)
			if v is not None and str(v).strip():
				return str(v).strip()
		except Exception:
			continue
	return ""


def _parse_gsm_width_from_item_text(raw_text):
	"""Parse GSM and width (inch) from item code + item name (same token rules as SO line populate)."""
	if not raw_text:
		return 0, 0.0
	rt = str(raw_text)
	width_pref = 0.0
	# Prefer explicit inch width in item name: "W - 16.5" / "W-16.9"
	mw = re.search(r"W\s*-\s*(\d+(?:\.\d+)?)", rt, re.IGNORECASE)
	if mw:
		width_pref = flt(mw.group(1))
	# "16''" / 16" style (marketing text; often rounded vs mm in parentheses)
	if width_pref <= 0:
		m_inch = re.search(r"(\d+(?:\.\d+)?)\s*(?:''|\"|[\u2019]{2}|″)", rt)
		if m_inch:
			width_pref = flt(m_inch.group(1))
	# Millimetres in parentheses, e.g. "( 1075 MM )" → inches to 2 decimals (42.32)
	mm = re.search(r"\(\s*(\d+)\s*MM\s*\)", rt, re.IGNORECASE)
	if width_pref <= 0 and mm:
		width_pref = round(flt(mm.group(1)) / 25.4, 2)
	clean_txt = raw_text.upper().replace("-", " ").replace("_", " ").replace("(", " ").replace(")", " ")
	clean_txt = clean_txt.replace("''", " INCH ").replace('"', " INCH ")
	words = clean_txt.split()
	gsm = 0
	for i, w in enumerate(words):
		if w == "GSM" and i > 0 and words[i - 1].isdigit():
			gsm = int(words[i - 1])
			break
		elif w.endswith("GSM") and len(w) > 3 and w[:-3].isdigit():
			gsm = int(w[:-3])
			break
	width = 0.0
	for i, w in enumerate(words):
		if w == "W" and i < len(words) - 1 and words[i + 1].replace(".", "", 1).isdigit():
			width = float(words[i + 1])
			break
		elif w.startswith("W") and len(w) > 1 and w[1:].replace(".", "", 1).isdigit():
			width = float(w[1:])
			break
		elif w == "INCH" and i > 0 and words[i - 1].replace(".", "", 1).isdigit():
			width = float(words[i - 1])
			break
		elif w.endswith("INCH") and len(w) > 4 and w[:-4].replace(".", "", 1).isdigit():
			width = float(w[:-4])
			break
	if width_pref > 0:
		# Keep exact name width (e.g. 42.32 / 45.47); only normalize float noise
		width = round(flt(width_pref), 2)
	elif width > 0:
		width = round(flt(width), 2)
	return gsm, width


def _fabric_gsm_before_width_in_item_text(raw_text):
	"""Prefer ``110 GSM W -`` style fabric GSM over earlier marketing numbers in long titles."""
	rt = str(raw_text or "")
	m = re.search(r"(\d{2,3})\s*GSM\s*W\s*[-\s]", rt, re.IGNORECASE)
	if m:
		try:
			v = int(m.group(1))
			if 30 <= v <= 500:
				return v
		except Exception:
			pass
	return 0


def _fabric_row_specs_from_fabric_item(fabric_ic, so_it, lam_row):
	"""
	GSM, width, colour, quality for the fabric line  from fabric Item only (never lamination row).
	Reuses the same extraction rules as _populate_planning_sheet_items for 100* items.
	"""
	quality_lookup = list(QUAL_LIST)
	try:
		qm_names = frappe.get_all("Quality Master", pluck="name") or []
		for qn in qm_names:
			qn_up = str(qn or "").upper().strip()
			if qn_up and qn_up not in quality_lookup:
				quality_lookup.append(qn_up)
	except Exception:
		pass
	quality_lookup.sort(key=len, reverse=True)

	item_name = frappe.db.get_value("Item", fabric_ic, "item_name") or ""
	raw_txt = f"{fabric_ic} {item_name}"
	gsm_bw = _fabric_gsm_before_width_in_item_text(raw_txt)
	gsm, width = _parse_gsm_width_from_item_text(raw_txt)
	if gsm_bw > 0:
		gsm = gsm_bw
	for col in ("custom_gsm", "gsm"):
		if gsm > 0:
			break
		if frappe.db.has_column("Item", col):
			try:
				v = frappe.db.get_value("Item", fabric_ic, col)
				if v is not None and flt(v) > 0:
					gsm = cint(v)
					break
			except Exception:
				pass
	# Prefer width parsed from item name / code; Item master width often rounded wrong (e.g. 17 vs 16.9).
	for col in ("custom_width_inch", "width_inch", "custom_width"):
		if flt(width) > 0:
			break
		if frappe.db.has_column("Item", col):
			try:
				v = frappe.db.get_value("Item", fabric_ic, col)
				if v is not None and flt(v) > 0:
					width = flt(v)
					break
			except Exception:
				pass
	if gsm <= 0:
		gsm, _ = _parse_gsm_width_from_item_text(raw_txt)
	if width <= 0:
		_, width = _parse_gsm_width_from_item_text(raw_txt)

	clean_txt = raw_txt.upper().replace("-", " ").replace("_", " ").replace("(", " ").replace(")", " ")
	clean_txt = clean_txt.replace("''", " INCH ").replace('"', " INCH ")
	words = clean_txt.split()
	qual = ""
	col = ""
	item_code_str = str(fabric_ic).strip()
	if len(item_code_str) >= 9 and item_code_str.startswith("100"):
		q_code = item_code_str[3:6]
		c_code = item_code_str[6:9]
		try:
			qual_name = (
				frappe.db.get_value("Quality Master", {"short_code": q_code}, "name")
				or frappe.db.get_value("Quality Master", {"code": q_code}, "name")
				or frappe.db.get_value("Quality Master", {"quality_code": q_code}, "name")
			)
			if qual_name:
				qual = qual_name
		except Exception:
			pass
		try:
			color_result = _get_color_by_code(c_code)
			if color_result:
				col = color_result
		except Exception:
			pass

	search_text = " " + " ".join(words) + " "
	search_norm = _normalize_quality_key(search_text)
	if not qual:
		for q in quality_lookup:
			if _normalize_quality_key(q) and _normalize_quality_key(q) in search_norm:
				qual = q
				break
	if not col:
		for c in COL_LIST:
			if (" " + c + " ") in search_text:
				col = c
				break
	if not col:
		su = search_text.upper()
		for c in COL_LIST:
			if c in su:
				col = c
				break

	line_quality = (qual or "").strip()
	if not line_quality:
		line_quality = _item_quality_from_db(fabric_ic)
	if not line_quality:
		line_quality = "GENERIC"

	m_roll = flt(getattr(so_it, "custom_meter_per_roll", 0) or 0)
	wt = 0.0

	meter = cint(lam_row.meter) if lam_row else 0
	meter_per_roll = cint(lam_row.meter_per_roll) if lam_row else cint(m_roll)
	no_of_rolls = cint(lam_row.no_of_rolls) if lam_row else cint(getattr(so_it, "custom_no_of_rolls", 0) or 0)

	if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(fabric_ic or "")) == "107":
		p107 = _parse_107_item_code(str(fabric_ic)) or {}
		comb107 = _combined_bopp_line_gsm(p107)
		if comb107 > 0:
			gsm = comb107
		elif cint(p107.get("fabric_gsm") or 0) > 0:
			gsm = cint(p107.get("fabric_gsm") or 0)
		if flt(p107.get("width_inch") or 0) > 0 and flt(width) <= 0:
			width = flt(p107.get("width_inch"))
		if (p107.get("colour_code") or "").strip():
			try:
				c107 = _get_color_by_code(p107.get("colour_code"))
				if c107:
					col = c107
			except Exception:
				pass
		qn107 = (p107.get("quality_name") or "").strip()
		if qn107:
			qual = qn107
			line_quality = qn107
	if LAMINATION_FLOW_ENABLED and (_item_process_prefix(str(fabric_ic or "")) == "255" or _lamination_process_from_item_code(str(fabric_ic or "")) == "255"):
		p255 = _parse_255_item_code(str(fabric_ic)) or {}
		comb255 = _combined_bopp_line_gsm(p255)
		if comb255 > 0:
			gsm = comb255
		elif cint(p255.get("fabric_gsm") or 0) > 0:
			gsm = cint(p255.get("fabric_gsm") or 0)
		if flt(p255.get("width_inch") or 0) > 0 and flt(width) <= 0:
			width = flt(p255.get("width_inch"))
		if (p255.get("colour_code") or "").strip():
			try:
				c255 = _get_color_by_code(p255.get("colour_code"))
				if c255:
					col = c255
			except Exception:
				pass
		qn255 = (p255.get("quality_name") or "").strip()
		if qn255:
			qual = qn255
			line_quality = qn255
	# Process 104 laminated FG: GSM + roll width from item code (not fabric Item master / sheet-size text).
	if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(fabric_ic or "")) == "104":
		gc = _gsm_from_lamination_item_code(str(fabric_ic))
		if gc > 0:
			gsm = gc
		w104 = _width_inch_from_104_item_code(str(fabric_ic))
		if w104 > 0:
			width = w104
		if gsm > 0 and width > 0 and m_roll > 0:
			wt = flt(gsm * width * m_roll * 0.0254) / 1000

	if gsm > 0 and width > 0 and m_roll > 0:
		wt = flt(gsm * width * m_roll * 0.0254) / 1000

	if _is_printed_bopp_item_code(str(fabric_ic or "")):
		width = 0.0
	elif flt(width) > 0:
		rw = round(flt(width), 2)
		width = float(int(rw)) if abs(rw - round(rw)) < 1e-9 else rw

	return {
		"gsm": cint(gsm) if gsm else 0,
		"width_inch": flt(width),
		"color": (col or "").strip() or "Unknown Color",
		"quality": line_quality,
		"custom_quality": (qual or line_quality),
		"weight_per_roll": wt,
		"meter": meter,
		"meter_per_roll": meter_per_roll,
		"no_of_rolls": no_of_rolls,
	}


# ... Limits ...
# --------------------------------------------------------------------------------
# SHARED HELPERS
# --------------------------------------------------------------------------------

def _populate_planning_sheet_items(ps, doc):
    """
    Populates items from a Sales Order into a Planning Sheet.
    Includes strict de-duplication based on sales_order_item.
    For existing items: UPDATE unit if changed (e.g., unassigned white order now assigned to a unit).
    For new items: CREATE new PSI record.
    """
    # Legacy ``Planning sheet Item`` grid + ``Planning Table`` board must share identical ``unit`` Select metadata in DB.
    ensure_planning_line_unit_docfield_options()
    # Stamp owning company from the Sales Order (create / regenerate / update all flow through here).
    try:
        if ps.meta.has_field("custom_company") and getattr(doc, "company", None):
            ps.custom_company = doc.company
    except Exception:
        pass
    try:
        so_name = getattr(doc, "name", None)
        if so_name and frappe.db.has_column("Sales Order", "custom_production_status"):
            current = (frappe.db.get_value("Sales Order", so_name, "custom_production_status") or "").strip()
            if current.lower() in ("", "draft"):
                frappe.db.set_value("Sales Order", so_name, "custom_production_status", "Confirmed")
    except Exception:
        pass
    # Use confirmed field name
    target_field = "planned_items"
    for field in ["planned_items", "custom_planned_items", "planning_table", "custom_planning_table", "table"]:
        if hasattr(ps, field) or ps.meta.has_field(field):
            target_field = field
            break

    # Fix: Use a list-based map (1:N) instead of a single mapping (1:1) to support split rows
    from collections import defaultdict
    existing_items_map = defaultdict(list)
    raw_list = getattr(ps, target_field, ps.get("items", []))
    for it in raw_list:
        _so_key = (getattr(it, "sales_order_item", None) or getattr(it, "so_item", None) or "").strip()
        if _so_key:
            existing_items_map[_so_key].append(it)

    # ... [Quality Lookup Logic] ...
    quality_lookup = list(QUAL_LIST)
    try:
        qm_names = frappe.get_all("Quality Master", pluck="name") or []
        for qn in qm_names:
            qn_up = str(qn or "").upper().strip()
            if qn_up and qn_up not in quality_lookup:
                quality_lookup.append(qn_up)
    except Exception:
        pass
    quality_lookup.sort(key=len, reverse=True)
    
    for it in doc.items:
        if _is_cylinder_yield_so_item(it.item_code):
            continue
        # Match all rows belonging to this SO item
        existing_psi_list = existing_items_map.get(it.name, [])
        is_existing = len(existing_psi_list) > 0
            
        raw_txt = (it.item_code or "") + " " + (it.item_name or "")
        clean_txt = raw_txt.upper().replace("-", " ").replace("_", " ").replace("(", " ").replace(")", " ")
        clean_txt = clean_txt.replace("''", " INCH ").replace('"', " INCH ")
        words = clean_txt.split()

        gsm, width = _parse_gsm_width_from_item_text(raw_txt)

        qual = ""
        col = ""
        item_code_str = str(it.item_code or "").strip()
        process_prefix = _item_process_prefix(item_code_str)
        if process_prefix == "100" or item_code_str.startswith("100"):
            gbw_pop = _fabric_gsm_before_width_in_item_text(raw_txt)
            if gbw_pop > 0:
                gsm = gbw_pop
        parsed107_early = {}
        if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(item_code_str) == "107":
            parsed107_early = _parse_107_item_code(item_code_str) or {}
            if parsed107_early.get("quality_name"):
                qual = str(parsed107_early.get("quality_name") or "").strip()
            comb107 = _combined_bopp_line_gsm(parsed107_early)
            if comb107 > 0:
                gsm = comb107
            elif cint(parsed107_early.get("fabric_gsm") or 0) > 0:
                gsm = cint(parsed107_early.get("fabric_gsm") or 0)
            if parsed107_early.get("colour_code"):
                try:
                    _c107 = _get_color_by_code(parsed107_early.get("colour_code"))
                    if _c107:
                        col = _c107
                except Exception:
                    pass
            if parsed107_early.get("width_inch") and flt(width) <= 0:
                width = flt(parsed107_early.get("width_inch") or 0)

        parsed255_early = {}
        if LAMINATION_FLOW_ENABLED and (
            _lamination_process_from_item_code(item_code_str) == "255" or process_prefix == "255"
        ):
            parsed255_early = _parse_255_item_code(item_code_str) or {}
            if parsed255_early.get("quality_name"):
                qual = str(parsed255_early.get("quality_name") or "").strip()
            comb255 = _combined_bopp_line_gsm(parsed255_early)
            if comb255 > 0:
                gsm = comb255
            elif cint(parsed255_early.get("fabric_gsm") or 0) > 0:
                gsm = cint(parsed255_early.get("fabric_gsm") or 0)
            if parsed255_early.get("colour_code"):
                try:
                    _c255 = _get_color_by_code(parsed255_early.get("colour_code"))
                    if _c255:
                        col = _c255
                except Exception:
                    pass
            if parsed255_early.get("width_inch") and flt(width) <= 0:
                width = flt(parsed255_early.get("width_inch") or 0)

        parsed108_early = {}
        if SLITTING_FLOW_ENABLED and process_prefix == "108":
            parsed108_early = _parse_108_item_code(item_code_str) or {}
            if parsed108_early.get("quality_name"):
                qual = str(parsed108_early.get("quality_name") or "").strip()
            comb108 = _combined_bopp_line_gsm(parsed108_early)
            if comb108 > 0:
                gsm = comb108
            elif cint(parsed108_early.get("fabric_gsm") or 0) > 0:
                gsm = cint(parsed108_early.get("fabric_gsm") or 0)
            if parsed108_early.get("colour_code"):
                try:
                    _c108 = _get_color_by_code(parsed108_early.get("colour_code"))
                    if _c108:
                        col = _c108
                except Exception:
                    pass
            if parsed108_early.get("width_inch") and flt(width) <= 0:
                width = flt(parsed108_early.get("width_inch") or 0)

        if process_prefix in BOX_BAG_PROCESS_CODES:
            box_specs = _box_bag_line_specs_from_item_code(item_code_str)
            if box_specs:
                if box_specs.get("quality"):
                    qual = box_specs["quality"]
                if box_specs.get("color"):
                    col = box_specs["color"]
                if cint(box_specs.get("gsm") or 0) > 0:
                    gsm = cint(box_specs["gsm"])

        digits = "".join(ch for ch in item_code_str if ch.isdigit())
        # For hyphenated codes like 6002-105..., extract from part after hyphen
        if "-" in item_code_str:
            after_hyphen = item_code_str.split("-", 1)[1] if "-" in item_code_str else item_code_str
            after_digits = "".join(ch for ch in after_hyphen if ch.isdigit())
        else:
            after_digits = digits
        parsed252_early = {}
        if process_prefix in ("251", "252"):
            parsed252_early = _parse_sheet_cutting_item_code(item_code_str) or {}
            if cint(parsed252_early.get("gsm") or 0) > 0:
                gsm = cint(parsed252_early.get("gsm") or 0)
            cc252 = (parsed252_early.get("colour_code") or "").strip()
            if cc252:
                try:
                    _col252 = _get_color_by_code(cc252)
                    if _col252:
                        col = _col252
                except Exception:
                    pass
            q252 = (parsed252_early.get("quality_code") or "").strip()
            if q252:
                qn252 = _quality_name_from_master(q252)
                if qn252:
                    qual = qn252
        parsed105_early = {}
        if process_prefix == "105" or _is_printing_105_parent_process(item_code_str):
            parsed105_early = _parse_105_item_code(item_code_str) or {}
            if cint(parsed105_early.get("gsm") or 0) > 0:
                gsm = cint(parsed105_early.get("gsm") or 0)
            cc105 = (parsed105_early.get("colour_code") or "").strip()
            if cc105:
                try:
                    _col105 = _get_color_by_code(cc105)
                    if _col105:
                        col = _col105
                except Exception:
                    pass
            q105 = (parsed105_early.get("quality_code") or "").strip()
            if q105:
                qn105 = _quality_name_from_master(q105)
                if qn105:
                    qual = qn105
            if cint(parsed105_early.get("width_mm") or 0) > 0 and flt(width) <= 0:
                width = round(cint(parsed105_early.get("width_mm") or 0) / 25.4)
        if len(after_digits) >= 9 and _lamination_process_from_item_code(item_code_str) not in ("107", "255") and process_prefix not in ("253", "255", "254", "108", "251", "252", "105", "211", "212", "213", "216", "221", "222", "223", "224", "231", "232", "233", "241", "242", "225", "226"):
            q_code = after_digits[3:6]
            c_code = after_digits[6:9]
            qn = _quality_name_from_master(q_code)
            if qn:
                qual = qn
            try:
                color_result = _get_color_by_code(c_code)
                if color_result:
                    col = color_result
            except Exception:
                pass
        strict_col = _color_from_item_code_6_to_8(item_code_str)
        # 107 BOPP letter codes: colour/quality/fabric GSM come from _parse_107_item_code. The
        # digit-window helper merges all digits in the code and does not match 107 layout, so it
        # overwrites a resolved colour with a wrong/empty value (table shows UNKNOWN / wrong GSM).
        bopp107_linespec_ok = bool(
            LAMINATION_FLOW_ENABLED
            and _lamination_process_from_item_code(item_code_str) == "107"
            and (
                (parsed107_early.get("colour_code") or "").strip()
                or (parsed107_early.get("quality_code") or "").strip()
                or (parsed107_early.get("fabric_gsm_code") or "").strip()
            )
        )
        bopp255_linespec_ok = bool(
            LAMINATION_FLOW_ENABLED
            and (
                _lamination_process_from_item_code(item_code_str) == "255" or process_prefix == "255"
            )
            and (
                (parsed255_early.get("colour_code") or "").strip()
                or (parsed255_early.get("quality_code") or "").strip()
                or (parsed255_early.get("fabric_gsm_code") or "").strip()
            )
        )
        bopp108_linespec_ok = bool(
            SLITTING_FLOW_ENABLED
            and process_prefix == "108"
            and (
                (parsed108_early.get("colour_code") or "").strip()
                or (parsed108_early.get("quality_code") or "").strip()
                or (parsed108_early.get("fabric_gsm_code") or "").strip()
            )
        )
        if process_prefix == "103":
            # Slitting must use code-based color only (digits 6:9); never infer from item text.
            col = strict_col or ""
        elif bopp107_linespec_ok or bopp255_linespec_ok or bopp108_linespec_ok:
            pass
        elif strict_col:
            col = strict_col

        search_text = " " + " ".join(words) + " "
        search_norm = _normalize_quality_key(search_text)
        if not qual:
            for q in quality_lookup:
                if _normalize_quality_key(q) and _normalize_quality_key(q) in search_norm:
                    qual = q
                    break
        if not col and process_prefix != "103":
            for c in COL_LIST:
                if (" " + c + " ") in search_text:
                    col = c
                    break
        # Fallback: substring match (longest-first COL_LIST) when spacing breaks " GOLDEN YELLOW " style match
        if not col and process_prefix != "103":
            su = search_text.upper()
            for c in COL_LIST:
                if c in su:
                    col = c
                    break

        # Mandatory `quality` on Planning sheet Item / Planning Table (DocType requires it)
        line_quality = (qual or "").strip()
        if not line_quality:
            line_quality = (
                str(getattr(it, "custom_quality", None) or getattr(it, "quality", None) or "").strip()
            )
        if not line_quality and it.item_code:
            line_quality = _item_quality_from_db(it.item_code)
        if not line_quality:
            line_quality = "GENERIC"

        m_roll = flt(it.custom_meter_per_roll)
        # For laminated FG (process 104), GSM must come from item-code index 9:12.
        if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(it.item_code or "")) == "104":
            gsm_from_code = _gsm_from_lamination_item_code(it.item_code)
            if gsm_from_code > 0:
                gsm = gsm_from_code
            w104_pop = _width_inch_from_104_item_code(it.item_code, getattr(it, "item_name", None) or "")
            if w104_pop > 0:
                width = w104_pop
        elif _item_process_prefix(str(it.item_code or "")) == "106":
            p106g = _parse_106_item_code(it.item_code) or {}
            if cint(p106g.get("gsm") or 0) > 0:
                gsm = cint(p106g.get("gsm") or 0)
            else:
                g6n, g6w = _parse_gsm_width_from_item_text(raw_txt)
                if g6n > 0:
                    gsm = g6n
                if g6w > 0 and flt(width) <= 0:
                    width = g6w
            if cint(p106g.get("width_mm") or 0) > 0:
                width = round(cint(p106g.get("width_mm") or 0) / 25.4)
        elif _item_process_prefix(str(it.item_code or "")) == "109":
            p109g = _parse_109_item_code(it.item_code) or {}
            if cint(p109g.get("gsm") or 0) > 0:
                gsm = cint(p109g.get("gsm") or 0)
        elif process_prefix in ("251", "252"):
            p252g = parsed252_early or (_parse_sheet_cutting_item_code(item_code_str) or {})
            if cint(p252g.get("gsm") or 0) > 0:
                gsm = cint(p252g.get("gsm") or 0)
            cc252g = (p252g.get("colour_code") or "").strip()
            if cc252g and not col:
                try:
                    _col252g = _get_color_by_code(cc252g)
                    if _col252g:
                        col = _col252g
                except Exception:
                    pass
            q252g = (p252g.get("quality_code") or "").strip()
            if q252g:
                qn252g = _quality_name_from_master(q252g)
                if qn252g:
                    qual = qn252g
        elif process_prefix == "105" or _is_printing_105_parent_process(item_code_str):
            p105g = parsed105_early or (_parse_105_item_code(item_code_str) or {})
            if cint(p105g.get("gsm") or 0) > 0:
                gsm = cint(p105g.get("gsm") or 0)
            if cint(p105g.get("width_mm") or 0) > 0:
                width = round(cint(p105g.get("width_mm") or 0) / 25.4)
        elif process_prefix in BOPP_BOX_BAG_PROCESS_CODES:
            try:
                from production_entry.production_planning.bopp_bag_api import _parse_bopp_bag_item_code
                p233g = _parse_bopp_bag_item_code(item_code_str) or {}
                if cint(p233g.get("total_gsm") or 0) > 0:
                    gsm = cint(p233g.get("total_gsm") or 0)
            except Exception:
                pass
        elif process_prefix in ("221", "224"):
            box_gsm = (_box_bag_line_specs_from_item_code(item_code_str) or {}).get("gsm") or 0
            if cint(box_gsm) > 0:
                gsm = cint(box_gsm)
        elif process_prefix == "253":
            p253g = _parse_253_item_code(it.item_code) or {}
            if cint(p253g.get("gsm") or 0) > 0:
                gsm = cint(p253g.get("gsm") or 0)
            cc253 = (p253g.get("colour_code") or "").strip()
            if cc253:
                try:
                    _col253 = _get_color_by_code(cc253)
                    if _col253:
                        col = _col253
                except Exception:
                    pass
            q3 = (p253g.get("quality_code") or "").strip()
            if q3:
                qn3 = _quality_name_from_master(q3)
                if qn3:
                    qual = qn3
        elif process_prefix == "254":
            p254g = _parse_254_item_code(it.item_code) or {}
            if cint(p254g.get("gsm") or 0) > 0:
                gsm = cint(p254g.get("gsm") or 0)
            cc254 = (p254g.get("colour_code") or "").strip()
            if cc254:
                try:
                    _col254 = _get_color_by_code(cc254)
                    if _col254:
                        col = _col254
                except Exception:
                    pass
            q4 = (p254g.get("quality_code") or "").strip()
            if q4:
                try:
                    for qc in (q4, q4.lstrip("0") or "0", (q4.lstrip("0") or "0").zfill(2)):
                        qual_name = (
                            frappe.db.get_value("Quality Master", {"short_code": qc}, "name")
                            or frappe.db.get_value("Quality Master", {"code": qc}, "name")
                            or frappe.db.get_value("Quality Master", {"quality_code": qc}, "name")
                            or frappe.db.get_value("Quality Master", qc, "name")
                        )
                        if qual_name:
                            qual = qual_name
                            break
                except Exception:
                    pass
        wt = 0.0
        if gsm > 0 and width > 0 and m_roll > 0:
            wt = flt(gsm * width * m_roll * 0.0254) / 1000

        lam_gsm = 0
        if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(it.item_code or "")) == "104":
            lam_gsm = _lam_gsm_from_item_code_suffix(it.item_code)
        elif LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(it.item_code or "")) == "107":
            p107g = parsed107_early or (_parse_107_item_code(it.item_code) or {})
            lam_gsm = cint(p107g.get("lam_gsm") or 0)
        elif _lamination_process_from_item_code(str(it.item_code or "")) == "255" or _item_process_prefix(str(it.item_code or "")) == "255":
            p255g = parsed255_early or (_parse_255_item_code(it.item_code) or {})
            lam_gsm = cint(p255g.get("lam_gsm") or 0)
        elif _item_process_prefix(str(it.item_code or "")) == "253":
            lam_gsm = cint((_parse_253_item_code(it.item_code) or {}).get("lam_gsm") or 0)
        elif _item_process_prefix(str(it.item_code or "")) == "254":
            lam_gsm = cint((_parse_254_item_code(it.item_code) or {}).get("lam_gsm") or 0)
        elif _item_process_prefix(str(it.item_code or "")) == "108":
            lam_gsm = cint((parsed108_early or _parse_108_item_code(it.item_code) or {}).get("lam_gsm") or 0)
        elif _item_process_prefix(str(it.item_code or "")) in ("106", "109"):
            lam_gsm = _stage3_lam_gsm_from_item_code(it.item_code)

        # Lamination side from Sales Order for lamination / slitting-lam parents (107, 104, 109).
        lam_side = ""
        _ic_so = str(it.item_code or "")
        _pp_so = _item_process_prefix(_ic_so)
        _lam_so = _lamination_process_from_item_code(_ic_so)
        if LAMINATION_FLOW_ENABLED and (_lam_so in ("107", "104") or _pp_so in ("104", "109")):
            lam_side = _lam_side_from_sales_order_item(getattr(it, "name", None))
            if not lam_side:
                lam_side = (getattr(it, "custom_lamination_side", None) or "").strip()

        unit = compute_default_production_unit(col, width, it.item_code)
        if process_prefix in BOX_BAG_PROCESS_CODES:
            unit = BOX_BAG_UNASSIGNED_UNIT
        
        # Planned date for Lamination parent (104/107) must be order date.
        # For Fabric (100), white-color logic remains unchanged.
        # For Sheet Cutting (251): always set planned_date = order date so board/table always shows them.
        p_date = None
        if LAMINATION_FLOW_ENABLED and _is_lamination_parent_process(str(it.item_code or "")):
             p_date = getdate(doc.transaction_date or ps.ordered_date)
        elif SLITTING_FLOW_ENABLED and _item_process_prefix(str(it.item_code or "")) in SLITTING_BOARD_PROCESS_CODES:
             p_date = getdate(doc.transaction_date or ps.ordered_date)
        elif REWINDING_FLOW_ENABLED and _item_process_prefix(str(it.item_code or "")) == "102":
             p_date = getdate(doc.transaction_date or ps.ordered_date)
        elif _item_process_prefix(str(it.item_code or "")) in ("251", "252", "253", "255", "254"):
             p_date = getdate(doc.transaction_date or ps.ordered_date)
        elif _is_printing_parent_process(str(it.item_code or "")):
             p_date = getdate(doc.transaction_date or ps.ordered_date)
        elif _is_white_color(col):
             p_date = getdate(ps.ordered_date)

        trace_id = _parent_child_trace_id_for_planning_row(
            it.item_code, it.name, getattr(ps, "name", None) or None
        )

        _sc_pp_pop = _item_process_prefix(item_code_str)
        _sc_lam_pop = _lamination_process_from_item_code(item_code_str)
        _so_sheets = 0
        if _sc_pp_pop in ("251", "252", "253", "254", "255") or _sc_lam_pop == "255":
            _so_sheets = _no_of_sheets_from_sales_order_item(getattr(it, "name", None))

        # Prepare PSI record data for syncing/creation
        psi_data = {
            "sales_order_item": it.name,
            "item_code": it.item_code,
            "item_name": it.item_name,
            "qty": it.qty,
            "uom": it.uom,
            "meter": flt(it.custom_meter),
            "meter_per_roll": m_roll,
            "no_of_rolls": flt(it.custom_no_of_rolls),
            "gsm": gsm,
            "width_inch": width,
            "quality": line_quality,
            "custom_quality": (qual or line_quality),
            "color": col,
            "weight_per_roll": wt,
            "unit": unit,
            "party_code": ps.party_code,
            "planned_date": p_date,
            "planning_sheet": ps.name # Explicitly link for grid visibility
        }
        if frappe.db.has_column("Planning sheet Item", "so_item") or frappe.db.has_column("Planning Table", "so_item"):
            psi_data["so_item"] = it.name
        if _so_sheets > 0 and frappe.db.has_column("Planning Table", "custom_no_of_sheets"):
            psi_data["custom_no_of_sheets"] = _so_sheets
        if _so_sheets > 0 and frappe.db.has_column("Planning sheet Item", "custom_no_of_sheets"):
            psi_data["custom_no_of_sheets"] = _so_sheets
        _set_movement_type_if_supported(psi_data, MOVEMENT_DESPATCH, "Planning sheet Item")
        if lam_gsm > 0 and frappe.db.has_column("Planning Table", "custom_lam_gsm"):
            psi_data["custom_lam_gsm"] = lam_gsm
        if lam_gsm > 0 and frappe.db.has_column("Planning sheet Item", "custom_lam_gsm"):
            psi_data["custom_lam_gsm"] = lam_gsm
        if lam_side:
            if frappe.db.has_column("Planning Table", "custom_lam_side_"):
                psi_data["custom_lam_side_"] = lam_side
            if frappe.db.has_column("Planning sheet Item", "custom_lam_side"):
                psi_data["custom_lam_side"] = lam_side
            # Also stamp header
            if frappe.db.has_column("Planning sheet", "custom_lam_side"):
                ps.custom_lam_side = lam_side
        if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(it.item_code or "")) == "107":
            for k, v in _planning_row_dict_107_lamination_extras(
				it.item_code, parsed107_early, it.name, getattr(ps, "name", None)
			).items():
                if k == "custom_parent_child_trace_id" and trace_id:
                    continue
                psi_data[k] = v
            _dn_so = _pb_design_name_from_sales_order_item(it.name)
            if _dn_so:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_so
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_so
        if _lamination_process_from_item_code(str(it.item_code or "")) == "255" or _item_process_prefix(str(it.item_code or "")) == "255":
            for k, v in _planning_row_dict_255_lamination_extras(it.item_code, parsed255_early, it.name).items():
                psi_data[k] = v
            _dn_so255 = _pb_design_name_from_sales_order_item(it.name)
            if _dn_so255:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_so255
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_so255
            _stamp_sheet_cutting_size_on_planning_dict(psi_data, it.item_code)
            if frappe.db.has_column("Planning Table", "unit"):
                psi_data["unit"] = SHEET_CUTTING_UNIT
        if _item_process_prefix(str(it.item_code or "")) == "253":
            p253row = _parse_253_item_code(it.item_code) or {}
            dc253 = (p253row.get("design_code") or "").strip().upper()
            if dc253 and frappe.db.has_column("Planning Table", "custom_design_code"):
                psi_data["custom_design_code"] = dc253
            dc253_so = _pb_design_code_from_sales_order_item(it.name)
            if dc253_so and frappe.db.has_column("Planning Table", "custom_design_code") and not psi_data.get("custom_design_code"):
                psi_data["custom_design_code"] = dc253_so
            _dn253 = _pb_design_name_from_sales_order_item(it.name)
            if _dn253:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn253
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn253
            _da253 = _printing_design_attachment_from_sales_order_item(it.name)
            if _da253:
                if frappe.db.has_column("Planning Table", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da253
                if frappe.db.has_column("Planning sheet Item", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da253
            _col253 = _pb_design_colour_from_sales_order_item(it.name)
            if _col253:
                if frappe.db.has_column("Planning Table", "custom_design_colour"):
                    psi_data["custom_design_colour"] = _col253
                if frappe.db.has_column("Planning sheet Item", "custom_design_colour"):
                    psi_data["custom_design_colour"] = _col253
            _stamp_sheet_cutting_size_on_planning_dict(psi_data, it.item_code)
            if frappe.db.has_column("Planning Table", "custom_bopp_gsm"):
                psi_data["custom_bopp_gsm"] = 0
            if frappe.db.has_column("Planning sheet Item", "custom_bopp_gsm"):
                psi_data["custom_bopp_gsm"] = 0
            psi_data["unit"] = SHEET_CUTTING_UNIT
        if _item_process_prefix(str(it.item_code or "")) == "254":
            p254row = _parse_254_item_code(it.item_code) or {}
            dc254 = (p254row.get("design_code") or "").strip().upper()
            if dc254 and frappe.db.has_column("Planning Table", "custom_design_code"):
                psi_data["custom_design_code"] = dc254
            dc254_so = _pb_design_code_from_sales_order_item(it.name)
            if dc254_so and frappe.db.has_column("Planning Table", "custom_design_code") and not psi_data.get("custom_design_code"):
                psi_data["custom_design_code"] = dc254_so
            _dn254 = _pb_design_name_from_sales_order_item(it.name)
            if _dn254:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn254
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn254
            _da254 = _printing_design_attachment_from_sales_order_item(it.name)
            if _da254:
                if frappe.db.has_column("Planning Table", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da254
                if frappe.db.has_column("Planning sheet Item", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da254
            _col254 = _pb_design_colour_from_sales_order_item(it.name)
            if _col254:
                if frappe.db.has_column("Planning Table", "custom_design_colour"):
                    psi_data["custom_design_colour"] = _col254
                if frappe.db.has_column("Planning sheet Item", "custom_design_colour"):
                    psi_data["custom_design_colour"] = _col254
            _dc_for_dm = (psi_data.get("custom_design_code") or dc254 or dc254_so or "").strip()
            for _k, _v in (_design_master_extra_fields(_dc_for_dm) or {}).items():
                if not _v or not str(_v).strip():
                    continue
                if frappe.db.has_column("Planning Table", _k) and not (psi_data.get(_k) or "").strip():
                    psi_data[_k] = _v
            _stamp_sheet_cutting_size_on_planning_dict(psi_data, it.item_code)
            if frappe.db.has_column("Planning Table", "custom_bopp_gsm"):
                psi_data["custom_bopp_gsm"] = 0
            if frappe.db.has_column("Planning sheet Item", "custom_bopp_gsm"):
                psi_data["custom_bopp_gsm"] = 0
            psi_data["unit"] = SHEET_CUTTING_UNIT
        if REWINDING_FLOW_ENABLED and _item_process_prefix(str(it.item_code or "")) == "102":
            psi_data["unit"] = REWINDING_UNASSIGNED_UNIT
        # Process 105 (Printing): extract design code/name/attachment from SO and parsed item code
        if _is_printing_105_parent_process(str(it.item_code or "")):
            p105_data = _parse_105_item_code(it.item_code) or {}
            _design_code_105 = (p105_data.get("design_code") or "").strip().upper()
            if _design_code_105 and frappe.db.has_column("Planning Table", "custom_design_code"):
                psi_data["custom_design_code"] = _design_code_105
            _dn_105 = _pb_design_name_from_sales_order_item(it.name)
            if _dn_105:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_105
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_105
            _da_105 = _printing_design_attachment_from_sales_order_item(it.name)
            if _da_105:
                if frappe.db.has_column("Planning Table", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da_105
                if frappe.db.has_column("Planning sheet Item", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da_105
            _dc_for_dm105 = (psi_data.get("custom_design_code") or _design_code_105 or "").strip()
            for _k105, _v105 in (_design_master_extra_fields(_dc_for_dm105) or {}).items():
                if not _v105 or not str(_v105).strip():
                    continue
                if frappe.db.has_column("Planning Table", _k105) and not (psi_data.get(_k105) or "").strip():
                    psi_data[_k105] = _v105
                if frappe.db.has_column("Planning sheet Item", _k105) and not (psi_data.get(_k105) or "").strip():
                    psi_data[_k105] = _v105
            # GSM from item code position 9-11 after hyphen
            if p105_data.get("gsm"):
                gsm_105 = cint(p105_data.get("gsm") or 0)
                if gsm_105 > 0:
                    psi_data["gsm"] = gsm_105
            # Width from item code last 4 digits (mm -> inches, rounded)
            if p105_data.get("width_mm"):
                w_mm = cint(p105_data.get("width_mm") or 0)
                if w_mm > 0:
                    w_inch = round(w_mm / 25.4)
                    psi_data["width_inch"] = w_inch
            # Force unit to UNASSIGNED PRINTING MACHINE
            psi_data["unit"] = PRINTING_UNASSIGNED_UNIT
        # Process 106 (Laminated Printing): printing board parent with lamination GSM.
        if _item_process_prefix(str(it.item_code or "")) == "106":
            p106_data = _parse_106_item_code(it.item_code) or {}
            _apply_design_fields_to_planning_dict(
                psi_data,
                so_item_name=it.name,
                design_code=(p106_data.get("design_code") or "").strip().upper() or None,
                item_code=it.item_code,
            )
            g106_so, w106_so = _parse_gsm_width_from_item_text(f"{it.item_code or ''} {it.item_name or ''}")
            g106_code = cint(p106_data.get("gsm") or 0)
            if g106_code > 0:
                psi_data["gsm"] = g106_code
            elif g106_so > 0:
                psi_data["gsm"] = g106_so
            if w106_so > 0:
                psi_data["width_inch"] = w106_so
            elif cint(p106_data.get("width_mm") or 0) > 0:
                psi_data["width_inch"] = round(cint(p106_data.get("width_mm") or 0) / 25.4)
            if cint(p106_data.get("lam_gsm") or 0) > 0 and (
                frappe.db.has_column("Planning Table", "custom_lam_gsm")
                or frappe.db.has_column("Planning sheet Item", "custom_lam_gsm")
            ):
                psi_data["custom_lam_gsm"] = cint(p106_data.get("lam_gsm") or 0)
            psi_data["unit"] = PRINTING_UNASSIGNED_UNIT
        # Process 108 (BOPP laminated slitting): slitting unit + BOPP stack extras.
        if _item_process_prefix(str(it.item_code or "")) == "108":
            p108_data = parsed108_early or (_parse_108_item_code(it.item_code) or {})
            csum108 = _combined_bopp_line_gsm(p108_data)
            if csum108 > 0:
                psi_data["gsm"] = csum108
            elif cint(p108_data.get("fabric_gsm") or 0) > 0:
                psi_data["gsm"] = cint(p108_data.get("fabric_gsm") or 0)
            if flt(p108_data.get("width_inch") or 0) > 0:
                w108 = round(flt(p108_data.get("width_inch") or 0), 1)
                psi_data["width_inch"] = float(int(w108)) if abs(w108 - round(w108)) < 1e-9 else w108
            for k, v in _planning_row_dict_108_slitting_extras(it.item_code, p108_data, it.name).items():
                if v is not None and str(v).strip() != "":
                    psi_data[k] = v
            dc108 = _cstr(p108_data.get("design_code") or "").strip().upper()
            if dc108 and (
                frappe.db.has_column("Planning Table", "custom_design_code")
                or frappe.db.has_column("Planning sheet Item", "custom_design_code")
            ):
                psi_data["custom_design_code"] = dc108
            _dn108 = _pb_design_name_from_sales_order_item(it.name)
            if _dn108:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn108
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn108
            _da108 = _printing_design_attachment_from_sales_order_item(it.name)
            if _da108:
                if frappe.db.has_column("Planning Table", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da108
                if frappe.db.has_column("Planning sheet Item", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da108
            _dc108_dm = (psi_data.get("custom_design_code") or dc108 or "").strip()
            for _k108, _v108 in (_design_master_extra_fields(_dc108_dm) or {}).items():
                if not _v108 or not str(_v108).strip():
                    continue
                if (frappe.db.has_column("Planning Table", _k108) or frappe.db.has_column("Planning sheet Item", _k108)) and not (
                    psi_data.get(_k108) or ""
                ).strip():
                    psi_data[_k108] = _v108
            psi_data["unit"] = SLITTING_UNIT
        # Process 109 (Laminated Slitting): slitting board parent with lamination GSM.
        if _item_process_prefix(str(it.item_code or "")) == "109":
            p109_data = _parse_109_item_code(it.item_code) or {}
            if cint(p109_data.get("gsm") or 0) > 0:
                psi_data["gsm"] = cint(p109_data.get("gsm") or 0)
            if cint(p109_data.get("lam_gsm") or 0) > 0 and (
                frappe.db.has_column("Planning Table", "custom_lam_gsm")
                or frappe.db.has_column("Planning sheet Item", "custom_lam_gsm")
            ):
                psi_data["custom_lam_gsm"] = cint(p109_data.get("lam_gsm") or 0)
            psi_data["unit"] = SLITTING_UNIT
        # Process 252 (Printed Sheet): sheet-cutting board parent with design metadata.
        if _item_process_prefix(str(it.item_code or "")) == "252":
            p252_data = parsed252_early or (_parse_sheet_cutting_item_code(it.item_code) or {})
            _dc_252 = (p252_data.get("design_code") or "").strip().upper()
            if _dc_252 and frappe.db.has_column("Planning Table", "custom_design_code"):
                psi_data["custom_design_code"] = _dc_252
            _dn_252 = _pb_design_name_from_sales_order_item(it.name)
            if _dn_252:
                if frappe.db.has_column("Planning Table", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_252
                if frappe.db.has_column("Planning sheet Item", "custom_design_name"):
                    psi_data["custom_design_name"] = _dn_252
            _da_252 = _printing_design_attachment_from_sales_order_item(it.name)
            if _da_252:
                if frappe.db.has_column("Planning Table", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da_252
                if frappe.db.has_column("Planning sheet Item", "custom_design_attachment"):
                    psi_data["custom_design_attachment"] = _da_252
            _dc_for_dm252 = (psi_data.get("custom_design_code") or _dc_252 or "").strip()
            for _k252, _v252 in (_design_master_extra_fields(_dc_for_dm252) or {}).items():
                if not _v252 or not str(_v252).strip():
                    continue
                if frappe.db.has_column("Planning Table", _k252) and not (psi_data.get(_k252) or "").strip():
                    psi_data[_k252] = _v252
                if frappe.db.has_column("Planning sheet Item", _k252) and not (psi_data.get(_k252) or "").strip():
                    psi_data[_k252] = _v252
            _stamp_sheet_cutting_size_on_planning_dict(psi_data, it.item_code)
            if cint(p252_data.get("gsm") or 0) > 0:
                psi_data["gsm"] = cint(p252_data.get("gsm") or 0)
            psi_data["unit"] = SHEET_CUTTING_UNIT
        # BOM children (100 / 104 / 106) on the same SO line key as the 254 FG row: inherit design + lam GSM from the sheet's 254 Planning row.
        _pp254child = _item_process_prefix(str(it.item_code or ""))
        if _pp254child in ("100", "104", "106") and getattr(ps, "name", None):
            _row254psi = _planning_row_254_parent_for_soi(ps.name, it.name) or {}
            if _row254psi:
                for _fld254 in (
                    "custom_design_code",
                    "custom_design_name",
                    "custom_design_attachment",
                    "custom_design_colour",
                    "custom_lam_gsm",
                ):
                    if not (
                        frappe.db.has_column("Planning Table", _fld254)
                        or frappe.db.has_column("Planning sheet Item", _fld254)
                    ):
                        continue
                    _vx = _cstr(_row254psi.get(_fld254)).strip()
                    if _vx and not _cstr(psi_data.get(_fld254)).strip():
                        psi_data[_fld254] = _vx
                _dc_psi254 = _cstr(psi_data.get("custom_design_code")).strip()
                for _kdm254, _vdm254 in (_design_master_extra_fields(_dc_psi254) or {}).items():
                    if not _vdm254 or not str(_vdm254).strip():
                        continue
                    if not (
                        frappe.db.has_column("Planning Table", _kdm254)
                        or frappe.db.has_column("Planning sheet Item", _kdm254)
                    ):
                        continue
                    if not _cstr(psi_data.get(_kdm254)).strip():
                        psi_data[_kdm254] = _vdm254
        _set_trace_id_if_supported(psi_data, trace_id)

        # Fix: Sync logic must be split-aware. Update existing rows without wiping extras.
        if is_existing:
            # Update all split pieces with latest metadata from SO (Qual/Color/etc if changed)
            for existing_psi in existing_psi_list:
                # Update base info but PRESERVE unit and qty (don't overwrite board splits)
                existing_psi.uom = it.uom
                existing_psi.quality = line_quality
                existing_psi.custom_quality = qual or line_quality
                existing_psi.color = col
                if gsm > 0 and hasattr(existing_psi, "gsm"):
                    existing_psi.gsm = gsm
                if _so_sheets > 0 and hasattr(existing_psi, "custom_no_of_sheets"):
                    existing_psi.custom_no_of_sheets = _so_sheets
                if lam_gsm > 0 and frappe.db.has_column("Planning Table", "custom_lam_gsm"):
                    existing_psi.custom_lam_gsm = lam_gsm
                if lam_gsm > 0 and frappe.db.has_column("Planning sheet Item", "custom_lam_gsm"):
                    existing_psi.custom_lam_gsm = lam_gsm
                if lam_side:
                    if frappe.db.has_column("Planning Table", "custom_lam_side_"):
                        existing_psi.custom_lam_side_ = lam_side
                    if frappe.db.has_column("Planning sheet Item", "custom_lam_side"):
                        existing_psi.custom_lam_side = lam_side
                # Ensure the link to parent is set
                existing_psi.planning_sheet = ps.name
                # Lamination parent (104/107) rows are always Lamination Unit (ignore existing unit/color).
                # Non-lamination rows: keep prior behavior (only set if unassigned).
                if LAMINATION_FLOW_ENABLED and _is_lamination_parent_process(str(it.item_code or "")):
                    existing_psi.unit = LAMINATION_UNIT
                    existing_psi.planned_date = p_date
                elif SLITTING_FLOW_ENABLED and _item_process_prefix(str(it.item_code or "")) in SLITTING_BOARD_PROCESS_CODES:
                    _pp_sl = _item_process_prefix(str(it.item_code or ""))
                    _nu_sl = normalize_planning_unit_for_select(getattr(existing_psi, "unit", None))
                    if _nu_sl in SLITTING_BOARD_UNITS:
                        existing_psi.unit = _nu_sl
                    else:
                        existing_psi.unit = _default_slitting_unit_for_process(_pp_sl)
                    existing_psi.planned_date = p_date
                elif REWINDING_FLOW_ENABLED and _item_process_prefix(str(it.item_code or "")) == "102":
                    prev = normalize_planning_unit_for_select(getattr(existing_psi, "unit", None))
                    if prev in REWINDING_BOARD_UNITS:
                        existing_psi.unit = prev
                    else:
                        existing_psi.unit = REWINDING_UNASSIGNED_UNIT
                    if p_date:
                        existing_psi.planned_date = p_date
                elif _item_process_prefix(str(it.item_code or "")) in ("251", "252", "253", "255", "254"):
                    existing_psi.unit = SHEET_CUTTING_UNIT
                    existing_psi.planned_date = p_date
                elif _is_printing_parent_process(str(it.item_code or "")):
                    existing_psi.unit = PRINTING_UNASSIGNED_UNIT
                    existing_psi.planned_date = p_date
                elif not existing_psi.unit or existing_psi.unit == "UNASSIGNED":
                    existing_psi.unit = unit
                    existing_psi.planned_date = p_date
                if _is_printing_105_parent_process(str(it.item_code or "")):
                    p105_data_e = parsed105_early or (_parse_105_item_code(it.item_code) or {})
                    _dc_e = (p105_data_e.get("design_code") or "").strip().upper()
                    if _dc_e and hasattr(existing_psi, "custom_design_code"):
                        existing_psi.custom_design_code = _dc_e
                    _dn_105_e = _pb_design_name_from_sales_order_item(it.name)
                    if _dn_105_e and hasattr(existing_psi, "custom_design_name"):
                        existing_psi.custom_design_name = _dn_105_e
                    _da_105_e = _printing_design_attachment_from_sales_order_item(it.name)
                    if _da_105_e and hasattr(existing_psi, "custom_design_attachment"):
                        existing_psi.custom_design_attachment = _da_105_e
                    for _k105e, _v105e in (_design_master_extra_fields(_dc_e) or {}).items():
                        if _v105e and hasattr(existing_psi, _k105e) and not _cstr(getattr(existing_psi, _k105e, None)).strip():
                            setattr(existing_psi, _k105e, _v105e)
                    if cint(p105_data_e.get("gsm") or 0) > 0:
                        existing_psi.gsm = cint(p105_data_e.get("gsm") or 0)
                    if cint(p105_data_e.get("width_mm") or 0) > 0:
                        existing_psi.width_inch = round(cint(p105_data_e.get("width_mm") or 0) / 25.4)
                if _item_process_prefix(str(it.item_code or "")) == "106":
                    p106_data_e = _parse_106_item_code(it.item_code) or {}
                    _dc_106_e = (p106_data_e.get("design_code") or "").strip().upper()
                    if _dc_106_e and hasattr(existing_psi, "custom_design_code"):
                        existing_psi.custom_design_code = _dc_106_e
                    _dn_106_e = _pb_design_name_from_sales_order_item(it.name)
                    if _dn_106_e and hasattr(existing_psi, "custom_design_name"):
                        existing_psi.custom_design_name = _dn_106_e
                    if cint(p106_data_e.get("gsm") or 0) > 0:
                        existing_psi.gsm = cint(p106_data_e.get("gsm") or 0)
                    if cint(p106_data_e.get("width_mm") or 0) > 0:
                        existing_psi.width_inch = round(cint(p106_data_e.get("width_mm") or 0) / 25.4)
                    if cint(p106_data_e.get("lam_gsm") or 0) > 0 and hasattr(existing_psi, "custom_lam_gsm"):
                        existing_psi.custom_lam_gsm = cint(p106_data_e.get("lam_gsm") or 0)
                if _item_process_prefix(str(it.item_code or "")) == "109":
                    p109_data_e = _parse_109_item_code(it.item_code) or {}
                    if cint(p109_data_e.get("gsm") or 0) > 0:
                        existing_psi.gsm = cint(p109_data_e.get("gsm") or 0)
                    if cint(p109_data_e.get("lam_gsm") or 0) > 0 and hasattr(existing_psi, "custom_lam_gsm"):
                        existing_psi.custom_lam_gsm = cint(p109_data_e.get("lam_gsm") or 0)
                if _item_process_prefix(str(it.item_code or "")) == "108":
                    p108_data_e = parsed108_early or (_parse_108_item_code(it.item_code) or {})
                    c108e = _combined_bopp_line_gsm(p108_data_e)
                    if c108e > 0:
                        existing_psi.gsm = c108e
                    elif cint(p108_data_e.get("fabric_gsm") or 0) > 0:
                        existing_psi.gsm = cint(p108_data_e.get("fabric_gsm") or 0)
                    for k, v in _planning_row_dict_108_slitting_extras(it.item_code, p108_data_e, it.name).items():
                        if hasattr(existing_psi, k):
                            setattr(existing_psi, k, v)
                if _item_process_prefix(str(it.item_code or "")) == "252":
                    p252_data_e = parsed252_early or (_parse_sheet_cutting_item_code(it.item_code) or {})
                    _dc_252_e = (p252_data_e.get("design_code") or "").strip().upper()
                    if _dc_252_e and hasattr(existing_psi, "custom_design_code"):
                        existing_psi.custom_design_code = _dc_252_e
                    _dn_252_e = _pb_design_name_from_sales_order_item(it.name)
                    if _dn_252_e and hasattr(existing_psi, "custom_design_name"):
                        existing_psi.custom_design_name = _dn_252_e
                    for _k252e, _v252e in (_design_master_extra_fields(_dc_252_e) or {}).items():
                        if _v252e and hasattr(existing_psi, _k252e) and not _cstr(getattr(existing_psi, _k252e, None)).strip():
                            setattr(existing_psi, _k252e, _v252e)
                    if cint(p252_data_e.get("gsm") or 0) > 0:
                        existing_psi.gsm = cint(p252_data_e.get("gsm") or 0)
                if _item_process_prefix(str(it.item_code or "")) == "253":
                    p253_e = _parse_253_item_code(it.item_code) or {}
                    _dc_253_e = (p253_e.get("design_code") or "").strip().upper()
                    if _dc_253_e and hasattr(existing_psi, "custom_design_code"):
                        existing_psi.custom_design_code = _dc_253_e
                    if lam_gsm > 0 and hasattr(existing_psi, "custom_lam_gsm"):
                        existing_psi.custom_lam_gsm = lam_gsm
                if _item_process_prefix(str(it.item_code or "")) == "254":
                    p254_e = _parse_254_item_code(it.item_code) or {}
                    _dc_254_e = (p254_e.get("design_code") or "").strip().upper()
                    if _dc_254_e and hasattr(existing_psi, "custom_design_code"):
                        existing_psi.custom_design_code = _dc_254_e
                    if lam_gsm > 0 and hasattr(existing_psi, "custom_lam_gsm"):
                        existing_psi.custom_lam_gsm = lam_gsm
                if _lamination_process_from_item_code(str(it.item_code or "")) == "255" or _item_process_prefix(str(it.item_code or "")) == "255":
                    for k, v in _planning_row_dict_255_lamination_extras(it.item_code, parsed255_early, it.name).items():
                        setattr(existing_psi, k, v)
                    _dn255e = _pb_design_name_from_sales_order_item(it.name)
                    if _dn255e and hasattr(existing_psi, "custom_design_name"):
                        existing_psi.custom_design_name = _dn255e
                if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(str(it.item_code or "")) == "107":
                    for k, v in _planning_row_dict_107_lamination_extras(
						it.item_code, parsed107_early, it.name, getattr(ps, "name", None)
					).items():
                        if k == "custom_parent_child_trace_id" and trace_id:
                            continue
                        setattr(existing_psi, k, v)
                    _dn_so_e = _pb_design_name_from_sales_order_item(it.name)
                    if _dn_so_e and hasattr(existing_psi, "custom_design_name"):
                        existing_psi.custom_design_name = _dn_so_e
                if _item_process_prefix(str(it.item_code or "")) in (
                    "105",
                    "106",
                    "108",
                    "252",
                    "253",
                    "254",
                    "255",
                ) or _is_printing_105_parent_process(str(it.item_code or "")):
                    _apply_design_fields_to_planning_row_doc(existing_psi, it.name, it.item_code)
                _set_trace_id_if_supported(existing_psi, trace_id)
        else:
            pt_data = psi_data.copy()
            pt_data["planned_date"] = p_date
            pt_data["plan_name"] = ps.get("custom_plan_name")
            pt_data["planning_sheet"] = ps.name # For redundancy
            if lam_gsm > 0 and frappe.db.has_column("Planning sheet Item", "custom_lam_gsm"):
                pt_data["custom_lam_gsm"] = lam_gsm
            
            # Plan 1: Always fill the legacy 'items' table if it exists
            if hasattr(ps, "items") or ps.meta.has_field("items"):
                ps.append("items", pt_data)
                
            # Plan 2: Also fill the new custom table field if it exists and is NOT the legacy 'items'
            target_fields = ["planned_items", "custom_planned_items", "planning_table", "custom_planning_table", "table"]
            for field in target_fields:
                if (hasattr(ps, field) or ps.meta.has_field(field)) and field != "items":
                    ps.append(field, pt_data)
                    # Once appended to a new-table row, stop checking other fields for this psi.
                    # This ensures 1:1 row order mapping for synchronisation logic.
                    break 
    return ps


def _is_white_color(color):
    """Return True if color string matches a white-family color."""
    if not color:
        return False
    c = color.upper().strip()
    return any(w == c for w in WHITE_COLORS)


def _default_slitting_unit_for_process(process_code: str) -> str:
    """Default slitting unit per process; 103 starts in unassigned lane."""
    return SLITTING_UNASSIGNED_UNIT if str(process_code or "") == "103" else SLITTING_UNIT


def compute_default_production_unit(color, width_inch, item_code=None):
    """
    Only white-family colors use UNASSIGNED (pool for that order date).
    Lamination parent (104/107) orders ALWAYS use Lamination Unit.
    PB-* printed BOPP BOM lines use the dedicated VR BOPP printing unit.
    All other colors: pick one of Unit 1-4 by minimum width waste.
    """
    ic = str(item_code or "").strip().upper()
    if ic.startswith("PB-"):
        return PRINTED_BOPP_FILM_UNIT
    if LAMINATION_FLOW_ENABLED and item_code and _is_lamination_parent_process(str(item_code)):
        return LAMINATION_UNIT
    if SLITTING_FLOW_ENABLED and item_code and _item_process_prefix(str(item_code)) == "103":
        return SLITTING_UNASSIGNED_UNIT
    if item_code and _item_process_prefix(str(item_code)) == "109":
        return SLITTING_UNIT
    if SLITTING_FLOW_ENABLED and item_code and _item_process_prefix(str(item_code)) in ("108", "110"):
        return SLITTING_UNIT
    if item_code and _item_process_prefix(str(item_code)) == "251":
        return SHEET_CUTTING_UNIT
    if item_code and _item_process_prefix(str(item_code)) == "252":
        return SHEET_CUTTING_UNIT
    if item_code and _item_process_prefix(str(item_code)) in ("253", "255", "254"):
        return SHEET_CUTTING_UNIT
    if item_code and _item_process_prefix(str(item_code)) in BOX_BAG_PROCESS_CODES:
        return BOX_BAG_UNASSIGNED_UNIT
    if item_code and _item_process_prefix(str(item_code)) in D_CUT_PROCESS_CODES:
        return D_CUT_UNASSIGNED_UNIT
    if item_code and _item_process_prefix(str(item_code)) in W_CUT_PROCESS_CODES:
        return W_CUT_UNASSIGNED_UNIT
    if REWINDING_FLOW_ENABLED and item_code and _item_process_prefix(str(item_code)) == "102":
        return REWINDING_UNASSIGNED_UNIT
    if item_code and _item_process_prefix(str(item_code)) == "106":
        return PRINTING_UNASSIGNED_UNIT
    if item_code and _is_printing_105_parent_process(str(item_code)):
        return PRINTING_UNASSIGNED_UNIT
    w = flt(width_inch)
    if _is_white_color(color):
        return "UNASSIGNED"
    UNIT_WIDTHS = {"Unit 1": 63, "Unit 2": 126, "Unit 3": 126, "Unit 4": 90}
    viable_units = []
    for u in ["Unit 1", "Unit 2", "Unit 3", "Unit 4"]:
        uw = UNIT_WIDTHS[u]
        if uw >= w:
            viable_units.append({"name": u, "width_waste": uw - w})
    if viable_units:
        return min(viable_units, key=lambda x: x["width_waste"])["name"]
    return "Unit 2"


def resolve_color_name_for_planning_row(item_code, item_name, existing_color=None):
    """Resolve color for width/unit rules when `color` was blank (item text / code parsing)."""
    if (existing_color or "").strip():
        return (existing_color or "").strip()
    raw_txt = ((item_code or "") + " " + (item_name or "")).strip()
    if not raw_txt:
        return ""
    clean_txt = raw_txt.upper().replace("-", " ").replace("_", " ").replace("(", " ").replace(")", " ")
    words = clean_txt.split()
    search_text = " " + " ".join(words) + " "
    col = ""
    item_code_str = str(item_code or "").strip()
    if LAMINATION_FLOW_ENABLED and _lamination_process_from_item_code(item_code_str) == "107":
        p107 = _parse_107_item_code(item_code_str) or {}
        if (p107.get("colour_code") or "").strip():
            try:
                c107 = _get_color_by_code(p107.get("colour_code"))
                if c107:
                    return str(c107).strip()
            except Exception:
                pass
    if LAMINATION_FLOW_ENABLED and (
        _lamination_process_from_item_code(item_code_str) == "255" or _item_process_prefix(item_code_str) == "255"
    ):
        p255c = _parse_255_item_code(item_code_str) or {}
        if (p255c.get("colour_code") or "").strip():
            try:
                c255 = _get_color_by_code(p255c.get("colour_code"))
                if c255:
                    return str(c255).strip()
            except Exception:
                pass
    if _item_process_prefix(item_code_str) == "253":
        p253c = _parse_253_item_code(item_code_str) or {}
        if (p253c.get("colour_code") or "").strip():
            try:
                c253 = _get_color_by_code(p253c.get("colour_code"))
                if c253:
                    return str(c253).strip()
            except Exception:
                pass
    if _item_process_prefix(item_code_str) == "108":
        p108c = _parse_108_item_code(item_code_str) or {}
        if (p108c.get("colour_code") or "").strip():
            try:
                c108 = _get_color_by_code(p108c.get("colour_code"))
                if c108:
                    return str(c108).strip()
            except Exception:
                pass
    if _item_process_prefix(item_code_str) == "254":
        p254c = _parse_254_item_code(item_code_str) or {}
        if (p254c.get("colour_code") or "").strip():
            try:
                c254 = _get_color_by_code(p254c.get("colour_code"))
                if c254:
                    return str(c254).strip()
            except Exception:
                pass
    # Slitting / 104-style: digit window 6:9 on the merged digit stream.
    color_from_code = _color_from_item_code_6_to_8(item_code_str)
    if color_from_code:
        return color_from_code
    for c in COL_LIST:
        if (" " + c + " ") in search_text:
            return c
    su = search_text.upper()
    for c in COL_LIST:
        if c in su:
            return c
    return ""


def _get_color_by_code(color_code):
    """
    Look up color in Colour Master by color code.
    Returns the color name if found, None otherwise.
    """
    if not color_code:
        return None
    
    color_code = str(color_code).strip()
    color_code_num = "".join(ch for ch in color_code if ch.isdigit())
    candidates = []
    for c in [color_code, color_code_num, color_code_num.lstrip("0")]:
        c = str(c or "").strip()
        if c and c not in candidates:
            candidates.append(c)
    # Common Colour Master format uses fixed-width numeric codes.
    if color_code_num:
        z3 = color_code_num.zfill(3)
        if z3 not in candidates:
            candidates.append(z3)
    
    # Try multiple field names in order of preference. Colour Master commonly stores
    # the business code in `colour_code`; keep aliases for older/custom sites.
    fields_to_try = ["colour_code", "custom_colour_code", "custom_color_code", "color_code", "short_code", "code"]
    cm_cols = set(frappe.db.get_table_columns("Colour Master") or [])
    fields_to_try = [f for f in fields_to_try if f in cm_cols]
    
    def _normalized_code_tokens(v):
        s = str(v or "").strip()
        if not s:
            return set()
        d = "".join(ch for ch in s if ch.isdigit())
        out = {s}
        if d:
            out.add(d)
            out.add(d.lstrip("0") or "0")
            out.add((d.lstrip("0") or "0").zfill(3))
            if len(d) >= 3:
                out.add(d[-3:])
        return {x.strip() for x in out if str(x or "").strip()}

    wanted_tokens = set()
    for c in candidates:
        wanted_tokens |= _normalized_code_tokens(c)

    for field in fields_to_try:
        for code in candidates:
            try:
                result = frappe.db.get_value(
                    "Colour Master",
                    {field: code},
                    ["name", "colour_name", "custom_colour_name", "color_name", "colour", "color"],
                    as_dict=True
                )
                if result:
                    color_name = (
                        result.get("colour_name")
                        or result.get("custom_colour_name")
                        or result.get("color_name")
                        or result.get("colour")
                        or result.get("color")
                        or result.get("name")
                    )
                    if color_name:
                        return color_name.upper().strip()
            except Exception:
                pass
        # Robust fallback: normalize db values (trim + remove leading zeros) before compare.
        try:
            ph = ", ".join(["%s"] * len(candidates))
            rows = frappe.db.sql(
                f"""
                SELECT name, colour_name, custom_colour_name, color_name, colour, color
                FROM `tabColour Master`
                WHERE IFNULL(TRIM(CAST({field} AS CHAR)), '') IN ({ph})
                   OR IFNULL(TRIM(LEADING '0' FROM TRIM(CAST({field} AS CHAR))), '') IN ({ph})
                ORDER BY modified DESC
                LIMIT 1
                """,
                tuple(candidates + candidates),
                as_dict=True,
            )
            if rows:
                rr = rows[0] or {}
                color_name = (
                    rr.get("colour_name")
                    or rr.get("custom_colour_name")
                    or rr.get("color_name")
                    or rr.get("colour")
                    or rr.get("color")
                    or rr.get("name")
                )
                if color_name:
                    return str(color_name).upper().strip()
        except Exception:
            pass

    # Last-resort Python fallback for messy code formats in Colour Master
    # (e.g. "C-221", "CLR 0521", etc.). Compare normalized numeric tokens.
    try:
        cols = set(frappe.db.get_table_columns("Colour Master") or [])
        code_cols = [c for c in ("colour_code", "custom_colour_code", "custom_color_code", "color_code", "short_code", "code") if c in cols]
        name_cols = [c for c in ("colour_name", "custom_colour_name", "color_name", "colour", "color") if c in cols]
        if code_cols:
            select_cols = list(dict.fromkeys(["name"] + code_cols + name_cols))
            rows = frappe.get_all("Colour Master", fields=select_cols, limit_page_length=0) or []
            for rr in rows:
                row_tokens = set()
                for c in code_cols:
                    row_tokens |= _normalized_code_tokens(rr.get(c))
                if not row_tokens.intersection(wanted_tokens):
                    continue
                color_name = ""
                for ncol in ("colour_name", "custom_colour_name", "color_name", "colour", "color"):
                    if ncol in rr and str(rr.get(ncol) or "").strip():
                        color_name = str(rr.get(ncol)).strip()
                        break
                if not color_name:
                    color_name = str(rr.get("name") or "").strip()
                if color_name:
                    return color_name.upper()
    except Exception:
        pass

    return None


def _color_from_item_code_6_to_8(item_code):
    """Color resolution from item-code numeric stream via Colour Master."""
    digits = "".join(ch for ch in str(item_code or "") if ch.isdigit())
    if len(digits) < 9:
        return ""
    candidates = []
    for start in (6, 5, 7):
        if len(digits) >= start + 3:
            cc = digits[start:start + 3]
            if cc and cc not in candidates:
                candidates.append(cc)
    for cc in candidates:
        c_name = str(_get_color_by_code(cc) or "").strip().upper()
        if c_name:
            return c_name
    return ""


def _normalize_color_text(v) -> str:
    s = str(v or "").strip()
    if not s:
        return ""
    su = s.upper()
    if su in {"UNKNOWN", "UNKNOWN COLOR", "NO COLOR", "N/A", "NA", "-"}:
        return ""
    return s


def _extract_color_from_sales_order_item(so_item_name: str) -> str:
    if not so_item_name or not frappe.db.exists("Sales Order Item", so_item_name):
        return ""
    cols = set(frappe.db.get_table_columns("Sales Order Item") or [])
    candidates = []
    for c in ("color", "custom_color", "colour", "custom_colour"):
        if c in cols:
            candidates.append(c)
    if not candidates:
        return ""
    row = frappe.db.get_value("Sales Order Item", so_item_name, candidates, as_dict=True) or {}
    for c in candidates:
        v = _normalize_color_text(row.get(c))
        if v:
            return v.upper().strip()
    return ""


@frappe.whitelist()
def refresh_planning_sheet_colors(planning_sheet: str):
    """Re-sync Planning sheet item colors from Sales Order Item / Item code parsing even after submit."""
    if not planning_sheet or not frappe.db.exists("Planning sheet", planning_sheet):
        return {"status": "error", "message": "Planning sheet not found", "updated": 0}

    rows = frappe.get_all(
        "Planning Table",
        filters={"parent": planning_sheet, "parenttype": "Planning sheet"},
        fields=["name", "sales_order_item", "item_code", "item_name", "color"],
        order_by="idx asc",
    ) or []

    updated = 0
    for r in rows:
        existing = _normalize_color_text(r.get("color"))
        from_so = _extract_color_from_sales_order_item(r.get("sales_order_item"))
        parsed = resolve_color_name_for_planning_row(
            r.get("item_code"), r.get("item_name"), existing_color=""
        )
        parsed = _normalize_color_text(parsed)
        # Keep color deterministic from item code across all processes.
        next_color = (parsed or from_so or "").upper().strip()
        if next_color and next_color != str(r.get("color") or "").strip().upper():
            frappe.db.set_value("Planning Table", r["name"], "color", next_color, update_modified=False)
            updated += 1

    if updated:
        frappe.db.set_value("Planning sheet", planning_sheet, "modified", frappe.utils.now(), update_modified=False)

    return {"status": "ok", "updated": updated, "message": f"Updated color on {updated} row(s)."}


def _spr_names_for_pp_item(pp_id: str, item_code: str = "") -> list:
	"""All SPRs (draft + submitted) for a PP that contain roll lines for item_code."""
	pp_id = _cstr(pp_id).strip()
	ic = _cstr(item_code).strip()
	if not pp_id:
		return []
	names = frappe.get_all(
		"Shaft Production Run",
		filters={"production_plan": pp_id, "docstatus": ["<", 2]},
		pluck="name",
		order_by="modified desc",
		limit_page_length=0,
	) or []
	if not ic:
		return [n for n in names if _spr_belongs_to_pp(n, pp_id)]
	out = []
	for sn in names:
		if not _spr_belongs_to_pp(sn, pp_id):
			continue
		if frappe.db.exists("Shaft Production Run Item", {"parent": sn, "item_code": ic}):
			out.append(sn)
	return out


@frappe.whitelist()
def refresh_planning_sheet_spr_and_order_sheet(planning_sheet: str):
    """Backfill Planning Table `order_sheet` and `spr_name` for a sheet even after submit."""
    if not planning_sheet or not frappe.db.exists("Planning sheet", planning_sheet):
        return {"status": "error", "message": "Planning sheet not found", "updated_order_sheet": 0, "updated_spr": 0}

    def _pick_valid_pp(raw) -> str:
        return _pick_valid_pp_id(raw)

    sheet_pp = (
        frappe.db.get_value("Planning sheet", planning_sheet, "custom_production_plan")
        if frappe.db.has_column("Planning sheet", "custom_production_plan")
        else ""
    ) or (
        frappe.db.get_value("Planning sheet", planning_sheet, "production_plan")
        if frappe.db.has_column("Planning sheet", "production_plan")
        else ""
    ) or (frappe.db.get_value("Planning sheet", planning_sheet, "order_sheet") or "")
    sheet_pp = _pick_valid_pp(sheet_pp)

    rows = frappe.get_all(
        "Planning Table",
        filters={"parent": planning_sheet, "parenttype": "Planning sheet"},
        fields=["name", "spr_name", "order_sheet", "item_code"],
        order_by="idx asc",
    ) or []

    pp_to_spr = {}
    updated_order_sheet = 0
    updated_spr = 0

    candidate_pps = set()
    if sheet_pp:
        candidate_pps.add(sheet_pp)
    for col in ("custom_planning_sheet", "planning_sheet"):
        if frappe.db.has_column("Production Plan", col):
            for ppn in frappe.db.get_all("Production Plan", filters={col: planning_sheet, "docstatus": ["<", 2]}, pluck="name"):
                if ppn:
                    candidate_pps.add(ppn)
    for row in rows:
        item_pp = _pick_valid_pp(_get_item_level_production_plan(row.get("name")))
        if item_pp:
            candidate_pps.add(item_pp)

    pp_by_item_code = {}
    if candidate_pps:
        fmt = ", ".join(["%s"] * len(candidate_pps))
        q = frappe.db.sql(
            f"""
            SELECT ppi.item_code, ppi.parent as production_plan
            FROM `tabProduction Plan Item` ppi
            WHERE ppi.parent IN ({fmt})
              AND IFNULL(ppi.item_code, '') != ''
            """,
            tuple(candidate_pps),
            as_dict=True,
        ) or []
        for r in q:
            it = (r.get("item_code") or "").strip()
            ppn = (r.get("production_plan") or "").strip()
            if it and ppn:
                pp_by_item_code.setdefault(it, [])
                if ppn not in pp_by_item_code[it]:
                    pp_by_item_code[it].append(ppn)

    def _pick_spr_for_pp(pp_id: str) -> str:
        pp_id = (pp_id or "").strip()
        if not pp_id:
            return ""
        if pp_id in pp_to_spr:
            return pp_to_spr[pp_id]

        spr_name = ""
        raw = str(frappe.db.get_value("Production Plan", pp_id, "custom_shaft_production_run_id") or "").strip()
        if raw:
            for p in [x.strip() for x in raw.split(",") if x and x.strip()]:
                if frappe.db.exists("Shaft Production Run", p) and _spr_belongs_to_pp(p, pp_id):
                    spr_name = p
                    break
        if not spr_name:
            spr_name = (
                frappe.db.get_value(
                    "Shaft Production Run",
                    {"production_plan": pp_id, "docstatus": ["<", 2]},
                    "name",
                    order_by="modified desc",
                )
                or ""
            )
            if spr_name and not _spr_belongs_to_pp(spr_name, pp_id):
                spr_name = ""
        pp_to_spr[pp_id] = spr_name
        return spr_name

    for r in rows:
        row_pp = _row_order_sheet_pp(row_name=r.get("name"), row_dict=r)
        if not row_pp:
            row_pp = _pick_valid_pp(_get_item_level_production_plan(r.name))
        if not row_pp:
            item_code = (r.get("item_code") or "").strip()
            choices = pp_by_item_code.get(item_code) or []
            if len(choices) == 1:
                row_pp = choices[0]
            elif len(choices) > 1:
                existing = _pick_valid_pp(r.get("order_sheet"))
                row_pp = existing if existing in choices else ""
        if not row_pp:
            row_pp = _pick_valid_pp(r.get("order_sheet"))
        if not row_pp:
            row_pp = sheet_pp
        os_field = _psi_order_sheet_field() or "order_sheet"
        cur_os = _pick_valid_pp(r.get("order_sheet"))
        if row_pp and cur_os and cur_os != row_pp:
            row_pp = cur_os
        if row_pp and cur_os != row_pp:
            if frappe.db.has_column("Planning Table", os_field):
                frappe.db.set_value("Planning Table", r["name"], os_field, row_pp, update_modified=False)
                updated_order_sheet += 1

        row_spr_ids = _spr_names_for_pp_item(row_pp, r.get("item_code")) if row_pp else []
        if not row_spr_ids and row_pp:
            row_spr_single = _pick_spr_for_pp(row_pp)
            if row_spr_single:
                row_spr_ids = [row_spr_single]
        cur_raw = str((r.get("spr_name") or "")).strip()
        cur_ids = _expand_spr_name_tokens(cur_raw)
        valid_ids = []
        seen_local = set()
        for sid in cur_ids:
            if row_pp and not _spr_belongs_to_pp(sid, row_pp):
                continue
            if sid not in seen_local:
                seen_local.add(sid)
                valid_ids.append(sid)
        for sid in row_spr_ids:
            if sid and sid not in seen_local:
                seen_local.add(sid)
                valid_ids.append(sid)
        new_spr_val = ", ".join(valid_ids)
        if new_spr_val != cur_raw:
            frappe.db.set_value("Planning Table", r["name"], "spr_name", new_spr_val, update_modified=False)
            updated_spr += 1

    return {
        "status": "ok",
        "updated_order_sheet": updated_order_sheet,
        "updated_spr": updated_spr,
        "message": f"Updated Order Sheet on {updated_order_sheet} row(s), SPR on {updated_spr} row(s).",
    }


def sync_spr_planning_table_links(spr_name: str) -> dict:
	"""Link SPR to Planning Table rows by production plan + item_code (enables transfer + board sync)."""
	sn = _cstr(spr_name).strip()
	if not sn or not frappe.db.exists("Shaft Production Run", sn):
		return {"status": "error", "message": _("SPR not found"), "linked_rows": 0}
	if not frappe.db.table_exists("Planning Table") or not frappe.db.has_column("Planning Table", "spr_name"):
		return {"status": "skipped", "linked_rows": 0}

	spr = frappe.get_doc("Shaft Production Run", sn)
	pp_id = _cstr(spr.get("production_plan")).strip()
	if not pp_id:
		return {"status": "skipped", "linked_rows": 0, "message": _("SPR has no production plan")}

	item_codes = {
		_cstr(getattr(it, "item_code", "")).strip()
		for it in (spr.items or [])
		if _cstr(getattr(it, "item_code", "")).strip()
	}
	if not item_codes:
		return {"status": "skipped", "linked_rows": 0}

	os_field = _psi_order_sheet_field()
	linked = 0
	planning_sheets = set()
	rows_by_name = {}

	if item_codes:
		pp_clauses = []
		pp_params = []
		if os_field:
			pp_clauses.append(f"IFNULL(pt.`{os_field}`, '') = %s")
			pp_params.append(pp_id)
		for col in ("order_sheet", "custom_order_sheet", "custom_order_plan"):
			if col != os_field and frappe.db.has_column("Planning Table", col):
				pp_clauses.append(f"IFNULL(pt.`{col}`, '') = %s")
				pp_params.append(pp_id)
		if pp_clauses:
			fmt_items = ", ".join(["%s"] * len(item_codes))
			rows = frappe.db.sql(
				f"""
				SELECT pt.name, pt.parent, pt.item_code, pt.spr_name
				FROM `tabPlanning Table` pt
				WHERE pt.item_code IN ({fmt_items})
				  AND ({' OR '.join(pp_clauses)})
				""",
				tuple(list(item_codes) + pp_params),
				as_dict=True,
			) or []
			for batch in rows:
				rows_by_name[batch["name"]] = batch

	for row in frappe.get_all(
		"Planning Table",
		filters={"spr_name": ["like", f"%{sn}%"]},
		fields=["name", "parent", "item_code", "spr_name"],
		limit_page_length=500,
	) or []:
		cur_ids = _expand_spr_name_tokens(row.get("spr_name"))
		if sn in cur_ids:
			rows_by_name[row["name"]] = row

	for row_name, row in rows_by_name.items():
		if os_field and pp_id and not _row_order_sheet_pp(row_name=row_name, row_dict=row):
			frappe.db.set_value("Planning Table", row_name, os_field, pp_id, update_modified=False)
		cur = str(row.get("spr_name") or "").strip()
		cur_ids = _expand_spr_name_tokens(cur)
		if sn in cur_ids:
			continue
		new_val = ", ".join([*cur_ids, sn]) if cur_ids else sn
		frappe.db.set_value("Planning Table", row_name, "spr_name", new_val, update_modified=False)
		linked += 1
		if row.get("parent"):
			planning_sheets.add(row["parent"])

	for sheet in planning_sheets:
		try:
			refresh_planning_sheet_spr_and_order_sheet(sheet)
		except Exception:
			frappe.log_error(frappe.get_traceback(), f"sync_spr_planning_table_links:{sn}:{sheet}")

	return {"status": "ok", "linked_rows": linked, "spr_name": sn, "planning_sheets": list(planning_sheets)}


@frappe.whitelist()
def repair_spr_planning_table_links(spr_name=None):
	"""Desk/GSM helper — backfill Planning Table spr_name + order_sheet for one SPR."""
	return sync_spr_planning_table_links(spr_name)


@frappe.whitelist()
def manual_update_planning_sheet_links(planning_sheet: str, mappings):
    """
    Manual safe updater for Planning Table links.
    mappings: JSON array of objects -> {row_name?, item_code?, order_sheet, spr_name}
    """
    if not planning_sheet or not frappe.db.exists("Planning sheet", planning_sheet):
        return {"status": "error", "message": "Planning sheet not found", "updated": 0, "errors": []}

    if isinstance(mappings, str):
        try:
            mappings = json.loads(mappings)
        except Exception:
            return {"status": "error", "message": "Invalid mappings JSON", "updated": 0, "errors": ["Invalid JSON"]}
    mappings = mappings or []
    if not isinstance(mappings, list):
        return {"status": "error", "message": "Mappings must be a list", "updated": 0, "errors": ["Mappings must be list"]}

    rows = frappe.get_all(
        "Planning Table",
        filters={"parent": planning_sheet, "parenttype": "Planning sheet"},
        fields=["name", "item_code"],
    ) or []
    valid_rows = {r.get("name") for r in rows}
    rows_by_item_code = {}
    for r in rows:
        ic = (r.get("item_code") or "").strip()
        if ic:
            rows_by_item_code.setdefault(ic, [])
            rows_by_item_code[ic].append(r.get("name"))
    updated = 0
    errors = []

    for i, m in enumerate(mappings, start=1):
        row_name = (m.get("row_name") or "").strip()
        item_code = (m.get("item_code") or "").strip()
        pp = (m.get("order_sheet") or "").strip()
        spr = (m.get("spr_name") or "").strip()
        if not row_name and item_code:
            candidates = rows_by_item_code.get(item_code) or []
            if len(candidates) == 1:
                row_name = candidates[0]
            elif len(candidates) > 1:
                errors.append(f"Line {i}: item_code {item_code} matches multiple rows; use row_name")
                continue
            else:
                errors.append(f"Line {i}: item_code {item_code} not found in this sheet")
                continue
        if not row_name:
            errors.append(f"Line {i}: row_name or item_code is required")
            continue
        if row_name not in valid_rows:
            errors.append(f"Line {i}: row {row_name} is not part of {planning_sheet}")
            continue
        if pp and not frappe.db.exists("Production Plan", pp):
            errors.append(f"Line {i}: Production Plan {pp} not found")
            continue
        if spr and not frappe.db.exists("Shaft Production Run", spr):
            errors.append(f"Line {i}: SPR {spr} not found")
            continue
        if pp and spr:
            spr_pp = (frappe.db.get_value("Shaft Production Run", spr, "production_plan") or "").strip()
            if spr_pp and spr_pp != pp:
                errors.append(f"Line {i}: SPR {spr} belongs to {spr_pp}, not {pp}")
                continue

        if pp:
            frappe.db.set_value("Planning Table", row_name, "order_sheet", pp, update_modified=False)
        if spr:
            frappe.db.set_value("Planning Table", row_name, "spr_name", spr, update_modified=False)
        updated += 1

    return {
        "status": "ok",
        "updated": updated,
        "errors": errors,
        "message": f"Updated {updated} row(s)." + (f" Errors: {len(errors)}" if errors else ""),
    }

