WHITE_COLORS = {
    "WHITE", "BRIGHT WHITE", "SUNSHINE WHITE", "MILKY WHITE", 
    "SUPER WHITE", "BLEACH WHITE", "BLEACH WHITE 1.0", "BLEACH WHITE 2.0"
}

def _normalize_unit(raw):
    """Normalize unit key for Color Sequence Approval.

    Must be stable across UI labels and stored Workstation names.
    """
    s = str(raw or "").strip()
    if not s:
        return "UNASSIGNED"
    # If already one of our workstation keys, keep it.
    if s in (
        "UNASSIGNED",
        "Unit 1",
        "Unit 2",
        "Unit 3",
        "Unit 4",
        LAMINATION_UNIT,
        SLITTING_UNIT,
        REWINDING_UNIT_L3,
        REWINDING_UNIT_L4,
        REWINDING_UNIT_L5,
        REWINDING_UNASSIGNED_UNIT,
        SHEET_CUTTING_UNIT,
        PRINTED_BOPP_FILM_UNIT,
    ):
        return s
    r = s.upper().replace(" ", "")
    if "UNIT1" in r:
        return "Unit 1"
    if "UNIT2" in r:
        return "Unit 2"
    if "UNIT3" in r:
        return "Unit 3"
    if "UNIT4" in r:
        return "Unit 4"
    if "LAMINATIONUNIT" in r or ("TNSPL" in r and "LAMINATION" in r):
        return LAMINATION_UNIT
    if "SLITTINGUNIT" in r or ("JVE" in r and "SLITTING" in r):
        return SLITTING_UNIT
    if "REWINDING" in r:
        if "L3" in r and "TSNPL" in r:
            return REWINDING_UNIT_L3
        if "L4" in r and "JSB" in r:
            return REWINDING_UNIT_L4
        if "L5" in r and "JSB" in r:
            return REWINDING_UNIT_L5
        if "UNASSIGNED" in r:
            return REWINDING_UNASSIGNED_UNIT
    if "SHEET" in r and "CUTTING" in r and "JVE" in r:
        return SHEET_CUTTING_UNIT
    if "BOPP" in r and "PRINTING" in r:
        return PRINTED_BOPP_FILM_UNIT
    return "UNASSIGNED"


def _csa_docname(plan_name: str, unit: str, date: str) -> str:
    """Build a safe, deterministic Color Sequence Approval name (<=140 chars)."""
    import hashlib

    pn = str(plan_name or "Default").strip() or "Default"
    un = _normalize_unit(unit)
    dt = str(date or "").strip()
    base = f"CSA-{pn}-{un}-{dt}"
    if len(base) <= 140:
        return base
    h = hashlib.md5(base.encode("utf-8")).hexdigest()[:8]
    pn_t = pn[:30].strip()
    un_t = un[:30].strip()
    dt_t = dt[:16].strip()
    out = f"CSA-{pn_t}-{un_t}-{dt_t}-{h}"
    return out[:140]

def _get_standard_month_name(month_index):
    # month_index 1-12
    month_names = ["JANUARY","FEBRUARY","MARCH","APRIL","MAY","JUNE","JULY","AUGUST","SEPTEMBER","OCTOBER","NOVEMBER","DECEMBER"]
    if 1 <= month_index <= 12:
        return month_names[month_index - 1]
    return "UNKNOWN"

def _get_contextual_plan_name(base_name, date_val):
    """
    Returns the full contextual plan name with month/week prefix, matching the
    frontend display logic in ColorChart.vue: currentMonthPrefix + ' ' + p.name
    e.g. base_name='PLAN 1', date_val='2026-03-19' -> 'MARCH W12 26 PLAN 1'

    If base_name already contains a month prefix (legacy), returns it as-is.
    If base_name is 'Default', returns 'Default'.
    """
    if not base_name or base_name == "Default":
        return base_name

    clean = base_name.strip()

    # If already prefixed (contains month name), return as-is
    month_names = ["JANUARY","FEBRUARY","MARCH","APRIL","MAY","JUNE",
                   "JULY","AUGUST","SEPTEMBER","OCTOBER","NOVEMBER","DECEMBER"]
    upper = clean.upper()
    if any(upper.startswith(m) for m in month_names):
        return clean

    # Build prefix from date_val (mirrors frontend currentMonthPrefix computed for weekly scope)
    try:
        import datetime as _dt
        if date_val:
            d = frappe.utils.getdate(date_val)
            # ISO week number
            iso = d.isocalendar()  # (year, week, weekday)
            week_num = iso[1]
            year_2 = str(d.year)[2:]
            month_prefix = month_names[d.month - 1]
            prefix = f"{month_prefix} W{week_num} {year_2}"
            return f"{prefix} {clean}"
    except Exception:
        pass

    return clean

def _find_best_unlocked_plan(parsed_plans, doc_date):
    """
    Returns the first unlocked plan name.
    Matches primarily by 'base name' to avoid prefix issues.
    """
    if not parsed_plans:
        return None
        
    first_unlocked = None
    default_plan = None
    
    for plan in parsed_plans:
        is_locked = str(plan.get("locked", "0")) in ["1", 1, "true", True]
        if is_locked:
            continue
            
        p_name = str(plan.get("name", "")).strip()
        # Get base name for matching (e.g. MARCH W10 26 PLAN 1 -> PLAN 1)
        base = _strip_legacy_prefixes(p_name)
        
        if base.upper() == "DEFAULT":
            default_plan = p_name
            continue
            
        if not first_unlocked:
            first_unlocked = p_name
                
    return first_unlocked or default_plan

def _strip_legacy_prefixes(name):
    """
    Strips various month/week prefixes to get the base plan name.
    Example: 'MAR-26 PLAN 1' -> 'PLAN 1'
             'MARCH W10 26 PLAN 1' -> 'PLAN 1'
    """
    if not name or name == "Default":
        return name
        
    # Pattern 1: [MONTH] W[XX] [YY] [NAME] -> (e.g. MARCH W10 26 PLAN 1)
    p1 = re.sub(r'^[A-Z]+\s+W\d+\s+\d{2}\s+', '', name, flags=re.IGNORECASE)
    if p1 != name:
        return p1.strip()
        
    # Pattern 2: [MON]-[YY] [NAME] -> (e.g. MAR-26 PLAN 1)
    p2 = re.sub(r'^[A-Z]{3}-\d{2}\s+', '', name, flags=re.IGNORECASE)
    if p2 != name:
        return p2.strip()
        
    # Pattern 3: [MONTH] [YY] [NAME] -> (e.g. MARCH 26 PLAN 1)
    p3 = re.sub(r'^[A-Z]+\s+\d{2}\s+', '', name, flags=re.IGNORECASE)
    if p3 != name:
        return p3.strip()
        
    return name.strip()

