def _effective_date_expr(alias="p"):
    """Returns SQL expression for effective date."""
    if _has_planned_date_column():
        return f"COALESCE({alias}.custom_planned_date, {alias}.ordered_date)"
    return f"{alias}.ordered_date"


def _pt_item_planned_date_column():
    """Return physical planned-date column on Planning Table (new or legacy), else None."""
    if frappe.db.has_column("Planning Table", "planned_date"):
        return "planned_date"
    if frappe.db.has_column("Planning Table", "custom_item_planned_date"):
        return "custom_item_planned_date"
    return None

def get_unit_load(date, unit, plan_name=None, pb_only=0):
    """Calculates current load (in Tons) for a unit on a given date.
    Filtered per-plan so each plan has its own independent capacity.
    Uses planned_date if set, otherwise falls back to parent.
    """
    # Priority: Item Date -> Sheet Date -> Sheet Ordered Date
    eff = "COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)"
    pb_only = cint(pb_only)
    # Build plan filter ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶ each plan is treated independently
    if plan_name and plan_name != "__all__":
        if plan_name == "Default":
            plan_cond = "AND (p.custom_plan_name IS NULL OR p.custom_plan_name = '' OR p.custom_plan_name = 'Default')"
            params = (date, unit)
        else:
            plan_cond = "AND p.custom_plan_name = %s"
            params = (date, unit, plan_name)
    else:
        # No plan filter ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶ sum all (used internally for global capacity checks)
        plan_cond = ""
        params = (date, unit)

    # Optional Production Board-only mode:
    # Only count items/sheets explicitly pushed/planned to PB.
    pb_cond = ""
    if pb_only and _has_planned_date_column():
        pb_cond = "AND p.custom_planned_date IS NOT NULL AND p.custom_planned_date != ''"
    
    # MIX WASTE EXCLUSION:
    # Matches frontend logic (is_mix_roll || itemName.startsWith('MIX'))
    mix_cond = "AND i.item_name NOT LIKE 'MIX%%'"
    
    sql = f"""
        SELECT SUM(i.qty) as total_qty
        FROM `tabPlanning Table` i
        JOIN `tabPlanning sheet` p ON i.parent = p.name
        WHERE {eff} = %s
          AND i.unit = %s
          AND p.docstatus < 2
          AND i.docstatus < 2
          {plan_cond}
          {pb_cond}
          {mix_cond}
    """
    result = frappe.db.sql(sql, params)
    return flt(result[0][0]) / 1000.0 if result and result[0][0] else 0.0

# ===========================
# EQUIPMENT MAINTENANCE HELPERS
# ===========================

# Mesh/Die Change: banner + times only (approx). Do not cascade or cut daily kg.
NON_BLOCKING_MAINTENANCE_TYPES = {"MESH CHANGE", "DIE CHANGE"}
MAINTENANCE_UNIT_OPTIONS = (
    "Unit 1",
    "Unit 2",
    "Unit 3",
    "Unit 4",
    LAMINATION_UNIT,
    SLITTING_UNIT,
    SLITTING_UNIT_VTP,
    SLITTING_UNASSIGNED_UNIT,
    REWINDING_UNIT_L3,
    REWINDING_UNIT_L4,
    REWINDING_UNIT_L5,
    REWINDING_UNASSIGNED_UNIT,
    SHEET_CUTTING_UNIT,
    PRINTED_BOPP_FILM_UNIT,
)


def _is_non_blocking_maintenance_type(maintenance_type):
    return str(maintenance_type or "").strip().upper() in NON_BLOCKING_MAINTENANCE_TYPES


def _normalize_maintenance_unit(unit):
    u = _cstr(unit)
    if not u:
        return u
    canon = normalize_planning_unit_for_select(u)
    resolved = resolve_planning_workstation_name(canon or u)
    return resolved or canon or u


def _maintenance_unit_sql_in(unit):
    """Return (sql_fragment, params) for matching equivalent workstation names."""
    values = maintenance_unit_match_values(unit)
    if not values:
        return "1=0", ()
    placeholders = ", ".join(["%s"] * len(values))
    return f"unit IN ({placeholders})", tuple(values)


def _ensure_equipment_maintenance_unit_options():
    """Ensure maintenance ``unit`` field supports boards (Link → Workstation) or legacy Select."""
    if not frappe.db.exists("DocType", "Equipment Maintenance"):
        return
    ftype = frappe.db.get_value(
        "DocField",
        {"parent": "Equipment Maintenance", "fieldname": "unit"},
        "fieldtype",
    )
    if (ftype or "").strip() == "Link":
        for ps in frappe.get_all(
            "Property Setter",
            filters={
                "doc_type": "Equipment Maintenance",
                "field_name": "unit",
                "property": "options",
            },
            pluck="name",
        ) or []:
            try:
                frappe.delete_doc("Property Setter", ps, force=True, ignore_missing=True)
            except Exception:
                pass
        frappe.db.sql(
            """
            UPDATE `tabDocField`
            SET `options`='Workstation'
            WHERE `parent`='Equipment Maintenance' AND `fieldname`='unit' AND `fieldtype`='Link'
            """
        )
        frappe.clear_cache(doctype="Equipment Maintenance")
        return
    desired = "\n".join(MAINTENANCE_UNIT_OPTIONS)
    # Update Property Setter overrides first (highest precedence in meta).
    ps_rows = frappe.get_all(
        "Property Setter",
        filters={
            "doc_type": "Equipment Maintenance",
            "field_name": "unit",
            "property": "options",
        },
        fields=["name"],
        limit_page_length=50,
    ) or []
    for ps in ps_rows:
        frappe.db.set_value("Property Setter", ps.get("name"), "value", desired, update_modified=False)
    # Keep DocField options updated as fallback/default source.
    df_name = frappe.db.get_value(
        "DocField",
        {"parent": "Equipment Maintenance", "fieldname": "unit"},
        "name",
    )
    if df_name:
        frappe.db.set_value("DocField", df_name, "options", desired, update_modified=False)
    frappe.clear_cache(doctype="Equipment Maintenance")

@frappe.whitelist()
def get_maintenance_windows(unit, start_date, end_date):
    """
    Query all maintenance periods for a unit within a date range.
    Returns: dict {date: [list of maintenance records]}
    """
    from frappe.utils import getdate, add_days
    
    start_dt = getdate(start_date)
    end_dt = getdate(end_date)
    
    if not frappe.db.exists("DocType", "Equipment Maintenance"):
        return {}
    
    unit_sql, unit_params = _maintenance_unit_sql_in(unit)
    if not unit_params:
        return {}

    has_st, has_et = _maintenance_has_time_columns()
    time_cols = ""
    if has_st:
        time_cols += ", start_time"
    if has_et:
        time_cols += ", end_time"

    records = frappe.db.sql(f"""
        SELECT name, unit, maintenance_type, start_date, end_date, status{time_cols}
        FROM `tabEquipment Maintenance`
        WHERE {unit_sql}
          AND start_date <= %s
          AND end_date >= %s
          AND docstatus < 2
    """, unit_params + (end_dt, start_dt), as_dict=True)
    
    # Build date map
    result = {}
    for rec in records:
        current = getdate(rec.start_date)
        end = getdate(rec.end_date)
        while current <= end:
            date_str = str(current)
            if date_str not in result:
                result[date_str] = []
            entry = {
                "type": rec.maintenance_type,
                "start_date": str(rec.start_date),
                "end_date": str(rec.end_date),
                "status": rec.status,
                "blocked_hours": round(get_maintenance_blocked_hours(unit, date_str), 2),
                "available_hours": round(get_unit_available_hours(unit, date_str), 2),
                "effective_limit_tons": round(get_unit_effective_limit_tons(unit, date_str), 4),
            }
            if has_st:
                entry["start_time"] = str(rec.get("start_time") or "")
            if has_et:
                entry["end_time"] = str(rec.get("end_time") or "")
            result[date_str].append(entry)
            current = add_days(current, 1)
    
    return result


def _parse_maintenance_time(value, *, end_of_day=False):
	"""Return (h, m, s). Missing/blank → start-of-day or end-of-day."""
	from datetime import time as dtime

	if value in (None, "", "None"):
		return (23, 59, 59) if end_of_day else (0, 0, 0)
	try:
		from frappe.utils import get_time

		t = get_time(value)
		if isinstance(t, dtime):
			return (t.hour, t.minute, t.second or 0)
		parts = str(t).split(":")
		h = int(parts[0]) if parts else 0
		m = int(parts[1]) if len(parts) > 1 else 0
		s = int(float(parts[2])) if len(parts) > 2 else 0
		return (h, m, s)
	except Exception:
		return (23, 59, 59) if end_of_day else (0, 0, 0)


def _maintenance_has_time_columns():
	cols = set(frappe.db.get_table_columns("Equipment Maintenance") or [])
	return "start_time" in cols, "end_time" in cols


def _ensure_equipment_maintenance_time_fields():
	"""Ensure start/end time + after-order anchor fields exist on Equipment Maintenance."""
	if not frappe.db.exists("DocType", "Equipment Maintenance"):
		return
	meta = frappe.get_meta("Equipment Maintenance")
	for fieldname, label, fieldtype, insert_after in (
		("start_time", "Start Time", "Time", "start_date"),
		("end_time", "End Time", "Time", "end_date"),
		("after_order_code", "After Order Code", "Data", "end_time"),
		("after_quality", "After Quality", "Data", "after_order_code"),
		("after_color", "After Colour", "Data", "after_quality"),
	):
		if meta.has_field(fieldname):
			continue
		if frappe.db.exists("Custom Field", {"dt": "Equipment Maintenance", "fieldname": fieldname}):
			continue
		cf = frappe.get_doc(
			{
				"doctype": "Custom Field",
				"dt": "Equipment Maintenance",
				"fieldname": fieldname,
				"label": label,
				"fieldtype": fieldtype,
				"insert_after": insert_after,
			}
		)
		cf.insert(ignore_permissions=True)
	frappe.clear_cache(doctype="Equipment Maintenance")


def _maintenance_window_bounds(rec):
	"""Inclusive maintenance window as datetimes. Blank times = full calendar days."""
	from datetime import datetime, timedelta

	from frappe.utils import getdate

	sd = getdate(rec.get("start_date"))
	ed = getdate(rec.get("end_date") or rec.get("start_date"))
	has_start_t = bool(str(rec.get("start_time") or "").strip())
	has_end_t = bool(str(rec.get("end_time") or "").strip())
	sh, sm, ss = _parse_maintenance_time(rec.get("start_time"), end_of_day=False)
	eh, em, es = _parse_maintenance_time(rec.get("end_time"), end_of_day=True)
	# Legacy date-only rows: block entire days.
	if not has_start_t and not has_end_t:
		start_dt = datetime(sd.year, sd.month, sd.day, 0, 0, 0)
		end_dt = datetime(ed.year, ed.month, ed.day, 23, 59, 59)
		return start_dt, end_dt
	start_dt = datetime(sd.year, sd.month, sd.day, sh, sm, ss)
	end_dt = datetime(ed.year, ed.month, ed.day, eh, em, es)
	if end_dt < start_dt:
		end_dt = start_dt + timedelta(seconds=1)
	return start_dt, end_dt


def _merge_hour_intervals(intervals):
	"""Merge overlapping (start_hour, end_hour) floats on a 0–24 day."""
	if not intervals:
		return []
	sorted_iv = sorted((max(0.0, float(a)), min(24.0, float(b))) for a, b in intervals if b > a)
	if not sorted_iv:
		return []
	merged = [list(sorted_iv[0])]
	for a, b in sorted_iv[1:]:
		if a <= merged[-1][1]:
			merged[-1][1] = max(merged[-1][1], b)
		else:
			merged.append([a, b])
	return merged


def get_maintenance_blocked_hours(unit, date_string):
	"""Blocking maintenance hours overlapping the calendar day (0–24)."""
	from datetime import datetime

	from frappe.utils import getdate

	if not frappe.db.exists("DocType", "Equipment Maintenance"):
		return 0.0
	check_date = getdate(date_string)
	unit_sql, unit_params = _maintenance_unit_sql_in(unit)
	if not unit_params:
		return 0.0

	has_st, has_et = _maintenance_has_time_columns()
	time_cols = ""
	if has_st:
		time_cols += ", start_time"
	if has_et:
		time_cols += ", end_time"

	rows = frappe.db.sql(
		f"""
		SELECT name, maintenance_type, start_date, end_date{time_cols}
		FROM `tabEquipment Maintenance`
		WHERE {unit_sql}
		  AND start_date <= %s
		  AND end_date >= %s
		  AND docstatus < 2
		  AND UPPER(TRIM(COALESCE(maintenance_type, ''))) NOT IN ('MESH CHANGE', 'DIE CHANGE')
		""",
		unit_params + (check_date, check_date),
		as_dict=True,
	)
	day_start = datetime(check_date.year, check_date.month, check_date.day, 0, 0, 0)
	day_end = datetime(check_date.year, check_date.month, check_date.day, 23, 59, 59)
	intervals = []
	for rec in rows or []:
		w_start, w_end = _maintenance_window_bounds(rec)
		ov_start = max(w_start, day_start)
		ov_end = min(w_end, day_end)
		if ov_end <= ov_start:
			continue
		start_h = (ov_start - day_start).total_seconds() / 3600.0
		end_h = (ov_end - day_start).total_seconds() / 3600.0
		# Treat end-of-day 23:59:59 as 24.0 for capacity math.
		if ov_end.hour == 23 and ov_end.minute >= 59:
			end_h = 24.0
		intervals.append((start_h, end_h))
	merged = _merge_hour_intervals(intervals)
	return flt(sum(b - a for a, b in merged))


def get_unit_available_hours(unit, date_string):
	return max(0.0, 24.0 - flt(get_maintenance_blocked_hours(unit, date_string)))


def get_unit_effective_limit_tons(unit, date_string):
	"""Daily hard limit for queuing.

	Maintenance start/end times are informational only (approximate). Do not
	scale/lock kg by available hours — queue uses the full unit day limit.
	"""
	unit_key = normalize_planning_unit_for_select(unit) or unit
	return flt(HARD_LIMITS.get(unit_key, HARD_LIMITS.get(unit, 999.0)))


def is_date_under_maintenance(unit, date_string):
	"""True when the calendar day has essentially no production capacity left."""
	return get_unit_available_hours(unit, date_string) < 0.01


def get_maintenance_info_on_date(unit, date_string):
	"""Get BLOCKING maintenance details if date is under maintenance (full or partial)."""
	from frappe.utils import getdate

	if not frappe.db.exists("DocType", "Equipment Maintenance"):
		return None

	check_date = getdate(date_string)
	unit_sql, unit_params = _maintenance_unit_sql_in(unit)
	if not unit_params:
		return None

	has_st, has_et = _maintenance_has_time_columns()
	time_cols = ""
	if has_st:
		time_cols += ", start_time"
	if has_et:
		time_cols += ", end_time"

	rec = frappe.db.sql(
		f"""
		SELECT name, maintenance_type, start_date, end_date, status{time_cols}
		FROM `tabEquipment Maintenance`
		WHERE {unit_sql}
		  AND start_date <= %s
		  AND end_date >= %s
		  AND docstatus < 2
		  AND UPPER(TRIM(COALESCE(maintenance_type, ''))) NOT IN ('MESH CHANGE', 'DIE CHANGE')
		LIMIT 1
		""",
		unit_params + (check_date, check_date),
		as_dict=True,
	)

	if not rec:
		return None
	r0 = rec[0]
	blocked = get_maintenance_blocked_hours(unit, date_string)
	available = max(0.0, 24.0 - blocked)
	out = {
		"type": r0.maintenance_type,
		"start_date": str(r0.start_date),
		"end_date": str(r0.end_date),
		"status": r0.status,
		"blocked_hours": round(blocked, 2),
		"available_hours": round(available, 2),
		"effective_limit_tons": round(get_unit_effective_limit_tons(unit, date_string), 4),
	}
	if has_st:
		out["start_time"] = str(r0.get("start_time") or "")
	if has_et:
		out["end_time"] = str(r0.get("end_time") or "")
	return out


def get_next_available_date_skipping_maintenance(unit, start_date, required_tons=0, days_ahead=30):
	"""Find next date where unit has capacity and is NOT fully under maintenance."""
	from frappe.utils import add_days, getdate

	if not unit or not start_date:
		return {"date": None}

	start_dt = getdate(start_date)
	required = flt(required_tons)
	days_ahead = cint(days_ahead) or 30

	for i in range(days_ahead + 1):
		candidate = add_days(start_dt, i)
		candidate_str = str(candidate)

		if is_date_under_maintenance(unit, candidate_str):
			continue

		limit = get_unit_effective_limit_tons(unit, candidate_str)
		load = get_unit_load(candidate_str, unit, "__all__", pb_only=0)
		if load + required <= (limit * 1.05):
			return {
				"date": candidate_str,
				"current_load": load,
				"limit": limit,
				"reason": "available",
			}

	fallback = add_days(start_dt, 1)
	return {
		"date": str(fallback),
		"current_load": get_unit_load(str(fallback), unit, "__all__", pb_only=0),
		"limit": get_unit_effective_limit_tons(unit, str(fallback)),
		"reason": "no_clean_slot_found",
	}


@frappe.whitelist()
def add_equipment_maintenance(
	unit,
	maintenance_type,
	start_date,
	end_date,
	notes=None,
	start_time=None,
	end_time=None,
	after_order_code=None,
	after_quality=None,
	after_color=None,
):
	"""Create new Equipment Maintenance record (optional times + after-order banner anchor)."""
	import json

	if not frappe.db.exists("DocType", "Equipment Maintenance"):
		return {"status": "error", "message": "Equipment Maintenance module not found"}
	_ensure_equipment_maintenance_unit_options()
	_ensure_equipment_maintenance_time_fields()
	unit = _normalize_maintenance_unit(unit)

	payload = {
		"doctype": "Equipment Maintenance",
		"unit": unit,
		"maintenance_type": maintenance_type,
		"start_date": start_date,
		"end_date": end_date,
		"notes": notes or "",
		"status": "Planned",
	}
	has_st, has_et = _maintenance_has_time_columns()
	if has_st and start_time not in (None, ""):
		payload["start_time"] = start_time
	if has_et and end_time not in (None, ""):
		payload["end_time"] = end_time

	cols = set(frappe.db.get_table_columns("Equipment Maintenance") or [])
	if "after_order_code" in cols and after_order_code not in (None, ""):
		payload["after_order_code"] = _cstr(after_order_code).strip()
	if "after_quality" in cols and after_quality not in (None, ""):
		payload["after_quality"] = _cstr(after_quality).strip()
	if "after_color" in cols and after_color not in (None, ""):
		payload["after_color"] = _cstr(after_color).strip()

	doc = frappe.get_doc(payload)
	doc.insert(ignore_permissions=False)

	cascade_result = {"cascaded_count": 0}
	if not _is_non_blocking_maintenance_type(maintenance_type):
		cascade_result = cascade_orders_after_maintenance_removal(unit, start_date, end_date)
		movement_log = cascade_result.get("movement_log") or []

		if movement_log:
			marker = "MAINTENANCE_CASCADE_LOG::"
			user_notes = (notes or "").strip()
			log_line = marker + json.dumps(movement_log, separators=(",", ":"))
			stored_notes = f"{user_notes}\n\n{log_line}" if user_notes else log_line
			frappe.db.set_value("Equipment Maintenance", doc.name, "notes", stored_notes, update_modified=False)
			frappe.cache().set_value(f"maintenance_cascade_log::{doc.name}", movement_log)

	frappe.db.commit()

	time_msg = ""
	if start_time or end_time:
		time_msg = f" ({start_time or '00:00'} – {end_time or '23:59'})"

	after_msg = ""
	if after_order_code:
		parts = [after_order_code]
		if after_quality:
			parts.append(after_quality)
		if after_color:
			parts.append(after_color)
		after_msg = f" After order: {' · '.join(parts)}."

	if _is_non_blocking_maintenance_type(maintenance_type):
		return {
			"status": "success",
			"message": f"{maintenance_type} noted for {unit} from {start_date} to {end_date}{time_msg}.{after_msg} Times are approximate — daily kg capacity is not locked. Queue orders as usual.",
			"cascaded_count": 0,
			"name": doc.name,
		}

	return {
		"status": "success",
		"message": f"Maintenance scheduled for {unit} from {start_date} to {end_date}{time_msg}.{after_msg} Moved {cascade_result.get('cascaded_count', 0)} items forward.",
		"cascaded_count": cascade_result.get("cascaded_count", 0),
		"name": doc.name,
	}

@frappe.whitelist()
def cascade_orders_after_maintenance_removal(unit, maint_start_date, maint_end_date):
	"""
	Re-pack items planned inside a maintenance window against partial-day capacity.
	Orders that no longer fit move forward to the next date with remaining capacity.
	"""
	from frappe.utils import add_days, getdate

	if not unit or not maint_start_date or not maint_end_date:
		return {"status": "error", "message": "Missing parameters"}

	start_dt = getdate(maint_start_date)
	end_dt = getdate(maint_end_date)
	unit_sql, unit_params = _maintenance_unit_sql_in(unit)
	if not unit_params:
		return {"status": "success", "message": "No items to cascade", "cascaded_count": 0}

	items = frappe.db.sql(
		f"""
		SELECT i.name, i.qty, i.unit, COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date) as effective_planned_date
		FROM `tabPlanning Table` i
		JOIN `tabPlanning sheet` p ON i.parent = p.name
		WHERE i.unit IN ({", ".join(["%s"] * len(unit_params))})
		  AND DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) >= %s
		  AND DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) <= %s
		  AND p.docstatus < 2
		  AND i.docstatus < 2
		ORDER BY DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) ASC, i.idx ASC
		""",
		unit_params + (start_dt, end_dt),
		as_dict=True,
	)

	if not items:
		return {"status": "success", "message": "No items to cascade", "cascaded_count": 0}

	has_item_planned_col = frappe.db.has_column("Planning Table", "planned_date")
	cascaded_count = 0
	local_loads = {}
	movement_log = []

	# Group by planned date, then keep what fits under effective limit; cascade overflow.
	by_date = {}
	for item in items:
		d = str(getdate(item.get("effective_planned_date")))
		by_date.setdefault(d, []).append(item)

	overflow = []
	for date_str, day_items in sorted(by_date.items()):
		item_unit = normalize_planning_unit_for_select((day_items[0].get("unit") or unit)) or unit
		limit = get_unit_effective_limit_tons(item_unit, date_str)
		load_key = (date_str, item_unit)
		# Rebuild day from empty for packing against new maintenance capacity.
		running = 0.0
		for item in day_items:
			qty_tons = flt(item.get("qty")) / 1000.0
			if limit < 0.01:
				overflow.append(item)
				continue
			if (running + qty_tons <= limit * 1.05) or (running == 0 and qty_tons >= limit):
				running += qty_tons
			else:
				overflow.append(item)
		local_loads[load_key] = running

	for item in overflow:
		item_name = item.get("name")
		item_unit = normalize_planning_unit_for_select(item.get("unit") or unit) or unit
		qty_tons = flt(item.get("qty")) / 1000.0
		current_date = getdate(item.get("effective_planned_date"))
		original_date_str = current_date.strftime("%Y-%m-%d")

		candidate = add_days(current_date, 1)
		found_slot = False

		for _i in range(60):
			candidate_str = candidate if isinstance(candidate, str) else candidate.strftime("%Y-%m-%d")

			if is_date_under_maintenance(item_unit, candidate_str):
				candidate = add_days(candidate, 1)
				continue

			unit_limit = get_unit_effective_limit_tons(item_unit, candidate_str)
			load_key = (candidate_str, item_unit)
			if load_key not in local_loads:
				local_loads[load_key] = get_unit_load(candidate_str, item_unit, "__all__", pb_only=1)

			current_load = local_loads[load_key]

			if (current_load + qty_tons <= unit_limit * 1.05) or (current_load == 0 and qty_tons >= unit_limit):
				local_loads[load_key] = current_load + qty_tons
				if has_item_planned_col:
					frappe.db.sql(
						"""
						UPDATE `tabPlanning Table`
						SET planned_date = %s
						WHERE name = %s
						""",
						(candidate_str, item_name),
					)
				elif frappe.db.has_column("Planning sheet", "custom_planned_date"):
					frappe.db.sql(
						"""
						UPDATE `tabPlanning sheet` p
						INNER JOIN `tabPlanning Table` i ON i.parent = p.name
						SET p.custom_planned_date = %s
						WHERE i.name = %s
						""",
						(candidate_str, item_name),
					)
				movement_log.append(
					{
						"item_name": item_name,
						"from_date": original_date_str,
						"to_date": candidate_str,
					}
				)
				cascaded_count += 1
				found_slot = True
				break

			candidate = add_days(candidate, 1)

		if not found_slot:
			frappe.log_error(
				f"Could not cascade item {item_name} from {original_date_str}",
				"Maintenance Cascade",
			)

	frappe.db.commit()

	return {
		"status": "success",
		"message": f"Cascaded {cascaded_count} items to next available dates",
		"cascaded_count": cascaded_count,
		"movement_log": movement_log,
	}

@frappe.whitelist()
def forward_orders_from_date_range(cascade_start_date, cascade_end_date, plan_name=None):
    """
    Forward ALL orders queued on cascade_start_date to cascade_end_date
    to next available dates (after the cascade ends).
    
    Used when pushing colors - automatically clears the cascade range.
    
    Args:
        cascade_start_date: Start of cascade range (e.g. '2026-03-08')
        cascade_end_date: End of cascade range (e.g. '2026-03-16')
        plan_name: Plan name to filter by (optional)
    
    Returns:
        {
            "status": "success|error",
            "forwarded_count": number of items moved,
            "dates_cleared": list of dates that were cleared,
            "movement_log": [{"item_name": "...", "from_date": "...", "to_date": "...", "unit": "..."}, ...]
        }
    """
    from frappe.utils import getdate, add_days
    import datetime
    
    if not cascade_start_date or not cascade_end_date:
        return {"status": "error", "message": "Missing cascade date range"}
    
    start_dt = getdate(cascade_start_date)
    end_dt = getdate(cascade_end_date)
    
    if not frappe.db.has_column("Planning Table", "planned_date"):
        return {"status": "error", "message": "Required column planned_date not found"}
    
    # Find ALL items (any type) queued on dates in the cascade range
    items = frappe.db.sql("""
        SELECT 
            i.name, 
            i.qty, 
            i.unit, 
            i.color,
            COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date) as effective_planned_date
        FROM `tabPlanning Table` i
        JOIN `tabPlanning sheet` p ON i.parent = p.name
        WHERE p.docstatus < 2
          AND i.docstatus < 2
          AND DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) >= %s
          AND DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) <= %s
    """, (start_dt, end_dt), as_dict=True)
    
    if not items:
        # Generate date list for cleared dates
        dates_cleared = []
        current = start_dt
        while current <= end_dt:
            dates_cleared.append(str(current))
            current = add_days(current, 1)
        
        return {
            "status": "success",
            "message": "No items to forward",
            "forwarded_count": 0,
            "dates_cleared": dates_cleared,
            "movement_log": []
        }
    
    # Group items by unit for independent cascading
    items_by_unit = {}
    for item in items:
        unit = item.get("unit") or "Unit 1"
        if unit not in items_by_unit:
            items_by_unit[unit] = []
        items_by_unit[unit].append(item)
    
    forwarded_count = 0
    movement_log = []
    local_loads = {}  # (date, unit) -> current load in tons
    
    # Generate date list for cleared dates
    dates_cleared = []
    current = start_dt
    while current <= end_dt:
        dates_cleared.append(str(current))
        current = add_days(current, 1)
    
    for unit, unit_items in items_by_unit.items():
        for item in unit_items:
            item_name = item.get("name")
            qty_tons = flt(item.get("qty")) / 1000.0
            original_date = getdate(item.get("effective_planned_date"))
            original_date_str = str(original_date)
            color = item.get("color") or ""
            
            # Start looking from the day AFTER cascade_end_date
            candidate = add_days(end_dt, 1)
            forward_found = False
            
            # Search up to 60 days ahead for available slot
            for search_days in range(60):
                candidate_str = str(candidate) if isinstance(candidate, str) else candidate.strftime("%Y-%m-%d")
                
                # Skip if fully under maintenance
                if is_date_under_maintenance(unit, candidate_str):
                    candidate = add_days(candidate, 1)
                    continue
                
                unit_limit = get_unit_effective_limit_tons(unit, candidate_str)

                # Check current load for this date/unit
                load_key = (candidate_str, unit)
                if load_key not in local_loads:
                    local_loads[load_key] = get_unit_load(candidate_str, unit, "__all__", pb_only=1)
                
                current_load = local_loads[load_key]
                
                # Check if item fits (with 5% buffer) or if day is empty but item is oversized
                if (current_load + qty_tons <= unit_limit * 1.05) or (current_load == 0 and qty_tons >= unit_limit):
                    local_loads[load_key] = current_load + qty_tons
                    
                    # Update the item's planned date
                    frappe.db.sql("""
                        UPDATE `tabPlanning Table`
                        SET planned_date = %s
                        WHERE name = %s
                    """, (candidate_str, item_name))
                    
                    movement_log.append({
                        "item_name": item_name,
                        "color": color,
                        "from_date": original_date_str,
                        "to_date": candidate_str,
                        "unit": unit,
                        "qty_tons": round(qty_tons, 2)
                    })
                    
                    forwarded_count += 1
                    forward_found = True
                    break
                
                candidate = add_days(candidate, 1)
            
            if not forward_found:
                frappe.log_error(f"Could not forward item {item_name} from {original_date_str} - no available slot found in 60 days", "Forward Orders Error")
    
    frappe.db.commit()
    
    return {
        "status": "success",
        "message": f"Forwarded {forwarded_count} items from cascade range {cascade_start_date} to {cascade_end_date}",
        "forwarded_count": forwarded_count,
        "dates_cleared": dates_cleared,
        "movement_log": movement_log
    }

def _extract_maintenance_cascade_log(notes_text):
    """Read embedded movement log from maintenance notes."""
    import json

    marker = "MAINTENANCE_CASCADE_LOG::"
    if not notes_text or marker not in notes_text:
        return []

    raw = notes_text.split(marker, 1)[1].strip()
    if "\n" in raw:
        raw = raw.split("\n", 1)[0].strip()

    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, list) else []
    except Exception:
        return []

def _restore_orders_to_original_dates(unit, movement_log):
    """Restore moved items back to their original dates after maintenance is deleted."""
    from frappe.utils import getdate

    if not movement_log:
        return {"restored_count": 0, "skipped_count": 0}

    if not frappe.db.has_column("Planning Table", "planned_date"):
        return {"restored_count": 0, "skipped_count": len(movement_log)}

    restored_count = 0
    skipped_count = 0

    for move in movement_log:
        item_name = move.get("item_name")
        from_date = move.get("from_date")
        to_date = move.get("to_date")

        if not item_name or not from_date or not to_date:
            skipped_count += 1
            continue

        row = frappe.db.sql("""
            SELECT i.unit, COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date) AS effective_planned_date
            FROM `tabPlanning Table` i
            JOIN `tabPlanning sheet` p ON p.name = i.parent
            WHERE i.name = %s
              AND p.docstatus < 2
              AND i.docstatus < 2
            LIMIT 1
        """, (item_name,), as_dict=True)

        if not row:
            skipped_count += 1
            continue

        current_unit = row[0].get("unit")
        current_effective = str(getdate(row[0].get("effective_planned_date")))

        # Restore if item is still on or after the maintenance-shifted date.
        # This allows rollback even when later logic pushed it further forward.
        if not maintenance_units_equal(current_unit, unit) or current_effective < str(getdate(to_date)):
            skipped_count += 1
            continue

        # Avoid restoring into another active maintenance window.
        if is_date_under_maintenance(unit, from_date):
            skipped_count += 1
            continue

        frappe.db.sql("""
            UPDATE `tabPlanning Table`
            SET planned_date = %s
            WHERE name = %s
        """, (from_date, item_name))
        restored_count += 1

    frappe.db.commit()
    return {"restored_count": restored_count, "skipped_count": skipped_count}

def _fallback_restore_by_range(unit, maint_start_date, maint_end_date):
    """Fallback restore when movement log is missing/corrupted: pull next-day shifted items back into the maintenance window dates."""
    from frappe.utils import getdate, add_days

    if not frappe.db.has_column("Planning Table", "planned_date"):
        return {"restored_count": 0, "skipped_count": 0}

    start_dt = getdate(maint_start_date)
    end_dt = getdate(maint_end_date)
    window_days = (end_dt - start_dt).days + 1
    search_end = add_days(end_dt, max(3, window_days + 2))

    unit_sql, unit_params = _maintenance_unit_sql_in(unit)
    if not unit_params:
        return {"restored_count": 0, "skipped_count": 0}

    rows = frappe.db.sql(f"""
        SELECT i.name, i.unit, i.qty,
               DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) AS effective_planned_date
        FROM `tabPlanning Table` i
        JOIN `tabPlanning sheet` p ON p.name = i.parent
        WHERE i.unit IN ({", ".join(["%s"] * len(unit_params))})
          AND DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) > %s
          AND DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) <= %s
          AND p.docstatus < 2
          AND i.docstatus < 2
        ORDER BY DATE(COALESCE(i.planned_date, p.custom_planned_date, p.ordered_date)) ASC, i.idx ASC
    """, unit_params + (end_dt, search_end), as_dict=True)

    if not rows:
        return {"restored_count": 0, "skipped_count": 0}

    local_loads = {}
    restored = 0
    skipped = 0

    for r in rows:
        item_name = r.get("name")
        qty_tons = flt(r.get("qty")) / 1000.0

        placed = False
        for day_offset in range(window_days):
            candidate = add_days(start_dt, day_offset)
            candidate_str = candidate if isinstance(candidate, str) else candidate.strftime("%Y-%m-%d")

            if is_date_under_maintenance(unit, candidate_str):
                continue

            unit_limit = get_unit_effective_limit_tons(unit, candidate_str)
            load_key = (candidate_str, unit)
            if load_key not in local_loads:
                local_loads[load_key] = get_unit_load(candidate_str, unit, "__all__", pb_only=1)

            current_load = local_loads[load_key]
            if (current_load + qty_tons <= unit_limit * 1.05) or (current_load == 0 and qty_tons >= unit_limit):
                frappe.db.sql("""
                    UPDATE `tabPlanning Table`
                    SET planned_date = %s
                    WHERE name = %s
                """, (candidate_str, item_name))
                local_loads[load_key] = current_load + qty_tons
                restored += 1
                placed = True
                break

        if not placed:
            skipped += 1

    frappe.db.commit()
    return {"restored_count": restored, "skipped_count": skipped}

@frappe.whitelist()
def delete_maintenance_and_cascade(maintenance_record_name):
    """
    Delete a maintenance record and restore previously moved orders backward.
    This is called from the frontend when user clicks "Remove" on maintenance.
    """
    if not maintenance_record_name:
        return {"status": "error", "message": "No maintenance record specified"}
    
    # Fetch maintenance record details before deletion
    maint_doc = frappe.db.get_value(
        "Equipment Maintenance",
        maintenance_record_name,
        ["unit", "start_date", "end_date", "notes", "maintenance_type"],
        as_dict=True
    )
    
    if not maint_doc:
        return {"status": "error", "message": "Maintenance record not found"}
    
    unit = maint_doc.get("unit")
    start_date = maint_doc.get("start_date")
    end_date = maint_doc.get("end_date")
    notes = maint_doc.get("notes")
    maintenance_type = maint_doc.get("maintenance_type")
    movement_log = frappe.cache().get_value(f"maintenance_cascade_log::{maintenance_record_name}") or _extract_maintenance_cascade_log(notes)
    
    # Delete the maintenance record
    frappe.delete_doc("Equipment Maintenance", maintenance_record_name)

    if _is_non_blocking_maintenance_type(maintenance_type):
        try:
            frappe.cache().delete_value(f"maintenance_cascade_log::{maintenance_record_name}")
        except Exception:
            pass
        return {
            "status": "success",
            "message": "Maintenance removed.",
            "restored_count": 0,
            "skipped_count": 0
        }

    restore_result = _restore_orders_to_original_dates(unit, movement_log)
    if restore_result.get("restored_count", 0) == 0:
        fallback = _fallback_restore_by_range(unit, start_date, end_date)
        restore_result["restored_count"] = restore_result.get("restored_count", 0) + fallback.get("restored_count", 0)
        restore_result["skipped_count"] = restore_result.get("skipped_count", 0) + fallback.get("skipped_count", 0)

    try:
        frappe.cache().delete_value(f"maintenance_cascade_log::{maintenance_record_name}")
    except Exception:
        pass

    return {
        "status": "success",
        "message": f"Maintenance removed. Restored {restore_result.get('restored_count', 0)} items to original dates.",
        "restored_count": restore_result.get("restored_count", 0),
        "skipped_count": restore_result.get("skipped_count", 0)
    }

@frappe.whitelist()
def get_all_equipment_maintenance(start_date=None, end_date=None):
    """Get all maintenance records, optionally filtered by date range.

    Hardening note:
    Some sites miss optional columns (for example ``status`` / ``notes``) during partial migrations.
    Avoid 5xx by selecting only existing columns and returning an empty list on unexpected failures.
    """
    try:
        if not frappe.db.exists("DocType", "Equipment Maintenance"):
            return []

        _ensure_equipment_maintenance_time_fields()
        cols = set(frappe.db.get_table_columns("Equipment Maintenance") or [])
        fields = ["name", "unit", "maintenance_type", "start_date", "end_date"]
        for opt in ("status", "notes", "start_time", "end_time", "after_order_code", "after_quality", "after_color"):
            if opt in cols:
                fields.append(opt)

        if start_date and end_date:
            # Find records that overlap with the date range.
            # Keep SELECT dynamic so missing optional columns don't break SQL.
            select_cols = ", ".join(fields)
            return frappe.db.sql(
                f"""
                SELECT {select_cols}
                FROM `tabEquipment Maintenance`
                WHERE start_date <= %s
                  AND end_date >= %s
                  AND docstatus < 2
                ORDER BY unit, start_date
                """,
                (end_date, start_date),
                as_dict=True,
            )

        return frappe.get_all(
            "Equipment Maintenance",
            filters={"docstatus": ["<", 2]},
            fields=fields,
            order_by="unit, start_date",
        )
    except Exception:
        frappe.log_error(frappe.get_traceback(), "get_all_equipment_maintenance_failed")
        return []


# --- Production Table mesh / die tonnage reminders (Units 1–4 only) ---

PRODUCTION_TABLE_MAINTENANCE_UNITS = ("Unit 1", "Unit 2", "Unit 3", "Unit 4")

UNIT_MAINTENANCE_TONNAGE_THRESHOLDS = {
    "Unit 1": {"mesh": 30, "die": 90},
    "Unit 2": {"mesh": 70, "die": 210},
    "Unit 3": {"mesh": 75, "die": 150},
    "Unit 4": {"mesh": 40, "die": 120},
}


def _maintenance_reminder_month_range(month):
    from calendar import monthrange

    month = str(month or "").strip()[:7]
    if len(month) != 7 or month[4] != "-":
        today = getdate()
        month = today.strftime("%Y-%m")
    year_s, mon_s = month.split("-")
    year_i, mon_i = int(year_s), int(mon_s)
    last_day = monthrange(year_i, mon_i)[1]
    start_date = f"{month}-01"
    end_date = f"{month}-{last_day:02d}"
    return month, start_date, end_date


def _normalize_maintenance_reminder_unit(raw):
    from production_entry.production_planning.planning_doctypes import (
        normalize_planning_unit_for_select,
    )

    unit = normalize_planning_unit_for_select(raw)
    if unit in PRODUCTION_TABLE_MAINTENANCE_UNITS:
        return unit
    return None


def _aggregate_monthly_target_kg_by_unit(rows):
    """Sum planned target kg (qty) per unit for the month — matches TOTAL TARGET (Kgs) on Production Table."""
    unit_totals = {u: 0.0 for u in PRODUCTION_TABLE_MAINTENANCE_UNITS}
    for row in rows or []:
        unit = _normalize_maintenance_reminder_unit((row or {}).get("unit"))
        if not unit:
            continue
        w = flt((row or {}).get("qty") or 0)
        if w <= 0:
            continue
        unit_totals[unit] += w
    return unit_totals


def _fetch_production_table_month_rows(start_date, end_date):
    try:
        return (
            _get_color_chart_data_impl(
                start_date=start_date,
                end_date=end_date,
                plan_name="__all__",
                mode=None,
                planned_only=1,
                board_process_scope="exclude_special",
            )
            or []
        )
    except Exception:
        frappe.log_error(frappe.get_traceback(), "fetch_production_table_month_rows_failed")
        return []


@frappe.whitelist()
def get_monthly_unit_target_tons(month=None):
    """Month-to-date total target tons (sum of qty kg) per Unit 1–4 for Production Table reminders."""
    month, start_date, end_date = _maintenance_reminder_month_range(month)
    rows = _fetch_production_table_month_rows(start_date, end_date)
    kg_by_unit = _aggregate_monthly_target_kg_by_unit(rows)
    units = {}
    for unit in PRODUCTION_TABLE_MAINTENANCE_UNITS:
        kg = flt(kg_by_unit.get(unit) or 0)
        units[unit] = {"kg": kg, "tons": flt(kg / 1000.0, 2), "target_kg": kg, "target_tons": flt(kg / 1000.0, 2)}
    return {"month": month, "start_date": start_date, "end_date": end_date, "units": units}


@frappe.whitelist()
def get_monthly_unit_actual_tons(month=None):
    """Deprecated alias — reminders use total target kg (qty), not actual production."""
    return get_monthly_unit_target_tons(month)


def _count_unit_maintenance_in_month(month, unit, reminder_type_label):
    month, start_date, end_date = _maintenance_reminder_month_range(month)
    records = get_all_equipment_maintenance(start_date=start_date, end_date=end_date) or []
    want = str(reminder_type_label or "").strip().upper()
    count = 0
    for rec in records:
        if _normalize_maintenance_reminder_unit(rec.get("unit")) != unit:
            continue
        if str(rec.get("maintenance_type") or "").strip().upper() != want:
            continue
        count += 1
    return count


def _latest_reminder_ack(month, unit, reminder_type, level):
    if not frappe.db.exists("DocType", "Maintenance Reminder Ack"):
        return None
    rows = frappe.get_all(
        "Maintenance Reminder Ack",
        filters={
            "period_month": month,
            "unit": unit,
            "reminder_type": reminder_type,
            "level": cint(level),
            "user": frappe.session.user,
        },
        fields=["name", "tonnage_at_ack", "creation"],
        order_by="creation desc",
        limit=1,
    )
    return rows[0] if rows else None


def _reminder_should_show(month, unit, reminder_type, level, current_tons):
    ack = _latest_reminder_ack(month, unit, reminder_type, level)
    if not ack:
        return True, False
    ack_tons = flt(ack.get("tonnage_at_ack"))
    if current_tons > ack_tons + 0.99:
        return True, True
    return False, False


@frappe.whitelist()
def get_maintenance_reminder_status(month=None, unit_targets_json=None):
    """Pending mesh/die reminders for Production Table based on MTD total target tons (qty)."""
    month, start_date, end_date = _maintenance_reminder_month_range(month)
    if unit_targets_json:
        try:
            client_targets = json.loads(unit_targets_json) if isinstance(unit_targets_json, str) else (unit_targets_json or {})
        except Exception:
            client_targets = {}
        units_payload = {}
        for unit in PRODUCTION_TABLE_MAINTENANCE_UNITS:
            entry = client_targets.get(unit) if isinstance(client_targets, dict) else {}
            entry = entry or {}
            kg = flt(entry.get("kg") or entry.get("target_kg") or (flt(entry.get("tons")) * 1000))
            units_payload[unit] = {"kg": kg, "tons": flt(kg / 1000.0, 2)}
    else:
        payload = get_monthly_unit_target_tons(month)
        units_payload = payload.get("units") or {}
    reminders = []
    unit_summaries = {}

    for unit in PRODUCTION_TABLE_MAINTENANCE_UNITS:
        thresholds = UNIT_MAINTENANCE_TONNAGE_THRESHOLDS.get(unit) or {}
        current_tons = flt((units_payload.get(unit) or {}).get("tons") or 0)
        mesh_interval = flt(thresholds.get("mesh") or 0)
        die_interval = flt(thresholds.get("die") or 0)
        mesh_required = int(current_tons // mesh_interval) if mesh_interval > 0 else 0
        die_required = int(current_tons // die_interval) if die_interval > 0 else 0
        mesh_logged = _count_unit_maintenance_in_month(month, unit, "Mesh Change")
        die_logged = _count_unit_maintenance_in_month(month, unit, "Die Change")
        unit_summaries[unit] = {
            "kg": flt((units_payload.get(unit) or {}).get("kg") or 0),
            "tons": current_tons,
            "mesh_interval": mesh_interval,
            "die_interval": die_interval,
            "mesh_required": mesh_required,
            "die_required": die_required,
            "mesh_logged": mesh_logged,
            "die_logged": die_logged,
            "mesh_pending": max(0, mesh_required - mesh_logged),
            "die_pending": max(0, die_required - die_logged),
        }

        for key, reminder_type, interval in (
            ("mesh", "Mesh Change", mesh_interval),
            ("die", "Die Change", die_interval),
        ):
            if interval <= 0:
                continue
            required = int(current_tons // interval)
            logged = mesh_logged if key == "mesh" else die_logged
            pending = max(0, required - logged)
            if pending <= 0:
                continue
            level = logged + 1
            threshold_tons = flt(level * interval, 2)
            show, overdue = _reminder_should_show(
                month, unit, reminder_type, level, current_tons
            )
            if not show:
                continue
            reminders.append(
                {
                    "unit": unit,
                    "reminder_type": reminder_type,
                    "level": level,
                    "interval_tons": interval,
                    "threshold_tons": threshold_tons,
                    "current_tons": current_tons,
                    "current_kg": flt((units_payload.get(unit) or {}).get("kg") or 0),
                    "pending_levels": pending,
                    "overdue": overdue,
                }
            )

    # Mesh reminders before die at same visit
    reminders.sort(
        key=lambda r: (
            PRODUCTION_TABLE_MAINTENANCE_UNITS.index(r.get("unit") or "Unit 1"),
            0 if r.get("reminder_type") == "Mesh Change" else 1,
            cint(r.get("level") or 0),
        )
    )
    return {
        "month": month,
        "start_date": start_date,
        "end_date": end_date,
        "units": unit_summaries,
        "reminders": reminders,
    }


@frappe.whitelist()
def ack_maintenance_reminder(month, unit, reminder_type, level, tonnage_at_ack=None):
    """Record user dismissed a maintenance reminder popup."""
    month, _, _ = _maintenance_reminder_month_range(month)
    unit = _normalize_maintenance_reminder_unit(unit)
    if not unit:
        frappe.throw("Invalid unit for maintenance reminder")
    reminder_type = str(reminder_type or "").strip()
    if reminder_type not in ("Mesh Change", "Die Change"):
        frappe.throw("Invalid reminder type")
    if not frappe.db.exists("DocType", "Maintenance Reminder Ack"):
        return {"status": "skipped", "message": "Ack DocType missing"}
    doc = frappe.get_doc(
        {
            "doctype": "Maintenance Reminder Ack",
            "period_month": month,
            "unit": unit,
            "reminder_type": reminder_type,
            "level": cint(level),
            "tonnage_at_ack": flt(tonnage_at_ack),
            "user": frappe.session.user,
        }
    )
    doc.insert(ignore_permissions=True)
    frappe.db.commit()
    return {"status": "success", "name": doc.name}


def find_best_slot(item_qty_tons, quality, preferred_unit, start_date, recursion_depth=0):
    """
    Recursive function to find the best available slot (Date/Unit).
    Order:
    1. Preferred Unit (on Date)
    2. Neighbor Units (on Date) - Must support Quality
    3. Next Day (Recurse)
    Uses maintenance-adjusted effective daily limits.
    """
    if recursion_depth > 30: # Look ahead max 30 days
        return None # No slot found

    check_date = getdate(start_date)
    check_date_str = str(check_date)
    
    # 1. Check Preferred Unit
    if preferred_unit and preferred_unit in HARD_LIMITS:
        if not is_date_under_maintenance(preferred_unit, check_date_str):
            current_load = get_unit_load(check_date, preferred_unit)
            limit = get_unit_effective_limit_tons(preferred_unit, check_date_str)
            if current_load + item_qty_tons <= limit:
                return {"date": check_date, "unit": preferred_unit}

    # 2. Check Neighbor Units (on same date)
    compatible_units = []
    for unit, valid_qualities in UNIT_QUALITY_MAP.items():
        if unit == preferred_unit: continue
        if quality in valid_qualities:
            compatible_units.append(unit)
    
    # Check Neighbors
    for unit in ["Unit 1", "Unit 2", "Unit 3", "Unit 4"]:
        if unit in compatible_units and unit in HARD_LIMITS:
            if is_date_under_maintenance(unit, check_date_str):
                continue
            load = get_unit_load(check_date, unit)
            limit = get_unit_effective_limit_tons(unit, check_date_str)
            if load + item_qty_tons <= limit:
                return {"date": check_date, "unit": unit}

    # 3. Next Day (Recurse)
    next_date = frappe.utils.add_days(check_date, 1)
    return find_best_slot(item_qty_tons, quality, preferred_unit, next_date, recursion_depth + 1)


def get_preferred_unit(quality):
    """
    Determines the best unit for an item when width info is not available.
    Since ANY quality can run on ANY unit now, just return Unit 1 as default.
    Width-based assignment is handled in _populate_planning_sheet_items and frontend autoAllocate.
    """
    return "Unit 1"


def generate_plan_code(date_str, unit, plan_name):
    """
    Generates a readable plan code: {YY}{MonthLetter}{Unit}-{PlanName}
    e.g. 26CU1-PLAN 1
    UNASSIGNED uses segment UA. Legacy Mixed normalizes to UNASSIGNED before this runs.
    """
    if not str(date_str) or not plan_name or not unit:
        return ""
    
    try:
        # Robust unit normalization for code generation
        u_clean = str(unit).upper().replace(" ", "")
        if "LAMINATIONUNIT" in u_clean:
            u_code = "L1"
        elif "SLITTINGUNIT" in u_clean:
            u_code = "SL1"
        elif "L3" in u_clean and "TSNPL" in u_clean and "REWINDING" in u_clean:
            u_code = "RW3"
        elif "L4" in u_clean and "JSB" in u_clean and "REWINDING" in u_clean:
            u_code = "RW4"
        elif "L5" in u_clean and "JSB" in u_clean and "REWINDING" in u_clean:
            u_code = "RW5"
        elif "REWINDING" in u_clean and "UNASSIGNED" in u_clean:
            u_code = "RWU"
        elif "UNIT1" in u_clean:
            u_code = "U1"
        elif "UNIT2" in u_clean:
            u_code = "U2"
        elif "UNIT3" in u_clean:
            u_code = "U3"
        elif "UNIT4" in u_clean:
            u_code = "U4"
        elif u_clean in ("UNASSIGNED", "NONE", "NA") or "MIXED" in u_clean:
            u_code = "UA"
        else:
            return ""

        d = frappe.utils.getdate(str(date_str))
        yy = str(d.year)[-2:]
        # Month letters mapping (A-L)
        month_letters = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L"]
        month_char = month_letters[d.month - 1]
        
        # Strip Month/Week prefix (e.g., "MARCH W10 26 PLAN 1" -> "PLAN 1")
        clean_plan = _strip_legacy_prefixes(plan_name)
        
        return f"{yy}{month_char}{u_code}-{clean_plan}"
    except Exception:
        return ""

def update_sheet_plan_codes(sheet_doc, include_legacy=False):
    """
    Sets plan codes on board rows (`plan_name` + `custom_plan_code`) and on legacy `items`
    (`custom_plan_code` ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â the field shown as Plan Code on Planning sheet Item).
    Aligns with color chart / active plan name + date + unit segment.
    """
    sheet_date = sheet_doc.get("custom_planned_date") or sheet_doc.get("ordered_date")
    active_plan = sheet_doc.get("custom_plan_name") or "Default"

    unique_codes = set()

    def _row_unit(raw):
        item_unit = raw
        raw_upper = str(raw or "").upper().replace(" ", "")
        if item_unit:
            iu_upper = raw_upper
            if ("TNSPL" in iu_upper and "LAMINATION" in iu_upper) or ("LAMINATIONUNIT" in iu_upper):
                item_unit = LAMINATION_UNIT
            elif "UNASSIGNED" in iu_upper and "SLITTING" in iu_upper:
                item_unit = SLITTING_UNASSIGNED_UNIT
            elif "VTP" in iu_upper and "SLITTING" in iu_upper:
                item_unit = SLITTING_UNIT_VTP
            elif ("JVE" in iu_upper and "SLITTING" in iu_upper) or ("SLITTINGUNIT" in iu_upper):
                item_unit = SLITTING_UNIT
            elif "UNIT1" in iu_upper:
                item_unit = "Unit 1"
            elif "UNIT2" in iu_upper:
                item_unit = "Unit 2"
            elif "UNIT3" in iu_upper:
                item_unit = "Unit 3"
            elif "UNIT4" in iu_upper:
                item_unit = "Unit 4"
        normalized = normalize_planning_unit_for_select(item_unit)
        # Preserve dedicated process units even if older normalizer maps them to UNASSIGNED.
        if normalized == "UNASSIGNED":
            if ("TNSPL" in raw_upper and "LAMINATION" in raw_upper) or ("LAMINATIONUNIT" in raw_upper):
                return LAMINATION_UNIT
            if "UNASSIGNED" in raw_upper and "SLITTING" in raw_upper:
                return SLITTING_UNASSIGNED_UNIT
            if "VTP" in raw_upper and "SLITTING" in raw_upper:
                return SLITTING_UNIT_VTP
            if ("JVE" in raw_upper and "SLITTING" in raw_upper) or ("SLITTINGUNIT" in raw_upper):
                return SLITTING_UNIT
            if "REWINDING" in raw_upper:
                if "L3" in raw_upper and "TSNPL" in raw_upper:
                    return REWINDING_UNIT_L3
                if "L4" in raw_upper and "JSB" in raw_upper:
                    return REWINDING_UNIT_L4
                if "L5" in raw_upper and "JSB" in raw_upper:
                    return REWINDING_UNIT_L5
                if "UNASSIGNED" in raw_upper:
                    return REWINDING_UNASSIGNED_UNIT
        return normalized

    def _row_planned_date(item):
        if isinstance(item, dict):
            return (
                item.get("planned_date")
                or item.get("custom_item_planned_date")
                or sheet_date
            )
        return (
            getattr(item, "planned_date", None)
            or getattr(item, "custom_item_planned_date", None)
            or sheet_date
        )

    def _item_unit_raw(item):
        if isinstance(item, dict):
            return item.get("unit")
        return getattr(item, "unit", None)

    def _calc_code_for_item(item):
        item_unit = _row_unit(_item_unit_raw(item))
        item_date = _row_planned_date(item)
        return generate_plan_code(item_date, item_unit, active_plan)

    def _apply_code_to_row(item, code):
        """Set only fields that exist on the child DocType (Planning sheet Item vs Planning Table)."""
        dt = getattr(item, "doctype", None)
        if not dt:
            return
        meta = frappe.get_meta(dt)
        if meta.has_field("custom_plan_code"):
            item.custom_plan_code = code
        if meta.has_field("plan_name"):
            item.plan_name = code

    if include_legacy:
        for item in sheet_doc.get("items", []):
            code = _calc_code_for_item(item)
            _apply_code_to_row(item, code)
            if code:
                unique_codes.add(code)

    # New table (Planning Table) -- check all possible fieldnames
    for tf in ["planned_items", "custom_planned_items", "planning_table", "custom_planning_table", "table"]:
        new_items = sheet_doc.get(tf)
        if new_items:
            for item in new_items:
                code = _calc_code_for_item(item)
                _apply_code_to_row(item, code)
                if code:
                    unique_codes.add(code)
            break

    if unique_codes:
        sheet_doc.custom_plan_code = ", ".join(sorted(unique_codes))
    elif getattr(sheet_doc, "custom_plan_code", None) is None:
        sheet_doc.custom_plan_code = ""


@frappe.whitelist()
def update_sequence(items):
    """
    Updates the 'idx' of items based on the provided list.
    items: [{"name": "item_name", "idx": 1}, ...]
    """
    import json
    if isinstance(items, str):
        items = json.loads(items)
        
    for item in items:
        if item.get("name") and item.get("idx") is not None:
            # Use SQL to bypass DocStatus immutability for reordering
            frappe.db.sql("""
                UPDATE `tabPlanning Table`
                SET idx = %s
                WHERE name = %s
            """, (item.get("idx"), item.get("name")))
            
    frappe.db.commit()
    return {"status": "success"}


@frappe.whitelist()
def update_schedule(item_name, unit, date, index=0, force_move=0, perform_split=0, plan_name=None, strict_next_day=0):
    """
    Moves a specific Planning Sheet Item to a new unit/date.
    If date changes, the item is re-parented to a suitable Planning Sheet for that date.
    """
    enforce_board_write(request_board_slug("production-board"), unit=unit, date=date)
    force_move = flt(force_move)
    perform_split = flt(perform_split)
    strict_next_day = flt(strict_next_day)
    unit = normalize_planning_unit_for_select(unit)

    # 1. Get Item and Parent Details
    item = frappe.get_doc("Planning Table", item_name)
    parent_sheet = frappe.get_doc("Planning sheet", item.parent)
    date_text = _cstr(date)
    if date_text.lower() in ("none", "null", "undefined", "nan"):
        date_text = ""
    fallback_date = (
        item.get("planned_date")
        or parent_sheet.get("custom_planned_date")
        or parent_sheet.get("ordered_date")
        or frappe.utils.today()
    )
    target_date = getdate(date_text or fallback_date)
    
    # 2. Docstatus check ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶ allow movement even from submitted sheets
    # (user requested free movement; we use raw SQL to bypass Frappe immutability)

    item_wt_tons = flt(item.qty) / 1000.0
    quality = item.custom_quality or ""
    
    # QUALITY ENFORCEMENT
    if not is_quality_allowed(unit, quality):
        frappe.throw(_("Quality <b>{}</b> is not allowed in <b>{}</b>.").format(quality, unit))

    # 3. Check Capacity of Target Slot (scoped to this item's plan; maintenance-scaled)
    current_load = get_unit_load(target_date, unit, plan_name=plan_name or parent_sheet.get("custom_plan_name") or "Default")
    limit = get_unit_effective_limit_tons(unit, str(target_date))
    
    # Moving within same date (even to different unit): subtract item's own weight
    # to avoid double-counting it and causing false overflow / duplicate creation
    current_effective_date = getdate(item.get("planned_date") or parent_sheet.get("custom_planned_date") or parent_sheet.ordered_date)
    is_same_date = (str(current_effective_date) == str(target_date))
    if is_same_date and item.unit == unit:
        # Same date + same unit: pure reorder, load stays same
        load_for_check = current_load
    elif is_same_date:
        # Same date, different unit: item moves FROM old unit TO new unit.
        # Don't count the item's own weight in the old unit's load ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶ only the new unit's load matters
        load_for_check = current_load + item_wt_tons
    else:
        # Different date: full new load
        load_for_check = current_load + item_wt_tons

    if load_for_check > limit:
        # Exceeds Capacity
        available_space = max(0, limit - current_load)
        
        # Scenario A: SMART MOVE (find best slot - checks neighbor units first, then next day)
        if force_move:
            best_slot = find_best_slot(item_wt_tons, quality, unit, target_date)
            if not best_slot:
                frappe.throw(_("Could not find a valid slot on future dates."))
            final_unit = best_slot["unit"]
            final_date = getdate(best_slot["date"])
            
        # Scenario A2: STRICT NEXT DAY (same unit, next day - re-check capacity)
        elif strict_next_day:
            next_day = frappe.utils.add_days(target_date, 1)
            next_load = get_unit_load(next_day, unit)
            next_limit = get_unit_effective_limit_tons(unit, str(next_day))
            
            if next_load + item_wt_tons > next_limit:
                # Next day also full ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¶ ask user again
                return {
                    "status": "overflow",
                    "available": max(0, next_limit - next_load),
                    "limit": next_limit,
                    "current_load": next_load,
                    "order_weight": item_wt_tons,
                    "target_date": str(next_day),
                    "target_unit": unit,
                    "message": f"Next day ({next_day}) is also full for {unit}"
                }
            else:
                final_unit = unit
                final_date = next_day
            
        # Scenario B: SMART SPLIT
        elif perform_split:
            if available_space < 0.1:
                frappe.throw(_("Available space ({:.3f}T) is too small to split (Min 0.1T).").format(available_space))
            
            # Split qty stays on the target slot; remainder goes to find_best_slot ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â decide *that* before legacy logic.
            original_board_qty = flt(item.qty)
            remainder_qty = original_board_qty - (available_space * 1000.0)
            split_qty = available_space * 1000.0

            best_slot_rem = find_best_slot(remainder_qty / 1000.0, quality, unit, target_date)
            if not best_slot_rem:
                frappe.throw(_("Could not find slot for remaining quantity."))

            nu_rem = normalize_planning_unit_for_select(best_slot_rem.get("unit"))
            nu_split = normalize_planning_unit_for_select(unit)
            # Only add a second Planning sheet Item row when remainder and split piece land on different units.
            units_differ = nu_rem != nu_split

            # Update Original Item -> remainder; will be moved to best_slot_rem below
            item.qty = remainder_qty
            item.is_split = 1
            item.save()

            parent_name = item.parent
            legacy_table = "Planning sheet Item"
            new_legacy_name = None
            src_psi = _resolve_planning_table_source_item_link(item.get("source_item"), item.name)
            if src_psi and frappe.db.exists(legacy_table, src_psi):
                if units_differ:
                    frappe.db.set_value(legacy_table, src_psi, "qty", flt(remainder_qty))
                    old_legacy_doc = frappe.get_doc(legacy_table, src_psi)
                    new_legacy_doc = frappe.copy_doc(old_legacy_doc)
                    new_legacy_doc.name = None
                    new_legacy_doc.qty = flt(split_qty)
                    new_legacy_doc.unit = nu_split
                    new_legacy_doc.insert(ignore_permissions=True)
                    new_legacy_name = new_legacy_doc.name
                else:
                    frappe.db.set_value(
                        legacy_table,
                        src_psi,
                        {"unit": nu_rem, "qty": original_board_qty},
                    )

            max_idx = frappe.db.sql(
                "SELECT MAX(idx) FROM `tabPlanning Table` WHERE parent = %s", (parent_name,)
            )
            new_idx = int(max_idx[0][0] or 0) + 1 if max_idx and max_idx[0][0] else 1

            new_row_doc = frappe.new_doc("Planning Table")
            for field in item.meta.fields:
                if field.fieldtype not in ("Section Break", "Column Break", "Table") and field.fieldname not in ("name", "idx", "parent", "parentfield", "parenttype"):
                    new_row_doc.set(field.fieldname, item.get(field.fieldname))
            new_row_doc.parent = parent_name
            new_row_doc.parentfield = _get_pt_parentfield()
            new_row_doc.parenttype = "Planning sheet"
            new_row_doc.idx = new_idx
            new_row_doc.qty = flt(split_qty)
            new_row_doc.unit = unit
            new_row_doc.is_split = 1
            new_row_doc.split_from = item.name
            split_code = generate_plan_code(
                target_date,
                normalize_planning_unit_for_select(unit),
                (parent_sheet.get("custom_plan_name") or "Default"),
            )
            if frappe.db.has_column("Planning Table", "plan_name"):
                new_row_doc.plan_name = split_code
            if frappe.db.has_column("Planning Table", "custom_plan_code"):
                new_row_doc.custom_plan_code = split_code
            # New split line represents remaining/new queue work; never carry old SPR link.
            if frappe.db.has_column("Planning Table", "spr_name"):
                new_row_doc.spr_name = ""
            if new_legacy_name and src_psi and units_differ:
                new_row_doc.source_item = new_legacy_name
            else:
                new_row_doc.source_item = src_psi or _resolve_planning_table_source_item_link(
                    item.get("source_item"), item.name
                )
            new_row_doc.insert(ignore_permissions=True)

            frappe.db.commit()

            _move_item_to_slot(item, best_slot_rem["unit"], best_slot_rem["date"], None, plan_name)

            frappe.db.commit()
            try:
                frappe.publish_realtime("production_board_update", {"date": str(best_slot_rem["date"])})
            except Exception:
                pass
            return {"status": "success", "message": "Split successful"}
            
        else:
            # Scenario C: OVERFLOW (Ask User)
            return {
                "status": "overflow",
                "available": available_space,
                "limit": limit,
                "current_load": current_load,
                "order_weight": item_wt_tons
            }
    else:
        final_unit = unit
        final_date = target_date

    # 4. Perform Move
    # Convert index to int if provided
    idx_val = int(index) if index else None
    # If index is 0/None, maybe append? 
    # User drags to specific position. index is the new index in the list.
    # We should respect it.
    
    _move_item_to_slot(item, final_unit, final_date, idx_val, plan_name)
    try:
        _dedupe_slitting_pt_after_board_move(item.name, item.parent)
        _remove_duplicate_slitting_pt_rows_on_sheet(item.parent)
        frappe.db.commit()
    except Exception:
        frappe.log_error(frappe.get_traceback(), "update_schedule:dedupe_slitting")

    try:
        move_code = generate_plan_code(
            final_date,
            normalize_planning_unit_for_select(final_unit),
            (parent_sheet.get("custom_plan_name") or "Default"),
        )
        _force_sync_unit_both_planning_tables(item, final_unit, move_code)
        _normalize_planning_sheet_workstation_units(item.parent)
    except Exception:
        frappe.log_error(frappe.get_traceback(), "update_schedule:force_sync_unit")

    frappe.db.commit()
    try:
        frappe.publish_realtime("production_board_update", {"date": str(final_date)})
        frappe.publish_realtime(
            "planning_sheet_row_sync",
            {"planning_sheet": item.parent, "row": item_name, "unit": final_unit, "date": str(final_date)},
        )
    except Exception:
        pass
    return {
        "status": "success", 
        "moved_to": {"date": final_date, "unit": final_unit}
    }

def _planning_sheet_item_so_line_column():
    """Column on Planning sheet Item that links to the Sales Order line (for merge logic)."""
    if frappe.db.has_column("Planning sheet Item", "sales_order_item"):
        return "sales_order_item"
    if frappe.db.has_column("Planning sheet Item", "so_item"):
        return "so_item"
    return None


def _planning_table_so_line_column():
    """Column on Planning Table that links to the Sales Order line."""
    if frappe.db.has_column("Planning Table", "sales_order_item"):
        return "sales_order_item"
    if frappe.db.has_column("Planning Table", "custom_sales_order_item"):
        return "custom_sales_order_item"
    return None


def _resolve_legacy_source_item_from_board_row(item_doc):
    """Fallback legacy-row resolver when Planning Table.source_item is stale/missing."""
    if not item_doc or not item_doc.parent:
        return None
    so_col_pt = _planning_table_so_line_column()
    so_col_psi = _planning_sheet_item_so_line_column()
    if so_col_pt and so_col_psi:
        so_val = str(item_doc.get(so_col_pt) or "").strip()
        if so_val:
            hit = frappe.db.sql(
                f"""
                SELECT name
                FROM `tabPlanning sheet Item`
                WHERE parent = %s AND `{so_col_psi}` = %s
                ORDER BY idx ASC
                LIMIT 1
                """,
                (item_doc.parent, so_val),
            )
            if hit:
                return hit[0][0]
    item_code = str(item_doc.get("item_code") or "").strip()
    if item_code:
        rows = frappe.db.sql(
            """
            SELECT name FROM `tabPlanning sheet Item`
            WHERE parent = %s AND item_code = %s
            ORDER BY idx ASC
            """,
            (item_doc.parent, item_code),
        )
        if len(rows) == 1:
            return rows[0][0]
    return None


def _sync_legacy_planning_sheet_item_unit(source_item, unit, plan_code=None):
    """After a board move, mirror `unit` (+ plan code when available) onto Planning sheet Item."""
    name = (source_item or "").strip()
    if not name or not frappe.db.exists("Planning sheet Item", name):
        return
    updates = {}
    norm_unit = normalize_planning_unit_for_select(unit)
    if frappe.db.has_column("Planning sheet Item", "unit"):
        updates["unit"] = norm_unit
    if plan_code and frappe.db.has_column("Planning sheet Item", "custom_plan_code"):
        updates["custom_plan_code"] = plan_code
    if not updates:
        return
    set_clause = ", ".join([f"`{k}` = %s" for k in updates.keys()])
    frappe.db.sql(f"UPDATE `tabPlanning sheet Item` SET {set_clause} WHERE name = %s", list(updates.values()) + [name])


def _resolve_psi_for_board_row(item_doc):
    """Best-effort Planning sheet Item link for a Planning Table (board) row."""
    if not item_doc:
        return None
    board_name = _cstr(getattr(item_doc, "name", None) or (item_doc.get("name") if isinstance(item_doc, dict) else ""))
    if not board_name:
        return None
    if not isinstance(item_doc, dict):
        try:
            row = item_doc.as_dict()
        except Exception:
            row = {"name": board_name, "parent": getattr(item_doc, "parent", None), "source_item": getattr(item_doc, "source_item", None)}
    else:
        row = item_doc

    psi = _resolve_planning_table_source_item_link(row.get("source_item"), board_name)
    if psi:
        return psi
    if frappe.db.exists("Planning Table", board_name):
        psi = _resolve_legacy_source_item_from_board_row(frappe.get_doc("Planning Table", board_name))
        if psi:
            return psi

    sheet_parent = _cstr(row.get("parent"))
    if sheet_parent and frappe.db.exists("Planning sheet", sheet_parent):
        try:
            _link_board_planned_rows_to_legacy_items(sheet_parent)
        except Exception:
            frappe.log_error(frappe.get_traceback(), "resolve_psi: link by idx")
        refreshed = frappe.db.get_value("Planning Table", board_name, "source_item")
        psi = _resolve_planning_table_source_item_link(refreshed, board_name)
        if psi:
            return psi

    so_col_pt = _planning_table_so_line_column()
    so_col_psi = _planning_sheet_item_so_line_column()
    ic = _cstr(row.get("item_code"))
    so_val = _cstr(row.get(so_col_pt)) if so_col_pt else ""
    if sheet_parent and ic:
        filters = {"parent": sheet_parent, "item_code": ic}
        if so_col_psi and so_val:
            filters[so_col_psi] = so_val
        candidates = frappe.get_all("Planning sheet Item", filters=filters, pluck="name", limit=2)
        if len(candidates) == 1:
            return candidates[0]
    return None


def _force_sync_unit_both_planning_tables(item_doc, unit, plan_code=None):
    """Guarantee Planning Table (board) + Planning sheet Item (legacy) share the same unit immediately."""
    if not item_doc:
        return None
    board_name = _cstr(getattr(item_doc, "name", None) or (item_doc.get("name") if isinstance(item_doc, dict) else ""))
    if not board_name or not frappe.db.exists("Planning Table", board_name):
        return None

    norm_unit = normalize_planning_unit_for_select(unit)
    plan_code = _cstr(plan_code).strip() or None

    pt_updates = {"unit": norm_unit}
    if plan_code:
        if frappe.db.has_column("Planning Table", "custom_plan_code"):
            pt_updates["custom_plan_code"] = plan_code
        if frappe.db.has_column("Planning Table", "plan_name"):
            pt_updates["plan_name"] = plan_code
    set_clause = ", ".join([f"`{k}` = %s" for k in pt_updates.keys()])
    frappe.db.sql(
        f"UPDATE `tabPlanning Table` SET {set_clause} WHERE name = %s",
        list(pt_updates.values()) + [board_name],
    )

    if not isinstance(item_doc, dict):
        item_doc.unit = norm_unit

    psi_name = _resolve_psi_for_board_row(item_doc)
    if psi_name:
        cur_src = frappe.db.get_value("Planning Table", board_name, "source_item")
        if cur_src != psi_name:
            frappe.db.set_value("Planning Table", board_name, "source_item", psi_name, update_modified=False)
        _sync_legacy_planning_sheet_item_unit(psi_name, norm_unit, plan_code)
    return psi_name


def _legacy_psi_has_board_on_unit(sheet_parent, psi_name, target_unit):
    """True if any Planning Table row on this sheet links to this PSI with the given normalized unit."""
    if not sheet_parent or not psi_name:
        return False
    nu_t = normalize_planning_unit_for_select(target_unit)
    rows = frappe.get_all(
        "Planning Table",
        filters={"parent": sheet_parent, "source_item": psi_name},
        fields=["unit"],
    )
    for r in rows:
        if normalize_planning_unit_for_select(r.unit) == nu_t:
            return True
    return False


def _merge_reunited_legacy_psi_rows(sheet_parent):
    """Merge duplicate Planning sheet Item rows when all board rows for that group are on one unit again.

    Groups by sales-order line when `so_item` / `sales_order_item` is set; otherwise by `item_code` on the
    same sheet (splits often lose the SO line link on cloned PSI rows).
    """
    legacy_table = "Planning sheet Item"
    if not sheet_parent:
        return

    so_col = _planning_sheet_item_so_line_column()
    fields = ["name", "qty", "item_code"]
    if so_col:
        fields.append(so_col)

    all_rows = frappe.get_all(
        legacy_table,
        filters={"parent": sheet_parent},
        fields=fields,
    )
    from collections import defaultdict

    def _try_merge_group(lst):
        if len(lst) < 2:
            return
        names_with_pts = []
        for row in lst:
            pts = frappe.get_all(
                "Planning Table",
                filters={"parent": sheet_parent, "source_item": row.name},
                fields=["unit"],
            )
            if not pts:
                continue
            names_with_pts.append((row.name, pts))
        if len(names_with_pts) < 2:
            return

        union_units = set()
        for _n, pts in names_with_pts:
            for p in pts:
                union_units.add(normalize_planning_unit_for_select(p.unit))
        if len(union_units) != 1:
            return

        u_only = list(union_units)[0]
        psi_names = [n for n, _pts in names_with_pts]
        keeper = min(psi_names)
        others = [n for n in psi_names if n != keeper]

        merged_qty = flt(frappe.db.get_value(legacy_table, keeper, "qty"))
        for o in others:
            merged_qty += flt(frappe.db.get_value(legacy_table, o, "qty"))
            frappe.db.sql(
                """
                UPDATE `tabPlanning Table`
                SET source_item=%s
                WHERE parent=%s AND source_item=%s
                """,
                (keeper, sheet_parent, o),
            )
            frappe.db.sql(f"DELETE FROM `tab{legacy_table}` WHERE name=%s", (o,))
        frappe.db.set_value(
            legacy_table,
            keeper,
            {"qty": merged_qty, "unit": u_only},
        )

    # 1) Same SO line (preferred)
    if so_col:
        by_so = defaultdict(list)
        for r in all_rows:
            key = str(r.get(so_col) or "").strip()
            if key:
                by_so[key].append(r)
        for lst in by_so.values():
            _try_merge_group(lst)

    # 2) Same item_code on this sheet when SO line is blank (common after split / clone)
    by_item = defaultdict(list)
    for r in all_rows:
        if so_col and str(r.get(so_col) or "").strip():
            continue
        ic = str(r.get("item_code") or "").strip()
        if ic:
            by_item[ic].append(r)
    for lst in by_item.values():
        _try_merge_group(lst)


def _resolve_planning_table_source_item_link(source_item_value, board_row_name=None):
    """Planning Table.source_item must link to Planning sheet Item. Board row ids often get stored by mistake.

    Walk Planning Table.source_item chains until a valid Planning sheet Item is found.
    """
    def _walk(cur):
        cur = (cur or "").strip()
        for _ in range(8):
            if not cur:
                return None
            if frappe.db.exists("Planning sheet Item", cur):
                return cur
            if frappe.db.exists("Planning Table", cur):
                cur = frappe.db.get_value("Planning Table", cur, "source_item") or ""
                continue
            return None
        return None

    out = _walk(source_item_value)
    if out:
        return out
    if board_row_name:
        return _walk(board_row_name)
    return None


def _planning_table_so_line_key(row):
	"""Sales order line id for deduping Planning Table rows after a unit move."""
	if isinstance(row, dict):
		data = row
	elif hasattr(row, "as_dict"):
		data = row.as_dict()
	else:
		data = {}
	for fn in ("so_item", "sales_order_item", "custom_sales_order_item"):
		v = _cstr(data.get(fn)).strip()
		if v:
			return v
	return ""


def _cleanup_duplicate_planning_table_rows_after_unit_move(moved_pt, target_unit):
	"""Remove duplicate PT rows for the same SO line + item on other units (slitting board dupes)."""
	parent = _cstr(getattr(moved_pt, "parent", None) or "").strip()
	ic = _cstr(getattr(moved_pt, "item_code", None) or "").strip()
	moved_name = _cstr(getattr(moved_pt, "name", None) or "").strip()
	if not parent or not ic or not moved_name:
		return
	so_key = _planning_table_so_line_key(moved_pt)
	target_norm = normalize_planning_unit_for_select(target_unit)
	is_split = False
	if frappe.db.has_column("Planning Table", "is_split"):
		is_split = cint(getattr(moved_pt, "is_split", 0) or frappe.db.get_value("Planning Table", moved_name, "is_split"))
	others = frappe.get_all(
		"Planning Table",
		filters={"parent": parent, "item_code": ic, "name": ["!=", moved_name]},
		fields=["name", "unit", "qty", "so_item", "sales_order_item", "is_split"],
		limit_page_length=0,
	)
	for o in others or []:
		if so_key and _planning_table_so_line_key(o) != so_key:
			continue
		if is_split or (frappe.db.has_column("Planning Table", "is_split") and cint(o.get("is_split"))):
			continue
		o_norm = normalize_planning_unit_for_select(o.get("unit"))
		if o_norm != target_norm:
			frappe.delete_doc("Planning Table", o["name"], force=1)
		else:
			new_qty = flt(getattr(moved_pt, "qty", 0)) + flt(o.get("qty"))
			frappe.db.set_value("Planning Table", moved_name, "qty", new_qty, update_modified=False)
			moved_pt.qty = new_qty
			frappe.delete_doc("Planning Table", o["name"], force=1)


def _move_item_to_slot(item_doc, unit, date, new_idx=None, plan_name=None):
    """Internal helper to move a Planning Sheet Item to a specific slot.
    Re-parents item if date changes, avoiding moving the entire order."""
    unit = normalize_planning_unit_for_select(unit)
    target_date = getdate(date)
    source_parent = frappe.get_doc("Planning sheet", item_doc.parent)
    
    source_effective_date = getdate(source_parent.get("custom_planned_date") or source_parent.ordered_date)
    move_code = generate_plan_code(
        target_date,
        normalize_planning_unit_for_select(unit),
        (source_parent.get("custom_plan_name") or "Default"),
    )
    
    # 1. Date Reparenting (Disabled Per User Request)
    # The user explicitly requested "NEVER ALLOW NEW PLANNING SHEET" and "ALWASY USE EXISTING PLANNING SHEET".
    # Therefore, we do not reparent items to new sheets when their date changes.
    # We rely solely on updating the `planned_date` at the item level below.

    # 2. DUAL TABLE SYNC: Planning Table <-> Planning sheet Item (legacy grid)
    # When split rows share one legacy PSI and move to different units, clone the legacy row.
    # When two legacy rows for the same SO line end up on the same unit again, merge them.
    legacy_table = "Planning sheet Item"
    # Repair stale/missing source_item link so unit sync reaches legacy PSI immediately.
    resolved_source = _resolve_planning_table_source_item_link(item_doc.get("source_item"), item_doc.name)
    if not resolved_source:
        # Last-resort repair: when board/legacy tables are 1:1 (same row count), relink by idx.
        # This fixes cases where Planning Table.source_item accidentally stores a board-row id or garbage,
        # causing unit changes (from Production Table / Color Chart) to not reflect in legacy grid.
        try:
            _link_board_planned_rows_to_legacy_items(item_doc.parent)
        except Exception:
            frappe.log_error(frappe.get_traceback(), "repair source_item links by idx")
        resolved_source = _resolve_planning_table_source_item_link(item_doc.get("source_item"), item_doc.name)
    if not resolved_source:
        resolved_source = _resolve_legacy_source_item_from_board_row(item_doc)
    if not resolved_source:
        # Direct match fallback: find Planning sheet Item with same parent + so_item + item_code.
        so_col = _planning_sheet_item_so_line_column()
        si_ic = (item_doc.get("item_code") or "").strip()
        si_soi = (item_doc.get("so_item") or item_doc.get("sales_order_item") or "").strip()
        si_par = (item_doc.get("parent") or "").strip()
        if so_col and si_ic and si_soi and si_par:
            _candidates = frappe.get_all(
                legacy_table,
                filters={"parent": si_par, so_col: si_soi, "item_code": si_ic},
                pluck="name",
                limit=1,
            )
            if _candidates:
                resolved_source = _candidates[0]
    if resolved_source and resolved_source != (item_doc.get("source_item") or ""):
        item_doc.source_item = resolved_source
        frappe.db.sql(
            "UPDATE `tabPlanning Table` SET source_item = %s WHERE name = %s",
            (resolved_source, item_doc.name),
        )
        frappe.db.commit()
    if item_doc.get("source_item") and frappe.db.exists(legacy_table, item_doc.source_item):
        siblings = frappe.get_all(
            "Planning Table",
            filters={"source_item": item_doc.source_item, "name": ["!=", item_doc.name]},
            fields=["name", "unit"],
        )
        # No other Planning Table rows share this legacy PSI (e.g. sole split leaving Unassigned): only sync legacy unit.
        if siblings:
            s0 = normalize_planning_unit_for_select(siblings[0].unit or "")
            new_unit_norm = normalize_planning_unit_for_select(unit)
            legacy_qty = flt(frappe.db.get_value(legacy_table, item_doc.source_item, "qty") or 0)
            pt_total = flt(item_doc.qty) + sum(flt(s.get("qty")) for s in siblings)
            split_across_units = (
                new_unit_norm != s0
                and legacy_qty > 0
                and flt(item_doc.qty) < legacy_qty - 1e-6
                and pt_total <= legacy_qty + 1e-6
            )
            if split_across_units:
                old_legacy_doc = frappe.get_doc(legacy_table, item_doc.source_item)
                new_legacy_doc = frappe.copy_doc(old_legacy_doc)
                new_legacy_doc.name = None
                new_legacy_doc.qty = flt(item_doc.qty)
                new_legacy_doc.unit = unit
                new_legacy_doc.insert(ignore_permissions=True)
                new_orig_qty = max(0, flt(old_legacy_doc.qty) - flt(item_doc.qty))
                frappe.db.set_value(legacy_table, old_legacy_doc.name, "qty", new_orig_qty)
                item_doc.source_item = new_legacy_doc.name
            else:
                for sib in siblings:
                    try:
                        frappe.delete_doc("Planning Table", sib["name"], force=1)
                    except Exception:
                        frappe.log_error(frappe.get_traceback(), f"remove stale PT sibling:{sib.get('name')}")
                _sync_legacy_planning_sheet_item_unit(item_doc.get("source_item"), unit, move_code)
        else:
            _sync_legacy_planning_sheet_item_unit(item_doc.get("source_item"), unit, move_code)

        try:
            cur_legacy = frappe.get_doc(legacy_table, item_doc.source_item)
            so_col = _planning_sheet_item_so_line_column()
            so_item = (cur_legacy.get(so_col) if so_col else None) or ""
            so_item = str(so_item or "").strip()
            legacy_parent = cur_legacy.parent
            if so_col and so_item and legacy_parent:
                # Same SO line can have multiple Planning sheet Item rows after splits. Merge when they
                # represent the same unit again. Do not rely only on legacy `unit` ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â it often lags the board.
                dupes_all = frappe.db.sql(
                    f"""
                    SELECT name, qty, unit FROM `tab{legacy_table}`
                    WHERE parent = %s AND `{so_col}` = %s AND name != %s
                    """,
                    (legacy_parent, so_item, cur_legacy.name),
                    as_dict=True,
                )
                dupes = []
                for d in dupes_all or []:
                    nu_row = normalize_planning_unit_for_select(d.get("unit"))
                    if nu_row == unit:
                        dupes.append(d)
                    elif _legacy_psi_has_board_on_unit(legacy_parent, d.name, unit):
                        dupes.append(d)
                if dupes:
                    merged_qty = flt(cur_legacy.qty)
                    for d in dupes:
                        merged_qty += flt(d.qty)
                        frappe.db.sql(
                            "UPDATE `tabPlanning Table` SET source_item = %s WHERE source_item = %s",
                            (cur_legacy.name, d.name),
                        )
                        frappe.db.sql(f"DELETE FROM `tab{legacy_table}` WHERE name = %s", (d.name,))
                    frappe.db.set_value(
                        legacy_table,
                        cur_legacy.name,
                        {"qty": merged_qty, "unit": unit},
                    )
        except Exception:
            frappe.log_error(frappe.get_traceback(), "Legacy merge error")

        frappe.db.commit()

    # 3. Handle IDX Shifting if inserting at specific position
    # Update Item unit and parent first ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â use raw SQL to bypass docstatus immutability

    update_fields = {"unit": unit, "source_item": item_doc.source_item}
    if frappe.db.has_column("Planning Table", "planned_date"):
        update_fields["planned_date"] = target_date
    if frappe.db.has_column("Planning Table", "plan_name"):
        update_fields["plan_name"] = move_code
    if frappe.db.has_column("Planning Table", "custom_plan_code"):
        update_fields["custom_plan_code"] = move_code
    # Moving to a different production date starts a new run context; old SPR must not flow forward.
    if frappe.db.has_column("Planning Table", "spr_name"):
        date_changed = str(source_effective_date) != str(target_date)
        if date_changed:
            update_fields["spr_name"] = ""
    set_clause = ", ".join([f"`{k}` = %s" for k in update_fields.keys()])
    frappe.db.sql(
        f"UPDATE `tabPlanning Table` SET {set_clause} WHERE name = %s",
        list(update_fields.values()) + [item_doc.name]
    )
    frappe.db.commit() # FORCE SAVE FOR BOARD
    item_doc.unit = unit

    try:
        _cleanup_duplicate_planning_table_rows_after_unit_move(item_doc, unit)
        frappe.db.commit()
    except Exception:
        frappe.log_error(frappe.get_traceback(), "cleanup duplicate PT after unit move")

    try:
        _merge_reunited_legacy_psi_rows(item_doc.parent)
        frappe.db.commit()
    except Exception:
        frappe.log_error(frappe.get_traceback(), "merge reunited legacy PSI")

    # Final guarantee: board row + legacy Planning sheet Item always show the same unit.
    try:
        _force_sync_unit_both_planning_tables(item_doc, unit, move_code)
        _normalize_planning_sheet_workstation_units(item_doc.parent)
        frappe.db.commit()
    except Exception:
        frappe.log_error(frappe.get_traceback(), "force_sync_unit_both_planning_tables")

    # IDX shifting disabled to prevent child table corruption in Frappe.
    # Frappe requires idx to be unique per parent. Updating idx across multiple documents 
    # to form a board sequence breaks the native child table order (causing data cross-contamination).

    # 3. Update Plan Codes for Affected Sheets (Planning Table only)
    for sheet_name in set([source_parent.name, item_doc.parent]):
        if frappe.db.exists("Planning sheet", sheet_name):
            doc_sheet = frappe.get_doc("Planning sheet", sheet_name, ignore_cache=True)
            update_sheet_plan_codes(doc_sheet, include_legacy=True)
            frappe.db.sql("UPDATE `tabPlanning sheet` SET custom_plan_code = %s WHERE name = %s", (doc_sheet.custom_plan_code, doc_sheet.name))

            for tf in ["planned_items", "custom_planned_items", "planning_table", "custom_planning_table", "table"]:
                new_items = doc_sheet.get(tf)
                if new_items:
                    for d in new_items:
                        if d.get("plan_name"):
                            frappe.db.sql("UPDATE `tabPlanning Table` SET plan_name = %s WHERE name = %s", (d.plan_name, d.name))
                    break

@frappe.whitelist()
def get_kanban_board(start_date, end_date):
    enforce_board_read(
        request_board_slug(board_slug_for_api("get_kanban_board")),
        start_date=start_date,
        end_date=end_date,
    )
    start_date = getdate(start_date)
    end_date = getdate(end_date)
    
    sheets = frappe.get_all(
        "Planning sheet",
        filters={
            "ordered_date": ["between", [start_date, end_date]],
            "docstatus": ["<", 2]
        },
        fields=["name", "customer", "party_code", "ordered_date", "dod", "planning_status", "docstatus"],
        order_by="ordered_date asc"
    )
    
    data = []
    for sheet in sheets:
        items = frappe.get_all(
            "Planning Table",
            filters={"parent": sheet.name},
            fields=["qty", "unit", "custom_quality", "color", "gsm"],
            order_by="idx"
        )
        
        # Map custom_quality to quality for frontend consistency
        for item in items:
            item["quality"] = item.get("custom_quality")

        total_weight = sum([flt(d.qty) for d in items])
        
        # Determine Major Unit
        unit = "Unit 1" # Default
        if items:
            # Get most frequent unit
            units = [d.unit for d in items if d.unit]
            if units:
                unit = max(set(units), key=units.count)
        
        data.append({
            "name": sheet.name,
            "customer": sheet.customer,
            "party_code": sheet.party_code,
            "ordered_date": sheet.ordered_date,
            "dod": sheet.dod,
            "planning_status": sheet.planning_status,
            "docstatus": sheet.docstatus,
            "unit": unit,
            "total_weight": total_weight,
            "items": items
        })
        
    return data

