@frappe.whitelist()
def get_unscheduled_planning_sheets():
    """
    Fetches Planning Sheets that are 'Confirmed' (docstatus=0 or 1) but have NO ordered_date.
    These display in the 'Confirmed Order' view.
    """
    sql = """
        SELECT 
            p.name, p.customer, COALESCE(c.customer_name, p.customer) as customer_name,
            p.party_code, p.docstatus, p.ordered_date,
            SUM(i.qty) as total_qty
        FROM `tabPlanning sheet` p
        LEFT JOIN `tabPlanning Table` i ON i.parent = p.name
        LEFT JOIN `tabCustomer` c ON p.customer = c.name
        WHERE 
            (p.ordered_date IS NULL OR p.ordered_date = '')
            AND p.docstatus < 2
        GROUP BY p.name
    """
    sheets = frappe.db.sql(sql, as_dict=True)
    
    return sheets

# Company card order on the Confirm Orders kanban (matched on normalised name).
_CONFIRM_KANBAN_COMPANY_RULES = [
    lambda s: "jayashree" in s and "1zt" in s,
    lambda s: "jayashree" in s and "2zs" in s,
    lambda s: "thusma" in s and "1z0" in s,
    lambda s: "thusma" in s and "2zz" in s,
    lambda s: "varshinetex" in s and ("puducherry" in s or "pondicherry" in s),
    lambda s: "varshinetex" in s and "odisha" in s,
    lambda s: "vasanth" in s,
    lambda s: "varshineretail" in s,
    lambda s: "thusmattex" in s,
    lambda s: "avitas" in s,
]


def _confirm_kanban_company_priority(company_name):
    normalized = re.sub(r"[^a-z0-9]", "", (company_name or "").lower())
    for idx, rule in enumerate(_CONFIRM_KANBAN_COMPANY_RULES):
        try:
            if rule(normalized):
                return idx
        except Exception:
            continue
    return len(_CONFIRM_KANBAN_COMPANY_RULES)


def _get_confirm_orders_unit_options_list():
	"""Exact Workstation names only — no hardcoded Unit 1/UNIT 1 catalogue or planning distincts."""
	units = []
	seen = set()
	try:
		for name in frappe.get_all("Workstation", pluck="name", order_by="name", limit_page_length=0) or []:
			label = str(name or "").strip()
			if not label or label in seen:
				continue
			seen.add(label)
			units.append(label)
	except Exception:
		pass

	# When Production Board Access limits units, keep only workstations in that scope.
	try:
		from production_entry.production_planning.board_access import assert_unit_allowed, get_user_board_scope

		scope = get_user_board_scope()
		if scope and not scope.get("unlimited") and (scope.get("allowed_units") or []):
			filtered = []
			for u in units:
				try:
					assert_unit_allowed(u, scope=scope)
					filtered.append(u)
				except Exception:
					continue
			units = filtered
	except Exception:
		pass

	def _sort_key(label):
		s = (label or "").strip()
		low = s.lower()
		su = low.replace(" ", "").replace("_", "")
		if low.startswith("unit ") and len(low) > 5 and low[5:6].isdigit():
			return (0, int(low[5]), low)
		if su.startswith("unit") and len(su) > 4 and su[4:5].isdigit():
			return (0, int(su[4]), low)
		if su in ("unassigned", "mixed"):
			return (1, 0, low)
		return (2, 0, low)

	return sorted(units, key=_sort_key)


def _confirm_orders_date_filter_sql(has_custom_planned_date, order_date=None, start_date=None, end_date=None):
    """Match a sheet when ANY planning/board/SO date falls in the filter (not MIN-only HAVING)."""
    item_planned = "NULLIF(i2.planned_date, '')"
    sheet_exprs = ["NULLIF(p.ordered_date, '')", "so.transaction_date"]
    if has_custom_planned_date:
        sheet_exprs.insert(0, "NULLIF(p.custom_planned_date, '')")

    if order_date:
        parts = [
            f"EXISTS (SELECT 1 FROM `tabPlanning Table` i2 WHERE i2.parent = p.name AND {item_planned} = %s)"
        ]
        vals = [order_date]
        for expr in sheet_exprs:
            parts.append(f"({expr} = %s)")
            vals.append(order_date)
        return "(" + " OR ".join(parts) + ")", vals

    if start_date and end_date:
        parts = [
            "EXISTS (SELECT 1 FROM `tabPlanning Table` i2 WHERE i2.parent = p.name "
            f"AND {item_planned} BETWEEN %s AND %s)"
        ]
        vals = [start_date, end_date]
        for expr in sheet_exprs:
            parts.append(f"({expr} BETWEEN %s AND %s)")
            vals.extend([start_date, end_date])
        return "(" + " OR ".join(parts) + ")", vals

    return None, []


def _confirm_orders_eligibility_sql():
	"""Show planning sheets on the company from the Sales Order / Planning sheet.

	Confirm Orders is a company board of submitted sales orders that still need a
	production plan. Production Status may be Draft (2ZS/2ZZ) or Confirmed (1ZT/1Z0);
	both must appear. Only Planned/Completed/Cancelled production status is excluded.
	"""
	parts = [
		"p.docstatus < 2",
		"IFNULL(p.planning_status, '') NOT IN ('Cancelled', 'Completed')",
		"IFNULL(so.docstatus, 0) = 1",
	]
	if frappe.db.has_column("Sales Order", "custom_production_status"):
		parts.append(
			"LOWER(TRIM(IFNULL(so.custom_production_status, ''))) "
			"NOT IN ('planned', 'completed', 'cancelled')"
		)
	return parts


_CONFIRM_ORDERS_FG_PARENT_FABRICS = frozenset({"Bag FG", "FG Fabric", "FG Sheet"})
_CONFIRM_ORDERS_PCS_UOMS = frozenset({"nos", "pcs", "pieces", "piece", "pc"})
_CONFIRM_ORDERS_KG_UOMS = frozenset({"kg", "kilogram", "kilograms"})


def _confirm_orders_fg_parent_fabric_types():
	return _CONFIRM_ORDERS_FG_PARENT_FABRICS


def _confirm_orders_uom_bucket(uom):
	u = _cstr(uom).strip().lower()
	if u in _CONFIRM_ORDERS_PCS_UOMS:
		return "pcs"
	if u in _CONFIRM_ORDERS_KG_UOMS:
		return "kg"
	return "other"


def _confirm_orders_uom_label(uom):
	u = _cstr(uom).strip()
	low = u.lower()
	if low in _CONFIRM_ORDERS_PCS_UOMS:
		return "Pcs"
	if low in _CONFIRM_ORDERS_KG_UOMS:
		return "Kg"
	return u or ""


def _confirm_orders_format_qty_display(qty, uom_label):
	q = flt(qty)
	if q <= 0:
		return ""
	if uom_label == "Pcs":
		return f"{int(round(q)):,} Pcs"
	if uom_label == "Kg":
		if q >= 1000:
			return f"{q / 1000:.2f} T"
		return f"{q:,.2f} Kg"
	return f"{q:,.2f} {uom_label}" if uom_label else f"{q:,.2f}"


def _confirm_orders_is_fg_row(row, so_fg_by_soi=None):
	ic = _cstr(row.get("item_code")).strip()
	if not ic:
		return False
	mt = normalize_movement_type(row.get(PLANNING_MOVEMENT_TYPE_FIELD) or row.get("movement_type"))
	if mt == MOVEMENT_DESPATCH:
		return True
	pf = _cstr(row.get("custom_parent_fabric")).strip()
	if pf in _CONFIRM_ORDERS_FG_PARENT_FABRICS:
		return True
	if so_fg_by_soi:
		soi = _cstr(row.get("sales_order_item") or row.get("so_item")).strip()
		so_it = so_fg_by_soi.get(soi) if soi else None
		if so_it:
			so_ic = _cstr(
				getattr(so_it, "item_code", None)
				or (so_it.get("item_code") if isinstance(so_it, dict) else "")
			)
			if so_ic and (ic == so_ic or _same_fg_design_family(ic, so_ic)):
				return True
	return False


def _summarize_fg_qty_for_planning_sheets(sheet_rows):
	"""FG finished-good qty per planning sheet (Despatch / Bag FG / FG Fabric / FG Sheet only)."""
	if not sheet_rows:
		return {}
	sheet_names = [_cstr(s.get("name")).strip() for s in sheet_rows if _cstr(s.get("name")).strip()]
	if not sheet_names:
		return {}

	fields = ["parent", "item_code", "qty", "uom"]
	for col in ("sales_order_item", "so_item", "custom_parent_fabric", PLANNING_MOVEMENT_TYPE_FIELD):
		if frappe.db.has_column("Planning Table", col):
			fields.append(col)

	pt_rows = frappe.get_all(
		"Planning Table",
		filters={"parent": ["in", sheet_names]},
		fields=fields,
		limit_page_length=0,
	) or []

	sheet_so = {
		_cstr(s.get("name")).strip(): _cstr(s.get("sales_order")).strip() for s in sheet_rows
	}
	so_fg_maps = {}
	for so_name in {v for v in sheet_so.values() if v}:
		_, so_fg_maps[so_name] = _so_line_order_and_fg_map(so_name)

	by_sheet = {n: [] for n in sheet_names}
	for row in pt_rows:
		parent = _cstr(row.get("parent")).strip()
		if parent not in by_sheet:
			continue
		so_fg = so_fg_maps.get(sheet_so.get(parent, ""), {})
		if _confirm_orders_is_fg_row(row, so_fg):
			by_sheet[parent].append(row)

	out = {}
	for sheet_name in sheet_names:
		fg_rows = by_sheet.get(sheet_name) or []
		fg_qty_kg = 0.0
		fg_qty_pcs = 0.0
		other_lines = []
		parent_fabrics = []
		fg_lines = []
		seen_pf = set()

		for row in fg_rows:
			qty = flt(row.get("qty"))
			uom = _cstr(row.get("uom")).strip()
			bucket = _confirm_orders_uom_bucket(uom)
			pf = _cstr(row.get("custom_parent_fabric")).strip()
			if pf and pf not in seen_pf:
				seen_pf.add(pf)
				parent_fabrics.append(pf)
			fg_lines.append({"qty": qty, "uom": uom, "parent_fabric": pf})
			if bucket == "pcs":
				fg_qty_pcs += qty
			elif bucket == "kg":
				fg_qty_kg += qty
			else:
				other_lines.append((qty, uom))

		display_parts = []
		if fg_qty_pcs > 0:
			display_parts.append(_confirm_orders_format_qty_display(fg_qty_pcs, "Pcs"))
		if fg_qty_kg > 0:
			display_parts.append(_confirm_orders_format_qty_display(fg_qty_kg, "Kg"))
		for qty, uom in other_lines:
			label = _confirm_orders_uom_label(uom) or uom
			part = _confirm_orders_format_qty_display(qty, label)
			if part:
				display_parts.append(part)

		out[sheet_name] = {
			"fg_qty_kg": fg_qty_kg,
			"fg_qty_pcs": fg_qty_pcs,
			"fg_display": " + ".join(display_parts),
			"parent_fabrics": parent_fabrics,
			"parent_fabric": parent_fabrics[0] if parent_fabrics else "",
			"fg_lines": fg_lines,
		}
	return out


def _get_confirm_orders_company_kanban_impl(order_date=None, start_date=None, end_date=None, order_code=None, customer=None, unit=None):
    """Planning sheets grouped by Sales Order / Planning sheet company for every company."""
    has_ps_company = frappe.db.has_column("Planning sheet", "custom_company")
    has_custom_planned_date = frappe.db.has_column("Planning sheet", "custom_planned_date")
    company_expr = (
        "COALESCE(NULLIF(TRIM(p.custom_company), ''), NULLIF(TRIM(so.company), ''))"
        if has_ps_company
        else "NULLIF(TRIM(so.company), '')"
    )
    dod_expr = "p.dod" if frappe.db.has_column("Planning sheet", "dod") else "NULL"
    so_status_sel = "so.delivery_status" if frappe.db.has_column("Sales Order", "delivery_status") else "NULL"

    if has_custom_planned_date:
        eff = (
            "COALESCE(MAX(NULLIF(i.planned_date, '')), NULLIF(p.custom_planned_date, ''), "
            "NULLIF(p.ordered_date, ''), so.transaction_date)"
        )
    else:
        eff = "COALESCE(MAX(NULLIF(i.planned_date, '')), NULLIF(p.ordered_date, ''), so.transaction_date)"

    conditions = _confirm_orders_eligibility_sql()
    values = []

    if order_code:
        conditions.append("p.party_code LIKE %s")
        values.append(f"%{order_code}%")
    if customer:
        conditions.append("(p.customer LIKE %s OR c.customer_name LIKE %s)")
        values.extend([f"%{customer}%", f"%{customer}%"])
    if unit:
        conditions.append(
            "EXISTS (SELECT 1 FROM `tabPlanning Table` u WHERE u.parent = p.name "
            "AND LOWER(TRIM(u.unit)) = LOWER(TRIM(%s)))"
        )
        values.append(unit)

    date_sql, date_vals = _confirm_orders_date_filter_sql(
        has_custom_planned_date,
        order_date=order_date,
        start_date=start_date,
        end_date=end_date,
    )
    if date_sql:
        conditions.append(date_sql)
        values.extend(date_vals)

    where_clause = " AND ".join(conditions)

    sql = f"""
        SELECT
            p.name, p.sales_order, p.party_code, p.customer,
            COALESCE(c.customer_name, p.customer) AS customer_name,
            p.planning_status, {dod_expr} AS dod, p.creation,
            {company_expr} AS company,
            so.transaction_date AS so_date,
            {so_status_sel} AS delivery_status,
            GROUP_CONCAT(DISTINCT NULLIF(i.unit, '') ORDER BY NULLIF(i.unit, '') SEPARATOR ', ') AS units,
            {eff} AS effective_date
        FROM `tabPlanning sheet` p
        LEFT JOIN `tabSales Order` so ON so.name = p.sales_order
        LEFT JOIN `tabCustomer` c ON c.name = p.customer
        LEFT JOIN `tabPlanning Table` i ON i.parent = p.name
        WHERE {where_clause}
        GROUP BY p.name
        ORDER BY {eff} ASC, p.creation DESC
    """

    sheets = frappe.db.sql(sql, tuple(values), as_dict=True)
    fg_by_sheet = _summarize_fg_qty_for_planning_sheets(sheets)

    cards = {}

    def _card_for(company_name):
        key = company_name or "Unassigned"
        if key not in cards:
            cards[key] = {
                "company": key,
                "priority": _confirm_kanban_company_priority(key),
                "sheets": [],
                "total_qty_kg": 0.0,
                "total_qty_pcs": 0.0,
                "total_qty": 0.0,
            }
        return cards[key]

    # Show every company as a card (priority order), even if it has no confirmed sheets yet.
    for comp in frappe.get_all("Company", pluck="name"):
        _card_for(comp)

    for s in sheets:
        card = _card_for(s.company)
        fg = fg_by_sheet.get(s.name) or {}
        fg_qty_kg = flt(fg.get("fg_qty_kg"))
        fg_qty_pcs = flt(fg.get("fg_qty_pcs"))
        card["total_qty_kg"] += fg_qty_kg
        card["total_qty_pcs"] += fg_qty_pcs
        card["total_qty"] += fg_qty_kg
        card["sheets"].append({
            "name": s.name,
            "salesOrder": s.sales_order,
            "orderCode": s.party_code or "",
            "customer": s.customer or "",
            "customerName": s.customer_name or s.customer or "",
            "planningStatus": s.planning_status or "Draft",
            "qty": fg_qty_kg,
            "fg_qty_kg": fg_qty_kg,
            "fg_qty_pcs": fg_qty_pcs,
            "fg_display": fg.get("fg_display") or "",
            "parent_fabric": fg.get("parent_fabric") or "",
            "parent_fabrics": fg.get("parent_fabrics") or [],
            "units": s.units or "",
            "dod": str(s.dod) if s.dod else "",
            "plannedDate": str(s.effective_date) if s.effective_date else "",
            "soDate": str(s.so_date) if s.so_date else "",
            "deliveryStatus": s.delivery_status or "Not Delivered",
        })

    ordered = sorted(cards.values(), key=lambda card: (card["priority"], (card["company"] or "").lower()))
    return {"companies": ordered, "unitOptions": _get_confirm_orders_unit_options_list()}


@frappe.whitelist()
def get_confirm_orders_unit_options():
    """Workstation list for Confirm Orders unit filter dropdown."""
    try:
        return _get_confirm_orders_unit_options_list()
    except Exception:
        frappe.log_error(frappe.get_traceback(), "get_confirm_orders_unit_options_error")
        return []


@frappe.whitelist()
def get_confirm_orders_company_kanban(order_date=None, start_date=None, end_date=None, order_code=None, customer=None, unit=None):
    """Safe wrapper so the Confirm Orders page never 502s on schema drift."""
    try:
        return _get_confirm_orders_company_kanban_impl(
            order_date=order_date,
            start_date=start_date,
            end_date=end_date,
            order_code=order_code,
            customer=customer,
            unit=unit,
        )
    except Exception:
        frappe.log_error(frappe.get_traceback(), "get_confirm_orders_company_kanban_error")
        return {"companies": [], "unitOptions": _get_confirm_orders_unit_options_list()}



def create_planning_sheet_from_so(doc):
    """
    AUTO-CREATE PLANNING SHEET (QUALITY + GSM LOGIC)
    """
    try:
        existing_sheet = _find_existing_sheet_for_sales_order(doc.name)
        if existing_sheet:
            ps_existing = frappe.get_doc("Planning sheet", existing_sheet["name"])
            if int(ps_existing.docstatus or 0) != 0:
                frappe.msgprint(
                    f"Planning Sheet <b>{ps_existing.name}</b> is submitted — cannot rebuild from Sales Order.",
                    indicator="orange",
                )
                return ps_existing
            _rebuild_planning_sheet_from_sales_order(ps_existing, doc)
            frappe.msgprint(
                f"Planning Sheet <b>{ps_existing.name}</b> re-synced from Sales Order (all processes / BOM children)."
            )
            return ps_existing
            
        # --- GET ACTIVE UNLOCKED PLANS ---
        try:
            active_plans = get_active_plans()
            cc_plan = active_plans.get("color_chart", "Default")
            pb_plan = active_plans.get("production_board", "")
        except Exception:
            cc_plan = "Default"
            pb_plan = ""

        # --- QUALITIES PER UNIT ---
        UNIT_1_MAP = ["PREMIUM", "PLATINUM", "SUPER PLATINUM", "GOLD", "SILVER"]
        UNIT_2_MAP = ["GOLD", "SILVER", "BRONZE", "CLASSIC", "SUPER CLASSIC", "LIFE STYLE",
                      "ECO SPECIAL", "ECO GREEN", "SUPER ECO", "ULTRA", "DELUXE"]
        UNIT_3_MAP = ["PREMIUM", "PLATINUM", "SUPER PLATINUM", "GOLD", "SILVER", "BRONZE"]
        UNIT_4_MAP = ["PREMIUM", "GOLD", "SILVER", "BRONZE", "CLASSIC", "CRT"]

        ps = frappe.new_doc("Planning sheet")
        ps.sales_order = doc.name
        ps.customer = _resolve_customer_link(doc.customer, doc.get("party_code"))
        ps.party_code = doc.get("party_code") or doc.customer
        ps.ordered_date = doc.transaction_date 
        ps.custom_planned_date = doc.delivery_date
        ps.dod = doc.delivery_date
        ps.planning_status = "Draft"
        ps.custom_plan_name = _get_contextual_plan_name(cc_plan, doc.transaction_date)
        ps.custom_pb_plan_name = pb_plan

        _populate_planning_sheet_items(ps, doc)
        ensure_lamination_booking_for_planning_sheet(ps)
        update_sheet_plan_codes(ps, include_legacy=True)
        if not ps.get("quality"):
            ps.quality = "Standard"
        ps.flags.ignore_permissions = True
        ps.insert()
        frappe.db.commit()
        final_doc = _rebuild_planning_sheet_from_sales_order(ps, doc)
        frappe.msgprint(
            f"Planning Sheet <b>{final_doc.name}</b> created and synchronized (255/108 BOM children, all processes)."
        )
        return final_doc

    except Exception as e:
        frappe.log_error("Planning Sheet Creation Failed: " + str(e))
        frappe.msgprint("ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¹ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ Planning Sheet failed. Check 'Error Log' for details.")

@frappe.whitelist()
def create_production_plan_from_sheet(sheet_name):
    """
    Creates a Production Plan from a Planning Sheet.
    If the sheet already has a linked Production Plan (header or row), returns it ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â no duplicate PP.
    """
    if not sheet_name:
        return
    sheet = frappe.get_doc("Planning sheet", sheet_name)

    existing = _resolve_existing_production_plan_for_planning_sheet(sheet_name)
    if existing:
        return existing

    pp = frappe.new_doc("Production Plan")
    pp.company = frappe.defaults.get_user_default("Company")
    pp.customer = sheet.customer
    pp.get_items_from = "Material Request" 
    
    for item in sheet.items:
        row = pp.append("po_items", {})
        row.item_code = item.item_code
        row.qty = item.qty
        row.warehouse = item.warehouse if hasattr(item, 'warehouse') else ""
        if hasattr(item, 'sales_order_item'):
             row.sales_order_item = item.sales_order_item
             
    pp.insert()

    if frappe.db.has_column("Production Plan", "custom_planning_sheet"):
        frappe.db.set_value("Production Plan", pp.name, "custom_planning_sheet", sheet.name)
    elif frappe.db.has_column("Production Plan", "planning_sheet"):
        frappe.db.set_value("Production Plan", pp.name, "planning_sheet", sheet.name)

    # Persist PP link at sheet header (legacy) and item-level (source of truth for row actions)
    if frappe.db.has_column("Planning sheet", "custom_production_plan"):
        frappe.db.set_value("Planning sheet", sheet.name, "custom_production_plan", pp.name)
    elif frappe.db.has_column("Planning sheet", "production_plan"):
        frappe.db.set_value("Planning sheet", sheet.name, "production_plan", pp.name)

    psi_pp_field = _psi_production_plan_field()
    psi_order_sheet_field = _psi_order_sheet_field()
    if psi_pp_field or psi_order_sheet_field:
        for item in sheet.items:
            if psi_pp_field:
                frappe.db.set_value("Planning Table", item.name, psi_pp_field, pp.name)
            if psi_order_sheet_field and psi_order_sheet_field != psi_pp_field:
                frappe.db.set_value("Planning Table", item.name, psi_order_sheet_field, pp.name)
    
    # Update Status to Planned
    if sheet.sales_order:
        frappe.db.set_value("Sales Order", sheet.sales_order, "custom_production_status", "Planned")
        
    return pp.name

@frappe.whitelist()
def create_production_plan_bulk(sheets):
    """
    Creates Production Plans for multiple Planning Sheets at once.
    """
    import json
    if isinstance(sheets, str):
        sheets = json.loads(sheets)
    
    if not sheets: return
    
    created_plans = []
    
    # Optional: Group by Customer? 
    # Usually Production Plans are per Customer or Per SO.
    # If we select multiple sheets from different customers, we probably want separate Production Plans?
    # Or one big Production Plan?
    # Standard ERPNext Production Plan can take multiple Sales Orders / Material Requests.
    # But here we are mapping from Planning Sheet -> Production Plan.
    # Let's create ONE Production Plan per Planning Sheet for simplicity and traceability (1:1 mapping),
    # unless user requested merging.
    # The prompt doesn't specify merging.
    # "Create Plan: Button to convert selected/viewed confirmed orders into a production plan."
    # If 10 orders are visible, and I click "Create Plan", maybe I want 10 plans?
    # OR 1 plan with 10 items?
    # 1 Plan with 10 items is better for "Batching".
    # BUT if customers are different, we can't make 1 Plan (usually).
    # ERPNext Production Plan has `customer` field. If filled, restricts to that customer.
    # If empty, can handle multiple?
    # Let's try to group by Customer.
    
    # 1. Fetch all sheets
    sheet_docs = [frappe.get_doc("Planning sheet", s) for s in sheets]
    
    # 2. Group by Customer
    sheets_by_customer = {}
    for s in sheet_docs:
        cust = s.customer or "No Customer"
        if cust not in sheets_by_customer:
            sheets_by_customer[cust] = []
        sheets_by_customer[cust].append(s)
        
    # 3. Create Plans
    for cust, cust_sheets in sheets_by_customer.items():
        existing_pps = [
            _resolve_existing_production_plan_for_planning_sheet(s.name) for s in cust_sheets
        ]
        non_null = [p for p in existing_pps if p]
        if non_null:
            unique = set(non_null)
            if len(unique) > 1:
                frappe.throw(
                    _(
                        "These planning sheets are already linked to different Production Plans ({0}). "
                        "Cancel duplicate plans in Manufacturing or unlink sheets before creating a new merged plan."
                    ).format(", ".join(sorted(unique)))
                )
            only_pp = list(unique)[0]
            if len(non_null) == len(cust_sheets):
                # Every sheet in this batch already points at the same PP ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â do not create another.
                created_plans.append(only_pp)
                continue
            frappe.throw(
                _(
                    "Some planning sheets already have Production Plan {0}; others do not. "
                    "Link all rows first or create plans one sheet at a time."
                ).format(only_pp)
            )

        pp = frappe.new_doc("Production Plan")
        pp.company = frappe.defaults.get_user_default("Company")
        pp.customer = cust if cust != "No Customer" else None
        pp.get_items_from = "Material Request" # Dummy, we fill manually
        
        # Add Reference Sales Orders?
        # Production Plan has table `sales_orders`.
        seen_so = set()
        for s in cust_sheets:
            if s.sales_order and s.sales_order not in seen_so:
                pp.append("sales_orders", {
                    "sales_order": s.sales_order,
                    "sales_order_date": s.creation # approximation
                })
                seen_so.add(s.sales_order)
        
        # Add Items
        for s in cust_sheets:
            for item in s.items:
                row = pp.append("po_items", {})
                row.item_code = item.item_code
                row.qty = item.qty
                # row.warehouse = ... default?
                if hasattr(item, 'sales_order_item'):
                     row.sales_order_item = item.sales_order_item
            
            # Update Status of Schema
            if s.sales_order:
                frappe.db.set_value("Sales Order", s.sales_order, "custom_production_status", "Planned")
        
        pp.insert()

        if len(cust_sheets) == 1:
            s0 = cust_sheets[0]
            if frappe.db.has_column("Production Plan", "custom_planning_sheet"):
                frappe.db.set_value("Production Plan", pp.name, "custom_planning_sheet", s0.name)
            elif frappe.db.has_column("Production Plan", "planning_sheet"):
                frappe.db.set_value("Production Plan", pp.name, "planning_sheet", s0.name)

        # Persist PP link at item-level for exact row-to-PP mapping
        psi_pp_field = _psi_production_plan_field()
        psi_order_sheet_field = _psi_order_sheet_field()
        for s in cust_sheets:
            if frappe.db.has_column("Planning sheet", "custom_production_plan"):
                frappe.db.set_value("Planning sheet", s.name, "custom_production_plan", pp.name)
            elif frappe.db.has_column("Planning sheet", "production_plan"):
                frappe.db.set_value("Planning sheet", s.name, "production_plan", pp.name)

            if psi_pp_field or psi_order_sheet_field:
                for item in s.items:
                    if psi_pp_field:
                        frappe.db.set_value("Planning Table", item.name, psi_pp_field, pp.name)
                    if psi_order_sheet_field and psi_order_sheet_field != psi_pp_field:
                        frappe.db.set_value("Planning Table", item.name, psi_order_sheet_field, pp.name)

        created_plans.append(pp.name)
        
    return created_plans


@frappe.whitelist()
def audit_production_plans_for_planning_sheet(planning_sheet_name):
    """
    Read-only helper: list Production Plan documents tied to a Planning sheet.
    Use after repeated "Create Plan" clicks to see duplicates before cancelling extras in Manufacturing.
    """
    if not planning_sheet_name:
        return {"ok": False, "message": "planning_sheet_name required"}
    if not frappe.db.exists("Planning sheet", planning_sheet_name):
        return {"ok": False, "message": "Planning sheet not found"}

    resolved = _resolve_existing_production_plan_for_planning_sheet(planning_sheet_name)
    by_link = []
    for col in ("custom_planning_sheet", "planning_sheet"):
        if frappe.db.has_column("Production Plan", col):
            by_link.extend(
                frappe.get_all(
                    "Production Plan",
                    filters={col: planning_sheet_name},
                    fields=["name", "docstatus", "status", "creation"],
                    order_by="creation asc",
                )
            )

    header_pp = None
    for col in ("custom_production_plan", "production_plan"):
        if frappe.db.has_column("Planning sheet", col):
            header_pp = frappe.db.get_value("Planning sheet", planning_sheet_name, col)
            break

    return {
        "ok": True,
        "planning_sheet": planning_sheet_name,
        "reuse_would_return": resolved,
        "header_production_plan": header_pp,
        "production_plans_with_reverse_link": by_link,
    }


@frappe.whitelist()
def create_planning_sheets_bulk(sales_orders):
    """
    Creates Planning Sheets for selected Sales Orders.
    Uses GSM usage logic (Unit 1>50, etc) to auto-allocate items.
    """
    import json
    if isinstance(sales_orders, str):
        sales_orders = json.loads(sales_orders)
        
    created = []
    errors = []
    
    # GSM/Quality Maps (Helper)
    # Re-defining here or using global
    
    for so_name in sales_orders:
        try:
            # Strict singleton: never create another sheet unless existing one is deleted.
            if _find_existing_sheet_for_sales_order(so_name):
                continue
                
            doc = frappe.get_doc("Sales Order", so_name)
            
            ps = frappe.new_doc("Planning sheet")
            ps.sales_order = doc.name
            ps.party_code = doc.get("party_code") or doc.customer
            ps.customer = _resolve_customer_link(doc.customer, doc.get("party_code"))
            ps.dod = doc.delivery_date
            ps.ordered_date = doc.transaction_date
            ps.planning_status = "Draft"
            
            _populate_planning_sheet_items(ps, doc)
            update_sheet_plan_codes(ps, include_legacy=True)
            if not ps.get("quality"):
                ps.quality = "Standard"
            ps.insert(ignore_permissions=True)
            frappe.db.commit()
            _rebuild_planning_sheet_from_sales_order(ps, doc)
            created.append(ps.name)
            
        except Exception as e:
            frappe.log_error(f"Failed to create plan for {so_name}: {str(e)}")
            errors.append(so_name)
            
            
    return {"created": created, "errors": errors}


@frappe.whitelist()
def save_color_order(order):
    """Save custom color order global default."""
    if isinstance(order, str):
        try:
            import json
            order = json.loads(order)
        except:
            pass
    if not isinstance(order, list):
        return
    frappe.defaults.set_global_default("production_color_order", frappe.as_json(order))
    return "saved"

@frappe.whitelist()
def get_color_order():
    """Get custom color order global default."""
    try:
        order_str = frappe.defaults.get_global_default("production_color_order")
        if order_str:
            try:
                import json
                return json.loads(order_str)
            except Exception:
                return []
        return []
    except Exception:
        frappe.log_error(frappe.get_traceback(), "get_color_order_error")
        return []

@frappe.whitelist()
def update_sequence(items):
    """
    Updates the idx of items for manual reordering.
    Expects items = [{name: 'ITEM-ID', idx: 1}, ...]
    Uses SQL to bypass potential Framework overhead/re-indexing logic.
    """
    import json
    if isinstance(items, str):
        items = json.loads(items)
        
    # Batch update? No, simple loop is fine for < 50 items usually.
    for i in items:
        frappe.db.sql("UPDATE `tabPlanning Table` SET idx=%s WHERE name=%s", (i["idx"], i["name"]))
        
    frappe.db.commit() # Ensure committed immediately 
    return "ok"


