@frappe.whitelist()
def test_quality_extraction():
    """
    Test and verify that quality code extraction is working correctly.
    Can be called from console: frappe.call({method: 'production_entry.production_planning.scheduler_api.test_quality_extraction'})
    
    Tests:
    1. Quality Master structure and available fields
    2. Quality code extraction from 16-digit item codes
    3. Existing Planning Sheet items for quality population
    4. Manual extraction logic verification
    """
    import json
    
    results = {
        "status": "pending",
        "timestamp": frappe.utils.now(),
        "tests": [],
        "warnings": [],
        "errors": []
    }
    
    try:
        # TEST 1: Quality Master Count & Structure
        qm_count = frappe.db.count("Quality Master")
        results["tests"].append({
            "name": "Quality Master Count",
            "value": qm_count,
            "status": "PASS" if qm_count > 0 else "FAIL"
        })
        
        if qm_count == 0:
            results["warnings"].append("No Quality Masters found - quality extraction will have nothing to lookup")
        
        # TEST 2: Sample Quality Masters with codes
        qm_sample = frappe.db.sql("""
            SELECT name, short_code, code, quality_code
            FROM `tabQuality Master`
            LIMIT 3
        """, as_dict=True)
        
        results["tests"].append({
            "name": "Quality Master Samples",
            "samples": qm_sample,
            "status": "PASS"
        })
        
        # TEST 3: Manual extraction test (simulate _populate_planning_sheet_items logic)
        test_cases = [
            {"code": "1001165421501865", "q_code": "116", "c_code": "542", "desc": "Standard 16-digit format"},
            {"code": "1001035041001600", "q_code": "103", "c_code": "504", "desc": "Another standard format"},
        ]
        
        extraction_tests = []
        for tc in test_cases:
            item_code_str = str(tc["code"]).strip()
            if len(item_code_str) >= 9:
                q_code = item_code_str[3:6]
                c_code = item_code_str[6:9]
                
                # Lookup quality
                qual_name = None
                lookup_field = None
                for field in ["short_code", "code", "quality_code"]:
                    try:
                        result = frappe.db.get_value("Quality Master", {field: q_code}, "name")
                        if result:
                            qual_name = result
                            lookup_field = field
                            break
                    except:
                        pass
                
                extraction_tests.append({
                    "item_code": tc["code"],
                    "expected_q_code": tc["q_code"],
                    "extracted_q_code": q_code,
                    "q_code_match": q_code == tc["q_code"],
                    "expected_c_code": tc["c_code"],
                    "extracted_c_code": c_code,
                    "c_code_match": c_code == tc["c_code"],
                    "quality_found": qual_name or "NOT FOUND",
                    "lookup_field": lookup_field,
                    "status": "PASS" if (q_code == tc["q_code"] and c_code == tc["c_code"]) else "FAIL"
                })
        
        results["tests"].append({
            "name": "Quality Code Extraction Logic",
            "test_cases": extraction_tests,
            "status": "PASS" if all(t["status"] == "PASS" for t in extraction_tests) else "PARTIAL"
        })
        
        # TEST 4: Planning Sheet Item Population Status
        psi_total = frappe.db.count("Planning Table", {"docstatus": ["<", 2]})
        psi_with_qual = frappe.db.count("Planning Table", {"docstatus": ["<", 2], "custom_quality": ["!=", ""]})
        psi_without_qual = psi_total - psi_with_qual
        
        pct_populated = round((psi_with_qual / psi_total * 100) if psi_total > 0 else 0, 2)
        
        results["tests"].append({
            "name": "Planning Sheet Item Quality Population",
            "total_items": psi_total,
            "with_quality": psi_with_qual,
            "without_quality": psi_without_qual,
            "percentage_populated": pct_populated,
            "status": "PASS" if pct_populated > 0 or psi_total == 0 else "INFO"
        })
        
        # TEST 5: Sample PSI items with quality populated
        if psi_with_qual > 0:
            psi_samples = frappe.db.sql("""
                SELECT name, item_code, custom_quality, parent, unit, qty
                FROM `tabPlanning Table`
                WHERE docstatus < 2 AND custom_quality IS NOT NULL AND custom_quality != ''
                ORDER BY creation DESC
                LIMIT 5
            """, as_dict=True)
            
            results["tests"].append({
                "name": "Sample PSI Items with Populated Quality",
                "samples": psi_samples,
                "status": "PASS"
            })
        
        # TEST 6: Verify implementation function exists
        try:
            from production_entry.production_planning.scheduler_api import _populate_planning_sheet_items, _get_color_by_code
            results["tests"].append({
                "name": "Implementation Functions",
                "functions": ["_populate_planning_sheet_items", "_get_color_by_code"],
                "status": "PASS"
            })
        except Exception as e:
            results["tests"].append({
                "name": "Implementation Functions",
                "error": str(e),
                "status": "FAIL"
            })
            results["errors"].append(f"Could not import functions: {e}")
        
        # Overall status
        failed_tests = [t for t in results["tests"] if t.get("status") == "FAIL"]
        results["status"] = "FAIL" if failed_tests else "PASS"
        
        frappe.msgprint(f"<pre>{json.dumps(results, indent=2, default=str)}</pre>", 
                       title="Quality Extraction Test Results",
                       indicator="red" if failed_tests else "green")
        
        return results
        
    except Exception as e:
        results["status"] = "ERROR"
        results["errors"].append(str(e))
        import traceback as tb
        results["traceback"] = tb.format_exc()
        return results


@frappe.whitelist()
def create_item_spr(pp_id, planning_sheet_item_names, num_rolls=None, process_type=None):

    """
    Create a Shaft Production Run (SPR) for a Production Plan.
    Fetches shaft details from the Production Plan's shaft_details table.
    
    Args:
        pp_id: Production Plan ID
        planning_sheet_item_names: JSON list of Planning Sheet Item names to include
        num_rolls: Optional number of rolls created (stored on SPR as custom_no_of_rolls_created)
        process_type: Optional hint for process type ("sheet_cutting", "rewinding", "bopp_film")
    
    Returns: SPR name or error message
    """
    enforce_board_write(request_board_slug("production-board"))
    if isinstance(planning_sheet_item_names, str):
        planning_sheet_item_names = json.loads(planning_sheet_item_names)
    
    if not pp_id or not planning_sheet_item_names:
        return {"status": "error", "message": "PP ID and item names required"}
    
    if not frappe.db.exists("Production Plan", pp_id):
        return {"status": "error", "message": f"Production Plan {pp_id} not found"}
    
    try:
        def _ensure_spr_links_on_planning_rows(spr_nm, psi_names_list, link_pp_id=None):
            """Append SPR to Planning Table row (comma-separated); never overwrite prior runs."""
            try:
                if not spr_nm or not psi_names_list:
                    return
                if not frappe.db.has_column("Planning Table", "spr_name"):
                    return
                link_pp_id = str(link_pp_id or pp_id or "").strip()
                os_field = _psi_order_sheet_field()
                for pname in psi_names_list:
                    if not frappe.db.exists("Planning Table", pname):
                        continue
                    if link_pp_id and os_field:
                        row_pp = _row_order_sheet_pp(row_name=pname)
                        if row_pp and row_pp != link_pp_id:
                            continue
                        if not row_pp:
                            frappe.db.set_value(
                                "Planning Table", pname, os_field, link_pp_id, update_modified=False
                            )
                    cur = str(frappe.db.get_value("Planning Table", pname, "spr_name") or "").strip()
                    parts = []
                    seen_local = set()
                    for segment in cur.replace(";", ",").split(","):
                        x = segment.strip()
                        if not x or x in seen_local:
                            continue
                        if link_pp_id and not _spr_belongs_to_pp(x, link_pp_id):
                            continue
                        seen_local.add(x)
                        parts.append(x)
                    if spr_nm not in seen_local:
                        parts.append(spr_nm)
                    frappe.db.set_value("Planning Table", pname, "spr_name", ", ".join(parts))
            except Exception:
                pass

        def _spr_names_ordered_from_psi_rows(rows):
            out = []
            seen = set()
            for psi in rows or []:
                raw = str((psi.get("spr_name") or "")).strip()
                for segment in raw.replace(";", ",").split(","):
                    sn = segment.strip()
                    if sn and sn not in seen:
                        seen.add(sn)
                        out.append(sn)
            return out

        def _pp_allows_additional_spr(current_pp_id, rows):
            """False when every WO on this PP (matching item codes, else all) is terminal."""
            terminal = {"completed", "stopped", "stoped", "closed"}
            codes = {
                str((r.get("item_code") or "")).strip()
                for r in (rows or [])
                if str((r.get("item_code") or "")).strip()
            }
            wos = (
                frappe.get_all(
                    "Work Order",
                    filters={"production_plan": current_pp_id, "docstatus": ["<", 2]},
                    fields=["name", "status", "production_item"],
                )
                or []
            )
            relevant = [wo for wo in wos if str((wo.get("production_item") or "")).strip() in codes]
            check_list = relevant if relevant else wos
            if not check_list:
                return True
            for wo in check_list:
                if str((wo.get("status") or "")).strip().lower() not in terminal:
                    return True
            return False

        def _hydrate_existing_spr(existing_spr_name, current_pp_id):
            """Fill missing shaft job / bundle fields on reused draft SPR from PP."""
            if not existing_spr_name or not frappe.db.exists("Shaft Production Run", existing_spr_name):
                return

            spr_doc = frappe.get_doc("Shaft Production Run", existing_spr_name)
            if cint(getattr(spr_doc, "custom_is_sheet_cutting", 0)) or cint(getattr(spr_doc, "custom_is_box_bag", 0)):
                from production_entry.production_planning.doctype.shaft_production_run.shaft_production_run import (
                    populate_spr_bundle_calculation_from_pp,
                )

                populate_spr_bundle_calculation_from_pp(
                    spr_doc,
                    current_pp_id,
                    spr_doc.get("custom_order_code"),
                    0,
                )
                if spr_doc.get("bundle_calculation"):
                    spr_doc.save(ignore_permissions=True)
                return

            payload = get_spr_shaft_jobs_from_pp(current_pp_id)
            if not payload or payload.get("status") != "ok":
                return

            jobs = payload.get("jobs") or []
            if not jobs:
                return

            spr_doc = frappe.get_doc("Shaft Production Run", existing_spr_name)
            rows = list(spr_doc.get("shaft_jobs") or [])
            changed = False

            def _set_if_blank(row, keys, value):
                nonlocal changed
                if value in (None, ""):
                    return
                for k in keys:
                    if hasattr(row, k):
                        cur = row.get(k)
                        if cur in (None, "", 0, 0.0):
                            row.set(k, value)
                            changed = True

            # If no rows exist yet, create rows directly from jobs.
            if not rows:
                for i, job in enumerate(jobs, start=1):
                    row = spr_doc.append("shaft_jobs", {})
                    row.job_id = job.get("job_id") or str(i)
                    row.gsm = job.get("gsm") or ""
                    row.combination = job.get("combination") or ""
                    row.total_width = flt(job.get("total_width") or 0)
                    row.meter_roll_mtrs = flt(job.get("meter_roll_mtrs") or 0)
                    row.no_of_shafts = cint(job.get("no_of_shafts") or 0)
                    row.net_weight = job.get("net_weight") or job.get("net_weight_shaft_kgs") or ""
                    row.net_weight_shaft_kgs = row.net_weight
                    row.total_weight = flt(job.get("total_weight") or job.get("total_weight_kgs") or 0)
                    row.total_weight_kgs = row.total_weight
                    row.order_code = job.get("order_code") or ""
                    row.work_orders = job.get("work_orders") or ""
                    row.custom_label = job.get("custom_label") or ""
                changed = True
            else:
                for idx, row in enumerate(rows):
                    job = jobs[idx] if idx < len(jobs) else jobs[-1]
                    _set_if_blank(row, ["net_weight", "net_weight_shaft_kgs", "net_weight_shaft", "custom_net_weight_shaft_kgs"], job.get("net_weight") or job.get("net_weight_shaft_kgs"))
                    _set_if_blank(row, ["total_weight", "total_weight_kgs", "custom_total_weight_kgs"], flt(job.get("total_weight") or job.get("total_weight_kgs") or 0))
                    _set_if_blank(row, ["order_code", "custom_order_code"], job.get("order_code") or "")
                    _set_if_blank(row, ["work_orders", "work_order", "wo_no"], job.get("work_orders") or "")
                    _set_if_blank(row, ["combination", "shaft", "shaft_details"], job.get("combination") or "")
                    _set_if_blank(row, ["meter_roll_mtrs", "roll_mtrs", "meter_roll", "roll"], flt(job.get("meter_roll_mtrs") or 0))
                    _set_if_blank(row, ["no_of_shafts", "no_of_shaft", "no_of_sh", "no_of_sf"], cint(job.get("no_of_shafts") or 0))
                    _set_if_blank(row, ["custom_label", "label"], job.get("custom_label") or "")
                    _set_if_blank(row, ["custom_label", "label"], job.get("custom_label") or "")

            if changed:
                spr_doc.save(ignore_permissions=True)

        pp = frappe.get_doc("Production Plan", pp_id)

        psi_list = []
        for psi_name in planning_sheet_item_names:
            if frappe.db.exists("Planning Table", psi_name):
                psi_list.append(frappe.get_doc("Planning Table", psi_name))

        if not psi_list:
            return {"status": "error", "message": "No valid Planning Sheet Items found"}

        ordered_linked_sprs = _spr_names_ordered_from_psi_rows(psi_list)
        draft_reuse_spr = ""
        for sn in ordered_linked_sprs:
            if frappe.db.exists("Shaft Production Run", sn):
                if cint(frappe.db.get_value("Shaft Production Run", sn, "docstatus") or 0) == 0:
                    draft_reuse_spr = sn
                    break

        if draft_reuse_spr:
            _hydrate_existing_spr(draft_reuse_spr, pp_id)
            _ensure_spr_links_on_planning_rows(draft_reuse_spr, planning_sheet_item_names)
            frappe.db.commit()
            return {
                "status": "ok",
                "spr_id": draft_reuse_spr,
                "message": f"Continuing draft SPR {draft_reuse_spr}",
                "reused": 1,
            }

        if ordered_linked_sprs and not _pp_allows_additional_spr(pp_id, psi_list):
            return {
                "status": "error",
                "message": _("Cannot create a new SPR: Work Order is Completed, Stopped, or Closed for this Production Plan."),
            }

        is_slitting_from_rows = any(_item_process_prefix(str((psi.get("item_code") or "")).strip()) == "103" for psi in (psi_list or []))

        def _collect_child_pp_ids_for_slitting(rows):
            """Resolve child fabric PP IDs using trace-id first, then SO-item fallback."""
            pp_ids = set()
            pp_fields = _psi_production_plan_fields()
            has_trace_col = frappe.db.has_column("Planning Table", "custom_parent_child_trace_id")
            has_so_item_col = frappe.db.has_column("Planning Table", "sales_order_item")
            has_custom_so_item_col = frappe.db.has_column("Planning Table", "custom_sales_order_item")
            for row in rows or []:
                parent_sheet = str(row.get("parent") or "").strip()
                if not parent_sheet:
                    continue
                parent_trace = str(row.get("custom_parent_child_trace_id") or "").strip()
                if not parent_trace:
                    parent_trace = _parent_child_trace_id_from_item_code(row.get("item_code"))
                so_item = str(row.get("sales_order_item") or row.get("custom_sales_order_item") or "").strip()

                where_parts = ["parent = %s", "item_code LIKE '100%%'"]
                params = [parent_sheet]
                if parent_trace and has_trace_col:
                    where_parts.append("IFNULL(custom_parent_child_trace_id, '') = %s")
                    params.append(parent_trace)
                elif so_item and (has_so_item_col or has_custom_so_item_col):
                    so_parts = []
                    if has_so_item_col:
                        so_parts.append("IFNULL(sales_order_item, '') = %s")
                        params.append(so_item)
                    if has_custom_so_item_col:
                        so_parts.append("IFNULL(custom_sales_order_item, '') = %s")
                        params.append(so_item)
                    where_parts.append("(" + " OR ".join(so_parts) + ")")

                select_cols = ["name"] + pp_fields
                child_rows = frappe.db.sql(
                    f"SELECT {', '.join(select_cols)} FROM `tabPlanning Table` WHERE " + " AND ".join(where_parts),
                    tuple(params),
                    as_dict=True,
                )
                for ch in child_rows or []:
                    child_pp = ""
                    for pf in pp_fields:
                        v = str(ch.get(pf) or "").strip()
                        if v:
                            child_pp = v
                            break
                    if not child_pp:
                        child_pp = str(_get_item_level_production_plan(ch.get("name")) or "").strip()
                    if not child_pp and so_item:
                        child_pp = str(_resolve_pp_by_sales_order_item(so_item) or "").strip()
                    if child_pp:
                        pp_ids.add(child_pp)
            return pp_ids

        # Hard lock for slitting parent SPR: allow only after child WO reaches terminal state.
        if is_slitting_from_rows:
            # IMPORTANT: lock must be based on child fabric WOs only (not parent PP WOs).
            candidate_pps = _collect_child_pp_ids_for_slitting(psi_list)
            wo_rows = []
            if candidate_pps:
                wo_rows = frappe.get_all(
                    "Work Order",
                    filters={"production_plan": ["in", list(candidate_pps)], "docstatus": ["<", 2]},
                    fields=["name", "status", "docstatus", "production_plan"],
                    order_by="creation asc",
                )
            terminal_statuses = {"completed", "stopped", "stoped", "closed"}
            wo_open = False
            open_wo = ""
            for wo in wo_rows or []:
                st = str((wo.get("status") or "")).strip().lower()
                ds = cint(wo.get("docstatus") or 0)
                if ds == 2:
                    continue
                if st not in terminal_statuses:
                    wo_open = True
                    open_wo = str(wo.get("name") or "").strip()
                    break
            if wo_rows and wo_open:
                return {
                    "status": "error",
                    "message": f"Cannot create Slitting SPR until child WO is Completed/Stopped/Closed. Open WO: {open_wo}",
                }

        # Create SPR (second+ run for same PP/WO/planning row when prior SPRs are submitted)
        spr = frappe.new_doc("Shaft Production Run")
        spr.run_date = frappe.utils.today()
        spr.shift = get_current_shift()
        spr.is_mix_roll = 0
        spr.status = "Draft"
        spr.production_plan = pp_id
        # Auto-tick process checkboxes based on item codes in PSI rows.
        spr_meta = frappe.get_meta("Shaft Production Run")
        is_lamination_from_rows = any(
            _is_lamination_parent_process(str((psi.get("item_code") or "")).strip()) for psi in (psi_list or [])
        )
        is_rewinding_from_rows = any(
            _item_process_prefix(str((psi.get("item_code") or "")).strip()) == "102" for psi in (psi_list or [])
        )
        is_sheet_cutting_from_rows = any(
            _is_sheet_cutting_parent_process(str((psi.get("item_code") or "")).strip()) for psi in (psi_list or [])
        )
        is_printing_from_rows = any(
            _item_process_prefix(str((psi.get("item_code") or "")).strip()) in ("105", "106") for psi in (psi_list or [])
        )
        is_box_bag_from_rows = any(
            _item_process_prefix(str((psi.get("item_code") or "")).strip()) in ALL_BAG_FG_PROCESS_CODES
            for psi in (psi_list or [])
        )
        # BOPP Film = Printed BOPP items with PB- prefix (NOT 107 which is Lamination Unit like 104)
        is_bopp_film_from_rows = (
            any(str((psi.get("item_code") or "")).strip().upper().startswith("PB") for psi in (psi_list or []))
            or str(process_type or "").strip().lower() == "bopp_film"
        )
        if str(process_type or "").strip().lower() == "printing_105":
            is_printing_from_rows = True
        if is_lamination_from_rows and spr_meta.has_field("custom_is_lamination"):
            spr.custom_is_lamination = 1
        if is_slitting_from_rows and spr_meta.has_field("custom_is_slitting"):
            spr.custom_is_slitting = 1
        if is_rewinding_from_rows and spr_meta.has_field("custom_is_rewinding"):
            spr.custom_is_rewinding = 1
        if is_sheet_cutting_from_rows and spr_meta.has_field("custom_is_sheet_cutting"):
            spr.custom_is_sheet_cutting = 1
        if is_bopp_film_from_rows and spr_meta.has_field("custom_is_bopp_film"):
            spr.custom_is_bopp_film = 1
        if is_printing_from_rows and spr_meta.has_field("custom_is_printing"):
            spr.custom_is_printing = 1
        if is_box_bag_from_rows and spr_meta.has_field("custom_is_box_bag"):
            spr.custom_is_box_bag = 1
        
        # Extract order code and customer from first item's parent sheet and PP
        first_psi = psi_list[0]
        parent_sheet = frappe.get_doc("Planning sheet", first_psi.parent)
        
        spr.custom_order_code = parent_sheet.party_code or ""
        spr.customer = pp.customer or parent_sheet.customer or ""
        spr_unit = ""
        for unit_candidate in [first_psi.get("unit"), pp.get("custom_unit"), pp.get("workstation"), pp.get("custom_workstation")]:
            normalized_unit = normalize_planning_unit_for_select(unit_candidate)
            if normalized_unit and normalized_unit != "UNASSIGNED":
                spr_unit = normalized_unit
                break
        if spr_unit and spr_meta.has_field("custom_unit"):
            spr.custom_unit = spr_unit

        if (
            str(process_type or "").strip().lower() == "sheet_cutting"
            or spr_unit == "JVE - SHEET CUTTING MACHINE"
        ):
            is_sheet_cutting_from_rows = True
            if spr_meta.has_field("custom_is_sheet_cutting"):
                spr.custom_is_sheet_cutting = 1

        from production_entry.production_planning.doctype.shaft_production_run.shaft_production_run import (
            _production_plan_total_planned_qty,
            populate_spr_bundle_calculation_from_pp,
            resolve_label_from_planning_sheet_doc,
            resolve_label_from_pp_doc,
        )

        label_value = resolve_label_from_pp_doc(pp) or resolve_label_from_planning_sheet_doc(parent_sheet)
        if label_value:
            spr.custom_label = label_value

        frappe.logger().info(f"[create_item_spr] Set custom_label={label_value or ''} for PP {pp_id}")
        
        def pick_value(source, keys, default=None):
            for k in keys:
                v = source.get(k)
                if v not in (None, ""):
                    return v
            return default

        # Fetch shaft details from Production Plan (not from Planning Sheet Items)
        # Copy shaft details from PP to SPR
        pp_shafts = pp.get("custom_shaft_details") or pp.get("shaft_details") or []

        # Fetch linked Work Orders for this PP
        pp_work_orders = frappe.get_all("Work Order",
            filters={"production_plan": pp_id, "docstatus": ["<", 2]},
            fields=["name", "production_item", "qty", "produced_qty", "status"],
            order_by="creation asc"
        )
        wo_names_str = ", ".join([wo.name for wo in pp_work_orders]) if pp_work_orders else ""
        wo_total_qty = sum(flt(wo.qty) for wo in pp_work_orders)

        # Set custom_total_planned_qty from Work Orders; if WOs are missing/zero, use PP / PP-items (same as desk).
        if wo_total_qty > 0:
            spr.custom_total_planned_qty = wo_total_qty
            frappe.logger().info(f"[create_item_spr] Set custom_total_planned_qty={wo_total_qty} from WO sum for PP {pp_id}")
        else:
            pq = _production_plan_total_planned_qty(pp_id)
            if pq > 0:
                spr.custom_total_planned_qty = pq
                frappe.logger().info(f"[create_item_spr] Set custom_total_planned_qty={pq} from PP fallback for {pp_id}")

        # PP-level fallback values - try all possible field name variations
        # Standard PP fields + custom_ prefix variants
        pp_net_weight = (
            pp.get("custom_net_weight") or pp.get("net_weight") or
            pp.get("custom_net_weight_kgs") or pp.get("net_weight_kgs") or
            pp.get("custom_weight_per_roll") or pp.get("weight_per_roll") or ""
        )
        pp_total_weight = flt(
            pp.get("custom_total_weight_kgs") or pp.get("total_weight_kgs") or
            pp.get("custom_total_weight") or pp.get("total_weight") or
            pp.get("total_planned_qty") or pp.get("custom_total_planned_qty") or 0
        )
        pp_no_of_shaft = cint(
            pp.get("custom_no_of_shaft") or pp.get("no_of_shaft") or
            pp.get("custom_no_of_shafts") or pp.get("no_of_shafts") or 0
        )
        pp_combined_width = (
            pp.get("custom_combined_width") or pp.get("combined_width") or
            pp.get("custom_total_width") or pp.get("total_width") or ""
        )

        # Log PP-level values for debugging
        frappe.log_error(
            f"PP {pp_id} level values: net_weight={pp_net_weight}, total_weight={pp_total_weight}, "
            f"no_of_shaft={pp_no_of_shaft}, combined_width={pp_combined_width}",
            "SPR_DEBUG_PP_LEVEL"
        )
        # Also try standard PP FINISHED GOODS table (po_items) for enrichment
        pp_po_items = pp.get("po_items") or []
        po_item_data = {}
        for poi in pp_po_items:
            # Build a lookup by index for width/weight enrichment
            idx = cint(poi.get("idx") or 0)
            po_item_data[idx] = poi

        if is_sheet_cutting_from_rows or is_box_bag_from_rows:
            order_m = flt(
                pick_value(first_psi, ["meter", "mtr", "planned_length", "custom_meter"], 0) or 0
            )
            populate_spr_bundle_calculation_from_pp(
                spr, pp_id, spr.custom_order_code, order_m
            )
        elif pp_shafts:
            for idx, pp_shaft in enumerate(pp_shafts, start=1):
                matching_poi = po_item_data.get(idx, {})
                row = spr.append("shaft_jobs", {})
                row.job_id = pick_value(pp_shaft, ["job_id", "job", "job_no"], str(len(spr.shaft_jobs)))
                row.gsm = pick_value(pp_shaft, ["gsm"], "")
                row.combination = pick_value(pp_shaft, ["combination", "combined_width", "shaft", "shaft_details"], "") or pp_combined_width
                
                raw_width = flt(pick_value(pp_shaft, ["total_width", "combined_width", "width", "total_width_inches"], 0) or 0)
                if not raw_width and matching_poi:
                    raw_width = flt(pick_value(matching_poi, ["total_width", "width", "width_inches"], 0) or 0)
                if not raw_width:
                    raw_width = flt(pp_combined_width or 0)
                row.total_width = raw_width

                # Prefer PP shaft meter__roll; fall back to matching po_item, then PP-level fields before defaulting
                meter_keys = ["meter__roll", "meter_roll_mtrs", "meter_per_roll", "meter_roll", "roll_mtrs", "custom_meter_roll_mtrs", "custom_meter_per_roll", "custom_meterperroll", "meter_per_roll_mtrs", "roll", "meter", "length_per_roll", "length_roll", "length"]
                raw_meter = flt(pick_value(pp_shaft, meter_keys, 0))
                if not raw_meter and matching_poi:
                    raw_meter = flt(pick_value(matching_poi, meter_keys, 0))
                if not raw_meter:
                    raw_meter = flt(pp.get("meter__roll") or pp.get("custom_meter_roll_mtrs") or pp.get("meter_roll_mtrs") or pp.get("custom_meter_per_roll") or pp.get("custom_meterperroll") or pp.get("meter_per_roll") or pp.get("custom_meter") or pp.get("meter") or pp.get("length_per_roll") or pp.get("length_roll") or pp.get("length") or 500)
                row.meter_roll_mtrs = raw_meter
                row.no_of_shafts = cint(pick_value(pp_shaft, ["no_of_shafts", "no_of_shaft", "no_of_sh", "no_of_sf"], 0) or 0) or pp_no_of_shaft or 1
                
                # Field names confirmed by user: net_weight, total_width (SPR)
                _nw = pick_value(pp_shaft, ["net_weight_shaft_kgs", "net_weight_shaft", "net_weight"], "") or pp_net_weight
                row.net_weight = _nw
                row.net_weight_shaft_kgs = _nw # keep legacy for safety
                row.net_weight_shaft = _nw
                row.custom_net_weight_shaft_kgs = _nw
                
                _tw = flt(pick_value(pp_shaft, ["total_weight_kgs", "total_weight", "weight"], 0) or 0) or pp_total_weight
                row.total_weight_kgs = _tw
                row.total_weight = _tw # try without _kgs variant too
                row.custom_total_weight_kgs = _tw
                row.order_code = pick_value(pp_shaft, ["order_code", "party_code", "custom_order_code"], parent_sheet.party_code or "")
                row.custom_order_code = row.order_code
                row.work_orders = pick_value(pp_shaft, ["work_orders", "work_order", "wo", "wo_no"], "") or wo_names_str
                row.work_order = row.work_orders
                # Compute total_weight from WO qty if still zero
                if not flt(row.total_weight_kgs) and wo_total_qty:
                    row.total_weight_kgs = flt(wo_total_qty)
                    row.total_weight = row.total_weight_kgs
                    row.custom_total_weight_kgs = row.total_weight_kgs
                row.quality = first_psi.custom_quality or first_psi.get("quality") or ""
                row.color = first_psi.color or ""
                row.party_code = parent_sheet.party_code or ""
                row.custom_label = pick_value(pp_shaft, ["custom_label", "label"], label_value or "")
        elif not pp_shafts and not is_sheet_cutting_from_rows:
            # Fallback: create one shaft job from PSI data if PP has no shaft_details
            for i, psi in enumerate(psi_list):
                row = spr.append("shaft_jobs", {})
                row.job_id = str(i + 1)
                row.quality = psi.custom_quality or psi.get("quality") or ""
                row.color = psi.color or ""
                row.party_code = parent_sheet.party_code or ""
                row.gsm = psi.gsm or ""
                row.custom_label = label_value or ""
                
                # Get width info from PSI
                width = flt(psi.get("width") or psi.get("custom_width") or psi.get("width_inch") or 0)
                if width:
                    row.combination = str(int(width))
                    row.total_width = width
                else:
                    row.combination = "Standard"
                    row.total_width = 0
                
                row.no_of_shafts = 1
                meter_keys = ["meter__roll", "meter_roll_mtrs", "meter_per_roll", "meter_roll", "roll_mtrs", "custom_meter_roll_mtrs", "custom_meter_per_roll", "custom_meterperroll", "meter_per_roll_mtrs", "roll", "meter", "length_per_roll", "length_roll", "length", "planned_length"]
                raw_meter = flt(pick_value(psi, meter_keys, 0))
                if not raw_meter and pp_po_items:
                    for poi in pp_po_items:
                        if poi.get("item_code") == psi.get("item_code"):
                            raw_meter = flt(pick_value(poi, meter_keys, 0))
                            break
                if not raw_meter and pp_po_items:
                    raw_meter = flt(pick_value(pp_po_items[0], meter_keys, 0))
                if not raw_meter:
                    raw_meter = flt(pp.get("meter__roll") or pp.get("custom_meter_roll_mtrs") or pp.get("meter_roll_mtrs") or pp.get("custom_meter_per_roll") or pp.get("custom_meterperroll") or pp.get("meter_per_roll") or pp.get("custom_meter") or pp.get("meter") or pp.get("length_per_roll") or pp.get("length_roll") or pp.get("length") or 500)
                
                row.meter_roll_mtrs = raw_meter
        
        # Store selected Planning Sheet Item names for reference
        if psi_list:
            psi_names_str = ", ".join([psi.name for psi in psi_list])
            if spr.shaft_jobs:
                spr.shaft_jobs[0].manual_items = psi_names_str
        
        # Store no. of rolls if provided and field exists on SPR
        if num_rolls and cint(num_rolls) > 0:
            if frappe.get_meta("Shaft Production Run").has_field("custom_no_of_rolls_created"):
                spr.custom_no_of_rolls_created = cint(num_rolls)

        # Debug log before insert
        frappe.log_error(f"""
        About to insert SPR:
        - Name will be auto-generated
        - production_plan: {spr.production_plan}
        - customer: {spr.customer}
        - custom_order_code: {spr.custom_order_code}
        - shaft_jobs count: {len(spr.shaft_jobs or [])}
        - status: {spr.status}
        """, "create_item_spr_pre_insert")
        
        try:
            spr.insert(ignore_permissions=True)
        except Exception as insert_error:
            error_msg = str(insert_error)
            # Try to extract validation message
            if "Production Plan is required" in error_msg:
                return {
                    "status": "error", 
                    "message": f"SPR validation error: {error_msg}. Check that Production Plan {pp_id} exists."
                }
            frappe.log_error(frappe.get_traceback(), "create_item_spr_insert")
            return {"status": "error", "message": f"Failed to create SPR: {error_msg}"}
        
        # Link SPR back to Production Plan ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â append to existing value instead of overwriting
        existing_spr_link = str(frappe.db.get_value("Production Plan", pp_id, "custom_shaft_production_run_id") or "").strip()
        if spr.name not in existing_spr_link:
            new_link = f"{existing_spr_link}, {spr.name}".strip(", ") if existing_spr_link else spr.name
            frappe.db.set_value("Production Plan", pp_id, "custom_shaft_production_run_id", new_link)
        _ensure_spr_links_on_planning_rows(spr.name, planning_sheet_item_names)
        try:
            sync_spr_planning_table_links(spr.name)
        except Exception:
            frappe.log_error(frappe.get_traceback(), f"create_item_spr planning link:{spr.name}")
        
        frappe.db.commit()
        
        return {
            "status": "ok",
            "spr_id": spr.name,
            "message": f"SPR Created: {spr.name}"
        }
        
    except Exception as e:
        frappe.log_error(frappe.get_traceback(), "create_item_spr")
        return {"status": "error", "message": f"Unexpected error: {str(e)}"}


@frappe.whitelist()
def get_spr_shaft_jobs_from_pp(pp_id):
    """Return normalized shaft jobs from a Production Plan for SPR form auto-fill."""
    pp_id = str(pp_id or "").strip()
    if not pp_id:
        return {"status": "error", "message": "Production Plan is required", "jobs": []}

    if not frappe.db.exists("Production Plan", pp_id):
        return {
            "status": "error",
            "message": f"Production Plan {pp_id} not found",
            "jobs": [],
        }

    try:
        pp = frappe.get_doc("Production Plan", pp_id)
        jobs = []
        shafts = pp.get("custom_shaft_details") or pp.get("shaft_details") or []

        # Fetch linked Work Orders for WO name enrichment
        pp_work_orders = frappe.get_all("Work Order",
            filters={"production_plan": pp_id, "docstatus": ["<", 2]},
            fields=["name", "qty"],
            order_by="creation asc"
        )
        wo_names_str = ", ".join([wo.name for wo in pp_work_orders]) if pp_work_orders else ""
        wo_total_qty = sum(flt(wo.qty) for wo in pp_work_orders)

        def pick_value(source, keys, default=None):
            for k in keys:
                v = source.get(k)
                if v not in (None, ""):
                    return v
            return default

        # PP-level fallback values
        pp_net_weight = (
            pp.get("custom_net_weight") or pp.get("net_weight") or
            pp.get("custom_net_weight_kgs") or pp.get("net_weight_kgs") or
            pp.get("custom_weight_per_roll") or pp.get("weight_per_roll") or ""
        )
        pp_total_weight = flt(
            pp.get("custom_total_weight_kgs") or pp.get("total_weight_kgs") or
            pp.get("custom_total_weight") or pp.get("total_weight") or
            pp.get("total_planned_qty") or pp.get("custom_total_planned_qty") or 0
        )
        pp_no_of_shaft = cint(
            pp.get("custom_no_of_shaft") or pp.get("no_of_shaft") or
            pp.get("custom_no_of_shafts") or pp.get("no_of_shafts") or 0
        )
        pp_combined_width = (
            pp.get("custom_combined_width") or pp.get("combined_width") or
            pp.get("custom_total_width") or pp.get("total_width") or ""
        )

        # Log actual fields for debugging
        if shafts:
            first = shafts[0]
            raw_data = {}
            if hasattr(first, 'as_dict'):
                for k, v in first.as_dict().items():
                    if v not in (None, "", 0, 0.0) and k not in ("name", "owner", "creation", "modified", "modified_by", "doctype", "parent", "parentfield", "parenttype", "docstatus", "idx"):
                        raw_data[k] = str(v)[:200]
            frappe.log_error(f"PP {pp_id} shaft row fields: {json.dumps(raw_data, indent=2)}", "SPR_DEBUG_SHAFT_FIELDS")

        # Also try standard PP FINISHED GOODS table (po_items) for enrichment
        pp_po_items = pp.get("po_items") or []
        po_item_data = {}
        for poi in pp_po_items:
            # Build a lookup by index for width/weight enrichment
            idx = cint(poi.get("idx") or 0)
            po_item_data[idx] = poi

        for idx, pp_shaft in enumerate(shafts, start=1):
            # Get matching po_item for additional data
            matching_poi = po_item_data.get(idx, {})
            
            # For net_weight: try shaft row first, then po_item weight_per_unit/planned_qty
            raw_net_weight = pick_value(pp_shaft, ["net_weight_shaft_kgs", "net_weight_shaft", "net_weight", "weight_per_roll", "weight_roll", "weight"], "") or pp_net_weight
            if not raw_net_weight and matching_poi:
                raw_net_weight = pick_value(matching_poi, ["net_weight", "weight_per_roll", "weight_roll", "stock_qty"], "")

            # For total_weight: try shaft row, then matching po_item planned_qty
            raw_total_weight = flt(pick_value(pp_shaft, ["total_weight_kgs", "total_weight", "weight", "planned_qty"], 0) or 0) or pp_total_weight
            if not flt(raw_total_weight) and matching_poi:
                raw_total_weight = flt(pick_value(matching_poi, ["total_weight_kgs", "planned_qty", "qty", "stock_qty"], 0) or 0)

            # For total_width
            raw_width = flt(pick_value(pp_shaft, ["total_width", "combined_width", "width", "total_width_inches"], 0) or 0)
            if not flt(raw_width) and matching_poi:
                raw_width = flt(pick_value(matching_poi, ["total_width", "width", "width_inches"], 0) or 0)

            # For meter_roll_mtrs
            meter_keys = ["meter__roll", "meter_roll_mtrs", "meter_per_roll", "meter_roll", "roll_mtrs", "custom_meter_roll_mtrs", "custom_meter_per_roll", "custom_meterperroll", "meter_per_roll_mtrs", "roll", "meter", "length_per_roll", "length_roll", "length"]
            raw_meter = flt(pick_value(pp_shaft, meter_keys, 0))
            if not raw_meter and matching_poi:
                raw_meter = flt(pick_value(matching_poi, meter_keys, 0))
            if not raw_meter:
                raw_meter = flt(pp.get("meter__roll") or pp.get("custom_meter_roll_mtrs") or pp.get("meter_roll_mtrs") or pp.get("custom_meter_per_roll") or pp.get("custom_meterperroll") or pp.get("meter_per_roll") or pp.get("custom_meter") or pp.get("meter") or pp.get("length_per_roll") or pp.get("length_roll") or pp.get("length") or 500)

            jobs.append(
                {
                    "job_id": pick_value(pp_shaft, ["job_id", "job", "job_no"], str(idx)),
                    "gsm": pick_value(pp_shaft, ["gsm"], ""),
                    "combination": pick_value(pp_shaft, ["combination", "combined_width", "shaft", "shaft_details"], "") or pp_combined_width,
                    "total_width": raw_width,
                    "meter_roll_mtrs": raw_meter,
                    "no_of_shafts": cint(pick_value(pp_shaft, ["no_of_shafts", "no_of_shaft", "no_of_sh", "no_of_sf"], 0) or 0) or pp_no_of_shaft or 1,
                    "net_weight": raw_net_weight,
                    "net_weight_shaft_kgs": raw_net_weight,
                    "total_weight_kgs": raw_total_weight,
                    "total_weight": raw_total_weight,
                    "order_code": pick_value(pp_shaft, ["order_code", "party_code", "custom_order_code"], pp.get("order_code") or pp.get("custom_order_code") or ""),
                    "work_orders": pick_value(pp_shaft, ["work_orders", "work_order", "wo", "wo_no"], "") or wo_names_str,
                    "custom_label": pick_value(pp_shaft, ["custom_label", "label"], ""),
                }
            )

            # Enrich total_weight from WO qty if shaft row has zero weight
            if not flt(jobs[-1]["total_weight_kgs"]) and wo_total_qty:
                jobs[-1]["total_weight_kgs"] = flt(wo_total_qty)

            # Resolve work_orders from combination + GSM (e.g. 46"+42"+38" ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ three WOs on the PP)
            try:
                from production_entry.production_planning.doctype.shaft_production_run.shaft_production_run import (
                    _resolve_wos_for_pp_job_row,
                )

                jrow = jobs[-1]
                jid = jrow.get("job_id")
                comb = jrow.get("combination") or ""
                ppi = pick_value(pp_shaft, ["production_plan_item", "pp_item"], None) or jid
                job_gsm = None
                gsm_raw = jrow.get("gsm")
                if gsm_raw not in (None, ""):
                    try:
                        job_gsm = int(flt(str(gsm_raw).strip().split()[0]))
                    except Exception:
                        try:
                            job_gsm = int(flt(gsm_raw))
                        except Exception:
                            pass
                ppi_s = str(ppi).strip() if ppi not in (None, "") else None
                jid_s = str(jid).strip() if jid not in (None, "") else None
                ww = _resolve_wos_for_pp_job_row(
                    pp_id,
                    ppi=ppi_s,
                    job_id=jid_s,
                    row_index=idx - 1,
                    combination=comb if comb else None,
                    job_gsm=job_gsm,
                )
                if ww:
                    jrow["work_orders"] = ", ".join(w["name"] for w in ww)
            except Exception:
                pass

        # Build debug info to discover actual field names
        _debug = {
            "shaft_count": len(shafts),
            "pp_level_fields": {},
            "first_shaft_row_all_fields": {},
        }
        # PP-level fields related to weight/shaft
        for attr in dir(pp):
            if any(kw in attr.lower() for kw in ["weight", "shaft", "width", "net", "total", "combined"]):
                val = pp.get(attr)
                if val not in (None, "", 0, 0.0, []):
                    _debug["pp_level_fields"][attr] = str(val)[:100]
        # First shaft child row: dump ALL non-empty fields
        if shafts:
            first = shafts[0]
            for attr in (first.as_dict() if hasattr(first, 'as_dict') else {}):
                val = first.get(attr)
                if val not in (None, "", 0, 0.0) and attr not in ("name", "owner", "creation", "modified", "modified_by", "doctype", "parent", "parentfield", "parenttype", "docstatus"):
                    _debug["first_shaft_row_all_fields"][attr] = str(val)[:100]

        return {
            "status": "ok",
            "pp_id": pp_id,
            "jobs": jobs,
            "customer": pp.get("customer") or "",
            "order_code": pp.get("order_code") or pp.get("custom_order_code") or "",
            "_debug": _debug,
        }
    except Exception:
        frappe.log_error(frappe.get_traceback(), "get_spr_shaft_jobs_from_pp")
        return {
            "status": "error",
            "message": "Unable to fetch shaft details from Production Plan",
            "jobs": [],
        }


@frappe.whitelist()
def debug_pp_columns(pp_id):
    """Dump ALL non-empty columns of a PP doc via SQL - to discover actual field names."""
    if not frappe.db.exists("Production Plan", pp_id):
        return {"error": f"PP {pp_id} not found"}

    # Get all column names from tabProduction Plan
    cols = frappe.db.sql("SHOW COLUMNS FROM `tabProduction Plan`", as_dict=True)
    col_names = [c["Field"] for c in cols]

    # Fetch the PP row
    pp_row = frappe.db.sql(
        "SELECT * FROM `tabProduction Plan` WHERE name = %s", pp_id, as_dict=True
    )
    if not pp_row:
        return {"error": "Not found"}

    pp_data = pp_row[0]
    # Return only non-empty values, filter weight/shaft/net/total/width related
    relevant = {}
    all_non_empty = {}
    for k, v in pp_data.items():
        if v not in (None, "", 0, 0.0):
            all_non_empty[k] = str(v)[:100]
            if any(kw in k.lower() for kw in ["weight", "shaft", "net", "total", "width", "combined"]):
                relevant[k] = str(v)[:100]

    # Also check child table
    child_table_info = {}
    try:
        child_cols = frappe.db.sql("SHOW COLUMNS FROM `tabProduction Plan Item`", as_dict=True)
        child_col_names = [c["Field"] for c in child_cols if any(kw in c["Field"].lower() for kw in ["weight", "shaft", "net", "total", "width", "combined", "qty"])]
        child_table_info["columns"] = child_col_names
    except Exception:
        pass

    # PP custom_shaft_details child table
    shaft_child = frappe.db.sql(
        """SELECT * FROM `tabProduction Plan Item`
           WHERE parent = %s ORDER BY idx LIMIT 1""",
        pp_id, as_dict=True
    )
    shaft_row_data = {}
    if shaft_child:
        for k, v in shaft_child[0].items():
            if v not in (None, "", 0, 0.0) and k not in ("name", "owner", "creation", "modified", "modified_by", "parent", "parentfield", "parenttype", "docstatus"):
                shaft_row_data[k] = str(v)[:100]

    return {
        "pp_relevant_fields": relevant,
        "po_item_first_row_non_empty": shaft_row_data,
        "child_table_weight_cols": child_table_info,
    }


# ============================================================================
# PRODUCTION MERGE APIs
# ============================================================================

def _get_item_merge_key(item_name):
    """Get order_code + quality + color key for merge validation."""
    try:
        item = frappe.db.get_value(
            "Planning Table",
            item_name,
            ["custom_quality", "color", "parent"],
            as_dict=True
        )
        if not item:
            return None
        
        ps = frappe.db.get_value("Planning sheet", item.get("parent"), "party_code")
        quality = (item.get("custom_quality") or "").strip()
        color = (item.get("color") or "").strip()
        
        return f"{ps}||{quality}||{color}"
    except Exception:
        return None


def _validate_merge_items(item_names):
    """Validate that all items have same order_code + quality + color."""
    if not item_names or len(item_names) < 2:
        return True, "At least 2 items required to merge"
    
    keys = []
    for item_name in item_names:
        key = _get_item_merge_key(item_name)
        if not key:
            return False, f"Item {item_name} not found or invalid"
        keys.append(key)
    
    # All keys must be identical
    if len(set(keys)) != 1:
        return False, "All items must have same Order Code + Quality + Color to merge"
    
    return True, "Valid"


def _get_merge_row_name(merged_items):
    """Generate a safe row name from merged items."""
    import hashlib
    items_str = ",".join(sorted(merged_items))
    hash_suffix = hashlib.md5(items_str.encode()).hexdigest()[:6]
    return f"MERGE_{hash_suffix}"


@frappe.whitelist()
def create_merge(date, unit, plan_name, item_names, merge_label=None):
    """Create a new Production Merge record."""
    enforce_board_write(request_board_slug("production-board"), unit=unit, date=date)
    if isinstance(item_names, str):
        import json
        item_names = json.loads(item_names)
    
    if not isinstance(item_names, list):
        frappe.throw("item_names must be a list or JSON array")
    
    # Validate merge constraints
    valid, msg = _validate_merge_items(item_names)
    if not valid:
        frappe.throw(msg)

    # Capacity check: merged target weight must not exceed unit hard limit
    hard_limit_tons = HARD_LIMITS.get(unit)
    if hard_limit_tons:
        fmt = ','.join(['%s'] * len(item_names))
        total_kg = frappe.db.sql(f"""
            SELECT SUM(IFNULL(qty, 0))
            FROM `tabPlanning Table`
            WHERE name IN ({fmt})
        """, tuple(item_names))[0][0] or 0
        if flt(total_kg) > flt(hard_limit_tons) * 1000:
            frappe.throw("Selected merge weight {0} Kg exceeds {1} capacity {2} Kg".format(
                flt(total_kg),
                unit,
                flt(hard_limit_tons) * 1000
            ))
    
    # Check for overlap with existing merges
    existing_merges = frappe.db.sql("""
        SELECT name, merged_items
        FROM `tabProduction Merge`
        WHERE date = %s AND unit = %s AND plan_name = %s AND status = 'Active'
    """, (date, unit, plan_name), as_dict=True)
    
    for merge in existing_merges:
        import json
        existing_items = json.loads(merge.get("merged_items") or "[]")
        overlap = set(item_names) & set(existing_items)
        if overlap:
            frappe.throw("Items already in another merge: {}".format(", ".join(overlap)))
    
    # Create new merge record.
    # NOTE: The DocType autoname expression can collide for same unit/date,
    # so we provide our own unique name and retry safely.
    import json
    from frappe.exceptions import DuplicateEntryError

    base_name = f"PMRG-{str(unit).replace(' ', '')}-{str(date)}"
    last_error = None
    for attempt_idx in range(5):
        unique_name = f"{base_name}-{frappe.generate_hash(length=6)}"
        merge_doc = frappe.new_doc("Production Merge")
        merge_doc.name = unique_name
        merge_doc.flags.name_set = True
        merge_doc.plan_name = plan_name
        merge_doc.date = date
        merge_doc.unit = unit
        merge_doc.merge_label = merge_label or _get_merge_row_name(item_names)
        merge_doc.status = "Active"
        merge_doc.merged_items = json.dumps(item_names)
        try:
            merge_doc.insert(ignore_permissions=True, set_name=unique_name)
            return {"status": "success", "merge_id": merge_doc.name}
        except DuplicateEntryError as e:
            last_error = e
            continue

    if last_error:
        frappe.throw("Unable to create merge due to repeated duplicate name collision. Please try again.")

    frappe.throw("Unable to create merge")


@frappe.whitelist()
def update_merge(merge_id, merge_label=None, status=None):
    """Update merge label or status."""
    if not frappe.db.exists("Production Merge", merge_id):
        frappe.throw(_("Merge record not found"))
    
    merge_doc = frappe.get_doc("Production Merge", merge_id)
    
    if merge_label:
        merge_doc.merge_label = merge_label
    
    if status and status in ["Active", "Inactive"]:
        merge_doc.status = status
    
    merge_doc.save()
    return {"status": "success"}


@frappe.whitelist()
def delete_merge(merge_id):
    """Delete a merge record and revert items to original positions."""
    enforce_board_write(request_board_slug("production-board"))
    if not frappe.db.exists("Production Merge", merge_id):
        frappe.throw(_("Merge record not found"))

    merge_doc = frappe.get_doc("Production Merge", merge_id)
    import json
    merged_items = json.loads(merge_doc.merged_items or "[]")

    if merged_items:
        fmt = ','.join(['%s'] * len(merged_items))
        dispatched = frappe.db.sql(f"""
            SELECT DISTINCT COALESCE(so.delivery_status, 'Not Delivered') as delivery_status
            FROM `tabPlanning Table` i
            JOIN `tabPlanning sheet` p ON i.parent = p.name
            LEFT JOIN `tabSales Order` so ON p.sales_order = so.name
            WHERE i.name IN ({fmt})
        """, tuple(merged_items), as_dict=True)

        locked = any((r.get("delivery_status") or "") in ["Partly Delivered", "Fully Delivered"] for r in dispatched)
        if locked:
            frappe.throw("Cannot unmerge: one or more merged items are already dispatched.")
    
    frappe.delete_doc("Production Merge", merge_id)
    return {"status": "success"}


@frappe.whitelist()
def get_merges_for_date(date, unit=None, plan_name=None):
    """Fetch all active merges for a specific date/unit/plan."""
    enforce_board_read(
        request_board_slug("production-board"),
        unit=unit,
        date=date,
    )
    filters = ["date = %s", "status = 'Active'"]
    params = [date]
    
    if unit:
        filters.append("unit = %s")
        params.append(unit)
    
    if plan_name:
        filters.append("plan_name = %s")
        params.append(plan_name)
    
    where_clause = " AND ".join(filters)
    
    merges = frappe.db.sql(f"""
        SELECT name, unit, plan_name, date, merge_label, status, merged_items
        FROM `tabProduction Merge`
        WHERE {where_clause}
        ORDER BY creation ASC
    """, tuple(params), as_dict=True)
    
    # Parse merged_items JSON for each merge
    import json
    for merge in merges:
        try:
            merge["merged_items"] = json.loads(merge.get("merged_items") or "[]")
        except:
            merge["merged_items"] = []
    
    return merges


@frappe.whitelist()
def sync_merge_planned_date(merge_id, new_date):
    """Sync planned_date change from merged row back to all items in merge."""
    if not frappe.db.exists("Production Merge", merge_id):
        frappe.throw(_("Merge record not found"))
    
    merge_doc = frappe.get_doc("Production Merge", merge_id)
    
    import json
    merged_items = json.loads(merge_doc.merged_items or "[]")
    
    if not merged_items:
        return {"status": "success", "updated": 0}
    
    # Update each item's planned_date if the column exists
    updated_count = 0
    if frappe.db.has_column("Planning Table", "custom_planned_date"):
        for item_name in merged_items:
            frappe.db.set_value("Planning Table", item_name, "custom_planned_date", new_date)
            updated_count += 1
    
    return {"status": "success", "updated": updated_count}


# Mid-chain bag BOM rows that may stay in Meter until **Meter to Kgs** (not 100 / PB).
BAG_METER_TO_KG_CONVERT_PROCESSES = ("103", "104", "105", "106", "107", "108", "109", "110")
# Legacy alias (avoid using for meter conversion — includes 100).
BAG_BOM_METER_CHILD_PROCESSES = BAG_METER_TO_KG_CONVERT_PROCESSES + ("100",)

# Parents whose Planning Table qty drives BOM child Kg on the same SO line (103→100, 104→100, …).
_BOM_KG_PARENT_PROCESSES = frozenset(
	{
		"102",
		"103",
		"104",
		"105",
		"106",
		"107",
		"108",
		"109",
		"110",
		"221",
		"222",
		"223",
		"224",
		"225",
		"226",
		"231",
		"232",
		"233",
		"241",
		"242",
		"251",
	}
)


_SLITTING_LOOP_FABRIC_PROCESSES = frozenset({"103", "108", "109", "110"})
_MAIN_FABRIC_MID_PROCESSES = frozenset({"104", "105", "106", "107"})
_BASE_FABRIC_PARENT_PROCESSES = frozenset({"102", "103", "104", "105", "106", "107"})


def _fabric_parent_process_from_item_code(item_code):
	"""Embedded parent in legacy fabric codes (e.g. 100105… → 105)."""
	ic = _cstr(item_code).strip()
	if not ic.startswith("100") or len(ic) < 6:
		return ""
	cand = ic[3:6]
	if cand in _BASE_FABRIC_PARENT_PROCESSES:
		return cand
	return ""


def _planning_sheet_so_fg_process_codes(planning_sheet_name):
	"""Process codes on Sales Order lines linked to this planning sheet."""
	so_name = frappe.db.get_value("Planning sheet", planning_sheet_name, "sales_order")
	if not so_name:
		return frozenset()
	procs = set()
	for it in frappe.get_all(
		"Sales Order Item", filters={"parent": so_name}, fields=["item_code"], limit_page_length=0
	) or []:
		pp = _bom_item_process_code(it.get("item_code")) or _item_process_prefix(it.get("item_code"))
		if pp:
			procs.add(pp)
	return frozenset(procs)


def _is_bag_fg_item_code(item_code):
	"""True when item_code is a box / W-CUT / D-CUT finished-good bag process."""
	if _is_standalone_printing_fg_item_code(item_code):
		return False
	pp = _bom_item_process_code(item_code) or _item_process_prefix(item_code)
	return pp in ALL_BAG_FG_PROCESS_CODES


def _loop_parent_for_107_item(ic_107, soi, pt_rows, direct_by_soi):
	"""When this 107 row is the BOM child of loop 108/110 on the same SO line, return 108 or 110."""
	ic_107 = _cstr(ic_107).strip()
	soi = _cstr(soi).strip()
	if not ic_107 or not pt_rows:
		return ""
	for loop_pp in ("108", "110"):
		for prow in pt_rows:
			row_soi = _cstr(prow.get("sales_order_item") or prow.get("so_item")).strip()
			if soi and row_soi and row_soi != soi:
				continue
			pic = _cstr(prow.get("item_code")).strip()
			if not _planning_row_is_bag_fg_direct_bom_child(pic, soi, direct_by_soi):
				continue
			pp = _bom_item_process_code(pic) or _item_process_prefix(pic)
			if pp != loop_pp:
				continue
			try:
				res = _get_bom_child_item_from_process_item(pic, loop_pp, "107", "Loop parent fabric")
				if _cstr(res.get("child_item_code")).strip() == ic_107:
					return loop_pp
			except Exception:
				continue
	return ""


def _loop_fabric_process_on_soi(soi, pt_rows, direct_by_soi):
	"""Loop handle (103/108/110) that is a direct FG BOM child on this SO line."""
	soi = _cstr(soi).strip()
	for loop_pp in ("108", "110", "103"):
		for prow in pt_rows or []:
			row_soi = _cstr(prow.get("sales_order_item") or prow.get("so_item")).strip()
			if soi and row_soi and row_soi != soi:
				continue
			pic = _cstr(prow.get("item_code")).strip()
			if not _planning_row_is_bag_fg_direct_bom_child(pic, soi, direct_by_soi):
				continue
			pp = _bom_item_process_code(pic) or _item_process_prefix(pic)
			if pp == loop_pp:
				return loop_pp
	return ""


def _has_107_on_soi(soi, pt_rows):
	soi = _cstr(soi).strip()
	for prow in pt_rows or []:
		row_soi = _cstr(prow.get("sales_order_item") or prow.get("so_item")).strip()
		if soi and row_soi and row_soi != soi:
			continue
		pic = _cstr(prow.get("item_code")).strip()
		if _lamination_process_from_item_code(pic) == "107" or _item_process_prefix(pic) == "107":
			return True
	return False


def _fabric_chain_parent_item_for_child(fabric_ic, soi, pt_rows, parent_pp):
	"""Planning-row item_code of the mid-chain parent (107 / 104 / 103 …) for a 100* fabric."""
	fabric_ic = _cstr(fabric_ic).strip()
	parent_pp = _cstr(parent_pp).strip()
	soi = _cstr(soi).strip()
	if not fabric_ic.startswith("100") or not parent_pp or not pt_rows:
		return ""
	for prow in pt_rows:
		pic = _cstr(prow.get("item_code")).strip()
		row_soi = _cstr(prow.get("sales_order_item") or prow.get("so_item")).strip()
		if soi and row_soi and row_soi != soi:
			continue
		if parent_pp == "104":
			if _lamination_process_from_item_code(pic) != "104":
				continue
		elif _item_process_prefix(pic) != parent_pp and _lamination_process_from_item_code(pic) != parent_pp:
			continue
		try:
			res = _get_fabric_item_from_process_item(pic, expected_process=parent_pp, process_label="Parent fabric")
			if _cstr(res.get("fabric_item_code")).strip() == fabric_ic:
				return pic
		except Exception:
			continue
	return ""


def _107_parent_item_for_planning_child(child_ic, soi, pt_rows):
	"""Which 107 row on this SO line owns the given 100* or PB child (via 107 BOM)."""
	child_ic = _cstr(child_ic).strip()
	soi = _cstr(soi).strip()
	if not child_ic or not pt_rows:
		return ""
	for prow in pt_rows:
		pic = _cstr(prow.get("item_code")).strip()
		row_soi = _cstr(prow.get("sales_order_item") or prow.get("so_item")).strip()
		if soi and row_soi and row_soi != soi:
			continue
		if _lamination_process_from_item_code(pic) != "107" and _item_process_prefix(pic) != "107":
			continue
		try:
			if child_ic.startswith("100"):
				res = _get_fabric_item_from_process_item(pic, expected_process="107", process_label="Parent fabric")
				if _cstr(res.get("fabric_item_code")).strip() == child_ic:
					return pic
			elif _is_printed_bopp_item_code(child_ic):
				res107 = _resolve_107_child_components(pic)
				pb = res107.get("pb")
				if pb and _cstr(pb[0]).strip() == child_ic:
					return pic
		except Exception:
			continue
	return ""


def _bag_fabric_100_on_loop_chain(chain_parent_pp, parent_ic, soi, pt_rows, direct_by_soi):
	"""True when this 100* row belongs to loop slitting / BOPP loop (103 / 108→107 …), not main chain."""
	cp = _cstr(chain_parent_pp).strip()
	if cp in _SLITTING_LOOP_FABRIC_PROCESSES and cp != "109":
		return True
	if cp == "107" and parent_ic:
		return bool(_loop_parent_for_107_item(parent_ic, soi, pt_rows, direct_by_soi))
	return False


def _bag_fabric_100_parent_fabric_label(chain_parent_pp, parent_ic, soi, pt_rows, direct_by_soi, bag_fg_context):
	"""Bag 100* rows: loop chain → Loop {pp} Base Fabric; main chain → Main {pp} Base Fabric."""
	if not bag_fg_context:
		cp = _cstr(chain_parent_pp).strip()
		return f"{cp} Base Fabric" if cp else "100 Base Fabric"
	if _bag_fabric_100_on_loop_chain(chain_parent_pp, parent_ic, soi, pt_rows, direct_by_soi):
		return _chain_child_parent_fabric_label(
			parent_ic, chain_parent_pp, soi, pt_rows, direct_by_soi, bag_fg_context, pb=False
		)
	cp = _cstr(chain_parent_pp).strip()
	if cp:
		return _chain_child_parent_fabric_label(
			parent_ic, cp, soi, pt_rows, direct_by_soi, bag_fg_context, pb=False
		)
	return "Main 100 Base Fabric"


def _bag_main_mid_process_parent_fabric_label(ic, pp, soi, pt_rows, direct_on_fg_bom):
	"""
	Bag main-chain mid processes (104/105/106/107):
	- Direct FG BOM child → Main Fabric
	- Chained child (e.g. 104 under 106 on 203) → Main {immediate_parent} Base Fabric
	"""
	if direct_on_fg_bom:
		return "Main Fabric"
	imm_pp = _immediate_parent_process_for_planning_child(ic, soi, pt_rows)
	if imm_pp:
		if imm_pp in _SLITTING_LOOP_FABRIC_PROCESSES and imm_pp != "109":
			return "Loop Fabric"
		return f"Main {imm_pp} Base Fabric"
	return f"{pp} Base Fabric"


def _chain_child_parent_fabric_label(parent_ic, parent_pp, soi, pt_rows, direct_by_soi, bag_fg_context, pb=False):
	"""Main / Loop label for 100* or PB rows under a mid-chain parent (107 / 104 / 103 …)."""
	parent_pp = _cstr(parent_pp).strip()
	if not bag_fg_context:
		return f"{parent_pp} PB" if pb else f"{parent_pp} Base Fabric"
	if parent_pp == "107":
		if parent_ic and _planning_row_is_bag_fg_direct_bom_child(parent_ic, soi, direct_by_soi):
			return "Main 107 PB" if pb else "Main 107 Base Fabric"
		if parent_ic and _loop_parent_for_107_item(parent_ic, soi, pt_rows, direct_by_soi):
			return "Loop 107 PB" if pb else "Loop 107 Base Fabric"
		return "Main 107 PB" if pb else "Main 107 Base Fabric"
	if parent_pp in _SLITTING_LOOP_FABRIC_PROCESSES and parent_pp != "109":
		return f"Loop {parent_pp} PB" if pb else f"Loop {parent_pp} Base Fabric"
	return f"Main {parent_pp} PB" if pb else f"Main {parent_pp} Base Fabric"


def _resolve_parent_fabric_label(
	item_code,
	so_fg_item_code=None,
	direct_on_fg_bom=False,
	chain_parent_process=None,
	soi=None,
	pt_rows=None,
	direct_by_soi=None,
	bag_fg_context=None,
	is_direct_so_line=False,
):
	"""Human-friendly BOM role — Main vs Loop chains for all bag FG processes (221–226, 231/232/233/241/242, W/D-CUT)."""
	ic = _cstr(item_code).strip()
	if not ic:
		return ""
	pp = _bom_item_process_code(ic) or _item_process_prefix(ic)
	fg_pp = _bom_item_process_code(so_fg_item_code) if so_fg_item_code else ""
	if bag_fg_context is None:
		bag_fg_context = _is_bag_fg_item_code(so_fg_item_code)

	fg_pp_label = _bom_item_process_code(so_fg_item_code) if so_fg_item_code else ""
	if not fg_pp_label and so_fg_item_code:
		fg_pp_label = _item_process_prefix(so_fg_item_code)

	# 232 screen-printed box bag: FG 232 → 231 RM → 107 main / 103 loop → 100 / PB.
	if bag_fg_context and fg_pp_label == "232":
		if pp == "232" or (fg_pp_label and pp == fg_pp_label):
			return "Bag FG"
		if pp == "231":
			return "232 RM Bag"
		if pp in _SLITTING_LOOP_FABRIC_PROCESSES and pp != "109":
			return "231 Loop Fabric"
		if pp == "107" or _lamination_process_from_item_code(ic) == "107":
			return "231 Main Fabric"
		if ic.startswith("100"):
			cp = _cstr(chain_parent_process).strip() or _infer_fabric_chain_parent_process(ic, soi, pt_rows)
			if not cp:
				cp = _fabric_parent_process_from_item_code(ic)
			if cp:
				parent_ic = _fabric_chain_parent_item_for_child(ic, soi, pt_rows, cp) if pt_rows else ""
				return _bag_fabric_100_parent_fabric_label(
					cp, parent_ic, soi, pt_rows, direct_by_soi, bag_fg_context
				)
		if _is_printed_bopp_item_code(ic):
			parent_107 = _107_parent_item_for_planning_child(ic, soi, pt_rows)
			if parent_107:
				return _chain_child_parent_fabric_label(
					parent_107, "107", soi, pt_rows, direct_by_soi, bag_fg_context, pb=True
				)
			return "Main 107 PB"

	if is_direct_so_line:
		if pp in ALL_BAG_FG_PROCESS_CODES or _is_bag_fg_item_code(ic):
			return "Bag FG"
		if _is_sheet_cutting_fg_item_code(ic):
			return "FG Sheet"
		return "FG Fabric"

	if not bag_fg_context and not is_direct_so_line:
		nb_early = _non_bag_parent_fabric_label(
			ic, soi, pt_rows, pb=_is_printed_bopp_item_code(ic)
		)
		if nb_early:
			return nb_early

	if _is_printed_bopp_item_code(ic):
		if direct_on_fg_bom:
			return "PB"
		if bag_fg_context:
			parent_107 = _107_parent_item_for_planning_child(ic, soi, pt_rows)
			if parent_107:
				return _chain_child_parent_fabric_label(
					parent_107, "107", soi, pt_rows, direct_by_soi, bag_fg_context, pb=True
				)
			return "Loop 107 PB"
		nb = _non_bag_parent_fabric_label(ic, soi, pt_rows, pb=True)
		return nb or "PB"

	if fg_pp and pp == fg_pp:
		if fg_pp in ALL_BAG_FG_PROCESS_CODES:
			return "Bag FG"
		return "FG Fabric"

	if ic.startswith("100"):
		if bag_fg_context and direct_on_fg_bom:
			return "Main 100 Base Fabric"
		cp = _cstr(chain_parent_process).strip() or _infer_fabric_chain_parent_process(ic, soi, pt_rows)
		if not cp:
			cp = _fabric_parent_process_from_item_code(ic)
		if cp:
			parent_ic = _fabric_chain_parent_item_for_child(ic, soi, pt_rows, cp) if pt_rows else ""
			if bag_fg_context:
				return _bag_fabric_100_parent_fabric_label(
					cp, parent_ic, soi, pt_rows, direct_by_soi, bag_fg_context
				)
			return f"{cp} Base Fabric"
		nb = _non_bag_parent_fabric_label(ic, soi, pt_rows)
		if nb:
			return nb
		cp_fb = _fabric_parent_process_from_item_code(ic)
		return f"Main {cp_fb} Base Fabric" if cp_fb else "100 Base Fabric"

	if direct_on_fg_bom and bag_fg_context:
		if pp in _SLITTING_LOOP_FABRIC_PROCESSES and pp != "109":
			return "Loop Fabric"
		if pp in _MAIN_FABRIC_MID_PROCESSES:
			return "Main Fabric"
		return ""

	if pp in _SLITTING_LOOP_FABRIC_PROCESSES and pp != "109":
		if bag_fg_context:
			return "Loop Fabric"
		nb = _non_bag_parent_fabric_label(ic, soi, pt_rows)
		return nb or f"{pp} Base Fabric"

	if pp == "107" or _lamination_process_from_item_code(ic) == "107":
		if direct_on_fg_bom:
			return "Main Fabric"
		if bag_fg_context:
			loop_pp = _loop_parent_for_107_item(ic, soi, pt_rows, direct_by_soi)
			if loop_pp:
				return f"Loop {loop_pp} Base Fabric"
			imm_pp = _immediate_parent_process_for_planning_child(ic, soi, pt_rows)
			if imm_pp:
				return f"Main {imm_pp} Base Fabric"
			return "107 Base Fabric"
		nb = _non_bag_parent_fabric_label(ic, soi, pt_rows)
		return nb or "107 Base Fabric"

	if pp in _MAIN_FABRIC_MID_PROCESSES:
		if bag_fg_context:
			return _bag_main_mid_process_parent_fabric_label(ic, pp, soi, pt_rows, direct_on_fg_bom)
		nb = _non_bag_parent_fabric_label(ic, soi, pt_rows)
		return nb or f"{pp} Base Fabric"
	return ""


def _infer_fabric_chain_parent_process(fabric_ic, soi, pt_rows):
	"""Match a 100* row to its mid-chain parent on the same SO line via BOM."""
	fabric_ic = _cstr(fabric_ic).strip()
	soi = _cstr(soi).strip()
	if not fabric_ic.startswith("100") or not pt_rows:
		return ""
	for parent_pp in ("251", "252", "253", "254", "255", "103", "104", "105", "106", "107", "102"):
		for prow in pt_rows:
			pic = _cstr(prow.get("item_code") if isinstance(prow, dict) else getattr(prow, "item_code", "")).strip()
			row_soi = _cstr(
				(prow.get("sales_order_item") or prow.get("so_item"))
				if isinstance(prow, dict)
				else (getattr(prow, "sales_order_item", None) or getattr(prow, "so_item", None))
			).strip()
			if soi and row_soi and row_soi != soi:
				continue
			if parent_pp == "255":
				if _item_process_prefix(pic) != "255" and _lamination_process_from_item_code(pic) != "255":
					continue
			elif parent_pp in ("251", "252", "253", "254"):
				if _item_process_prefix(pic) != parent_pp:
					continue
			elif parent_pp == "104":
				if _lamination_process_from_item_code(pic) != "104":
					continue
			elif _item_process_prefix(pic) != parent_pp:
				continue
			try:
				if parent_pp == "251":
					res = get_fabric_item_from_sheet_cutting_item(pic)
				else:
					res = _get_fabric_item_from_process_item(pic, expected_process=parent_pp, process_label="Parent fabric")
				if _cstr(res.get("fabric_item_code")).strip() == fabric_ic:
					return parent_pp
			except Exception:
				continue
	return _fabric_parent_process_from_item_code(fabric_ic)


def _stamp_parent_fabric_labels_on_planning_sheet(planning_sheet_name):
	"""Set custom_parent_fabric on Planning Table + Planning sheet Item (both grids, always)."""
	from production_entry.production_planning.parent_fabric_options import (
		normalize_parent_fabric_label,
		sync_parent_fabric_field_options_to_db,
	)

	sync_parent_fabric_field_options_to_db()

	if not planning_sheet_name:
		return 0
	if not (
		frappe.db.has_column("Planning Table", "custom_parent_fabric")
		or frappe.db.has_column("Planning sheet Item", "custom_parent_fabric")
	):
		return 0
	pt_rows = frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		fields=["name", "item_code", "sales_order_item", "so_item", "source_item", "custom_parent_fabric"],
		limit_page_length=0,
	) or []
	if not pt_rows:
		return 0
	so_fg_by_soi = {}
	for r in pt_rows:
		soi = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		ic = _cstr(r.get("item_code")).strip()
		pp = _bom_item_process_code(ic) or _item_process_prefix(ic)
		if pp in ALL_BAG_FG_PROCESS_CODES or _lamination_process_from_item_code(ic) in ("255", "254", "253", "252", "251"):
			if soi:
				so_fg_by_soi[soi] = ic
	direct_by_soi = _bag_fg_direct_bom_children_by_soi(planning_sheet_name)
	so_line_ic_by_soi = {}
	so_name = frappe.db.get_value("Planning sheet", planning_sheet_name, "sales_order")
	if so_name:
		for so_row in frappe.get_all(
			"Sales Order Item",
			filters={"parent": so_name},
			fields=["name", "item_code"],
			limit_page_length=0,
		) or []:
			if _is_cylinder_yield_so_item(so_row.get("item_code")):
				continue
			so_line_ic_by_soi[_cstr(so_row.get("name")).strip()] = _cstr(so_row.get("item_code")).strip()

	def _label_for_item(ic, soi, direct=None, chain_pp=None):
		ic = _cstr(ic).strip()
		soi = _cstr(soi).strip()
		if not ic:
			return ""
		if direct is None:
			direct = _planning_row_is_bag_fg_direct_bom_child(ic, soi, direct_by_soi)
		if chain_pp is None and ic.startswith("100") and not direct:
			chain_pp = _infer_fabric_chain_parent_process(ic, soi, pt_rows)
		so_fg = so_fg_by_soi.get(soi) or ""
		if not so_fg and soi:
			pass
		elif not so_fg and len(so_fg_by_soi) == 1:
			so_fg = next(iter(so_fg_by_soi.values()))
		so_direct_ic = so_line_ic_by_soi.get(soi, "")
		is_direct_so_line = bool(so_direct_ic and so_direct_ic == ic)
		bag_ctx = _is_bag_fg_item_code(so_direct_ic) if so_direct_ic else _is_bag_fg_item_code(so_fg)
		so_fg_for_label = so_direct_ic or so_fg
		raw = _resolve_parent_fabric_label(
			ic,
			so_fg_item_code=so_fg_for_label,
			direct_on_fg_bom=direct,
			chain_parent_process=chain_pp,
			soi=soi,
			pt_rows=pt_rows,
			direct_by_soi=direct_by_soi,
			bag_fg_context=bag_ctx,
			is_direct_so_line=is_direct_so_line,
		)
		label = normalize_parent_fabric_label(raw)
		if not label and _is_printed_bopp_item_code(ic):
			label = "PB"
		return label

	labels_by_pt = {}
	labels_by_soi_ic = {}
	for r in pt_rows:
		soi = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		ic = _cstr(r.get("item_code")).strip()
		label = _label_for_item(ic, soi)
		if not label:
			continue
		labels_by_pt[r.get("name")] = label
		labels_by_soi_ic[(soi, ic)] = label

	updated = 0
	if frappe.db.has_column("Planning Table", "custom_parent_fabric"):
		for pt_name, label in labels_by_pt.items():
			frappe.db.set_value("Planning Table", pt_name, "custom_parent_fabric", label, update_modified=False)
			updated += 1

	if not frappe.db.has_column("Planning sheet Item", "custom_parent_fabric"):
		frappe.db.commit()
		return updated

	# Board → legacy items: source_item link, then item_code + SO line match (same as qty sync).
	stamped_psi = set()
	for r in pt_rows:
		label = labels_by_pt.get(r.get("name"))
		if not label:
			continue
		ic = _cstr(r.get("item_code")).strip()
		soi = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		legacy = _cstr(r.get("source_item")).strip()
		target_psi = legacy if legacy and frappe.db.exists("Planning sheet Item", legacy) else ""
		if not target_psi:
			target_psi = _find_legacy_planning_sheet_item_row(planning_sheet_name, ic, soi)
		if not target_psi:
			continue
		frappe.db.set_value("Planning sheet Item", target_psi, "custom_parent_fabric", label, update_modified=False)
		stamped_psi.add(target_psi)
		if (
			frappe.db.has_column("Planning Table", "source_item")
			and legacy != target_psi
		):
			frappe.db.set_value("Planning Table", r.get("name"), "source_item", target_psi, update_modified=False)

	psi_rows = frappe.get_all(
		"Planning sheet Item",
		filters={"parent": planning_sheet_name},
		fields=["name", "item_code", "sales_order_item", "so_item", "custom_parent_fabric"],
		limit_page_length=0,
	) or []
	for psi in psi_rows:
		psi_name = _cstr(psi.get("name")).strip()
		psi_ic = _cstr(psi.get("item_code")).strip()
		psi_soi = _cstr(psi.get("sales_order_item") or psi.get("so_item")).strip()
		label = labels_by_soi_ic.get((psi_soi, psi_ic))
		if not label:
			label = _label_for_item(psi_ic, psi_soi)
		if not label:
			continue
		if label == _cstr(psi.get("custom_parent_fabric")).strip() and psi_name in stamped_psi:
			continue
		frappe.db.set_value("Planning sheet Item", psi_name, "custom_parent_fabric", label, update_modified=False)

	frappe.db.commit()
	return updated


def _meter_qty_to_kg_for_planning_row(item_code, meter_qty, source_item=None, pt_name=None):
	"""Meter → Kg using Item UOM conversion, else weight_per_roll / meter from planning row."""
	meter_qty = flt(meter_qty)
	if meter_qty <= 0 or not item_code:
		return 0
	conv = frappe.db.get_value(
		"UOM Conversion Detail",
		{"parent": item_code, "uom": "Meter"},
		"conversion_factor",
	)
	if conv and flt(conv) > 0:
		return flt(meter_qty) / flt(conv)
	for doctype, row_name in (
		("Planning sheet Item", source_item),
		("Planning Table", pt_name),
	):
		if not row_name or not frappe.db.exists(doctype, row_name):
			continue
		row = frappe.db.get_value(
			doctype,
			row_name,
			["meter", "weight_per_roll", "qty", "uom"],
			as_dict=True,
		) or {}
		m_ref = flt(row.get("meter") or 0)
		w_ref = flt(row.get("weight_per_roll") or 0)
		if m_ref > 0 and w_ref > 0:
			return flt(meter_qty) * w_ref / m_ref
		if _cstr(row.get("uom")).strip() == "Kg" and flt(row.get("qty") or 0) > 0 and m_ref > 0:
			return flt(meter_qty) * flt(row.get("qty")) / m_ref
	return 0


def _bag_fg_direct_bom_children_by_soi(planning_sheet_name):
	"""Per SO line: item codes that are direct children on the bag FG BOM (not 103→100 fabric)."""
	out = {}
	if not planning_sheet_name:
		return out
	rows = frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		fields=["item_code", "sales_order_item", "so_item"],
		limit_page_length=0,
	) or []
	for r in rows:
		fg_ic = _cstr(r.get("item_code")).strip()
		if _bom_item_process_code(fg_ic) not in ALL_BAG_FG_PROCESS_CODES:
			continue
		soi = _cstr(r.get("sales_order_item") or r.get("so_item")).strip()
		if not soi:
			continue
		bom = _resolve_lamination_bom(fg_ic)
		if not bom:
			out[soi] = set()
			continue
		children = set()
		for brow in bom.items or []:
			cic = _cstr(brow.item_code).strip()
			if cic:
				children.add(cic)
		out[soi] = children
	return out


def _planning_row_is_bag_fg_direct_bom_child(item_code, so_item_key, direct_by_soi):
	"""True when this row is a direct FG BOM line (eligible for Meter→Kg on button)."""
	ic = _cstr(item_code).strip()
	if not ic:
		return False
	soi = _cstr(so_item_key).strip()
	if soi and ic in (direct_by_soi or {}).get(soi, set()):
		return True
	# Child rows sometimes lack sales_order_item; match when only one SO line has this BOM child.
	holders = [s for s, ch in (direct_by_soi or {}).items() if ic in ch]
	return len(holders) == 1


def _unit_for_bag_fg_bom_child(child_ic, child_proc, specs=None):
	"""Default production unit for a direct BOM child on bag FG."""
	if _is_printed_bopp_item_code(child_ic):
		return PRINTED_BOPP_FILM_UNIT
	# Process 103 → Unassigned Slitting (same idea as fabric whites → UNASSIGNED).
	if child_proc == "103":
		return SLITTING_UNASSIGNED_UNIT
	if child_proc in ("108", "110"):
		return SLITTING_UNIT
	if child_proc in ("104", "107"):
		return LAMINATION_UNIT
	if child_proc in ("105", "106"):
		return PRINTING_UNASSIGNED_UNIT
	specs = specs or {}
	return compute_default_production_unit(
		specs.get("color") or "",
		flt(specs.get("width_inch") or 0),
		child_ic,
	)


def _bag_fg_bom_child_row_specs(child_ic, child_pp, so_it=None):
	"""Quality / colour / GSM / width for direct BOM children on bag FG (103 / 108 / 110 / 100)."""
	specs = {}
	child_ic = _cstr(child_ic).strip()
	if child_ic.startswith("100"):
		specs = _fabric_row_specs_from_fabric_item(child_ic, so_it, None) or {}
	elif child_pp == "103" and frappe.db.has_column("Planning Table", "width_inch"):
		w103 = flt(_resolve_planning_row_width_inch(child_ic))
		if w103 > 0:
			specs["width_inch"] = w103
	elif child_pp in ("108", "110"):
		parsed = (_parse_110_item_code(child_ic) if child_pp == "110" else _parse_108_item_code(child_ic)) or {}
		q, c, g = resolve_quality_color_gsm_from_item_code(child_ic)
		if q:
			specs["quality"] = q
		if c:
			specs["color"] = c
		if g:
			specs["gsm"] = g
		w_in = flt(parsed.get("width_inch") or 0)
		if w_in <= 0:
			w_in = _decoded_width_inch_for_planning_item(child_ic)
		if w_in > 0:
			specs["width_inch"] = w_in
		for fld, key in (
			("custom_fabric_gsm", "fabric_gsm"),
			("custom_lam_gsm", "lam_gsm"),
			("custom_bopp_gsm", "bopp_gsm"),
		):
			val = cint(parsed.get(key) or 0)
			if val > 0:
				specs[fld] = val
	if not specs.get("quality") or not specs.get("gsm"):
		q, c, g = resolve_quality_color_gsm_from_item_code(child_ic)
		if q and not specs.get("quality"):
			specs["quality"] = q
		if c and not specs.get("color"):
			specs["color"] = c
		if g and not specs.get("gsm"):
			specs["gsm"] = g
	if not specs.get("quality"):
		specs["quality"] = "GENERIC"
	if specs.get("gsm") is None:
		specs["gsm"] = 0
	return specs


def _immediate_parent_process_for_planning_child(child_ic, soi, pt_rows):
	"""Same SO line: parent planning row whose BOM contains this child (106→104→100 chains)."""
	child_ic = _cstr(child_ic).strip()
	soi = _cstr(soi).strip()
	if not child_ic or not pt_rows:
		return ""
	for prow in pt_rows:
		pic = _cstr(
			prow.get("item_code") if isinstance(prow, dict) else getattr(prow, "item_code", "")
		).strip()
		if not pic or pic == child_ic:
			continue
		row_soi = _cstr(
			(prow.get("sales_order_item") or prow.get("so_item"))
			if isinstance(prow, dict)
			else (getattr(prow, "sales_order_item", None) or getattr(prow, "so_item", None))
		).strip()
		if soi and row_soi and row_soi != soi:
			continue
		bom = _resolve_lamination_bom(pic)
		if not bom:
			continue
		for bom_row in bom.items or []:
			if _cstr(bom_row.item_code).strip() == child_ic:
				return _bom_item_process_code(pic) or _item_process_prefix(pic)
	return ""


def _non_bag_parent_fabric_label(ic, soi, pt_rows, pb=False):
	"""Standalone fabric SO chains: FG Fabric on SO line; children use {parent} Base Fabric."""
	parent_pp = _immediate_parent_process_for_planning_child(ic, soi, pt_rows)
	if parent_pp:
		return f"{parent_pp} PB" if pb else f"{parent_pp} Base Fabric"
	return ""


def _sync_box_bag_loop_bom_chain(planning_sheet_name, fg_parent_processes=None):
	"""
	All box bag FG processes: read 103 / 108 / 110 from FG BOM, then expand:
	  103 → 100, 108 → 107 → 100 + PB, 110 → 107 → 100 + PB.
	"""
	if not planning_sheet_name:
		return
	fg_tuple = tuple(fg_parent_processes or BOX_BAG_PROCESS_CODES)
	if not fg_tuple:
		return
	_sync_bag_fg_direct_bom_children(
		planning_sheet_name,
		fg_tuple,
		process_label="Box bag FG direct BOM (103/108/110 from BOM)",
	)
	_sync_bom_child_rows_from_planning_rows(
		planning_sheet_name,
		("103",),
		"100",
		so_parent_processes=fg_tuple,
		process_label="Box bag loop fabric (103 → 100)",
	)
	_sync_bom_child_rows_from_planning_rows(
		planning_sheet_name,
		("108",),
		"107",
		LAMINATION_UNIT,
		so_parent_processes=fg_tuple,
		process_label="Box bag BOPP loop (108 → 107)",
	)
	_sync_bom_child_rows_from_planning_rows(
		planning_sheet_name,
		("110",),
		"107",
		LAMINATION_UNIT,
		so_parent_processes=fg_tuple,
		process_label="Box bag BOPP metallic loop (110 → 107)",
	)


def _sync_bag_fg_direct_bom_children(planning_sheet_name, fg_processes, process_label="Bag FG direct BOM", so_fg_processes=None):
	"""Add planning rows for each line on the FG BOM (104+103 on 224, 103+100 on 221) — not hardcoded 105."""
	if not planning_sheet_name or not frappe.db.exists("Planning sheet", planning_sheet_name):
		return 0
	fg_set = {str(p).strip() for p in (fg_processes or ()) if str(p).strip()}
	so_fg_set = {str(p).strip() for p in (so_fg_processes or []) if str(p).strip()}
	if not fg_set:
		return 0
	ps = frappe.get_doc("Planning sheet", planning_sheet_name)
	if not ps.get("sales_order"):
		return 0
	so = frappe.get_doc("Sales Order", ps.sales_order)
	so_by_name = {str(it.name): it for it in (so.items or [])}
	parent_field = _get_pt_parentfield()
	pt_rows = frappe.get_all(
		"Planning Table",
		filters={"parent": ps.name},
		fields=["name", "item_code", "qty", "uom", "sales_order_item", "so_item"],
		limit_page_length=0,
	) or []
	added = 0
	for prow in pt_rows:
		parent_ic = _cstr(prow.get("item_code")).strip()
		parent_pp = _bom_item_process_code(parent_ic) or _item_process_prefix(parent_ic)
		if parent_pp not in fg_set:
			continue
		so_item_key = _cstr(prow.get("sales_order_item") or prow.get("so_item")).strip()
		so_it = so_by_name.get(so_item_key)
		if so_fg_set:
			so_fg_pp = _bom_item_process_code(getattr(so_it, "item_code", "") if so_it else "") or _item_process_prefix(
				getattr(so_it, "item_code", "") if so_it else ""
			)
			if so_fg_pp not in so_fg_set:
				continue
		if not so_it:
			so_it = frappe._dict(
				{
					"name": so_item_key,
					"item_code": parent_ic,
					"qty": flt(prow.get("qty") or 0),
					"uom": _cstr(prow.get("uom")) or "Kg",
				}
			)
		bom = _resolve_lamination_bom(parent_ic)
		if not bom:
			continue
		scale_qty, scale_uom = _parent_bom_scale_qty_uom(
			parent_ic, flt(prow.get("qty") or 0) or flt(so_it.qty), prow.get("uom") or getattr(so_it, "uom", None), ps.name
		)
		for bom_row in bom.items or []:
			child_ic = _cstr(bom_row.item_code).strip()
			if not child_ic:
				continue
			child_pp = _bom_item_process_code(child_ic) or _item_process_prefix(child_ic)
			if _is_printed_bopp_item_code(child_ic):
				child_pp = "PB"
			existing = frappe.db.sql(
				"""
				SELECT name FROM `tabPlanning Table`
				WHERE parent = %s AND item_code = %s
				  AND (IFNULL(sales_order_item, '') = %s OR IFNULL(so_item, '') = %s)
				LIMIT 1
				""",
				(ps.name, child_ic, so_item_key, so_item_key),
				as_dict=True,
			) or []
			if existing:
				_patch_bag_fg_bom_child_row_specs(
					ps.name, existing[0].name, child_ic, child_pp, so_it
				)
				continue
			child_qty, child_uom = _fabric_qty_uom_from_bom(
				bom.name,
				child_ic,
				scale_qty,
				from_uom=scale_uom or "Kg",
				parent_item_code=parent_ic,
				planning_sheet_name=ps.name,
			)
			specs = _bag_fg_bom_child_row_specs(child_ic, child_pp, so_it)
			item_name = frappe.db.get_value("Item", child_ic, "item_name") or child_ic
			trace_id = _parent_child_trace_id_from_item_code(parent_ic) or _parent_child_trace_id_for_planning_row(
				parent_ic, so_item_key, ps.name
			)
			row = {
				"sales_order_item": so_item_key,
				"so_item": so_item_key,
				"item_code": child_ic,
				"item_name": item_name,
				"qty": child_qty,
				"uom": child_uom,
				"unit": _unit_for_bag_fg_bom_child(child_ic, child_pp, specs),
				"custom_parent_child_trace_id": trace_id,
			}
			for fld in ("gsm", "width_inch", "color", "quality", "custom_quality"):
				if specs.get(fld) is not None and frappe.db.has_column("Planning Table", fld):
					row[fld] = specs[fld]
			for fld in ("custom_fabric_gsm", "custom_lam_gsm", "custom_bopp_gsm"):
				if specs.get(fld) is not None and frappe.db.has_column("Planning Table", fld):
					row[fld] = specs[fld]
			_apply_mandatory_planning_row_defaults(row, child_ic)
			_set_movement_type_if_supported(row, MOVEMENT_TRANSFER, "Planning Table")
			if hasattr(ps, "items") or ps.meta.has_field("items"):
				ps.append("items", dict(row))
			ps.append(parent_field, dict(row))
			added += 1
	if added:
		ps.flags.ignore_permissions = True
		ps.flags.ignore_validate = True
		ps.save(ignore_permissions=True)
		frappe.db.commit()
	return added


def _bag_deeper_child_qty_from_bom(
	bom_no,
	child_ic,
	parent_ic,
	parent_row,
	so_it,
	planning_sheet_name,
	bom_row=None,
):
	"""Qty for 100/PB under bag mid-parent — scale from parent Meter→Kg when parent is still in Meter."""
	if not bom_no or not child_ic:
		return 0.0, ""
	lam_scale, lam_uom = _lam_parent_scale_for_bom(parent_ic, parent_row, so_it, planning_sheet_name)
	pt_name = None
	if isinstance(parent_row, dict):
		pt_name = parent_row.get("name")
		if not lam_scale:
			lam_scale = flt(parent_row.get("qty") or 0)
			lam_uom = parent_row.get("uom") or lam_uom
	elif parent_row:
		pt_name = getattr(parent_row, "name", None)
	scale_kg = flt(lam_scale)
	uom_low = _cstr(lam_uom).strip().lower()
	if uom_low == "meter" and planning_sheet_name and _planning_sheet_has_bag_fg(planning_sheet_name):
		kg = _meter_qty_to_kg_for_planning_row(parent_ic, lam_scale, pt_name=pt_name)
		if kg > 0:
			scale_kg = kg
	elif uom_low and uom_low != "kg" and scale_kg > 0:
		scale_kg = _planning_qty_in_kg_for_bom(parent_ic, lam_scale, lam_uom)
	if bom_row is not None:
		qty = _scaled_component_qty_from_bom_row(bom_no, bom_row, scale_kg)
	else:
		qty = _fabric_qty_from_bom(
			bom_no,
			child_ic,
			scale_kg,
			from_uom="Kg",
			parent_item_code=parent_ic,
			planning_sheet_name=planning_sheet_name,
		)
	uom = _cstr(frappe.db.get_value("Item", child_ic, "stock_uom") or "Kg").strip() or "Kg"
	return flt(qty), uom


def _skip_bag_deeper_child_qty_on_sync(planning_sheet_name, parent_ic, child_ic):
	"""Deprecated — bag deeper child qty is computed on sync (no longer deferred to Meter→Kg)."""
	return False


def _planning_sheet_has_bag_fg(planning_sheet_name):
	"""True when this sheet has a W/D-CUT or box-bag finished-good row."""
	if not planning_sheet_name:
		return False
	for ic in frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		pluck="item_code",
		limit_page_length=0,
	) or []:
		if _item_process_prefix(_cstr(ic)) in ALL_BAG_FG_PROCESS_CODES:
			return True
	return False


def _parent_bom_scale_qty_uom(item_code, qty, uom, planning_sheet_name=None):
	"""Bag sheets: keep qty/uom until **Meter to Kgs** button. Other sheets: normalize to Kg."""
	qty = flt(qty)
	uom = _cstr(uom).strip()
	if planning_sheet_name and _planning_sheet_has_bag_fg(planning_sheet_name):
		if not uom:
			uom = _cstr(frappe.db.get_value("Item", item_code, "stock_uom") or "").strip()
		return qty, uom
	return _planning_qty_in_kg_for_bom(item_code, qty, uom), "Kg"


def _lam_parent_scale_for_bom(lam_ic, lam_row, so_it, planning_sheet_name=None):
	"""Scale qty for 107/104 BOM children (bag: planning row as-is; else Kg)."""
	lam_ic = _cstr(lam_ic).strip()
	if planning_sheet_name and _planning_sheet_has_bag_fg(planning_sheet_name):
		if lam_row:
			q = flt(getattr(lam_row, "qty", None) or (lam_row.get("qty") if isinstance(lam_row, dict) else 0))
			u = _cstr(
				getattr(lam_row, "uom", None) or (lam_row.get("uom") if isinstance(lam_row, dict) else "")
			).strip()
			if q > 0:
				return q, u or _cstr(frappe.db.get_value("Item", lam_ic, "stock_uom") or "").strip()
		if so_it:
			return flt(getattr(so_it, "qty", 0)), _cstr(getattr(so_it, "uom", None) or "").strip()
		return 0, ""
	qty = _lam_parent_scale_qty_kg(lam_ic, lam_row, so_it)
	return qty, "Kg"


def _lam_parent_scale_qty_kg(lam_ic, lam_row, so_it):
	"""Kg qty for scaling 107/104 BOM children — use the lamination planning row, not SO piece qty."""
	lam_ic = _cstr(lam_ic).strip()
	if lam_row:
		q = flt(getattr(lam_row, "qty", None) or (lam_row.get("qty") if isinstance(lam_row, dict) else 0))
		u = _cstr(
			getattr(lam_row, "uom", None) or (lam_row.get("uom") if isinstance(lam_row, dict) else "")
		).strip()
		if q > 0:
			return _planning_qty_in_kg_for_bom(lam_ic, q, u)
	if so_it and _is_lamination_parent_process(_cstr(getattr(so_it, "item_code", ""))):
		return _planning_qty_in_kg_for_bom(lam_ic, flt(getattr(so_it, "qty", 0)), getattr(so_it, "uom", None))
	return _planning_qty_in_kg_for_bom(
		lam_ic, flt(getattr(so_it, "qty", 0) if so_it else 0), getattr(so_it, "uom", None) if so_it else None
	)


def _resolve_planning_bom_child_match(parent_ic, parent_pp, child_ic):
	"""Resolve BOM child (100 / PB) for qty refresh without throwing desk messages."""
	parent_ic = _cstr(parent_ic).strip()
	child_ic = _cstr(child_ic).strip()
	if not parent_ic or not child_ic:
		return None, None
	lam_pp = _lamination_process_from_item_code(parent_ic)
	if lam_pp == "107" or parent_pp == "107":
		try:
			res107 = _resolve_107_child_components(parent_ic)
			bom_no = res107.get("bom_name")
			fab = res107.get("fabric")
			pb = res107.get("pb")
			if fab and fab[0] == child_ic:
				return child_ic, bom_no
			if pb and pb[0] == child_ic:
				return child_ic, bom_no
		except Exception:
			pass
	try:
		if child_ic.startswith("100"):
			res = _get_fabric_item_from_process_item(
				parent_ic, expected_process=parent_pp, process_label="BOM child fabric"
			)
			if res.get("fabric_item_code") == child_ic:
				return child_ic, res.get("bom_no")
		child_pp = "PB" if _is_printed_bopp_item_code(child_ic) else _item_process_prefix(child_ic)
		if child_pp:
			res = _get_bom_child_item_from_process_item(
				parent_ic, parent_pp, child_pp, process_label="BOM child"
			)
			if res.get("child_item_code") == child_ic:
				return child_ic, res.get("bom_no")
	except Exception:
		pass
	return None, None


def _planning_qty_in_kg_for_bom(item_code, qty, uom):
	"""Normalize planning row qty to Kg using Item UOM Conversion (Meter÷factor)."""
	qty = flt(qty)
	if qty <= 0 or not item_code:
		return 0
	if _planning_row_meter_qty_needs_kg_conversion(item_code, qty, uom):
		conv = frappe.db.get_value(
			"UOM Conversion Detail",
			{"parent": item_code, "uom": "Meter"},
			"conversion_factor",
		)
		if conv and flt(conv) > 0:
			return flt(qty) / flt(conv)
	return _uom_qty_to_stock_uom(item_code, qty, uom)


def _refresh_planning_sheet_bom_child_kg_qty(planning_sheet_name):
	"""Re-apply parent BOM math for child rows (103→100, bag FG→103, …) after sync / regenerate."""
	if not planning_sheet_name or not frappe.db.exists("Planning sheet", planning_sheet_name):
		return 0
	rows = frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		fields=["name", "item_code", "qty", "uom", "sales_order_item", "so_item", "custom_parent_child_trace_id", "source_item"],
		limit_page_length=0,
	)
	if not rows:
		return 0
	by_soi = {}
	for r in rows:
		soi = _cstr(r.get("sales_order_item") or r.get("so_item") or r.get("custom_parent_child_trace_id"))
		by_soi.setdefault(soi, []).append(r)
	updated = 0
	for _soi, group in by_soi.items():
		parent_rows = []
		for r in group:
			ic = _cstr(r.get("item_code"))
			pp = _item_process_prefix(ic)
			if ic.startswith("PB-") or "PRINTED" in ic.upper():
				pp = "PB"
			if pp in _BOM_KG_PARENT_PROCESSES:
				parent_rows.append(r)
		parent_rows.sort(
			key=lambda r: -(_production_sort_rank(_item_process_prefix(_cstr(r.get("item_code")))) or 0)
		)
		for prow in parent_rows:
			parent_ic = _cstr(prow.get("item_code"))
			parent_pp = _bom_item_process_code(parent_ic) or _item_process_prefix(parent_ic)
			if parent_ic.startswith("PB-") or "PRINTED" in parent_ic.upper():
				parent_pp = "PB"
			scale_qty = _planning_qty_in_kg_for_bom(parent_ic, prow.get("qty"), prow.get("uom"))
			if scale_qty <= 0:
				continue
			for crow in group:
				child_ic = _cstr(crow.get("item_code"))
				if not child_ic or child_ic == parent_ic:
					continue
				child_pp = _bom_item_process_code(child_ic) or _item_process_prefix(child_ic)
				if _is_printed_bopp_item_code(child_ic):
					child_pp = "PB"
				if child_pp in ALL_BAG_FG_PROCESS_CODES:
					continue
				msg_len = len(getattr(frappe.local, "message_log", None) or [])
				match_ic, bom_no = _resolve_planning_bom_child_match(parent_ic, parent_pp, child_ic)
				if hasattr(frappe.local, "message_log"):
					frappe.local.message_log = (frappe.local.message_log or [])[:msg_len]
				if not match_ic or not bom_no:
					continue
				child_qty = _fabric_qty_from_bom(
					bom_no, child_ic, scale_qty, from_uom="Kg", parent_item_code=parent_ic
				)
				if child_qty <= 0:
					continue
				cur = flt(crow.get("qty") or 0)
				if abs(cur - child_qty) < 0.001:
					continue
				stock_uom = _cstr(frappe.db.get_value("Item", child_ic, "stock_uom") or "Kg").strip() or "Kg"
				frappe.db.set_value(
					"Planning Table",
					crow.get("name"),
					{"qty": child_qty, "uom": stock_uom},
					update_modified=False,
				)
				_set_planning_table_qty_with_legacy_sync(planning_sheet_name, crow.get("name"), child_qty)
				crow["qty"] = child_qty
				updated += 1
	return updated


def _planning_row_meter_qty_needs_kg_conversion(
	item_code, qty, uom, planning_sheet_name=None, so_item_key=None, direct_by_soi=None
):
	"""True for bag FG **direct** BOM children in Meter (incl. 100* on 221/224 — not 103→100 fabric)."""
	ic = _cstr(item_code).strip()
	qty = flt(qty)
	uom = _cstr(uom).strip()
	if not ic or qty <= 0 or uom != "Meter":
		return False
	if _is_printed_bopp_item_code(ic):
		return False
	if planning_sheet_name and _planning_sheet_has_bag_fg(planning_sheet_name):
		if direct_by_soi is None:
			direct_by_soi = _bag_fg_direct_bom_children_by_soi(planning_sheet_name)
		if _planning_row_is_bag_fg_direct_bom_child(ic, so_item_key, direct_by_soi):
			return True
		return False
	pp = _item_process_prefix(ic)
	if pp in BAG_METER_TO_KG_CONVERT_PROCESSES:
		return True
	return _lamination_process_from_item_code(ic) == "107" or _is_107_mid_bopp_item(ic)


def _recalc_bag_fabric_under_bom_parent(planning_sheet_name, parent_process):
	"""After 103/104 parent is Kg: scale 100 from that parent's BOM (not meter÷factor on fabric)."""
	if not planning_sheet_name or not parent_process:
		return 0
	rows = (
		frappe.get_all(
			"Planning Table",
			filters={"parent": planning_sheet_name},
			fields=["name", "item_code", "qty", "uom", "sales_order_item", "so_item", "source_item"],
			limit_page_length=0,
		)
		or []
	)
	by_soi = {}
	orphan = []
	for r in rows:
		soi = _cstr(r.get("sales_order_item") or r.get("so_item"))
		if soi:
			by_soi.setdefault(soi, []).append(r)
		else:
			orphan.append(r)
	updated = 0
	exp = str(parent_process).strip()
	for _soi, group in list(by_soi.items()) + ([("", orphan)] if orphan else []):
		for prow in group:
			pic = _cstr(prow.get("item_code"))
			if exp == "104":
				if _lamination_process_from_item_code(pic) != "104":
					continue
			elif _item_process_prefix(pic) != exp:
				continue
			if _cstr(prow.get("uom")).strip().lower() == "meter":
				continue
			scale_kg = flt(prow.get("qty") or 0)
			if scale_kg <= 0:
				continue
			try:
				res = _get_fabric_item_from_process_item(
					pic, expected_process=exp, process_label="Bag BOM fabric"
				)
				fab_ic = res.get("fabric_item_code")
				bom_no = res.get("bom_no")
			except Exception:
				continue
			if not fab_ic or not bom_no:
				continue
			child_qty = _fabric_qty_from_bom(bom_no, fab_ic, scale_kg, from_uom="Kg", parent_item_code=pic)
			if child_qty <= 0:
				continue
			match_pool = group if _soi else rows
			for crow in match_pool:
				if _cstr(crow.get("item_code")) != fab_ic:
					continue
				c_soi = _cstr(crow.get("sales_order_item") or crow.get("so_item"))
				if _soi and c_soi and c_soi != _soi:
					continue
				stock_uom = _cstr(frappe.db.get_value("Item", fab_ic, "stock_uom") or "Kg").strip() or "Kg"
				frappe.db.set_value(
					"Planning Table",
					crow.get("name"),
					{"qty": child_qty, "uom": stock_uom},
					update_modified=False,
				)
				_set_planning_table_qty_with_legacy_sync(planning_sheet_name, crow.get("name"), child_qty)
				updated += 1
				break
	return updated


def _recalc_bag_fabric_under_slitting_parent(planning_sheet_name):
	return _recalc_bag_fabric_under_bom_parent(planning_sheet_name, "103")


def _recalc_bag_fabric_under_lamination_parent(planning_sheet_name):
	return _recalc_bag_fabric_under_bom_parent(planning_sheet_name, "104")


def _recalc_bag_deeper_bom_children(planning_sheet_name):
	"""After 107 is in Kg: set 100 + PB qty from 107 BOM (× ratios), never meter÷factor on those rows."""
	if not planning_sheet_name:
		return 0
	rows = frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		fields=["name", "item_code", "qty", "uom", "sales_order_item", "so_item", "source_item"],
		limit_page_length=0,
	) or []
	if not rows:
		return 0
	by_soi = {}
	for r in rows:
		soi = _cstr(r.get("sales_order_item") or r.get("so_item"))
		if soi:
			by_soi.setdefault(soi, []).append(r)
	updated = 0
	for _soi, group in by_soi.items():
		row_107 = None
		for r in group:
			ic = _cstr(r.get("item_code"))
			if _lamination_process_from_item_code(ic) == "107" or _item_process_prefix(ic) == "107":
				row_107 = r
				break
		if not row_107:
			continue
		parent_ic = _cstr(row_107.get("item_code"))
		if _cstr(row_107.get("uom")).strip().lower() == "meter":
			scale_kg = _meter_qty_to_kg_for_planning_row(
				parent_ic,
				flt(row_107.get("qty") or 0),
				pt_name=row_107.get("name"),
			)
		else:
			scale_kg = flt(row_107.get("qty") or 0)
		if scale_kg <= 0:
			continue
		res107 = _resolve_107_child_components(parent_ic) or {}
		bom_no = res107.get("bom_name")
		if not bom_no:
			continue
		targets = []
		fab = res107.get("fabric")
		if fab:
			targets.append((fab[0], fab[1]))
		pb = res107.get("pb")
		if pb:
			targets.append((pb[0], pb[1]))
		for child_ic, bom_row in targets:
			child_qty = _scaled_component_qty_from_bom_row(bom_no, bom_row, scale_kg)
			if child_qty <= 0:
				continue
			for crow in group:
				if _cstr(crow.get("item_code")) != child_ic:
					continue
				stock_uom = _cstr(frappe.db.get_value("Item", child_ic, "stock_uom") or "Kg").strip() or "Kg"
				update_dict = {"qty": child_qty, "uom": stock_uom}
				if _is_printed_bopp_item_code(child_ic) and frappe.db.has_column(
					"Planning Table", "custom_bopp_bom_kgs"
				):
					update_dict["custom_bopp_bom_kgs"] = child_qty
				frappe.db.set_value("Planning Table", crow.get("name"), update_dict, update_modified=False)
				_set_planning_table_qty_with_legacy_sync(planning_sheet_name, crow.get("name"), child_qty)
				src = crow.get("source_item")
				if src and frappe.db.exists("Planning sheet Item", src):
					psi_up = {"qty": child_qty, "uom": stock_uom}
					if _is_printed_bopp_item_code(child_ic) and frappe.db.has_column(
						"Planning sheet Item", "custom_bopp_bom_kgs"
					):
						psi_up["custom_bopp_bom_kgs"] = child_qty
					frappe.db.set_value("Planning sheet Item", src, psi_up, update_modified=False)
				updated += 1
				break
	return updated


def _convert_planning_row_meter_to_kg(row_name, item_code, qty, uom, source_item=None):
	"""Divide meter qty by conversion factor; update Planning Table + linked PSI."""
	if not _planning_row_meter_qty_needs_kg_conversion(item_code, qty, uom):
		return False
	conv = frappe.db.get_value(
		"UOM Conversion Detail",
		{"parent": item_code, "uom": "Meter"},
		"conversion_factor",
	)
	if not conv or flt(conv) <= 0:
		return False
	new_qty = flt(qty) / flt(conv)
	frappe.db.set_value(
		"Planning Table",
		row_name,
		{"uom": "Kg", "qty": new_qty},
		update_modified=False,
	)
	if source_item and frappe.db.exists("Planning sheet Item", source_item):
		frappe.db.set_value(
			"Planning sheet Item",
			source_item,
			{"uom": "Kg", "qty": new_qty},
			update_modified=False,
		)
	return True


@frappe.whitelist()
def convert_meter_to_kgs_for_box_bag_bom(planning_sheet_name, _internal_call=False):
	"""Desk **Meter to Kgs (All Bag BOM)**: bag sheets only — Meter→Kg then child BOM recalc."""
	if not planning_sheet_name:
		return {"status": "error", "message": "No planning sheet provided"}
	if not frappe.db.exists("Planning sheet", planning_sheet_name):
		frappe.throw(_("Planning Sheet {0} not found.").format(planning_sheet_name))
	if not _planning_sheet_has_bag_fg(planning_sheet_name):
		frappe.throw(
			_("Meter to Kg applies only to planning sheets with bag finished goods (W/D-CUT / box bag).")
		)

	try:
		ensure_planning_unit_field_links_workstation()
		_normalize_planning_sheet_workstation_units(planning_sheet_name)
	except Exception:
		frappe.log_error(frappe.get_traceback(), "convert_meter_to_kgs:unit_workstation")

	rows = frappe.get_all(
		"Planning Table",
		filters={"parent": planning_sheet_name},
		fields=[
			"name",
			"item_code",
			"qty",
			"uom",
			"custom_parent_child_trace_id",
			"sales_order_item",
			"so_item",
			"source_item",
		],
	) or []

	updated_count = 0
	skipped_no_conv = []
	direct_by_soi = _bag_fg_direct_bom_children_by_soi(planning_sheet_name)

	for r in rows:
		ic = r.get("item_code")
		if not ic:
			continue
		pp_prefix = _item_process_prefix(ic)
		if pp_prefix in BOPP_BOX_BAG_PROCESS_CODES:
			try:
				from production_entry.production_planning.bopp_bag_api import _parse_bopp_bag_item_code

				p = _parse_bopp_bag_item_code(ic)
				if p and p.get("total_gsm"):
					frappe.db.set_value("Planning Table", r.get("name"), "gsm", p["total_gsm"])
			except Exception:
				pass
		elif pp_prefix in ("221", "224"):
			try:
				from production_entry.production_planning.box_bag_api import _parse_box_bag_item_code

				p = _parse_box_bag_item_code(ic)
				if p and p.get("total_gsm"):
					frappe.db.set_value("Planning Table", r.get("name"), "gsm", p["total_gsm"])
			except Exception:
				pass
		elif pp_prefix in W_CUT_D_CUT_FG_PROCESS_CODES:
			try:
				from production_entry.production_planning.box_bag_api import _parse_dcut_bag_item_code

				p = _parse_dcut_bag_item_code(ic)
				if p and p.get("total_gsm"):
					frappe.db.set_value("Planning Table", r.get("name"), "gsm", p["total_gsm"])
			except Exception:
				pass

		so_item = r.get("sales_order_item") or r.get("so_item")
		if not _planning_row_meter_qty_needs_kg_conversion(
			ic,
			flt(r.get("qty")),
			r.get("uom"),
			planning_sheet_name=planning_sheet_name,
			so_item_key=so_item,
			direct_by_soi=direct_by_soi,
		):
			continue
		new_qty = _meter_qty_to_kg_for_planning_row(
			ic, flt(r.get("qty")), source_item=r.get("source_item"), pt_name=r.get("name")
		)
		if new_qty <= 0:
			skipped_no_conv.append(ic)
			continue
		frappe.db.set_value("Planning Table", r.get("name"), {"uom": "Kg", "qty": new_qty})
		source_item = r.get("source_item")
		if source_item and frappe.db.exists("Planning sheet Item", source_item):
			frappe.db.set_value("Planning sheet Item", source_item, {"uom": "Kg", "qty": new_qty})
		updated_count += 1

	frappe.db.commit()

	try:
		updated_count += _recalc_bag_fabric_under_slitting_parent(planning_sheet_name)
		updated_count += _recalc_bag_fabric_under_lamination_parent(planning_sheet_name)
		updated_count += _recalc_bag_deeper_bom_children(planning_sheet_name)
		frappe.db.commit()
	except Exception:
		frappe.log_error(frappe.get_traceback(), "convert_meter_to_kgs:recalc_deeper_children")

	try:
		_sync_linked_production_plans_rm_from_planning_sheet(planning_sheet_name)
	except Exception:
		frappe.log_error(frappe.get_traceback(), "convert_meter_to_kgs:sync_pp_wo")

	result = {"status": "success", "updated": updated_count}
	if skipped_no_conv:
		result["skipped"] = skipped_no_conv
		result["warning"] = _("Skipped {0} item(s) — no Meter→Kg conversion and no weight/meter on planning row.").format(
			len(skipped_no_conv)
		)
	return result




@frappe.whitelist()
def scan_stock_entry_batch(barcode, expected_item, source_warehouse=None):
    if not barcode:
        return {'error': 'No barcode provided'}
        
    batch = frappe.db.get_value('Batch', barcode, ['name', 'item', 'batch_qty'], as_dict=1)
    if not batch:
        return {'error': f'Batch {barcode} not found in the system.'}
        
    if expected_item and batch.item != expected_item:
        return {'error': f'Wrong Item: The scanned batch belongs to {batch.item}, but expected {expected_item}.'}
        
    available_qty = batch.batch_qty
    if source_warehouse:
        bin_qty = frappe.db.get_value('Bin', {'item_code': batch.item, 'warehouse': source_warehouse}, 'actual_qty')
        # Wait, get_batch_qty is better
        try:
            from erpnext.stock.utils import get_batch_qty
            available_qty = get_batch_qty(barcode, source_warehouse, batch.item)
        except Exception:
            pass
            
    return {
        'batch_no': batch.name,
        'item_code': batch.item,
        'available_qty': available_qty or batch.batch_qty
    }

@frappe.whitelist()
def add_batch_to_bundle(bundle_id, item_code, warehouse, batch_no, qty, voucher_type="Stock Entry"):
    qty = float(qty)
    if not bundle_id:
        bundle = frappe.get_doc({
            "doctype": "Serial and Batch Bundle",
            "item_code": item_code,
            "warehouse": warehouse,
            "type_of_transaction": "Outward",
            "voucher_type": voucher_type,
            "has_batch_no": 1,
            "entries": [{
                "batch_no": batch_no,
                "qty": qty
            }]
        })
        bundle.insert(ignore_permissions=True)
        return {"bundle_id": bundle.name, "added": True, "qty_added": qty}
    else:
        bundle = frappe.get_doc("Serial and Batch Bundle", bundle_id)
        # Check if already exists
        for row in bundle.entries:
            if row.batch_no == batch_no:
                # Do not increase qty if it's the same roll, just return
                return {"bundle_id": bundle.name, "added": False, "qty_added": 0}
        
        bundle.append("entries", {
            "batch_no": batch_no,
            "qty": qty
        })
        bundle.save(ignore_permissions=True)
        return {"bundle_id": bundle.name, "added": True, "qty_added": qty}
